fn audit_directory(path: &Path, total: &mut usize, compliant: &mut usize, legacy: &mut usize) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }

    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let entry_path = entry.path();

        if entry_path.is_dir() {
            audit_directory(&entry_path, total, compliant, legacy)?;
        } else if entry_path.extension().map(|s| s == "json").unwrap_or(false) {
            *total += 1;
            let filename = entry_path.file_name().unwrap_or_default().to_string_lossy();

            let data = fs::read_to_string(&entry_path)
                .with_context(|| format!("Failed to read fragment: {:?}", entry_path))?;

            match serde_json::from_str::<LogicFragment>(&data) {
                Ok(fragment) => {
                    let is_signed = fragment.signature.is_some();
                    let is_sequenced = fragment.sequence_id > 0;
                    let has_signer = fragment.signer_id.is_some();

                    if is_signed && is_sequenced && has_signer {
                        println!("[ COMPLIANT ] Fragment: {} (Seq: {})", filename, fragment.sequence_id);
                        *compliant += 1;
                    } else {
                        println!("[ VOID ] Legacy Fragment Detected: {} | Needs Up-Strike", filename);
                        *legacy += 1;
                    }
                },
                Err(e) => {
                    println!("[ CORRUPT ] Failed to parse fragment: {} | Error: {:?}", filename, e);
                    *legacy += 1;
                }
            }
        }
    }
    Ok(())
}

