fn scan_for_hallucinations(path: &Path) -> Vec<String> {
    let mut errors = Vec::new();

    let mut file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return errors,
    };

    // Use a small 8KB buffer to prevent memory collapse
    let mut reader = BufReader::new(file);
    let mut buffer = [0u8; 8192];

    while let Ok(bytes_read) = reader.read(&mut buffer) {
        if bytes_read == 0 { break; }

        // Scan the chunk without converting the whole file to a string
        let chunk = &buffer[..bytes_read];
        let text = String::from_utf8_lossy(chunk);

        // 1. Hardware Hallucinations
        if text.contains("RTX 4050") || text.contains("VRAM: 6GB") {
            errors.push("HW_HALLUCINATION: FAKE_HARDWARE_DETECTED".to_string());
