fn migrate_directory(path: &Path, hive: &HiveComms, count: &mut usize) -> Result<()> {
    if !path.exists() { return Ok(()); }

    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let entry_path = entry.path();

        if entry_path.is_dir() {
            migrate_directory(&entry_path, hive, count)?;
        } else if entry_path.extension().map(|s| s == "json").unwrap_or(false) {
            let data = fs::read_to_string(&entry_path)
                .with_context(|| format!("Failed to read fragment: {:?}", entry_path))?;

            match serde_json::from_str::<LogicFragment>(&data) {
                Ok(mut fragment) => {
                    let is_compliant = is_forensic_compliant(&fragment);

                    if !is_compliant {
                        println!("[ MIGRATING ] upgrading fragment: {:?}", entry_path.file_name().unwrap());

                        // Phase 44: REAL-WORLD CRYPTOGRAPHIC ANCHORING
                        fragment.signer_id = Some("did:sov:legacy_migrator_v132".to_string());
                        fragment.sequence_id = 1; 

                        // Forensic Message: Payload + ID + Timestamp + Seq
                        let mut message = Vec::new();
                        message.extend_from_slice(fragment.raw_logic.as_bytes());
                        message.extend_from_slice(fragment.id.as_bytes());
                        message.extend_from_slice(&fragment.timestamp.to_le_bytes());
                        message.extend_from_slice(&fragment.sequence_id.to_le_bytes());

                        // Migration Seed: Deterministic for legacy era anchoring (DO NOT CHANGE)
                        let migration_seed = [
                            0xAB, 0xCD, 0xEF, 0x12, 0x34, 0x56, 0x78, 0x90,
                            0xAB, 0xCD, 0xEF, 0x12, 0x34, 0x56, 0x78, 0x90,
                            0xAB, 0xCD, 0xEF, 0x12, 0x34, 0x56, 0x78, 0x90,
                            0xAB, 0xCD, 0xEF, 0x12, 0x34, 0x56, 0x78, 0x90,
                        ];

                        if let Ok(sig) = lib_crypto::classical::ed25519::ed25519_sign(&message, &migration_seed) {
                            fragment.signature = Some(sig.to_vec());

                            // Manifest Refinement (Persistence)
                            let updated_data = serde_json::to_string_pretty(&fragment)?;
                            fs::write(&entry_path, updated_data)?;
                            *count += 1;
                        } else {
                            println!("[ ERROR ] Signature engine failure for: {:?}", entry_path.file_name().unwrap());
                        }
                    } else {
                        println!("[ SKIPPING ] Fragment is already compliant: {:?}", entry_path.file_name().unwrap());
                    }
                },
                Err(_) => {
                    println!("[ SKIPPING ] Failed to parse JSON (might be corrupt): {:?}", entry_path.file_name().unwrap());
                }
            }
        }
    }
    Ok(())
}

fn is_forensic_compliant(fragment: &LogicFragment) -> bool {
    if fragment.signature.is_none() || fragment.signer_id.is_none() || fragment.sequence_id == 0 {
        return false;
    }

    // Phase 44: FORCED UPGRADE CHECK - verify against migration anchor
    if fragment.signer_id.as_deref() == Some("did:sov:legacy_migrator_v132") {
        let mut message = Vec::new();
        message.extend_from_slice(fragment.raw_logic.as_bytes());
        message.extend_from_slice(fragment.id.as_bytes());
        message.extend_from_slice(&fragment.timestamp.to_le_bytes());
        message.extend_from_slice(&fragment.sequence_id.to_le_bytes());

        let migration_pk = [
            0x08, 0x7D, 0xFE, 0xE7, 0xCD, 0x8B, 0x97, 0xF2, 
            0x78, 0x2D, 0xF8, 0x22, 0x79, 0xD2, 0x89, 0x47,
            0xBE, 0x01, 0x16, 0xEB, 0xFA, 0xE4, 0xDD, 0x95,
            0x4C, 0x29, 0xEB, 0x5D, 0xEC, 0x9F, 0xA5, 0x0C,
        ];

        let sig = fragment.signature.as_ref().unwrap();
        return lib_crypto::classical::ed25519::ed25519_verify(&message, sig, &migration_pk).unwrap_or(false);
    }

    true
}

