struct SearchIndex {
    chunks: Vec<CodeChunk>,
    doc_freq: HashMap<String, usize>,  // How many chunks contain this term
    total_files: usize,
    built_at: u64,
}

fn build_index() -> Result<SearchIndex> {
    let mut chunks: Vec<CodeChunk> = Vec::new();
    let mut doc_freq: HashMap<String, usize> = HashMap::new();
    let mut total_files = 0usize;

    // Directories to index
    let index_dirs = [
        r"C:\GENESIS\Sovereign_Specialized_Agents\src",
        r"C:\GENESIS\zhtp\src",
        r"C:\GENESIS\lib-identity\src",
        r"C:\GENESIS\lib-crypto\src",
        r"C:\GENESIS\lib-blockchain\src",
        r"C:\GENESIS\lib-network\src",
        r"C:\GENESIS\Sovereign_Suite_RS\src",
    ];

    // Also index GENESIS.md as documentation chunks
    let doc_files = [
        r"C:\GENESIS\GENESIS.md",
        r"C:\GENESIS\SESSION_BRIEFING.md",
    ];

    for dir in &index_dirs {
        if !Path::new(dir).exists() { continue; }
        index_directory(dir, &mut chunks, &mut doc_freq, &mut total_files);
    }
    for doc in &doc_files {
        if Path::new(doc).exists() {
            index_markdown_file(doc, &mut chunks, &mut doc_freq);
            total_files += 1;
        }
    }

    // Build TF vectors for all chunks
    for chunk in chunks.iter_mut() {
        let tokens = tokenize(&chunk.content);
        let total = tokens.len() as f64;
        if total == 0.0 { continue; }
        let mut freq: HashMap<String, usize> = HashMap::new();
        for t in &tokens { *freq.entry(t.clone()).or_insert(0) += 1; }
        chunk.tf = freq.into_iter().map(|(k, v)| (k, v as f64 / total)).collect();
    }

    let built_at = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    Ok(SearchIndex { chunks, doc_freq, total_files, built_at })
}

fn chunk_rust_file(path: &str, content: &str, id_offset: usize) -> Vec<CodeChunk> {
    let mut chunks = Vec::new();
    let lines: Vec<&str> = content.lines().collect();
    let mut chunk_start = 0usize;
    let mut brace_depth: i32 = 0;
    let mut in_chunk = false;
    let mut chunk_sig = String::new();

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();

        // Detect chunk boundary: fn, impl, struct, enum, trait at top level
        if brace_depth == 0 && !in_chunk {
            if trimmed.starts_with("pub fn ") || trimmed.starts_with("fn ") ||
               trimmed.starts_with("pub async fn ") || trimmed.starts_with("async fn ") ||
               trimmed.starts_with("impl ") || trimmed.starts_with("pub impl ") ||
               trimmed.starts_with("struct ") || trimmed.starts_with("pub struct ") ||
               trimmed.starts_with("enum ") || trimmed.starts_with("pub enum ") ||
               trimmed.starts_with("trait ") || trimmed.starts_with("pub trait ") {
                chunk_start = i;
                in_chunk = true;
                chunk_sig = extract_signature(trimmed);
            }
        }

        // Count braces
        for ch in line.chars() {
            match ch {
                '{' => brace_depth += 1,
                '}' => {
                    brace_depth -= 1;
                    if brace_depth < 0 { brace_depth = 0; }
                }
                _ => {}
            }
        }

        // Close chunk when braces return to 0 and we saw an open
        if in_chunk && brace_depth == 0 {
            let end = i;
            let chunk_lines = &lines[chunk_start..=end.min(lines.len()-1)];
            let text = chunk_lines.join("\n");

            // Skip tiny chunks (< 5 lines)
            if chunk_lines.len() >= 3 {
                chunks.push(CodeChunk {
                    id: id_offset + chunks.len(),
                    file: path.to_string(),
                    start_line: chunk_start + 1,
                    end_line: end + 1,
                    signature: chunk_sig.clone(),
                    content: text,
                    tf: HashMap::new(),
                });
            }
            in_chunk = false;
            chunk_sig = String::new();
        }
    }

    // If file never had balanced braces (small file), index it whole
    if chunks.is_empty() && !content.trim().is_empty() {
        chunks.push(CodeChunk {
            id: id_offset,
            file: path.to_string(),
            start_line: 1,
            end_line: lines.len(),
            signature: format!("[file] {}", Path::new(path).file_name()
                .and_then(|n| n.to_str()).unwrap_or(path)),
            content: content.to_string(),
            tf: HashMap::new(),
        });
    }

    chunks
}

