fn now_unix() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()
}

fn now_human() -> String {
    // Simple ISO-like timestamp without chrono dep
    let ts = now_unix();
    let secs = ts % 60;
    let mins = (ts / 60) % 60;
    let hours = (ts / 3600) % 24;
    let days = ts / 86400;
    format!("epoch+{}d {}:{:02}:{:02}Z", days, hours, mins, secs)
}

fn file_modified_time(path: &str) -> String {
    std::fs::metadata(path)
        .and_then(|m| m.modified())
        .map(|t| {
            let d = t.duration_since(UNIX_EPOCH).unwrap_or_default();
            format!("unix:{}", d.as_secs())
        })
        .unwrap_or_else(|_| "unknown".to_string())
}

fn file_size(path: &str) -> u64 {
    std::fs::metadata(path).map(|m| m.len()).unwrap_or(0)
}

fn count_processes(name: &str) -> (usize, Vec<u32>) {
    // Use Windows WMIC to count processes by name
    let out = std::process::Command::new("wmic")
        .args(["process", "where", &format!("name='{}.exe'", name), "get", "ProcessId"])
        .output();
    match out {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            let pids: Vec<u32> = text.split_whitespace()
                .filter_map(|s| s.parse::<u32>().ok())
                .collect();
            (pids.len(), pids)
        }
        Err(_) => (0, vec![]),
    }
}

fn process_ram_mb(pid: u32) -> f64 {
    let out = std::process::Command::new("wmic")
        .args(["process", "where", &format!("ProcessId={}", pid), "get", "WorkingSetSize"])
        .output();
    match out {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            text.split_whitespace()
                .filter_map(|s| s.parse::<u64>().ok())
                .next()
                .map(|b| b as f64 / 1_048_576.0)
                .unwrap_or(0.0)
        }
        Err(_) => 0.0,
    }
}

