            // Restart via launch bat
            std::process::Command::new("cmd")
                .args(["/c", r"C:\GENESIS\zhtp_launch.bat", ">", r"C:\GENESIS\zhtp_boot.log", "2>&1"])
                .spawn()
                .ok();
            log_incident("HIGH", "zhtp", &format!("ZHTP crashed. Auto-restart #{} initiated.", zhtp_restart_count));
