            println!("[HEALTH_PATROL] t={} ZHTP=ALIVE BMMS={}", now, if bmms_ok { "OK" } else { "WARN" });
        }

        // ── Fleet health ───────────────────────────────────────────
        let (agent_count, _) = count_processes("sovereign_agent");
        if agent_count < 100 {
            fleet_restart_count += 1;
            println!("[HEALTH_PATROL] t={} Fleet critically low: {} agents. Restart #{}", now, agent_count, fleet_restart_count);
            std::process::Command::new(r"C:\GENESIS\target\debug\universality_strike.exe")
