                .args(["build", "--package", crate_name])
                .current_dir(r"C:\GENESIS")
                .output();

            if let Ok(o) = out {
                let stderr = String::from_utf8_lossy(&o.stderr);
                if !o.status.success() {
                    // Match against known fixes
                    let mut matched_fixes = Vec::new();
                    for (pattern, fix) in &known_fixes {
                        if stderr.contains(pattern.as_str()) {
                            matched_fixes.push(fix.clone());
