fn run_codebase_sentinel(interval_secs: u64) -> Result<()> {
    let snapshot_path = r"C:\GENESIS\nanites\code_snapshot.json";
    let changes_path  = r"C:\GENESIS\nanites\code_changes.md";
    println!("[CODEBASE_SENTINEL] Watching GENESIS source. Output: {}", changes_path);
    std::fs::create_dir_all(r"C:\GENESIS\nanites").ok();

    let scan = || -> HashMap<String, u64> {
        let mut map = HashMap::new();
        let bases = [
            r"C:\GENESIS\Sovereign_Specialized_Agents\src",
            r"C:\GENESIS\zhtp\src",
        ];
        for base in &bases {
            let mut scan_dir = |dir: &str| {
                if let Ok(entries) = std::fs::read_dir(dir) {
                    for e in entries.flatten() {
                        let p = e.path();
                        if p.is_file() {
                            let ext = p.extension().and_then(|x| x.to_str()).unwrap_or("");
                            if matches!(ext, "rs" | "toml") {
                                if let Ok(m) = e.metadata() {
                                    if let Ok(t) = m.modified() {
                                        let ts = t.duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
                                        map.insert(p.to_string_lossy().replace('\\', "/"), ts);
                                    }
                                }
                            }
                        }
                    }
                }
            };
            scan_dir(base);
            if let Ok(es) = std::fs::read_dir(base) {
                for e in es.flatten() {
                    if e.path().is_dir() {
                        scan_dir(&e.path().to_string_lossy().to_string());
                    }
                }
            }
        }
        map
    };

    loop {
        let now = now_unix();
        let current = scan();
        let previous: HashMap<String, u64> = std::fs::read_to_string(snapshot_path)
            .ok().and_then(|s| serde_json::from_str(&s).ok()).unwrap_or_default();
        let mut added = Vec::new();
        let mut modified = Vec::new();
        let mut removed = Vec::new();
        for (path, &ts) in &current {
            match previous.get(path) {
                None => added.push(format!("  + `{}`", path)),
                Some(&p) if ts > p => modified.push(format!("  ~ `{}` (unix:{} -> {})", path, p, ts)),
                _ => {}
            }
        }
        for path in previous.keys() {
            if !current.contains_key(path) { removed.push(format!("  - `{}`", path)); }
        }
        if let Ok(json) = serde_json::to_string_pretty(&current) {
            std::fs::write(snapshot_path, json).ok();
        }
        let mut report = format!("# Code Changes (unix:{})\n\n", now);
        if added.is_empty() && modified.is_empty() && removed.is_empty() {
            report += "No changes since last check.\n";
        } else {
            if !added.is_empty() { report += &format!("## Added ({})\n{}\n\n", added.len(), added.join("\n")); }
            if !modified.is_empty() { report += &format!("## Modified ({})\n{}\n\n", modified.len(), modified.join("\n")); }
            if !removed.is_empty() { report += &format!("## Removed ({})\n{}\n\n", removed.len(), removed.join("\n")); }
        }
        report += &format!("*Tracking {} files*\n", current.len());
        std::fs::write(changes_path, &report).ok();
        println!("[CODEBASE_SENTINEL] t={} files={} +{} ~{} -{}", now, current.len(), added.len(), modified.len(), removed.len());
        std::thread::sleep(std::time::Duration::from_secs(interval_secs));
    }
}

