        println!("[!] VOLUME DISMOUNTED (CACHE PURGED)");
    }

    // 3. THE ASYNC PIPELINE
    let (tx, mut rx): (Sender<Vec<u8>>, Receiver<Vec<u8>>) = channel(128);

    // WRITER TASK
    let writer_task = tokio::spawn(async move {
        let mut total_files = 0;
        let mut total_bytes = 0u64;
        let output_handle = s_handle;

        while let Some(buffer) = rx.recv().await {
            let mut offset = 0;
            while offset < buffer.len() {
                let to_write = std::cmp::min(buffer.len() - offset, 64 * 1024 * 1024);
                unsafe {
                    let mut bytes_written = 0u32;
                    let _ = WriteFile(output_handle.0, Some(&buffer[offset..offset+to_write]), Some(&mut bytes_written), None);
                }
                offset += to_write;
            }
            total_bytes += buffer.len() as u64;
            total_files += 1;
        }
        println!("[!] ASYNC MIRROR COMPLETE.");
    });

