    println!("[!] INITIALIZING 23-TASK ASYNC DIAGNOSTIC WORKERS...");
    let mut entries = WalkDir::new(source_dir);
    let mut tasks = Vec::new();
    let source_root = PathBuf::from(source_dir);

    while let Some(entry) = entries.next().await {
        if let Ok(entry) = entry {
            if entry.file_type().await.map(|ft| ft.is_file()).unwrap_or(false) {
                let tx_clone = tx.clone();
                let path = entry.path();
                let root_clone = source_root.clone();

                tasks.push(tokio::spawn(async move {
                    let relative_path = path.strip_prefix(&root_clone).unwrap();
                    let path_str = relative_path.to_string_lossy();

                    // VERBOSE LOGGING: PINPOINT THE STALL
                    print!("\r[ SCANNING ] {}", path_str);

                    match tokio::fs::read(&path).await {
                        Ok(data) => {
                            let len = data.len() as u64;
                            let path_bytes = path_str.as_bytes().to_vec();
                            let mut buffer = Vec::with_capacity(4096 + data.len());
                            buffer.extend_from_slice(&(path_bytes.len() as u32).to_le_bytes());
                            buffer.extend_from_slice(&path_bytes);
                            buffer.extend_from_slice(&len.to_le_bytes());
                            buffer.extend_from_slice(&data);

                            let padding = (4096 - (buffer.len() % 4096)) % 4096;
                            buffer.extend(std::iter::repeat(0).take(padding));

                            let _ = tx_clone.send(buffer).await;
                        },
                        Err(e) => {
                            println!("\n[!] SKIP: {} | REASON: {}", path_str, e);
                        }
                    }
                }));

                if tasks.len() >= 23 {
                    for task in tasks.drain(..) {
                        let _ = task.await;
                    }
                }
            }
        }
    }

    for task in tasks {
        let _ = task.await;
    }

    drop(tx); 
    let _ = writer_task.await;

    Ok(())
}

