    /// Handle authenticated HTTP stream from control plane connection
    /// The session contains authentication context from UHP+Kyber handshake
    pub async fn handle_authenticated_http_stream(
        &self,
        buffered: &mut crate::server::quic_handler::BufferedStream,
        mut send: SendStream,
        session: &crate::server::quic_handler::ControlPlaneSession,
    ) -> Result<()> {
        debug!("🔄 Processing authenticated HTTP request from {} (compatibility mode)", session.peer_did);

        // Read HTTP request from buffered stream
        let buffer = buffered.read_to_end(10 * 1024 * 1024).await
            .map_err(|e| anyhow::anyhow!("Failed to read HTTP request from buffered stream: {}", e))?;

        if buffer.is_empty() {
            return Ok(());
        }

        // Parse HTTP request
        let http_data = String::from_utf8_lossy(&buffer);
        let mut request = match self.parse_http_request(&http_data) {
            Ok(req) => req,
            Err(e) => {
                warn!("❌ Failed to parse HTTP request from {}: {}", session.peer_did, e);
                let error_response = self.create_http_error_response(400, "Bad Request");
                send.write_all(&error_response).await
                    .map_err(|e| anyhow::anyhow!("Write error: {}", e))?;
                send.finish()
                    .map_err(|e| anyhow::anyhow!("Finish error: {}", e))?;
                return Ok(());
            }
        };

        // Add authenticated requester identity to request context
        // IdentityId is a Hash of the DID
        request.requester = Some(lib_crypto::Hash(lib_crypto::hash_blake3(session.peer_did.as_bytes())));

        info!("🔄 Authenticated HTTP {} {} → ZHTP from {}",
            match request.method {
                ZhtpMethod::Get => "GET",
                ZhtpMethod::Post => "POST",
                ZhtpMethod::Put => "PUT",
                ZhtpMethod::Delete => "DELETE",
                _ => "UNKNOWN",
            },
            request.uri,
            session.peer_did
        );

        // Route through ZHTP router
        let router = self.router.read().await;
        let response = router.route_request(request).await
            .unwrap_or_else(|e| {
                warn!("Handler error for authenticated request: {}", e);
                ZhtpResponse::error(ZhtpStatus::InternalServerError, e.to_string())
            });

        // Convert ZHTP response back to HTTP
        let http_response = self.zhtp_to_http_response(&response);

        send.write_all(&http_response).await
            .map_err(|e| anyhow::anyhow!("Write error: {}", e))?;
        send.finish()
            .map_err(|e| anyhow::anyhow!("Finish error: {}", e))?;

        debug!("✅ Authenticated HTTP response sent to {}", session.peer_did);
        Ok(())
    }

    /// Parse HTTP/1.1 request into ZHTP request
    fn parse_http_request(&self, http_data: &str) -> Result<ZhtpRequest> {
        let lines: Vec<&str> = http_data.lines().collect();

        if lines.is_empty() {
            return Err(anyhow::anyhow!("Empty HTTP request"));
        }

        // Parse request line
        let parts: Vec<&str> = lines[0].split_whitespace().collect();
        if parts.len() < 2 {
            return Err(anyhow::anyhow!("Invalid HTTP request line"));
        }

        let method = match parts[0] {
            "GET" => ZhtpMethod::Get,
            "POST" => ZhtpMethod::Post,
            "PUT" => ZhtpMethod::Put,
            "DELETE" => ZhtpMethod::Delete,
            "HEAD" => ZhtpMethod::Head,
            "OPTIONS" => ZhtpMethod::Options,
            _ => ZhtpMethod::Get,
        };

        let uri = parts[1].to_string();

        // Parse headers
        let mut headers = ZhtpHeaders::new();
        let mut body_start = 0;

        for (i, line) in lines.iter().enumerate().skip(1) {
            if line.is_empty() {
                body_start = i + 1;
                break;
            }
            if let Some((key, value)) = line.split_once(':') {
                headers.set(key.trim(), value.trim().to_string());
            }
        }

        // Parse body
        let body = if body_start < lines.len() {
            lines[body_start..].join("\n").into_bytes()
        } else {
            Vec::new()
        };

        Ok(ZhtpRequest {
            method,
            uri,
            headers,
            body,
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            version: "1.0".to_string(),
            requester: None,
            auth_proof: None,
        })
    }

    /// Convert ZHTP response to HTTP/1.1 response
    fn zhtp_to_http_response(&self, response: &ZhtpResponse) -> Vec<u8> {
        let status_line = match response.status {
            ZhtpStatus::Ok => "HTTP/1.1 200 OK\r\n",
            ZhtpStatus::Created => "HTTP/1.1 201 Created\r\n",
            ZhtpStatus::Accepted => "HTTP/1.1 202 Accepted\r\n",
            ZhtpStatus::BadRequest => "HTTP/1.1 400 Bad Request\r\n",
            ZhtpStatus::Unauthorized => "HTTP/1.1 401 Unauthorized\r\n",
            ZhtpStatus::Forbidden => "HTTP/1.1 403 Forbidden\r\n",
            ZhtpStatus::NotFound => "HTTP/1.1 404 Not Found\r\n",
            ZhtpStatus::TooManyRequests => "HTTP/1.1 429 Too Many Requests\r\n",
            ZhtpStatus::InternalServerError => "HTTP/1.1 500 Internal Server Error\r\n",
            _ => "HTTP/1.1 500 Internal Server Error\r\n",
        };

        let content_type = response.headers.get("content-type")
            .unwrap_or_else(|| "application/json".to_string());

        let mut http_response = String::new();
        http_response.push_str(status_line);
        http_response.push_str(&format!("Content-Type: {}\r\n", content_type));
        http_response.push_str("Access-Control-Allow-Origin: *\r\n");
        http_response.push_str("Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS\r\n");
        http_response.push_str("Access-Control-Allow-Headers: Content-Type, Authorization\r\n");
        http_response.push_str(&format!("Content-Length: {}\r\n", response.body.len()));
        http_response.push_str("X-ZHTP-Compatibility: HTTP-Legacy\r\n");
        http_response.push_str("Connection: close\r\n");
        http_response.push_str("\r\n");

        let mut result = http_response.into_bytes();
        result.extend_from_slice(&response.body);
        result
    }

    /// Create HTTP error response
    fn create_http_error_response(&self, status_code: u16, message: &str) -> Vec<u8> {
        let status_line = match status_code {
            400 => "HTTP/1.1 400 Bad Request\r\n",
            404 => "HTTP/1.1 404 Not Found\r\n",
            500 => "HTTP/1.1 500 Internal Server Error\r\n",
            _ => "HTTP/1.1 500 Internal Server Error\r\n",
        };

        let body = format!("{{\"error\": \"{}\"}}", message);
        let mut response = String::new();
        response.push_str(status_line);
        response.push_str("Content-Type: application/json\r\n");
        response.push_str("Access-Control-Allow-Origin: *\r\n");
        response.push_str(&format!("Content-Length: {}\r\n", body.len()));
        response.push_str("Connection: close\r\n");
        response.push_str("\r\n");
        response.push_str(&body);

        response.into_bytes()
    }
}

//! ZHTP Protocol Handler - Native ZHTP Over QUIC
//!
//! This module implements the native ZHTP protocol directly over QUIC streams,
//! replacing the HTTP layer entirely for Web4 communications.

pub mod router;
pub mod serialization;
pub mod compatibility;

pub use router::ZhtpRouter;
pub use serialization::{serialize_request, deserialize_request, serialize_response, deserialize_response};
pub use compatibility::HttpCompatibilityLayer;

pub struct ZhtpRouter {
    /// Registered route handlers
    routes: HashMap<String, Arc<dyn ZhtpRequestHandler>>,

    /// Request middleware
    middleware: Vec<Arc<dyn Middleware>>,
}

impl ZhtpRouter {
    /// Create a new ZHTP router
    pub fn new() -> Self {
        Self {
            routes: HashMap::new(),
            middleware: Vec::new(),
        }
    }

    /// Register a handler for a specific path
    pub fn register_handler(&mut self, path: String, handler: Arc<dyn ZhtpRequestHandler>) {
        info!("📝 Registering ZHTP handler: {}", path);
        self.routes.insert(path, handler);
    }

    /// Add middleware to the processing chain
    pub fn add_middleware(&mut self, middleware: Arc<dyn Middleware>) {
        info!("🔧 Adding ZHTP middleware: {}", middleware.name());
        self.middleware.push(middleware);
    }

    /// Handle a native ZHTP request over QUIC stream
    pub async fn handle_zhtp_stream(
        &self,
        mut recv: RecvStream,
        mut send: SendStream,
    ) -> Result<()> {
        debug!("📨 Processing native ZHTP request over QUIC");

        // Read request data from QUIC stream
        let request_data = recv.read_to_end(super::serialization::MAX_MESSAGE_SIZE)
            .await
            .map_err(|e| anyhow::anyhow!("Failed to read ZHTP request from QUIC stream: {}", e))?;

        self.handle_zhtp_request_data(request_data, send).await
    }

    /// Handle ZHTP request with already-read prefix data
    pub async fn handle_zhtp_stream_with_prefix(
        &self,
        prefix: Vec<u8>,
        mut recv: RecvStream,
        send: SendStream,
    ) -> Result<()> {
        debug!("📨 Processing native ZHTP request with {} byte prefix", prefix.len());

        // Read remaining data
        let remaining = recv.read_to_end(super::serialization::MAX_MESSAGE_SIZE)
            .await
            .map_err(|e| anyhow::anyhow!("Failed to read remaining ZHTP data: {}", e))?;

        // Combine prefix with remaining data
        let mut request_data = prefix;
        request_data.extend(remaining);

        self.handle_zhtp_request_data(request_data, send).await
    }

    /// Internal: process ZHTP request data and send response
    async fn handle_zhtp_request_data(
        &self,
        request_data: Vec<u8>,
        mut send: SendStream,
    ) -> Result<()> {
        if request_data.is_empty() {
            warn!("⚠️ Empty ZHTP request received");
            return Ok(());
        }

        debug!("📦 Received {} bytes of ZHTP request data", request_data.len());

        // Deserialize ZHTP request
        let request = match deserialize_request(&request_data) {
            Ok(req) => req,
            Err(e) => {
                warn!("❌ Failed to deserialize ZHTP request: {}", e);
                let error_response = ZhtpResponse::error(
                    ZhtpStatus::BadRequest,
                    format!("Invalid ZHTP request: {}", e),
                );
                let response_data = serialize_response(&error_response)?;
                send.write_all(&response_data).await
                    .map_err(|e| anyhow::anyhow!("Write error: {}", e))?;
                send.finish()
                    .map_err(|e| anyhow::anyhow!("Finish error: {}", e))?;
                return Ok(());
            }
        };

        info!("✅ ZHTP {} {}", request.method, request.uri);

        // Process middleware
        let (processed_request, middleware_response) = self.process_middleware(request).await?;

        // If middleware returned a response, use it
        let response = if let Some(middleware_resp) = middleware_response {
            middleware_resp
        } else {
            // Route to handler
            match self.route_request(processed_request).await {
                Ok(resp) => resp,
                Err(e) => {
                    warn!("❌ Handler error: {}", e);
                    ZhtpResponse::error(
                        ZhtpStatus::InternalServerError,
                        format!("Handler error: {}", e),
                    )
                }
            }
        };

        debug!("📤 Sending ZHTP response: {:?}", response.status);

        // Serialize response
        let response_data = serialize_response(&response)
            .map_err(|e| anyhow::anyhow!("Failed to serialize ZHTP response: {}", e))?;

        // Send response over QUIC stream
        send.write_all(&response_data).await
            .map_err(|e| anyhow::anyhow!("Failed to write ZHTP response to QUIC stream: {}", e))?;

        send.finish()
            .map_err(|e| anyhow::anyhow!("Failed to finish QUIC stream: {}", e))?;

        info!("✅ ZHTP response sent successfully");
        Ok(())
    }

