    /// Handle authenticated ZHTP stream from control plane connection
    /// The session contains authentication context from UHP+Kyber handshake
    pub async fn handle_authenticated_zhtp_stream(
        &self,
        buffered: &mut crate::server::quic_handler::BufferedStream,
        mut send: SendStream,
        session: &crate::server::quic_handler::ControlPlaneSession,
    ) -> Result<()> {
        debug!("📨 Processing authenticated ZHTP request from {}", session.peer_did);

        // Read request data from buffered stream
        let request_data = buffered.read_to_end(super::serialization::MAX_MESSAGE_SIZE)
            .await
            .map_err(|e| anyhow::anyhow!("Failed to read ZHTP request from buffered stream: {}", e))?;

        if request_data.is_empty() {
            warn!("⚠️ Empty ZHTP request received from authenticated session");
            return Ok(());
        }

        debug!("📦 Received {} bytes of authenticated ZHTP request data", request_data.len());

        // Deserialize ZHTP request
        let mut request = match deserialize_request(&request_data) {
            Ok(req) => req,
            Err(e) => {
                warn!("❌ Failed to deserialize ZHTP request from {}: {}", session.peer_did, e);
                let error_response = ZhtpResponse::error(
                    ZhtpStatus::BadRequest,
                    format!("Invalid ZHTP request: {}", e),
                );
                let response_data = serialize_response(&error_response)?;
                send.write_all(&response_data).await
                    .map_err(|e| anyhow::anyhow!("Write error: {}", e))?;
                send.finish()
                    .map_err(|e| anyhow::anyhow!("Finish error: {}", e))?;
                return Ok(());
            }
        };

        // Add authenticated requester identity to request context
        // IdentityId is a Hash of the DID
        request.requester = Some(lib_crypto::Hash(lib_crypto::hash_blake3(session.peer_did.as_bytes())));

        info!("✅ Authenticated ZHTP {} {} from {}", request.method, request.uri, session.peer_did);

        // Process middleware
        let (processed_request, middleware_response) = self.process_middleware(request).await?;

        // If middleware returned a response, use it
        let response = if let Some(middleware_resp) = middleware_response {
            middleware_resp
        } else {
            // Route to handler
            match self.route_request(processed_request).await {
                Ok(resp) => resp,
                Err(e) => {
                    warn!("❌ Handler error for authenticated request: {}", e);
                    ZhtpResponse::error(
                        ZhtpStatus::InternalServerError,
                        format!("Handler error: {}", e),
                    )
                }
            }
        };

        debug!("📤 Sending authenticated ZHTP response: {:?}", response.status);

        // Serialize response
        let response_data = serialize_response(&response)
            .map_err(|e| anyhow::anyhow!("Failed to serialize ZHTP response: {}", e))?;

        // Send response over QUIC stream
        send.write_all(&response_data).await
            .map_err(|e| anyhow::anyhow!("Failed to write ZHTP response to QUIC stream: {}", e))?;

        send.finish()
            .map_err(|e| anyhow::anyhow!("Failed to finish QUIC stream: {}", e))?;

        info!("✅ Authenticated ZHTP response sent to {}", session.peer_did);
        Ok(())
    }

    /// Route a ZHTP request to the appropriate handler
    pub async fn route_request(&self, request: ZhtpRequest) -> Result<ZhtpResponse> {
        let path = &request.uri;

        // Try exact match first
        if let Some(handler) = self.routes.get(path) {
            debug!("🎯 Exact route match: {}", path);
            return handler.handle_request(request).await;
        }

        // Try prefix matching for API routes - LONGEST PREFIX FIRST
        // This ensures /api/v1/blockchain/sync matches before /api/v1/blockchain
        let mut matching_routes: Vec<(&String, &Arc<dyn ZhtpRequestHandler>)> = self.routes
            .iter()
            .filter(|(route_path, _)| path.starts_with(route_path.as_str()))
            .collect();

        // Sort by route path length descending (longest first)
        matching_routes.sort_by(|a, b| b.0.len().cmp(&a.0.len()));

        if let Some((route_path, handler)) = matching_routes.first() {
            debug!("🎯 Prefix route match: {} → {}", path, route_path);
            return handler.handle_request(request).await;
        }

        // No handler found
        warn!("❓ No handler found for path: {}", path);
        Ok(ZhtpResponse::error(
            ZhtpStatus::NotFound,
            format!("No handler registered for path: {}", path),
        ))
    }

    /// Process middleware chain
    async fn process_middleware(
        &self,
        mut request: ZhtpRequest,
    ) -> Result<(ZhtpRequest, Option<ZhtpResponse>)> {
        let mut response: Option<ZhtpResponse> = None;

        for middleware in &self.middleware {
            match middleware.process(&mut request, &mut response).await {
                Ok(true) => continue, // Continue to next middleware
                Ok(false) => break,   // Middleware stopped processing
                Err(e) => {
                    warn!("⚠️ Middleware '{}' error: {}", middleware.name(), e);
                    response = Some(ZhtpResponse::error(
                        ZhtpStatus::InternalServerError,
                        format!("Middleware error: {}", e),
                    ));
                    break;
                }
            }
        }

        Ok((request, response))
    }

    /// Get list of registered routes
    pub fn get_routes(&self) -> Vec<String> {
        self.routes.keys().cloned().collect()
    }
}

impl Clone for ZhtpRouter {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            middleware: self.middleware.clone(),
        }
    }
}

pub fn serialize_request(request: &ZhtpRequest) -> Result<Vec<u8>> {
    // Serialize the request body
    let body = bincode::serialize(request)
        .context("Failed to serialize ZhtpRequest")?;

    if body.len() > MAX_MESSAGE_SIZE {
        return Err(anyhow::anyhow!("Request too large: {} bytes (max: {} bytes)", 
            body.len(), MAX_MESSAGE_SIZE));
    }

    // Build message with header
    let mut message = Vec::with_capacity(9 + body.len());

    // Magic bytes (4 bytes)
    message.extend_from_slice(ZHTP_MAGIC);

    // Version (1 byte)
    message.push(ZHTP_VERSION);

    // Message length (4 bytes, big-endian)
    message.extend_from_slice(&(body.len() as u32).to_be_bytes());

    // Request body
    message.extend_from_slice(&body);

    Ok(message)
}

pub fn deserialize_request(data: &[u8]) -> Result<ZhtpRequest> {
    // Validate minimum size
    if data.len() < 9 {
        return Err(anyhow::anyhow!("Message too short: {} bytes (min: 9)", data.len()));
    }

    // Validate magic bytes
    if &data[0..4] != ZHTP_MAGIC {
        return Err(anyhow::anyhow!("Invalid ZHTP magic bytes"));
    }

    // Validate version
    let version = data[4];
    if version != ZHTP_VERSION {
        return Err(anyhow::anyhow!("Unsupported ZHTP version: {}", version));
    }

    // Parse message length
    let length = u32::from_be_bytes([data[5], data[6], data[7], data[8]]) as usize;

    // Validate length
    if length > MAX_MESSAGE_SIZE {
        return Err(anyhow::anyhow!("Message too large: {} bytes (max: {})", 
            length, MAX_MESSAGE_SIZE));
    }

    if data.len() < 9 + length {
        return Err(anyhow::anyhow!("Incomplete message: expected {} bytes, got {}", 
            9 + length, data.len()));
    }

    // Deserialize request
    let request: ZhtpRequest = bincode::deserialize(&data[9..9 + length])
        .context("Failed to deserialize ZhtpRequest")?;

    Ok(request)
}

pub fn serialize_response(response: &ZhtpResponse) -> Result<Vec<u8>> {
    // Serialize the response body
    let body = bincode::serialize(response)
        .context("Failed to serialize ZhtpResponse")?;

    if body.len() > MAX_MESSAGE_SIZE {
        return Err(anyhow::anyhow!("Response too large: {} bytes (max: {} bytes)", 
            body.len(), MAX_MESSAGE_SIZE));
    }

    // Build message with header
    let mut message = Vec::with_capacity(9 + body.len());

    // Magic bytes (4 bytes)
    message.extend_from_slice(ZHTP_MAGIC);

    // Version (1 byte)
    message.push(ZHTP_VERSION);

    // Message length (4 bytes, big-endian)
    message.extend_from_slice(&(body.len() as u32).to_be_bytes());

    // Response body
    message.extend_from_slice(&body);

    Ok(message)
}

pub fn deserialize_response(data: &[u8]) -> Result<ZhtpResponse> {
    // Validate minimum size
    if data.len() < 9 {
        return Err(anyhow::anyhow!("Message too short: {} bytes (min: 9)", data.len()));
    }

    // Validate magic bytes
    if &data[0..4] != ZHTP_MAGIC {
        return Err(anyhow::anyhow!("Invalid ZHTP magic bytes"));
    }

    // Validate version
    let version = data[4];
    if version != ZHTP_VERSION {
        return Err(anyhow::anyhow!("Unsupported ZHTP version: {}", version));
    }

    // Parse message length
    let length = u32::from_be_bytes([data[5], data[6], data[7], data[8]]) as usize;

    // Validate length
    if length > MAX_MESSAGE_SIZE {
        return Err(anyhow::anyhow!("Message too large: {} bytes (max: {})", 
            length, MAX_MESSAGE_SIZE));
    }

    if data.len() < 9 + length {
        return Err(anyhow::anyhow!("Incomplete message: expected {} bytes, got {}", 
            9 + length, data.len()));
    }

    // Deserialize response
    let response: ZhtpResponse = bincode::deserialize(&data[9..9 + length])
        .context("Failed to deserialize ZhtpResponse")?;

    Ok(response)
}

pub struct BluetoothClassicRouter {
    connected_devices: Arc<RwLock<HashMap<String, String>>>,
    active_streams: Arc<RwLock<HashMap<String, Arc<tokio::sync::Mutex<lib_network::protocols::bluetooth::classic::RfcommStream>>>>>, // Store RFCOMM streams
    node_id: [u8; 32],
    protocol: Arc<RwLock<Option<lib_network::protocols::bluetooth::classic::BluetoothClassicProtocol>>>,
}

impl BluetoothClassicRouter {
    pub fn new() -> Self {
        let node_id = {
            let mut id = [0u8; 32];
            let uuid = Uuid::new_v4();
            let uuid_bytes = uuid.as_bytes();
            id[..16].copy_from_slice(uuid_bytes);
            id[16..].copy_from_slice(uuid_bytes);
            id
        };

        Self {
            connected_devices: Arc::new(RwLock::new(HashMap::new())),
            active_streams: Arc::new(RwLock::new(HashMap::new())),
            node_id,
            protocol: Arc::new(RwLock::new(None)),
        }
    }

    /// Initialize Bluetooth Classic RFCOMM protocol for high-throughput mesh
    pub async fn initialize(&self) -> Result<()> {
        info!("📻 Initializing Bluetooth Classic RFCOMM protocol for high-throughput mesh...");

        // Check if Windows Bluetooth feature is enabled on Windows
        #[cfg(all(target_os = "windows", not(feature = "windows-bluetooth")))]
        {
            warn!("⚠️  Windows: Bluetooth Classic requires --features windows-bluetooth");
            warn!("   Current build will NOT support RFCOMM discovery or connections");
            warn!("   Rebuild with: cargo build --features windows-bluetooth");
            warn!("   Skipping Bluetooth Classic initialization");
            return Err(anyhow::anyhow!("Windows Bluetooth feature not enabled"));
        }

        #[cfg(any(not(target_os = "windows"), feature = "windows-bluetooth"))]
        {
            use lib_network::protocols::bluetooth::classic::BluetoothClassicProtocol;
            use lib_crypto::PublicKey;

            // Create Bluetooth Classic protocol instance
            let bluetooth_classic = BluetoothClassicProtocol::new(self.node_id)?;

            // Initialize ZHTP authentication with blockchain public key
            info!("🔐 Initializing ZHTP authentication for Bluetooth Classic...");
            let blockchain_pubkey = PublicKey::new(self.node_id.to_vec());
            if let Err(e) = bluetooth_classic.initialize_zhtp_auth(blockchain_pubkey).await {
                warn!("⚠️  Bluetooth Classic auth initialization failed: {}", e);
                warn!("Continuing without authentication - connections may be insecure");
            } else {
                info!("✅ Bluetooth Classic ZHTP authentication initialized");
            }

            // Initialize RFCOMM advertising
            if let Err(e) = bluetooth_classic.start_advertising().await {
                warn!("Bluetooth Classic advertising failed to start: {}", e);
                return Err(anyhow::anyhow!("Bluetooth Classic advertising initialization failed: {}", e));
            }

            // Store the protocol instance
            *self.protocol.write().await = Some(bluetooth_classic);

            info!("✅ Bluetooth Classic RFCOMM initialized - discoverable as 'ZHTP-CLASSIC-{}'", 
                  hex::encode(&self.node_id[..4]));
            info!("📡 High-throughput mesh (375 KB/s) available via Bluetooth Classic");

            Ok(())
        }
    }

    /// Handle incoming Bluetooth Classic RFCOMM connection
    /// Uses same authentication flow as BLE but over RFCOMM transport
    ///
    /// # Security (HIGH-4 Fix)
    ///
    /// Rate limiting enforced before processing Bluetooth connections
    pub async fn handle_rfcomm_connection(
        &self,
        mut stream: TcpStream, // TODO: Replace with RfcommStream when implemented
        addr: SocketAddr,
        mesh_router: &MeshRouter,
    ) -> Result<()> {
        info!("📻 Processing Bluetooth Classic RFCOMM connection from: {}", addr);

        // HIGH-4 FIX: Check rate limit BEFORE processing handshake
        if let Err(block_duration) = mesh_router.connection_rate_limiter.check_ip(addr.ip()).await {
            warn!("🚫 Bluetooth connection rejected: IP {} rate limited for {:?}", addr.ip(), block_duration);
            return Ok(());
        }

        let mut buffer = vec![0; 8192];
        let bytes_read = stream.read(&mut buffer).await
            .context("Failed to read RFCOMM data")?;

        if bytes_read > 0 {
            debug!("RFCOMM data received: {} bytes", bytes_read);

            // Try to parse as binary mesh handshake (IDENTICAL to BLE!)
            if let Ok(handshake) = bincode::deserialize::<lib_network::discovery::local_network::MeshHandshake>(&buffer[..bytes_read]) {
                info!("🤝 Received RFCOMM mesh handshake from peer: {}", handshake.node_id);
                info!("   Version: {}, Port: {}, Protocols: {:?}", 
                    handshake.version, handshake.mesh_port, handshake.protocols);

                // Create peer identity
                let peer_pubkey = lib_crypto::PublicKey::new(handshake.node_id.as_bytes().to_vec());

                // Use BluetoothClassic protocol type
                let protocol = lib_network::protocols::NetworkProtocol::BluetoothClassic;

                // Create mesh connection with higher bandwidth (Ticket #146: Use UnifiedPeerId)
                let unified_peer = lib_network::identity::unified_peer::UnifiedPeerId::from_public_key_legacy(peer_pubkey.clone());
                let connection = lib_network::mesh::connection::MeshConnection {
                    peer: unified_peer,
                    protocol,
                    peer_address: Some(addr.to_string()),
                    signal_strength: 0.8, // Classic typically better than BLE
                    bandwidth_capacity: 375_000, // 375 KB/s - Bluetooth Classic EDR
                    latency_ms: 50, // Lower latency than BLE
                    connected_at: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_secs(),
                    data_transferred: 0,
                    tokens_earned: 0,
                    stability_score: 0.85,
                    zhtp_authenticated: false,
                    quantum_secure: false,
                    peer_dilithium_pubkey: None,
                    kyber_shared_secret: None,
                    trust_score: 0.5,
                    bootstrap_mode: false,
                };

                // Add to mesh connections (Ticket #146: Use UnifiedPeerId as key)
                {
                    let mut connections = mesh_router.connections.write().await;
                    let peer_key = connection.peer.clone();
                    // Ticket #149: Use peer_registry upsert instead of connections.insert
                    // connections is already a write guard, use it directly
                    let peer_entry = lib_network::peer_registry::PeerEntry::new(
                        peer_key,
                        vec![lib_network::peer_registry::PeerEndpoint {
                            address: String::new(), // TODO: Add actual address
                            protocol: connection.protocol.clone(),
                            signal_strength: 0.8,
                            latency_ms: 50,
                        }],
                        vec![connection.protocol.clone()],
                        lib_network::peer_registry::ConnectionMetrics {
                            signal_strength: 0.8,
                            bandwidth_capacity: 1_000_000,
                            latency_ms: 50,
                            stability_score: 0.9,
                            connected_at: std::time::SystemTime::now()
                                .duration_since(std::time::UNIX_EPOCH)
                                .unwrap_or_default()
                                .as_secs(),
                        },
                        true,
                        true,
                        None,
                        1,
                        0.8,
                        lib_network::peer_registry::NodeCapabilities {
                            protocols: vec![connection.protocol.clone()],
                            max_bandwidth: 1_000_000,
                            available_bandwidth: 800_000,
                            routing_capacity: 100,
                            energy_level: None,
                            availability_percent: 95.0,
                        },
                        None,
                        0.9,
                        None,
                        lib_network::peer_registry::DiscoveryMethod::MeshScan,
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        lib_network::peer_registry::PeerTier::Tier3,
                        0.8,
                    );
                    connections.upsert(peer_entry).await.expect("Failed to upsert peer");
                    // No need to drop(connections) as it will be dropped automatically

                    info!("✅ Bluetooth Classic peer {} added to mesh network ({} total peers)",
                        handshake.node_id, connections.all_peers().count());
                }

                // Run SAME authentication flow as BLE (transport-agnostic!)
                info!("🔐 Starting automatic authentication over RFCOMM");
                let _ = mesh_router.authenticate_and_register_peer(&peer_pubkey, &handshake, &addr, &mut stream).await;

                // Send acknowledgment
                let ack = bincode::serialize(&true)?;
                let _ = stream.write_all(&ack).await;

                info!("✅ Bluetooth Classic peer fully integrated - high-throughput mesh active!");

            } else {
                warn!("Failed to parse RFCOMM handshake");
            }
        }

        Ok(())
    }

    /// Get Bluetooth Classic service name
    pub fn get_service_name(&self) -> String {
        format!("ZHTP-CLASSIC-{}", hex::encode(&self.node_id[..4]))
    }

    /// Check if Bluetooth Classic is advertising
    pub async fn is_advertising(&self) -> bool {
        let protocol_guard: tokio::sync::RwLockReadGuard<Option<ClassicProtocol>> = self.protocol.read().await;
        protocol_guard.is_some()
    }

    /// Discover and connect to Bluetooth Classic peers
    /// Actively discovers paired devices, queries RFCOMM services, and connects to ZHTP nodes
    pub async fn discover_and_connect_peers(&self, mesh_router: &MeshRouter) -> Result<usize> {
        info!("🔍 Starting Bluetooth Classic peer discovery...");

        let protocol_guard: tokio::sync::RwLockReadGuard<Option<ClassicProtocol>> = self.protocol.read().await;
        let protocol: &ClassicProtocol = match protocol_guard.as_ref() {
            Some(p) => p,
            None => {
                warn!("Bluetooth Classic protocol not initialized");
                return Ok(0);
            }
        };

        // Step 1: Discover paired devices
        let devices: Vec<lib_network::protocols::bluetooth::classic::BluetoothDevice> = match protocol.discover_paired_devices().await {
            Ok(devs) => {
                info!("✅ Discovered {} paired Bluetooth devices", devs.len());
                devs
            }
            Err(e) => {
                warn!("Failed to discover Bluetooth devices: {}", e);
                return Ok(0);
            }
        };

        let mut connected_count = 0;

        // Step 2: Query each device for RFCOMM services and connect
        for device in devices {
            info!("🔍 Checking device: {} ({})", 
                device.name.as_deref().unwrap_or("Unknown"),
                device.address
            );

            // Only connect to paired and available devices
            if !device.is_paired {
                continue;
            }

            // Query RFCOMM services on this device
            let services = match protocol.query_rfcomm_services(&device.address).await {
                Ok(svcs) => svcs,
                Err(e) => {
                    debug!("Failed to query services on {}: {}", device.address, e);
                    continue;
                }
            };

            // Look for ZHTP services
            for service in services {
                if service.service_name.contains("ZHTP") || 
                   service.service_uuid.contains("6ba7b810") {
                    info!("✨ Found ZHTP service on {} (channel {})", 
                        device.address, service.channel);

                    // Attempt to connect
                    match protocol.connect_to_peer(&device.address, service.channel).await {
                        Ok(stream) => {
                            info!("✅ Connected to {} via Bluetooth Classic RFCOMM!", device.address);
                            connected_count += 1;

                            // Create mesh connection entry (Ticket #146: Use UnifiedPeerId)
                            let peer_pubkey = lib_crypto::PublicKey::new(device.address.as_bytes().to_vec());
                            let unified_peer = lib_network::identity::unified_peer::UnifiedPeerId::from_public_key_legacy(peer_pubkey.clone());
                            let connection = lib_network::mesh::connection::MeshConnection {
                                peer: unified_peer,
                                protocol: lib_network::protocols::NetworkProtocol::BluetoothClassic,
                                peer_address: Some(device.address.clone()),
                                signal_strength: device.rssi.map(|r| (r + 127) as f64 / 127.0).unwrap_or(0.7),
                                bandwidth_capacity: 375_000, // 375 KB/s
                                latency_ms: 50,
                                connected_at: std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                data_transferred: 0,
                                tokens_earned: 0,
                                stability_score: 0.8,
                                zhtp_authenticated: false,
                                quantum_secure: false,
                                peer_dilithium_pubkey: None,
                                kyber_shared_secret: None,
                                trust_score: 0.5,
                                bootstrap_mode: false,
                            };

                            // Add to mesh network (Ticket #146: Use UnifiedPeerId as key)
                            // Ticket #149: Use PeerRegistry upsert instead of connections.insert
                            let mut registry = mesh_router.connections.write().await;
                            let peer_entry = lib_network::peer_registry::PeerEntry::new(
                                connection.peer.clone(),
                                vec![lib_network::peer_registry::PeerEndpoint {
                                    address: device.address.clone(),
                                    protocol: connection.protocol.clone(),
                                    signal_strength: 0.8,
                                    latency_ms: 50,
                                }],
                                vec![connection.protocol.clone()],
                                lib_network::peer_registry::ConnectionMetrics {
                                    signal_strength: 0.8,
                                    bandwidth_capacity: 1_000_000,
                                    latency_ms: 50,
                                    stability_score: 0.9,
                                    connected_at: std::time::SystemTime::now()
                                        .duration_since(std::time::UNIX_EPOCH)
                                        .unwrap_or_default()
                                        .as_secs(),
                                },
                                true,
                                true,
                                None,
                                1,
                                0.8,
                                lib_network::peer_registry::NodeCapabilities {
                                    protocols: vec![connection.protocol.clone()],
                                    max_bandwidth: 1_000_000,
                                    available_bandwidth: 800_000,
                                    routing_capacity: 100,
                                    energy_level: None,
                                    availability_percent: 95.0,
                                },
                                None,
                                0.9,
                                None,
                                lib_network::peer_registry::DiscoveryMethod::MeshScan,
                                std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                lib_network::peer_registry::PeerTier::Tier3,
                                0.8,
                            );
                            registry.upsert(peer_entry).await.expect("Failed to upsert peer");

                            info!("✅ Added {} to mesh network", device.address);

                            // Store the stream for bidirectional communication
                            let stream_arc = Arc::new(tokio::sync::Mutex::new(stream));
                            self.active_streams.write().await.insert(
                                device.address.clone(),
                                stream_arc.clone()
                            );
                            self.connected_devices.write().await.insert(
                                device.address.clone(),
                                "bluetooth-classic-active".to_string()
                            );

                            info!("✅ Stream stored for bidirectional communication with {}", device.address);
                        }
                        Err(e) => {
                            debug!("Failed to connect to {}: {}", device.address, e);
                        }
                    }

                    // Only connect to first ZHTP service per device
                    break;
                }
            }
        }

        if connected_count > 0 {
            info!("🎊 Successfully connected to {} Bluetooth Classic peers", connected_count);
        } else {
            info!("No new Bluetooth Classic peers discovered");
        }

        Ok(connected_count)
    }

    /// Get connected devices via Bluetooth Classic
    pub async fn get_connected_devices(&self) -> HashMap<String, String> {
        self.connected_devices.read().await.clone()
    }

    /// Get a read guard for the Bluetooth Classic protocol
    pub async fn get_protocol(&self) -> tokio::sync::RwLockReadGuard<'_, Option<ClassicProtocol>> {
        self.protocol.read().await
    }
}

pub struct BluetoothRouter {
    connected_devices: Arc<RwLock<HashMap<String, String>>>,
    node_id: [u8; 32],
    protocol: Arc<RwLock<Option<Arc<BluetoothMeshProtocol>>>>,
}

impl BluetoothRouter {
    pub fn new() -> Self {
        let node_id = {
            let mut id = [0u8; 32];
            let uuid = Uuid::new_v4();
            let uuid_bytes = uuid.as_bytes();
            id[..16].copy_from_slice(uuid_bytes);
            id[16..].copy_from_slice(uuid_bytes); // Fill remaining with same UUID
            id
        };

        Self {
            connected_devices: Arc::new(RwLock::new(HashMap::new())),
            node_id,
            protocol: Arc::new(RwLock::new(None)),
        }
    }

    /// Initialize Bluetooth mesh protocol for phone connectivity
    // Ticket #146: Updated to use UnifiedPeerId as HashMap key
    pub async fn initialize(
        &self,
        peer_registry: Arc<RwLock<lib_network::peer_registry::PeerRegistry>>,
        peer_discovery_tx: Option<tokio::sync::mpsc::UnboundedSender<PublicKey>>,
        our_public_key: PublicKey,
        blockchain_provider: Option<Arc<dyn lib_network::blockchain_sync::BlockchainProvider>>,
        sync_coordinator: Arc<lib_network::blockchain_sync::SyncCoordinator>,
        mesh_router: Arc<MeshRouter>,
    ) -> Result<()> {
        info!("📱 Initializing Bluetooth mesh protocol for phone connectivity...");

        // Create Bluetooth mesh protocol instance
        let mut bluetooth_protocol = BluetoothMeshProtocol::new(self.node_id, our_public_key)?;

        // ========================================================================
        // Phase 6: Enable BLE edge node sync if blockchain provider is available
        // ========================================================================
        if let Some(provider) = blockchain_provider {
            bluetooth_protocol.set_blockchain_provider(provider).await;
            info!("✅ BLE edge sync enabled - will serve headers/proofs to mobile devices");
        }

        // Create GATT message channel for forwarding GATT writes to this router
        let (gatt_tx, mut gatt_rx) = tokio::sync::mpsc::unbounded_channel();
        bluetooth_protocol.set_gatt_message_channel(gatt_tx).await;
        info!("✅ GATT message channel connected to BluetoothRouter");

        // Initialize Bluetooth advertising for ZHTP service
        // Note: Windows COM threading handled within the Bluetooth implementation
        if let Err(e) = bluetooth_protocol.start_advertising().await {
            warn!("⚠️  Bluetooth advertising failed to start: {}", e);
            // Don't fail the entire initialization if Bluetooth fails
            warn!("Continuing without Bluetooth advertising support");
        } else {
            info!("✅ Bluetooth advertising started successfully");
        }

        // Store the protocol instance (wrapped in Arc for sharing)
        let protocol_arc = Arc::new(bluetooth_protocol);
        *self.protocol.write().await = Some(protocol_arc.clone());

        // Spawn GATT message handler task with mesh_connections access
        let connected_devices = self.connected_devices.clone();
        let mesh_conns = peer_registry.clone();
        let ble_peer_notify = peer_discovery_tx.clone();
        let sync_coordinator_for_gatt = sync_coordinator.clone();
        let mesh_router_for_gatt = mesh_router.clone();
        let bluetooth_protocol_for_gatt = protocol_arc.clone(); // Clone protocol for GATT handler
        tokio::spawn(async move {
            while let Some(gatt_message) = gatt_rx.recv().await {
                use lib_network::protocols::bluetooth::gatt::GattMessage;
                match gatt_message {
                    GattMessage::MeshHandshake { data, peripheral_id } => {
                        info!("📨 GATT: Received mesh message ({} bytes)", data.len());
                        if let Some(ref pid) = peripheral_id {
                            info!("   🆔 Peripheral ID: {}", pid);
                        }

                        // Try to parse as MeshHandshake first (initial connection)
                        if let Ok(handshake) = bincode::deserialize::<lib_network::discovery::local_network::MeshHandshake>(&data) {
                            info!("🤝 GATT handshake from: {}", handshake.node_id);

                            // Extract the real cryptographic public key from handshake
                            let peer_pubkey = handshake.public_key.clone();

                            // FIX: Use peripheral_id for macOS, node_id for other platforms
                            let gatt_address = if let Some(ref pid) = peripheral_id {
                                format!("gatt://{}", pid)  // macOS: Use CBPeripheral UUID
                            } else {
                                format!("gatt://{}", handshake.node_id)  // Windows/Linux: Use node_id
                            };
                            info!("   📍 GATT address: {}", gatt_address);

                            // Create mesh connection for GATT peer (Ticket #146: Use UnifiedPeerId)
                            let unified_peer = lib_network::identity::unified_peer::UnifiedPeerId::from_public_key_legacy(peer_pubkey.clone());
                            let connection = lib_network::mesh::connection::MeshConnection {
                                peer: unified_peer,
                                protocol: lib_network::protocols::NetworkProtocol::BluetoothLE,
                                peer_address: Some(gatt_address.clone()),
                                signal_strength: 0.7,
                                bandwidth_capacity: 250_000, // 250 KB/s BLE
                                latency_ms: 100,
                                connected_at: std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                data_transferred: 0,
                                tokens_earned: 0,
                                stability_score: 0.8,
                                zhtp_authenticated: false, // Will authenticate later
                                quantum_secure: false,
                                peer_dilithium_pubkey: None,
                                kyber_shared_secret: None,
                                trust_score: 0.5,
                                bootstrap_mode: false,
                            };

                            // Add to mesh network (Ticket #146: Use UnifiedPeerId as key)
                            let peer_key = connection.peer.clone();
                            // Ticket #149: Use PeerRegistry API instead of HashMap methods
                            let registry_read = mesh_conns.read().await;
                            let is_new_peer = registry_read.get(&peer_key).is_none();
                            drop(registry_read);

                            // Create PeerEntry and upsert into registry
                            let mut registry_write = mesh_conns.write().await;
                            let peer_entry = lib_network::peer_registry::PeerEntry::new(
                                peer_key,
                                vec![lib_network::peer_registry::PeerEndpoint {
                                    address: gatt_address.clone(),
                                    protocol: connection.protocol.clone(),
                                    signal_strength: 0.8,
                                    latency_ms: 50,
                                }],
                                vec![connection.protocol.clone()],
                                lib_network::peer_registry::ConnectionMetrics {
                                    signal_strength: 0.8,
                                    bandwidth_capacity: 1_000_000,
                                    latency_ms: 50,
                                    stability_score: 0.9,
                                    connected_at: std::time::SystemTime::now()
                                        .duration_since(std::time::UNIX_EPOCH)
                                        .unwrap_or_default()
                                        .as_secs(),
                                },
                                true,
                                true,
                                None,
                                1,
                                0.8,
                                lib_network::peer_registry::NodeCapabilities {
                                    protocols: vec![connection.protocol.clone()],
                                    max_bandwidth: 1_000_000,
                                    available_bandwidth: 800_000,
                                    routing_capacity: 100,
                                    energy_level: None,
                                    availability_percent: 95.0,
                                },
                                None,
                                0.9,
                                None,
                                lib_network::peer_registry::DiscoveryMethod::MeshScan,
                                std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                lib_network::peer_registry::PeerTier::Tier3,
                                0.8,
                            );
                            registry_write.upsert(peer_entry).await.expect("Failed to upsert peer");
                            info!("   ✅ Added GATT peer {} to mesh network", handshake.node_id);

                            // FIX: Also register with BluetoothMeshProtocol.current_connections
                            // This is required for send_mesh_message() to find the peer
                            let ble_connection = lib_network::protocols::bluetooth::BluetoothConnection {
                                peer_id: handshake.node_id.to_string(),
                                address: gatt_address.clone(),
                                mtu: 247,  // Default BLE MTU
                                rssi: -50, // Placeholder RSSI
                                connected_at: std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                                last_seen: std::time::SystemTime::now()
                                    .duration_since(std::time::UNIX_EPOCH)
                                    .unwrap_or_default()
                                    .as_secs(),
                            };
                            bluetooth_protocol_for_gatt.current_connections.write().await.insert(gatt_address.clone(), ble_connection);
                            info!("   ✅ Registered GATT peer in bluetooth_protocol.current_connections: {}", gatt_address);

                            // Register peer in DHT Kademlia routing table
                            // Generate node_id from public key hash (Blake3)
                            let node_id: [u8; 32] = lib_crypto::hash_blake3(&peer_pubkey.key_id);
                            // Note: KademliaNode registration removed (type no longer available)
                            // TODO: Use ZkDHTIntegration::register_peer() instead
                            info!("   📝 Would register BLE peer in Kademlia routing table: node_id={}", hex::encode(&node_id[0..8]));

                            // Track connected device
                            let device_key = handshake.node_id.to_string();
                            let device_info = format!("Bluetooth GATT (protocols: {:?})", handshake.protocols);
                            connected_devices.write().await.insert(device_key, device_info);

                            // Always trigger blockchain sync for BLE handshake completion
                            // The sync coordinator will detect and prevent duplicates if peer is also connected via UDP
                            info!("🔄 BLE handshake complete - notifying for blockchain sync (is_new_peer: {})", is_new_peer);
                            if let Some(notify_tx) = &ble_peer_notify {
                                if let Err(e) = notify_tx.send(peer_pubkey.clone()) {
                                    warn!("Failed to send BLE peer notification: {}", e);
                                } else {
                                    info!("📤 BLE peer notification sent for {}", handshake.node_id);
                                }
                            }
                        }
                        // If not MeshHandshake, try to parse as ZhtpMeshMessage (edge sync requests)
                        else if let Ok(mesh_message) = bincode::deserialize::<ZhtpMeshMessage>(&data) {
                            info!("📨 GATT: Received ZhtpMeshMessage");

                            // Handle HeadersRequest/BlockchainRequest messages
                            match &mesh_message {
                                ZhtpMeshMessage::HeadersRequest { requester, request_id, start_height, count } => {
                                    info!("📥 GATT HeadersRequest from peer (ID: {}, height: {}, count: {})", 
                                          request_id, start_height, count);

                                    // Get blockchain provider and fetch headers
                                    if let Some(provider) = mesh_router_for_gatt.get_blockchain_provider().await {
                                        match provider.get_headers(*start_height, *count as u64).await {
                                            Ok(headers) => {
                                                info!("📤 GATT: Sending {} headers back to requester", headers.len());

                                                // Serialize headers to Vec<Vec<u8>>
                                                let serialized_headers: Vec<Vec<u8>> = headers.iter()
                                                    .filter_map(|h| bincode::serialize(h).ok())
                                                    .collect();

                                                // Create HeadersResponse message
                                                let response = ZhtpMeshMessage::HeadersResponse {
                                                    request_id: *request_id,
                                                    headers: serialized_headers,
                                                    start_height: *start_height,
                                                };

                                                // Send response back via BLE
                                                if let Err(e) = mesh_router_for_gatt.send_to_peer(requester, response).await {
                                                    warn!("Failed to send HeadersResponse via GATT: {}", e);
                                                } else {
                                                    info!("✅ GATT: HeadersResponse sent successfully");
                                                }
                                            }
                                            Err(e) => {
                                                warn!("Failed to get headers from blockchain: {}", e);
                                            }
                                        }
                                    } else {
                                        warn!("No blockchain provider available to handle HeadersRequest");
                                    }
                                }
                                ZhtpMeshMessage::BlockchainRequest {  request_id, .. } => {
                                    info!("📥 GATT BlockchainRequest from peer (ID: {})", request_id);
                                    // TODO: Handle full blockchain request
                                    warn!("Full blockchain requests via GATT not yet implemented");
                                }
                                ZhtpMeshMessage::HeadersResponse { request_id, headers, start_height } => {
                                    info!("✅ GATT: Received HeadersResponse (ID: {}, {} headers, starting at height {})", 
                                          request_id, headers.len(), start_height);

                                    // Find peer by request_id and mark sync complete
                                    if let Some((peer_id, sync_type)) = sync_coordinator_for_gatt.find_peer_by_sync_id(*request_id).await {
                                        sync_coordinator_for_gatt.complete_sync(&peer_id, *request_id, sync_type).await;
                                        info!("   ✅ Marked edge sync complete for peer {}", hex::encode(&peer_id.key_id[..8]));
                                    } else {
                                        warn!("   ⚠️  No active sync found for request_id {}", request_id);
                                    }
                                }
                                _ => {
                                    debug!("GATT: Unhandled ZhtpMeshMessage variant");
                                }
                            }
                        }
                        else {
                            warn!("⚠️  GATT: Failed to deserialize message as MeshHandshake or ZhtpMeshMessage");
                        }
                    }
                    GattMessage::DhtBridge(text) => {
                        info!("🌉 GATT: DHT bridge message: {}", text);
                        // DHT forwarding handled by bridge_bluetooth_to_dht in MeshRouter
                    }
                    GattMessage::RawData(uuid, data) => {
                        info!("📦 GATT: Raw data on {}: {} bytes", uuid, data.len());
                        // Process based on characteristic UUID
                    }
                    GattMessage::RelayQuery(data) => {
                        info!("🔄 GATT: Relay query ({} bytes)", data.len());
                        // Relay queries processed by MeshRouter relay protocol
                    }
                    GattMessage::HeadersRequest { request_id, start_height, count } => {
                        info!("📥 GATT: HeadersRequest received (ID: {}, height: {}, count: {})", 
                              request_id, start_height, count);
                        // Handle via BluetoothMeshProtocol's edge sync handler
                        // Response will be sent back via BLE automatically
                    }
                    GattMessage::BootstrapProofRequest { request_id, current_height } => {
                        info!("📥 GATT: BootstrapProofRequest received (ID: {}, current: {})", 
                              request_id, current_height);
                        // Handle via BluetoothMeshProtocol's edge sync handler
                    }
                    GattMessage::HeadersResponse { request_id, headers } => {
                        info!("✅ GATT: HeadersResponse received (ID: {}, {} headers)", 
                              request_id, headers.len());
                        // Edge node received headers - sync complete

                        // Find peer by request_id and mark sync complete
                        if let Some((peer_id, sync_type)) = sync_coordinator_for_gatt.find_peer_by_sync_id(request_id).await {
                            sync_coordinator_for_gatt.complete_sync(&peer_id, request_id, sync_type).await;
                            info!("   ✅ Marked edge sync complete for peer {}", hex::encode(&peer_id.key_id[..8]));
                        } else {
                            warn!("   ⚠️  No active sync found for request_id {}", request_id);
                        }
                    }
                    GattMessage::BootstrapProofResponse { request_id, proof_height, headers, .. } => {
                        info!("✅ GATT: BootstrapProofResponse received (ID: {}, proof up to {}, {} headers)", 
                              request_id, proof_height, headers.len());
                        // Edge node received proof + headers - sync complete

                        // Find peer by request_id and mark sync complete
                        if let Some((peer_id, sync_type)) = sync_coordinator_for_gatt.find_peer_by_sync_id(request_id).await {
                            sync_coordinator_for_gatt.complete_sync(&peer_id, request_id, sync_type).await;
                            info!("   ✅ Marked edge sync complete for peer {}", hex::encode(&peer_id.key_id[..8]));
                        } else {
                            warn!("   ⚠️  No active sync found for request_id {}", request_id);
                        }
                    }
                    GattMessage::FragmentHeader { .. } => {
                        info!("🧩 GATT: Fragment header received (multi-part message)");
                        // Handled by fragment reassembler in BluetoothMeshProtocol
                    }
                    _ => {
                        info!("❓ GATT: Unknown message type");
                    }
                }
            }
            info!("GATT message handler stopped");
        });

        info!("✅ Bluetooth mesh protocol initialized - discoverable as 'ZHTP-{}'", 
              hex::encode(&self.node_id[..4]));
        info!("📱 Your phone can now discover and connect to this ZHTP node via Bluetooth");

        Ok(())
    }

    /// Get the bluetooth protocol instance for message routing
    pub async fn get_protocol(&self) -> Option<Arc<BluetoothMeshProtocol>> {
        (*self.protocol.read().await).clone()
    }

    /// Handle incoming Bluetooth connection with full mesh authentication
    pub async fn handle_bluetooth_connection(
        &self,
        mut stream: TcpStream,
        addr: SocketAddr,
        mesh_router: &MeshRouter,
    ) -> Result<()> {
        info!("📱 Processing Bluetooth mesh connection from: {}", addr);

        let mut buffer = vec![0; 8192];
        let bytes_read = stream.read(&mut buffer).await
            .context("Failed to read Bluetooth data")?;

        if bytes_read > 0 {
            debug!("Bluetooth data received: {} bytes", bytes_read);

            // Try to parse as binary mesh handshake (same as TCP!)
            if let Ok(handshake) = bincode::deserialize::<lib_network::discovery::local_network::MeshHandshake>(&buffer[..bytes_read]) {
                info!("🤝 Received Bluetooth mesh handshake from peer: {}", handshake.node_id);
                info!("   Version: {}, Port: {}, Protocols: {:?}", 
                    handshake.version, handshake.mesh_port, handshake.protocols);

                // Create peer identity
                let peer_pubkey = lib_crypto::PublicKey::new(handshake.node_id.as_bytes().to_vec());

                // Bluetooth connections use BluetoothLE protocol
                let protocol = lib_network::protocols::NetworkProtocol::BluetoothLE;

                // Create mesh connection (Ticket #146: Use UnifiedPeerId)
                let unified_peer = lib_network::identity::unified_peer::UnifiedPeerId::from_public_key_legacy(peer_pubkey.clone());
                let connection = lib_network::mesh::connection::MeshConnection {
                    peer: unified_peer,
                    protocol,
                    peer_address: Some(addr.to_string()), // Store Bluetooth peer address for relay queries
                    signal_strength: 0.7, // Bluetooth typically lower than WiFi
                    bandwidth_capacity: 250_000, // 250 KB/s - optimized BLE throughput (7.5ms interval + 1ms delay)
                    latency_ms: 100, // Bluetooth has higher latency
                    connected_at: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_secs(),
                    data_transferred: 0,
                    tokens_earned: 0,
                    stability_score: 0.8,
                    zhtp_authenticated: false, // Will be set after authentication
                    quantum_secure: false, // Will be set after Kyber exchange
                    peer_dilithium_pubkey: None,
                    kyber_shared_secret: None,
                    trust_score: 0.5,
                    bootstrap_mode: false,
                };

                // Add to mesh connections (Ticket #146: Use UnifiedPeerId as key)
                {
                    let mut connections = mesh_router.connections.write().await;
                    let peer_key = connection.peer.clone();
                    // Ticket #149: Use peer_registry upsert instead of connections.insert
                    // connections is already a write guard, use it directly
                    let peer_entry = lib_network::peer_registry::PeerEntry::new(
                        peer_key,
                        vec![lib_network::peer_registry::PeerEndpoint {
                            address: String::new(), // TODO: Add actual address
                            protocol: connection.protocol.clone(),
                            signal_strength: 0.8,
                            latency_ms: 50,
                        }],
                        vec![connection.protocol.clone()],
                        lib_network::peer_registry::ConnectionMetrics {
                            signal_strength: 0.8,
                            bandwidth_capacity: 1_000_000,
                            latency_ms: 50,
                            stability_score: 0.9,
                            connected_at: std::time::SystemTime::now()
                                .duration_since(std::time::UNIX_EPOCH)
                                .unwrap_or_default()
                                .as_secs(),
                        },
                        true,
                        true,
                        None,
                        1,
                        0.8,
                        lib_network::peer_registry::NodeCapabilities {
                            protocols: vec![connection.protocol.clone()],
                            max_bandwidth: 1_000_000,
                            available_bandwidth: 800_000,
                            routing_capacity: 100,
                            energy_level: None,
                            availability_percent: 95.0,
                        },
                        None,
                        0.9,
                        None,
                        lib_network::peer_registry::DiscoveryMethod::MeshScan,
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        lib_network::peer_registry::PeerTier::Tier3,
                        0.8,
                    );
                    connections.upsert(peer_entry).await.expect("Failed to upsert peer");
                    // No need to drop(connections) as it will be dropped automatically

                    info!("✅ Bluetooth peer {} added to mesh network ({} total peers)",
                        handshake.node_id, connections.all_peers().count());
                }

                // Run full authentication, key exchange, and DHT registration (same as TCP!)
                info!("🔐 Starting automatic authentication (no pairing code needed)");
                let _ = mesh_router.authenticate_and_register_peer(&peer_pubkey, &handshake, &addr, &mut stream).await;

                // Send acknowledgment
                let ack = bincode::serialize(&true)?;
                let _ = stream.write_all(&ack).await;

                info!("✅ Bluetooth peer fully integrated - zero-trust authentication complete!");

            } else {
                // Legacy text-based Bluetooth messages (DHT bridge)
                let message = String::from_utf8_lossy(&buffer[..bytes_read]);

                if message.starts_with("ZHTP-MESH:") || message.starts_with("DHT:") {
                    info!("🌉 Bridging Bluetooth ZHTP traffic to DHT network");

                    // ACTUALLY CALL THE BRIDGE FUNCTION
                    match mesh_router.bridge_bluetooth_to_dht(&buffer[..bytes_read], &addr).await {
                        Ok(()) => {
                            info!("✅ Bluetooth message successfully bridged to DHT");
                            let response = format!(
                                "ZHTP/1.0 200 OK\r\nX-Protocol: Bluetooth-DHT-Bridge\r\nX-Node-ID: {:?}\r\nX-Service: ZHTP-Mesh\r\nX-Bridge: Active\r\n\r\nBridged to DHT network",
                                &self.node_id[..8]
                            );
                            let _ = stream.write_all(response.as_bytes()).await;
                        }
                        Err(e) => {
                            warn!("Failed to bridge Bluetooth message to DHT: {}", e);
                            let response = format!(
                                "ZHTP/1.0 500 Internal Server Error\r\nX-Protocol: Bluetooth-DHT-Bridge\r\nX-Error: {}\r\n\r\nBridge failed",
                                e
                            );
                            let _ = stream.write_all(response.as_bytes()).await;
                        }
                    }
                } else {
                    // Unknown Bluetooth message - still acknowledge
                    info!("Bluetooth message received (not DHT): {} bytes", bytes_read);
                    let response = format!(
                        "ZHTP/1.0 200 OK\r\nX-Protocol: Bluetooth\r\nX-Node-ID: {:?}\r\nX-Service: ZHTP-Mesh\r\n\r\nBluetooth mesh node ready",
                        &self.node_id[..8]
                    );
                    let _ = stream.write_all(response.as_bytes()).await;
                }

                // Store legacy connection
                let mut devices = self.connected_devices.write().await;
                devices.insert(addr.to_string(), "bluetooth-legacy-bridge".to_string());
            }
        }

        Ok(())
    }

    /// Get the Bluetooth service name visible to phones
    pub fn get_service_name(&self) -> String {
        format!("ZHTP-{}", hex::encode(&self.node_id[..4]))
    }

    /// Check if Bluetooth is advertising and discoverable
    pub async fn is_advertising(&self) -> bool {
        if let Some(protocol) = self.protocol.read().await.as_ref() {
            protocol.is_advertising()
        } else {
            false
        }
    }

    /// Get connected phone devices
    pub async fn get_connected_phones(&self) -> HashMap<String, String> {
        self.connected_devices.read().await.clone()
    }
}

pub struct BootstrapRouter {
    server_id: Uuid,
}

impl BootstrapRouter {
    pub fn new(server_id: Uuid) -> Self {
        Self { server_id }
    }

    /// Handle TCP bootstrap connection
    pub async fn handle_tcp_bootstrap(&self, mut stream: TcpStream, addr: SocketAddr) -> Result<()> {
        info!("🚀 Processing TCP bootstrap connection from: {}", addr);

        let mut buffer = vec![0; 1024];
        let bytes_read = stream.read(&mut buffer).await
            .context("Failed to read bootstrap request")?;

        if bytes_read > 0 {
            debug!("Bootstrap request: {} bytes", bytes_read);

            // Send bootstrap response
            let response = format!("ZHTP Bootstrap Response\nServer ID: {}\n", self.server_id);
            let _ = stream.write_all(response.as_bytes()).await;
        }

        Ok(())
    }

    /// Handle UDP bootstrap discovery with capability announcement
    pub async fn handle_udp_bootstrap(
        &self, 
        data: &[u8], 
        addr: SocketAddr, 
        http_port: u16, 
        zhtp_port: u16, 
        socket: &UdpSocket
    ) -> Result<Vec<u8>> {
        info!("🚀 Processing UDP bootstrap packet from: {} ({} bytes)", addr, data.len());

        // Parse bootstrap request and send response
        let request_str = String::from_utf8_lossy(data);
        debug!("Bootstrap request content: {}", request_str);

        // Check if this is a bootstrap RESPONSE (not a request) - don't respond to responses!
        if request_str.contains("\"server_id\"") && request_str.contains("\"capabilities\"") {
            debug!("Received bootstrap response from {} - not responding to avoid loop", addr);
            return Ok(vec![]); // Return empty response to indicate no action needed
        }

        // Create bootstrap response with server capabilities
        let response_data = serde_json::json!({
            "server_id": self.server_id,
            "server_type": "zhtp_unified",
            "protocol_version": "ZHTP/1.0",
            "capabilities": [
                "blockchain_api",
                "storage_api", 
                "identity_api",
                "mesh_networking",
                "wifi_direct",
                "dht_operations"
            ],
            "endpoints": {
                "http": format!("http://localhost:{}", http_port),
                "zhtp": format!("zhtp://localhost:{}", zhtp_port),
                "websocket": format!("ws://localhost:{}/ws", http_port)
            },
            "network_info": {
                "node_type": "full_node",
                "uptime": SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs(),
                "peers_connected": 0
            },
            "timestamp": SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()
        });

        // Convert to bytes for UDP transmission
        let response_bytes = serde_json::to_vec(&response_data)
            .context("Failed to serialize bootstrap response")?;

        // Send the actual UDP response back to the client
        match socket.send_to(&response_bytes, addr).await {
            Ok(sent_bytes) => {
                info!("✅ Sent UDP bootstrap response to {} ({} bytes)", addr, sent_bytes);
                debug!("Bootstrap response: {}", response_data);
            }
            Err(e) => {
                error!("❌ Failed to send UDP bootstrap response to {}: {}", addr, e);
                return Err(anyhow::anyhow!("UDP send failed: {}", e));
            }
        }

        Ok(response_bytes)
    }
}

impl Clone for BootstrapRouter {
    fn clone(&self) -> Self {
        Self {
            server_id: self.server_id,
        }
    }
}

