impl PeerReputation {
    pub fn new(peer_id: String) -> Self {
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
        Self {
            peer_id,
            score: 50, // Start neutral
            blocks_accepted: 0,
