fn parse_did_to_identity_id(did_str: &str) -> Result<lib_crypto::Hash> {
    if did_str.starts_with("did:zhtp:") {
        let hex_part = did_str.strip_prefix("did:zhtp:").unwrap_or(did_str);
        match hex::decode(hex_part) {
            Ok(bytes) => {
                if bytes.len() == 32 {
                    let mut id_bytes = [0u8; 32];
                    id_bytes.copy_from_slice(&bytes);
                    Ok(lib_crypto::Hash::from_bytes(&id_bytes))
                } else {
                    Err(anyhow::anyhow!("Invalid DID format: incorrect length"))
                }
            },
            Err(_) => {
                Err(anyhow::anyhow!("Invalid DID format: not valid hex"))
            }
        }
    } else {
        Err(anyhow::anyhow!("Invalid DID format: must start with 'did:zhtp:'"))
    }
}

async fn create_standalone_wallet_direct(request_data: serde_json::Value) -> Result<serde_json::Value> {
    // Extract wallet parameters
    let wallet_name = request_data.get("wallet_name")
        .and_then(|v| v.as_str())
        .unwrap_or("New Wallet")
        .to_string();

    let node_name = request_data.get("node_name")
        .and_then(|v| v.as_str())
        .unwrap_or("API User")
        .to_string();

    let wallet_type_str = request_data.get("wallet_type")
        .and_then(|v| v.as_str())
        .unwrap_or("Standard");

    let wallet_alias = request_data.get("alias")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    info!("💳 Creating user identity with wallet: {} for node: {}", wallet_name, node_name);

    // Create user identity with wallet (P1-7: returns IDs only, not full identities)
    let (user_identity_id, wallet_id, seed_phrase) = lib_identity::create_user_identity_with_wallet(
        node_name.clone(),
        wallet_name.clone(),
        wallet_alias.clone()
    ).await?;

    info!("✅ User identity created: {}", hex::encode(&user_identity_id.0[..8]));

    // Create node device identity owned by the user (P1-7: returns ID only)
    info!("⚙️ Creating node device identity...");
    let node_device_name = format!("{}-device", node_name);
    let node_identity_id = lib_identity::create_node_device_identity(
        user_identity_id.clone(),
        wallet_id.clone(),
        node_device_name,
    ).await?;

    info!("✅ Created complete identity setup - User: {}, Node Device: {}, Wallet: {}",
        hex::encode(&user_identity_id.0[..8]),
        hex::encode(&node_identity_id.0[..8]),
        hex::encode(&wallet_id.0[..8]));

    // Record identity-wallet pair on blockchain
    record_standalone_wallet_on_blockchain(&user_identity_id, &wallet_id, &wallet_type_str, &wallet_name, &wallet_alias, &seed_phrase).await
        .unwrap_or_else(|e| warn!("Failed to record identity-wallet on blockchain: {}", e));

    // Distribute identity-wallet info to DHT
    distribute_standalone_wallet_to_dht(&user_identity_id, &wallet_id, &wallet_type_str, &wallet_name).await
        .unwrap_or_else(|e| warn!("Failed to distribute identity-wallet to DHT: {}", e));

    // Return wallet creation result with identity
    Ok(serde_json::json!({
        "success": true,
        "user_identity_id": user_identity_id,
        "node_identity_id": node_identity_id,
        "wallet_id": wallet_id,
        "wallet_type": wallet_type_str,
        "wallet_name": wallet_name,
        "node_name": node_name,
        "alias": wallet_alias,
        "seed_phrase": seed_phrase,
        "created_at": std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs(),
        "identity_linked": true,
        "blockchain_recorded": true,
        "dht_distributed": true
    }))
}

async fn record_identity_on_blockchain(identity_result: &serde_json::Value) -> Result<()> {
    info!("⛓️ Starting blockchain registration...");

    // Get global blockchain instance
    let blockchain = crate::runtime::blockchain_provider::get_global_blockchain().await?;
    let mut blockchain_guard = blockchain.write().await;

    // Extract identity data
    let identity_id_str = identity_result.get("identity_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("Missing identity_id string"))?;

    let identity_id_bytes = hex::decode(identity_id_str)?;
    let identity_hash = lib_crypto::Hash::from_bytes(&identity_id_bytes[..32]);
    let did = format!("did:zhtp:{}", identity_id_str);

    // Extract display name
    let display_name = identity_result.get("citizenship_result")
        .and_then(|cr| cr.get("display_name"))
        .and_then(|v| v.as_str())
        .unwrap_or("ZHTP Citizen")
        .to_string();

    // Extract public key and ownership proof
    let public_key = identity_result.get("citizenship_result")
        .and_then(|cr| cr.get("privacy_credentials"))
        .and_then(|pc| pc.get("public_key"))
        .and_then(|v| v.as_str())
        .and_then(|hex_str| hex::decode(hex_str).ok())
        .unwrap_or_else(|| vec![0u8; 32]);

    let ownership_proof = identity_result.get("citizenship_result")
        .and_then(|cr| cr.get("privacy_credentials"))
        .and_then(|pc| pc.get("ownership_proof"))
        .and_then(|v| v.as_str())
        .and_then(|hex_str| hex::decode(hex_str).ok())
        .unwrap_or_else(|| vec![0u8; 64]);

    let created_at = identity_result.get("citizenship_result")
        .and_then(|cr| cr.get("created_at"))
        .and_then(|v| v.as_u64())
        .unwrap_or_else(|| {
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs()
        });

    // Register identity
    let identity_data = lib_blockchain::IdentityTransactionData {
        did: did.clone(),
        display_name,
        public_key,
        ownership_proof,
        identity_type: "human".to_string(),
        did_document_hash: lib_blockchain::Hash::from_slice(&[0u8; 32]),
        created_at,
        registration_fee: 100,
        dao_fee: 50,
        controlled_nodes: Vec::new(),
        owned_wallets: Vec::new(),
    };

    let _identity_tx_hash = blockchain_guard.register_identity(identity_data)?;
    info!("✅ Registered identity {} on blockchain", identity_id_str);

    // Register all wallets
    if let Some(citizenship_result) = identity_result.get("citizenship_result") {
        register_wallet_on_blockchain(&mut blockchain_guard, citizenship_result, &identity_hash, "Primary", "primary_wallet_id", "primary_wallet_pubkey", "primary", created_at)?;
        register_wallet_on_blockchain(&mut blockchain_guard, citizenship_result, &identity_hash, "UBI", "ubi_wallet_id", "ubi_wallet_pubkey", "ubi", created_at)?;
        register_wallet_on_blockchain(&mut blockchain_guard, citizenship_result, &identity_hash, "Savings", "savings_wallet_id", "savings_wallet_pubkey", "savings", created_at)?;
    }

    info!("✅ Successfully recorded identity and wallets on blockchain");
    Ok(())
}

async fn distribute_identity_to_dht(identity_result: &serde_json::Value) -> Result<()> {
    info!("📡 Distributing identity to DHT network...");

    if let Ok(dht_client) = crate::runtime::shared_dht::get_dht_client().await {
        let mut dht = dht_client.write().await;

        let identity_id = identity_result.get("identity_id")
            .ok_or_else(|| anyhow::anyhow!("Missing identity_id"))?;

        let did = format!("did:zhtp:{}", identity_id);

        // Create DID document
        let did_document = serde_json::json!({
            "@context": "https://www.w3.org/ns/did/v1",
            "id": did,
            "verificationMethod": [{
                "id": format!("{}#key-1", did),
                "type": "Ed25519VerificationKey2020",
                "controller": did,
                "publicKeyMultibase": "z6Mkf5rGMoatrSj..."
            }],
            "service": [{
                "id": format!("{}#zhtp-endpoint", did),
                "type": "ZhtpEndpoint",
                "serviceEndpoint": "zhtp://identity.zhtp"
            }],
            "created": std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_secs()
        });

        // Store DID document
        let did_doc_bytes = serde_json::to_vec(&did_document)?;
        let did_path = format!("/did/{}", identity_id);
        dht.store_content("identity.zhtp", &did_path, did_doc_bytes).await?;

        // Store wallet registry
        if let Some(citizenship_result) = identity_result.get("citizenship_result") {
            let wallet_registry = serde_json::json!({
                "owner_did": did,
                "wallets": {
                    "primary": {
                        "id": citizenship_result.get("primary_wallet_id"),
                        "type": "Primary",
                        "capabilities": ["send", "receive", "stake"],
                        "public_endpoint": format!("zhtp://wallet.{}.zhtp/primary", identity_id)
                    },
                    "ubi": {
                        "id": citizenship_result.get("ubi_wallet_id"),
                        "type": "UBI",
                        "capabilities": ["receive"],
                        "public_endpoint": format!("zhtp://wallet.{}.zhtp/ubi", identity_id)
                    },
                    "savings": {
                        "id": citizenship_result.get("savings_wallet_id"),
                        "type": "Savings",
                        "capabilities": ["receive", "savings"],
                        "public_endpoint": format!("zhtp://wallet.{}.zhtp/savings", identity_id)
                    }
                },
                "created_at": std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)?
                    .as_secs()
            });

            let wallet_registry_bytes = serde_json::to_vec(&wallet_registry)?;
            let registry_path = format!("/registry/{}", identity_id);
            dht.store_content("wallet.zhtp", &registry_path, wallet_registry_bytes).await?;

            info!("💳 Distributed wallet registry to DHT");
        }

        info!("✅ Successfully distributed DID document to DHT");
    }

    Ok(())
}

pub async fn create_error_mesh_response(status_code: u16, message: &str) -> Result<Option<Vec<u8>>> {
    let error_response = serde_json::json!({
        "status": status_code,
        "statusText": match status_code {
            400 => "Bad Request",
            404 => "Not Found",
            500 => "Internal Server Error",
            _ => "Error"
        },
        "headers": {},
        "data": format!("{{\"error\": \"{}\"}}", message),
        "timestamp": std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs()
    });

    let mesh_response = serde_json::json!({
        "ZhtpResponse": error_response
    });

    Ok(Some(serde_json::to_vec(&mesh_response)?))
}

pub fn get_verification_attempt_count() -> u64 {
    VERIFICATION_ATTEMPTS.load(Ordering::Relaxed)
}

pub fn get_cache_hit_count() -> u64 {
    CACHE_HITS.load(Ordering::Relaxed)
}

pub fn get_verification_failure_count() -> u64 {
    VERIFICATION_FAILURES.load(Ordering::Relaxed)
}

pub struct VerifiedIdentity {
    /// DID of the verified identity
    pub did: String,
    /// Whether identity exists on blockchain
    pub is_verified: bool,
    /// Whether identity is in bootstrap mode (limited access)
    pub is_bootstrap: bool,
    /// Trust score from blockchain (0.0 - 1.0)
    pub trust_score: f64,
    /// Time when verification was performed
    pub verified_at: u64,
    /// Time when cache entry expires
    pub expires_at: u64,
}

impl VerifiedIdentity {
    /// Check if cache entry is expired
    pub fn is_expired(&self) -> bool {
        current_timestamp() > self.expires_at
    }
}

pub struct VerificationConfig {
    /// Cache TTL for verified identities (in seconds)
    pub cache_ttl_secs: u64,
    /// Cache TTL for unverified identities (in seconds) - shorter to re-check
    pub unverified_cache_ttl_secs: u64,
    /// Maximum cache size
    pub max_cache_size: usize,
    /// Allow routing for bootstrap peers (limited)
    pub allow_bootstrap_routing: bool,
    /// Minimum trust score required for full routing
    pub min_trust_score: f64,
}

impl Default for VerificationConfig {
    fn default() -> Self {
        Self {
            cache_ttl_secs: 300,            // 5 minutes for verified
            unverified_cache_ttl_secs: 60,  // 1 minute for unverified (re-check sooner)
            max_cache_size: 10_000,
            allow_bootstrap_routing: true,   // Allow limited bootstrap routing
            min_trust_score: 0.3,           // Minimum trust for full routing
        }
    }
}

pub enum VerificationResult {
    /// Identity verified on blockchain - full routing allowed
    Verified,
    /// Identity in bootstrap mode - limited routing only
    Bootstrap,
    /// Identity not found on blockchain - routing denied
    NotFound,
    /// Identity has insufficient trust score - routing denied
    InsufficientTrust,
    /// Identity is explicitly blocked
    Blocked,
}

impl VerificationResult {
    /// Check if routing should be allowed
    pub fn allows_routing(&self) -> bool {
        matches!(self, VerificationResult::Verified | VerificationResult::Bootstrap)
    }

    /// Check if this is full access (not bootstrap)
    pub fn is_full_access(&self) -> bool {
        matches!(self, VerificationResult::Verified)
    }
}

pub struct IdentityVerificationCache {
    /// Cached verification results by DID
    cache: RwLock<HashMap<String, VerifiedIdentity>>,
    /// Configuration
    config: VerificationConfig,
}

impl IdentityVerificationCache {
    /// Create a new verification cache with default configuration
    pub fn new() -> Self {
        Self::with_config(VerificationConfig::default())
    }

    /// Create a new verification cache with custom configuration
    pub fn with_config(config: VerificationConfig) -> Self {
        Self {
            cache: RwLock::new(HashMap::new()),
            config,
        }
    }

    /// Verify an identity for routing
    ///
    /// # Security (MEDIUM-3 Fix)
    ///
    /// This method:
    /// 1. Checks cache first (O(1) lookup)
    /// 2. If not cached, performs blockchain lookup
    /// 3. Caches result with appropriate TTL
    /// 4. Returns verification result for routing decision
    pub async fn verify_identity(
        &self,
        peer: &UnifiedPeerId,
        blockchain_lookup: impl FnOnce(&str) -> Option<f64>,
    ) -> VerificationResult {
        VERIFICATION_ATTEMPTS.fetch_add(1, Ordering::Relaxed);
        let did = peer.did();

        debug!("🔍 Verifying identity for routing: {}", did);

        // Check cache first
        {
            let cache = self.cache.read().await;
            if let Some(cached) = cache.get(did) {
                if !cached.is_expired() {
                    CACHE_HITS.fetch_add(1, Ordering::Relaxed);
                    debug!("✅ Cache hit for {}: verified={}, bootstrap={}",
                           did, cached.is_verified, cached.is_bootstrap);
                    return self.cached_to_result(cached);
                }
            }
        }

        // MEDIUM-3 FIX: Check if using unverified DID marker from CRITICAL-1 fix
        if did.contains(":unverified:") {
            warn!("⚠️ Peer {} has unverified DID marker - bootstrap mode only", did);

            // Cache as bootstrap mode
            let verified = VerifiedIdentity {
                did: did.to_string(),
                is_verified: false,
                is_bootstrap: true,
                trust_score: 0.5,
                verified_at: current_timestamp(),
                expires_at: current_timestamp() + self.config.unverified_cache_ttl_secs,
            };
            self.cache_entry(verified.clone()).await;

            if self.config.allow_bootstrap_routing {
                return VerificationResult::Bootstrap;
            } else {
                VERIFICATION_FAILURES.fetch_add(1, Ordering::Relaxed);
                return VerificationResult::NotFound;
            }
        }

        // Perform blockchain lookup
        let trust_score = blockchain_lookup(did);

        let result = match trust_score {
            Some(score) if score >= self.config.min_trust_score => {
                info!("✅ Identity {} verified on blockchain (trust: {:.2})", did, score);

                let verified = VerifiedIdentity {
                    did: did.to_string(),
                    is_verified: true,
                    is_bootstrap: false,
                    trust_score: score,
                    verified_at: current_timestamp(),
                    expires_at: current_timestamp() + self.config.cache_ttl_secs,
                };
                self.cache_entry(verified).await;

                VerificationResult::Verified
            }
            Some(score) => {
                warn!("⚠️ Identity {} has insufficient trust score: {:.2} < {:.2}",
                      did, score, self.config.min_trust_score);

                let verified = VerifiedIdentity {
                    did: did.to_string(),
                    is_verified: true,
                    is_bootstrap: true,
                    trust_score: score,
                    verified_at: current_timestamp(),
                    expires_at: current_timestamp() + self.config.unverified_cache_ttl_secs,
                };
                self.cache_entry(verified).await;

                VERIFICATION_FAILURES.fetch_add(1, Ordering::Relaxed);
                VerificationResult::InsufficientTrust
            }
            None => {
                warn!("❌ Identity {} not found on blockchain", did);

                let verified = VerifiedIdentity {
                    did: did.to_string(),
                    is_verified: false,
                    is_bootstrap: peer.is_bootstrap_mode(),
                    trust_score: 0.0,
                    verified_at: current_timestamp(),
                    expires_at: current_timestamp() + self.config.unverified_cache_ttl_secs,
                };
                self.cache_entry(verified).await;

                // Allow bootstrap routing if enabled
                if peer.is_bootstrap_mode() && self.config.allow_bootstrap_routing {
                    VerificationResult::Bootstrap
                } else {
                    VERIFICATION_FAILURES.fetch_add(1, Ordering::Relaxed);
                    VerificationResult::NotFound
                }
            }
        };

        result
    }

    /// Check if identity is verified (cache-only, no blockchain lookup)
    pub async fn is_cached_verified(&self, did: &str) -> Option<bool> {
        let cache = self.cache.read().await;
        cache.get(did)
            .filter(|c| !c.is_expired())
            .map(|c| c.is_verified)
    }

    /// Get verification stats
    pub async fn get_stats(&self) -> VerificationStats {
        let cache = self.cache.read().await;
        let now = current_timestamp();
        let expired = cache.values().filter(|v| v.is_expired()).count();

        VerificationStats {
            cached_identities: cache.len(),
            expired_entries: expired,
            total_verifications: get_verification_attempt_count(),
            cache_hits: get_cache_hit_count(),
            verification_failures: get_verification_failure_count(),
        }
    }

    /// Cleanup expired entries
    pub async fn cleanup(&self) {
        let now = current_timestamp();
        let mut cache = self.cache.write().await;
        let before = cache.len();
        cache.retain(|_, entry| entry.expires_at > now);
        let removed = before - cache.len();
        if removed > 0 {
            info!("🧹 Verification cache cleanup: removed {} expired entries", removed);
        }
    }

    /// Invalidate a specific identity (force re-verification)
    pub async fn invalidate(&self, did: &str) {
        let mut cache = self.cache.write().await;
        if cache.remove(did).is_some() {
            info!("🔄 Invalidated cache entry for {}", did);
        }
    }

    /// Clear all cache entries
    pub async fn clear(&self) {
        let mut cache = self.cache.write().await;
        let count = cache.len();
        cache.clear();
        info!("🧹 Cleared {} verification cache entries", count);
    }

    // Helper: Convert cached entry to result
    fn cached_to_result(&self, cached: &VerifiedIdentity) -> VerificationResult {
        if !cached.is_verified && !cached.is_bootstrap {
            return VerificationResult::NotFound;
        }

        if cached.is_bootstrap {
            if self.config.allow_bootstrap_routing {
                return VerificationResult::Bootstrap;
            } else {
                return VerificationResult::NotFound;
            }
        }

        if cached.trust_score < self.config.min_trust_score {
            return VerificationResult::InsufficientTrust;
        }

        VerificationResult::Verified
    }

    // Helper: Cache an entry
    async fn cache_entry(&self, entry: VerifiedIdentity) {
        let mut cache = self.cache.write().await;

        // Enforce max cache size
        if cache.len() >= self.config.max_cache_size {
            // Remove oldest entry
            let oldest_did = cache.iter()
                .min_by_key(|(_, e)| e.verified_at)
                .map(|(did, _)| did.clone());
            if let Some(did) = oldest_did {
                cache.remove(&did);
            }
        }

        cache.insert(entry.did.clone(), entry);
    }
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

