pub fn get_rate_limit_violation_count() -> u64 {
    RATE_LIMIT_VIOLATIONS.load(Ordering::Relaxed)
}

pub struct RateLimitEntry {
    /// Number of connection attempts in current window
    pub attempt_count: u32,
    /// Start of current rate limit window (Unix timestamp)
    pub window_start: u64,
    /// Number of consecutive windows with violations
    pub violation_count: u32,
    /// Time until which this entity is blocked (Unix timestamp, 0 = not blocked)
    pub blocked_until: u64,
    /// Last attempt timestamp
    pub last_attempt: u64,
}

impl RateLimitEntry {
    pub fn new() -> Self {
        let now = current_timestamp();
        Self {
            attempt_count: 0,
            window_start: now,
            violation_count: 0,
            blocked_until: 0,
            last_attempt: now,
        }
    }

    /// Check if currently blocked
    pub fn is_blocked(&self) -> bool {
        self.blocked_until > current_timestamp()
    }

    /// Get remaining block time in seconds
    pub fn block_remaining_secs(&self) -> u64 {
        let now = current_timestamp();
        if self.blocked_until > now {
            self.blocked_until - now
        } else {
            0
        }
    }
}

pub struct RateLimiterConfig {
    /// Maximum connection attempts per IP per window
    pub max_attempts_per_ip: u32,
    /// Maximum connection attempts per DID per window
    pub max_attempts_per_did: u32,
    /// Window duration in seconds
    pub window_secs: u64,
    /// Base block duration in seconds (exponential backoff)
    pub base_block_secs: u64,
    /// Maximum block duration in seconds
    pub max_block_secs: u64,
    /// Cleanup interval in seconds
    pub cleanup_interval_secs: u64,
}

impl Default for RateLimiterConfig {
    fn default() -> Self {
        Self {
            max_attempts_per_ip: 10,      // 10 connection attempts per IP per window
            max_attempts_per_did: 5,       // 5 connection attempts per DID per window
            window_secs: 60,               // 1 minute window
            base_block_secs: 30,           // Start with 30 second block
            max_block_secs: 3600,          // Max 1 hour block
            cleanup_interval_secs: 300,    // Cleanup every 5 minutes
        }
    }
}

pub struct ConnectionRateLimiter {
    /// Rate limit entries by IP address
    ip_limits: RwLock<HashMap<IpAddr, RateLimitEntry>>,
    /// Rate limit entries by DID
    did_limits: RwLock<HashMap<String, RateLimitEntry>>,
    /// Configuration
    config: RateLimiterConfig,
}

impl ConnectionRateLimiter {
    /// Create a new rate limiter with default configuration
    pub fn new() -> Self {
        Self::with_config(RateLimiterConfig::default())
    }

    /// Create a new rate limiter with custom configuration
    pub fn with_config(config: RateLimiterConfig) -> Self {
        Self {
            ip_limits: RwLock::new(HashMap::new()),
            did_limits: RwLock::new(HashMap::new()),
            config,
        }
    }

    /// Check if a connection attempt from an IP is allowed
    /// Returns Ok(()) if allowed, Err(block_duration) if blocked
    pub async fn check_ip(&self, ip: IpAddr) -> Result<(), Duration> {
        let mut limits = self.ip_limits.write().await;
        let now = current_timestamp();

        let entry = limits.entry(ip).or_insert_with(RateLimitEntry::new);

        // Check if blocked
        if entry.is_blocked() {
            let remaining = entry.block_remaining_secs();
            warn!("🚫 RATE LIMIT: IP {} blocked for {} more seconds (violations: {})",
                  ip, remaining, entry.violation_count);
            RATE_LIMIT_VIOLATIONS.fetch_add(1, Ordering::Relaxed);
            return Err(Duration::from_secs(remaining));
        }

        // Reset window if expired
        if now - entry.window_start >= self.config.window_secs {
            entry.attempt_count = 0;
            entry.window_start = now;
        }

        // Increment attempt count
        entry.attempt_count += 1;
        entry.last_attempt = now;

        // Check if over limit
        if entry.attempt_count > self.config.max_attempts_per_ip {
            entry.violation_count += 1;

            // Calculate exponential backoff: base * 2^(violations-1), capped at max
            let backoff = std::cmp::min(
                self.config.base_block_secs * (1 << (entry.violation_count.saturating_sub(1))),
                self.config.max_block_secs
            );
            entry.blocked_until = now + backoff;

            error!("🚨 RATE LIMIT VIOLATION: IP {} exceeded {} attempts/{}s, blocked for {}s (violation #{})",
                   ip, self.config.max_attempts_per_ip, self.config.window_secs,
                   backoff, entry.violation_count);
            RATE_LIMIT_VIOLATIONS.fetch_add(1, Ordering::Relaxed);

            return Err(Duration::from_secs(backoff));
        }

        Ok(())
    }

    /// Check if a connection attempt from a DID is allowed
    /// Returns Ok(()) if allowed, Err(block_duration) if blocked
    pub async fn check_did(&self, did: &str) -> Result<(), Duration> {
        let mut limits = self.did_limits.write().await;
        let now = current_timestamp();

        let entry = limits.entry(did.to_string()).or_insert_with(RateLimitEntry::new);

        // Check if blocked
        if entry.is_blocked() {
            let remaining = entry.block_remaining_secs();
            warn!("🚫 RATE LIMIT: DID {} blocked for {} more seconds (violations: {})",
                  did, remaining, entry.violation_count);
            RATE_LIMIT_VIOLATIONS.fetch_add(1, Ordering::Relaxed);
            return Err(Duration::from_secs(remaining));
        }

        // Reset window if expired
        if now - entry.window_start >= self.config.window_secs {
            entry.attempt_count = 0;
            entry.window_start = now;
        }

        // Increment attempt count
        entry.attempt_count += 1;
        entry.last_attempt = now;

        // Check if over limit
        if entry.attempt_count > self.config.max_attempts_per_did {
            entry.violation_count += 1;

            // Calculate exponential backoff
            let backoff = std::cmp::min(
                self.config.base_block_secs * (1 << (entry.violation_count.saturating_sub(1))),
                self.config.max_block_secs
            );
            entry.blocked_until = now + backoff;

            error!("🚨 RATE LIMIT VIOLATION: DID {} exceeded {} attempts/{}s, blocked for {}s (violation #{})",
                   did, self.config.max_attempts_per_did, self.config.window_secs,
                   backoff, entry.violation_count);
            RATE_LIMIT_VIOLATIONS.fetch_add(1, Ordering::Relaxed);

            return Err(Duration::from_secs(backoff));
        }

        Ok(())
    }

    /// Combined check for both IP and DID
    /// Fails if either is rate limited
    pub async fn check_connection(&self, ip: IpAddr, did: Option<&str>) -> Result<(), Duration> {
        // Check IP first
        self.check_ip(ip).await?;

        // Check DID if provided
        if let Some(did) = did {
            self.check_did(did).await?;
        }

        Ok(())
    }

    /// Record a successful connection (reduces violation count over time)
    pub async fn record_success(&self, ip: IpAddr, did: Option<&str>) {
        // Reduce IP violation count on success
        {
            let mut limits = self.ip_limits.write().await;
            if let Some(entry) = limits.get_mut(&ip) {
                if entry.violation_count > 0 {
                    entry.violation_count = entry.violation_count.saturating_sub(1);
                    info!("✅ Rate limit: IP {} violation count reduced to {}", ip, entry.violation_count);
                }
            }
        }

        // Reduce DID violation count on success
        if let Some(did) = did {
            let mut limits = self.did_limits.write().await;
            if let Some(entry) = limits.get_mut(did) {
                if entry.violation_count > 0 {
                    entry.violation_count = entry.violation_count.saturating_sub(1);
                    info!("✅ Rate limit: DID {} violation count reduced to {}", did, entry.violation_count);
                }
            }
        }
    }

    /// Cleanup expired entries
    pub async fn cleanup(&self) {
        let now = current_timestamp();
        let expiry_threshold = now - (self.config.window_secs * 10); // Keep entries for 10 windows

        // Cleanup IP entries
        {
            let mut limits = self.ip_limits.write().await;
            let before = limits.len();
            limits.retain(|_, entry| {
                // Keep if: recently active OR still blocked
                entry.last_attempt > expiry_threshold || entry.is_blocked()
            });
            let removed = before - limits.len();
            if removed > 0 {
                info!("🧹 Rate limiter cleanup: removed {} expired IP entries", removed);
            }
        }

        // Cleanup DID entries
        {
            let mut limits = self.did_limits.write().await;
            let before = limits.len();
            limits.retain(|_, entry| {
                entry.last_attempt > expiry_threshold || entry.is_blocked()
            });
            let removed = before - limits.len();
            if removed > 0 {
                info!("🧹 Rate limiter cleanup: removed {} expired DID entries", removed);
            }
        }
    }

    /// Get statistics for monitoring
    pub async fn get_stats(&self) -> RateLimiterStats {
        let ip_limits = self.ip_limits.read().await;
        let did_limits = self.did_limits.read().await;

        let ip_blocked = ip_limits.values().filter(|e| e.is_blocked()).count();
        let did_blocked = did_limits.values().filter(|e| e.is_blocked()).count();

        RateLimiterStats {
            tracked_ips: ip_limits.len(),
            tracked_dids: did_limits.len(),
            blocked_ips: ip_blocked,
            blocked_dids: did_blocked,
            total_violations: get_rate_limit_violation_count(),
        }
    }

    /// Start background cleanup task
    pub fn start_cleanup_task(self: std::sync::Arc<Self>) {
        let interval = Duration::from_secs(self.config.cleanup_interval_secs);
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(interval).await;
                self.cleanup().await;
            }
        });
    }
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

impl MeshRouter {
    /// Initialize advanced routing capabilities from lib-network
    /// 
    /// Enables:
    /// - Multi-hop routing (messages traverse multiple nodes)
    /// - Relay node functionality (this node can forward messages)
    /// - Long-range transport support (LoRaWAN, Satellite)
    /// 
    /// # Example
    /// ```rust
    /// mesh_router.initialize_advanced_routing().await?;
    /// mesh_router.send_with_routing(target_pubkey, message, sender_pubkey).await?;
    /// ```
    pub async fn initialize_advanced_routing(&self) -> Result<()> {
        info!("🔀 Initializing lib-network advanced routing capabilities...");

        // lib-network's MeshMessageRouter is already initialized in MeshRouter::new()
        // It uses self.connections and self.dht_storage

        info!("✅ Advanced routing ready: multi-hop, relay, and long-range supported");
        debug!("   - Multi-hop: Messages can traverse up to 5 nodes");
        debug!("   - Relay mode: Node can forward messages for others");
        debug!("   - Long-range: LoRaWAN and Satellite transports available");

        Ok(())
    }

    /// Send message with automatic routing (multi-hop/relay/long-range)
    ///
    /// Uses lib-network's MessageRouter for sophisticated path finding:
    /// 1. Tries direct connection first (lowest latency)
    /// 2. Falls back to multi-hop if direct unavailable
    /// 3. Uses relay nodes if target is in different network segment
    /// 4. Attempts long-range transports (LoRaWAN/Satellite) for global reach
    ///
    /// # Security (MEDIUM-3 Fix)
    ///
    /// Before routing, verifies:
    /// 1. Sender identity is verified on blockchain OR in bootstrap mode
    /// 2. Destination identity exists (optional, for unrestricted routing)
    ///
    /// # Arguments
    /// * `message` - ZHTP mesh message to send
    /// * `destination` - Public key of destination node
    /// * `sender` - Public key of sending node (for routing optimization)
    ///
    /// # Returns
    /// * `Ok(message_id)` - Message successfully routed, returns tracking ID
    /// * `Err` - Routing failed (identity not verified or all routing attempts failed)
    ///
    /// # Example
    /// ```rust
    /// let message = ZhtpMeshMessage::Request { /* ... */ };
    /// let msg_id = mesh_router.send_with_routing(message, &target_pubkey, &sender_pubkey).await?;
    /// ```
    pub async fn send_with_routing(
        &self,
        message: ZhtpMeshMessage,
        destination: &PublicKey,
        sender: &PublicKey,
    ) -> Result<u64> {
        debug!("🔀 Routing message to {} (type: {:?})",
               hex::encode(&destination.key_id[..8]),
               std::mem::discriminant(&message));

        // MEDIUM-3 FIX: Verify sender identity before routing
        #[allow(deprecated)]
        let sender_peer = UnifiedPeerId::from_public_key_legacy(sender.clone());

        // Perform identity verification with blockchain lookup
        let verification_result = self.identity_verification_cache
            .verify_identity(&sender_peer, |did| {
                // Blockchain lookup callback
                // For now, return None to trigger bootstrap mode behavior
                // In production, this would query the blockchain for the DID
                debug!("🔍 Blockchain lookup for DID: {}", did);

                // Check if the DID looks valid (not unverified marker)
                if did.contains(":unverified:") {
                    return None;
                }

                // TODO: Actual blockchain lookup would go here:
                // self.blockchain.get_identity_trust_score(did)

                // For now, assume verified identities have a trust score of 0.8
                // This will be replaced with actual blockchain lookup in production
                Some(0.8)
            })
            .await;

        // Check verification result
        match &verification_result {
            VerificationResult::Verified => {
                info!("✅ Sender {} verified - full routing access", sender_peer.did());
            }
            VerificationResult::Bootstrap => {
                warn!("⚠️ Sender {} in bootstrap mode - limited routing", sender_peer.did());
                // Allow routing but log for monitoring
            }
            VerificationResult::NotFound => {
                error!("❌ Sender {} identity not found on blockchain - routing denied",
                       sender_peer.did());
                return Err(anyhow::anyhow!(
                    "Routing denied: sender identity {} not verified on blockchain",
                    sender_peer.did()
                ));
            }
            VerificationResult::InsufficientTrust => {
                error!("❌ Sender {} has insufficient trust score - routing denied",
                       sender_peer.did());
                return Err(anyhow::anyhow!(
                    "Routing denied: sender {} has insufficient trust score",
                    sender_peer.did()
                ));
            }
            VerificationResult::Blocked => {
                error!("🚫 Sender {} is blocked - routing denied", sender_peer.did());
                return Err(anyhow::anyhow!(
                    "Routing denied: sender {} is blocked",
                    sender_peer.did()
                ));
            }
        }

        // Identity verified - proceed with routing
        let router = self.mesh_message_router.read().await;

        match router.route_message(message, destination.clone(), sender.clone()).await {
            Ok(message_id) => {
                info!("✅ Message routed successfully (ID: {}, verification: {:?})",
                      message_id, verification_result);
                Ok(message_id)
            }
            Err(e) => {
                warn!("❌ All routing attempts failed for {}: {}",
                      hex::encode(&destination.key_id[..8]), e);
                Err(anyhow::anyhow!("Message routing failed: {}", e))
            }
        }
    }

    /// Find optimal route to a destination
    ///
    /// Uses lib-network's path finding to discover available routes
    /// without actually sending a message.
    ///
    /// Useful for:
    /// - Checking connectivity before sending large data
    /// - Measuring latency to different peers
    /// - Network topology visualization
    pub async fn find_route_to_peer(
        &self,
        destination: &PublicKey,
        sender: &PublicKey,
    ) -> Result<Vec<lib_network::routing::message_routing::RouteHop>> {
        debug!("🔍 Discovering route to {}...", hex::encode(&destination.key_id[..8]));

        // Ticket #146: Convert PublicKey to UnifiedPeerId for routing
        #[allow(deprecated)]
        let dest_unified = UnifiedPeerId::from_public_key_legacy(destination.clone());
        #[allow(deprecated)]
        let sender_unified = UnifiedPeerId::from_public_key_legacy(sender.clone());

        let router = self.mesh_message_router.read().await;
        let route = router.find_optimal_route(&dest_unified, &sender_unified).await
            .context("No route found to destination")?;

        info!("✅ Route found: {} hops", route.len());

        Ok(route)
    }

