    }

    /// Get a transaction by hash
    pub async fn get_transaction(&self, hash: String) -> Result<Option<Transaction>> {
        let (response_tx, mut response_rx) = mpsc::unbounded_channel();

        let operation = BlockchainOperation::GetTransaction {
