                *trust_node,
            )?;

            deploy_site(
                build_dir,
                domain,
                mode.as_deref().unwrap_or("spa"),
                keystore,
                *fee,
                trust_config,
                *dry_run,
                cli,
            ).await
        }
        DeployAction::Status {
            domain,
            keystore,
            pin_spki,
            node_did,
            tofu,
            trust_node,
        } => {
            let trust_config = build_trust_config(
                pin_spki.clone(),
                node_did.clone(),
                *tofu,
                *trust_node,
            )?;

            check_deployment_status(
                domain,
                keystore.as_deref(),
                trust_config,
                cli,
            ).await
        }
        DeployAction::List {
            keystore,
            pin_spki,
            node_did,
            tofu,
            trust_node,
        } => {
            let trust_config = build_trust_config(
                pin_spki.clone(),
                node_did.clone(),
                *tofu,
                *trust_node,
            )?;

            list_deployments(
                keystore.as_deref(),
                trust_config,
                cli,
            ).await
        }

        DeployAction::History {
            domain,
            limit,
            keystore,
            pin_spki,
            node_did,
            tofu,
            trust_node,
        } => {
            let trust_config = build_trust_config(
                pin_spki.clone(),
                node_did.clone(),
                *tofu,
                *trust_node,
            )?;

            show_deployment_history(
                domain,
                *limit,
                keystore.as_deref(),
                trust_config,
                cli,
            ).await
        }

        DeployAction::Rollback {
            domain,
            to_version,
            keystore,
            pin_spki,
