fn get_default_keystore_path() -> Result<PathBuf> {
    let home = dirs::home_dir()
        .ok_or_else(|| anyhow!("Could not determine home directory"))?;
    Ok(home.join(".zhtp").join("keystore"))
}

fn load_identity_from_keystore(keystore: &PathBuf) -> Result<ZhtpIdentity> {
    let identity_file = keystore.join("identity.json");

    if !identity_file.exists() {
        return Err(anyhow!(
            "No identity found at {:?}\n\
            Create an identity first with: zhtp identity create <name>",
            identity_file
        ));
    }

    let data = std::fs::read_to_string(&identity_file)
        .context("Failed to read identity.json")?;
    let identity: ZhtpIdentity = serde_json::from_str(&data)
        .context("Failed to parse identity.json")?;

    info!("Loaded identity {} from {:?}", identity.did, identity_file);
    Ok(identity)
}

fn build_trust_config_from_cli(cli: &ZhtpCli) -> Result<TrustConfig> {
    if std::env::var("ZHTP_ALLOW_BOOTSTRAP").ok().map(|v| v == "1").unwrap_or(false) {
        // DEV ONLY: Bootstrap mode with security warnings
        warn!("╔══════════════════════════════════════════════════════════════╗");
        warn!("║  SECURITY WARNING: Bootstrap mode - TLS verification OFF     ║");
        warn!("║  This accepts ANY certificate without validation.            ║");
        warn!("║  NEVER use in production! Vulnerable to MITM attacks.        ║");
        warn!("╚══════════════════════════════════════════════════════════════╝");
        Ok(TrustConfig::bootstrap())
    } else {
        // Default to TOFU with explicit fingerprint logging
        let trustdb_path = TrustConfig::default_trustdb_path()?;
        let audit_path = TrustConfig::default_audit_path();

        info!("Trust mode: TOFU (Trust On First Use)");
        info!("Trustdb: {:?}", trustdb_path);
        info!("Audit log: {:?}", audit_path);
        info!("First connection to a new node will display its fingerprint.");
        info!("To reset trust: delete {:?}", trustdb_path);

        Ok(TrustConfig::with_tofu(trustdb_path))
    }
}

pub async fn handle_interactive_command(_args: InteractiveArgs, cli: &ZhtpCli) -> Result<()> {
    println!(" ZHTP Orchestrator Interactive Shell");
    println!("======================================");
    println!("Type 'help' for available commands, 'exit' to quit");
    println!("Server: {}", cli.server);
    println!("Format: {:?}", cli.format);
    println!("");

    let client = reqwest::Client::new();
    let base_url = format!("http://{}/api/v1", cli.server);

    loop {
        print!("zhtp> ");
        io::stdout().flush()?;

        let mut input = String::new();
        match io::stdin().read_line(&mut input) {
            Ok(_) => {
                let input = input.trim();

                match input {
                    "exit" | "quit" => {
                        println!("Goodbye!");
                        break;
                    }
                    "help" => {
                        show_interactive_help();
                    }
                    "status" => {
                        if let Err(e) = check_orchestrator_status(&client, &base_url, cli).await {
                            println!("Error: {}", e);
                        }
                    }
                    "health" => {
                        if let Err(e) = check_component_health(&client, &base_url, cli).await {
                            println!("Error: {}", e);
                        }
                    }
                    "components" => {
                        if let Err(e) = list_components(&client, &base_url, cli).await {
                            println!("Error: {}", e);
                        }
                    }
                    "" => continue,
                    _ => {
                        if input.starts_with("start ") {
                            let component = input.strip_prefix("start ").unwrap();
                            if let Err(e) = start_component(&client, &base_url, component, cli).await {
                                println!("Error: {}", e);
                            }
                        } else if input.starts_with("stop ") {
                            let component = input.strip_prefix("stop ").unwrap();
                            if let Err(e) = stop_component(&client, &base_url, component, cli).await {
                                println!("Error: {}", e);
                            }
                        } else if input.starts_with("info ") {
                            let component = input.strip_prefix("info ").unwrap();
                            if let Err(e) = component_info(&client, &base_url, component, cli).await {
                                println!("Error: {}", e);
                            }
                        } else {
                            println!("Unknown command: {}", input);
                            println!("Type 'help' for available commands");
                        }
                    }
                }
            }
            Err(error) => {
                println!("Error reading input: {}", error);
                break;
            }
        }
    }

    Ok(())
}

fn show_interactive_help() {
    println!("Available commands:");
    println!("  status      - Show orchestrator status");
    println!("  health      - Check component health");
    println!("  components  - List all components");
    println!("  start <name> - Start a component");
    println!("  stop <name>  - Stop a component");
    println!("  info <name>  - Get component information");
    println!("  help        - Show this help message");
    println!("  exit/quit   - Exit the shell");
    println!("");
    println!("Components: protocols, blockchain, network, consensus, storage, economy, proofs, identity, crypto");
}

