                hash: "none".to_string(),
                previous_hash: "none".to_string(),
                timestamp: 0,
                transaction_count: 0,
                merkle_root: "none".to_string(),
                nonce: 0,
            }
        };

        let json_response = serde_json::to_vec(&response_data)?;
        Ok(ZhtpResponse::success_with_content_type(
