    /// Add authorized controller to DAO wallet
    pub fn add_dao_controller(
        &mut self,
        wallet_id: &WalletId,
        new_controller: IdentityId,
        authorized_by: IdentityId,
    ) -> Result<()> {
        let wallet = self.wallets.get_mut(wallet_id)
