        let eligibility_request = CrossPackageRequest {
            target_package: "lib-economy".to_string(),
            operation: "check_ubi_eligibility".to_string(),
            parameters: serde_json::json!({
                "identity_id": identity_id,
                "verification_level": "citizen"
