}

impl UbiRegistration {
    /// Create a new UBI registration
    pub fn new(
        identity_id: IdentityId,
        ubi_wallet_id: WalletId,
        registration_tx: Transaction,
        daily_amount: u64,
        monthly_amount: u64,
        eligibility_proof: [u8; 32],
        registered_at: u64,
        last_payout: Option<u64>,
        total_received: u64,
    ) -> Self {
        Self {
            identity_id,
            ubi_wallet_id,
            registration_tx,
            daily_amount,
            monthly_amount,
            eligibility_proof,
            registered_at,
            last_payout,
            total_received,
        }
    }

    /// Register identity for Universal Basic Income payouts - IMPLEMENTATION FROM ORIGINAL
    pub async fn register_for_ubi_payouts(
        identity_id: &IdentityId,
        ubi_wallet_id: &WalletId,
        economic_model: &mut EconomicModel,
    ) -> Result<Self> {
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        // Calculate monthly UBI amount (1000 ZHTP tokens per month)
        let monthly_ubi_amount = 1000u64;
        let daily_ubi_amount = monthly_ubi_amount / 30; // ~33 ZHTP per day

        // Create UBI registration transaction
        let ubi_tx = Transaction::new(
            [0u8; 32], // UBI treasury
            identity_id.0,
            0, // No cost to register for UBI
            TransactionType::UbiDistribution,
            economic_model,
            128, // Transaction size
            Priority::Normal,
        )?;

        // Generate UBI eligibility proof
        let eligibility_proof = lib_crypto::hash_blake3(
            &[
                identity_id.0.as_slice(),
                ubi_wallet_id.0.as_slice(),
                &daily_ubi_amount.to_le_bytes(),
                &current_time.to_le_bytes(),
            ].concat()
        );

        tracing::info!(
            "UBI REGISTERED: Citizen {} eligible for {} ZHTP daily ({} ZHTP monthly)",
            hex::encode(&identity_id.0[..8]),
            daily_ubi_amount,
            monthly_ubi_amount
        );

        Ok(Self::new(
            identity_id.clone(),
            ubi_wallet_id.clone(),
            ubi_tx,
            daily_ubi_amount,
            monthly_ubi_amount,
            eligibility_proof,
            current_time,
            None,
            0,
        ))
    }

    /// Check if eligible for UBI payout
    pub fn is_eligible_for_payout(&self) -> bool {
        self.eligibility_proof != [0u8; 32] && self.daily_amount > 0
    }

    /// Check if due for daily payout
    pub fn is_due_for_daily_payout(&self) -> bool {
        if let Some(last_payout) = self.last_payout {
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();
            // Check if 24 hours have passed since last payout
            now - last_payout >= 24 * 3600
        } else {
            // Never received payout, eligible immediately
            true
        }
    }

    /// Record a UBI payout
    pub fn record_payout(&mut self, amount: u64) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        self.last_payout = Some(now);
        self.total_received += amount;
    }

    /// Get days since registration
    pub fn days_since_registration(&self) -> u64 {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        (now - self.registered_at) / (24 * 3600)
    }

    /// Calculate expected total UBI based on days since registration
    pub fn expected_total_ubi(&self) -> u64 {
        self.days_since_registration() * self.daily_amount
    }

    /// Check if citizen is up to date with UBI payouts
    pub fn is_ubi_up_to_date(&self) -> bool {
        let expected = self.expected_total_ubi();
        // Allow some tolerance (within 2 days worth)
        self.total_received + (2 * self.daily_amount) >= expected
    }

    /// Get next payout timestamp
    pub fn next_payout_timestamp(&self) -> Option<u64> {
        if let Some(last_payout) = self.last_payout {
            Some(last_payout + 24 * 3600) // 24 hours later
        } else {
            // Eligible for immediate payout
            Some(std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs())
        }
    }

    /// Get time until next payout in seconds
    pub fn seconds_until_next_payout(&self) -> u64 {
        if let Some(next_payout) = self.next_payout_timestamp() {
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();
            if next_payout > now {
                next_payout - now
            } else {
                0 // Payout is due
            }
        } else {
            0 // Eligible for immediate payout
        }
    }
}

pub struct Web4Access {
    /// Citizen's identity ID
    pub identity_id: IdentityId,
    /// Service access tokens for each Web4 service
    pub service_tokens: HashMap<String, String>,
    /// Global access proof
    pub access_proof: [u8; 32],
    /// Access granted timestamp
    pub granted_at: u64,
    /// Access level
    pub access_level: AccessLevel,
    /// Any access restrictions (none for full citizens)
    pub restrictions: Vec<String>,
}

impl Web4Access {
    /// Create new Web4 access
    pub fn new(
        identity_id: IdentityId,
        service_tokens: HashMap<String, String>,
        access_proof: [u8; 32],
        granted_at: u64,
        access_level: AccessLevel,
        restrictions: Vec<String>,
    ) -> Self {
        Self {
            identity_id,
            service_tokens,
            access_proof,
            granted_at,
            access_level,
            restrictions,
        }
    }

    /// Grant access to all Web4 services - IMPLEMENTATION FROM ORIGINAL
    pub async fn grant_web4_access(identity_id: &IdentityId) -> Result<Self> {
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        // Generate service access tokens
        let mut service_tokens = HashMap::new();

        // Core Web4 services
        let services = vec![
            "zhtp.browse",      // Web4 browsing
            "zhtp.publish",     // Content publishing
            "zhtp.storage",     // Decentralized storage
            "zhtp.messaging",   // Private messaging
            "zhtp.identity",    // Identity services
            "zhtp.wallet",      // Wallet services
            "zhtp.voting",      // DAO voting
            "zhtp.marketplace", // Decentralized marketplace
            "zhtp.compute",     // Distributed computing
            "zhtp.ai",          // AI services
        ];

        for service in services {
            let token = lib_crypto::hash_blake3(
                &[identity_id.0.as_slice(), service.as_bytes(), &current_time.to_le_bytes()].concat()
            );
            service_tokens.insert(service.to_string(), hex::encode(token));
        }

        // Generate global access proof
        let access_proof = lib_crypto::hash_blake3(
            &[
                identity_id.0.as_slice(),
                "web4_full_access".as_bytes(),
                &current_time.to_le_bytes(),
            ].concat()
        );

        tracing::info!(
            "WEB4 ACCESS GRANTED: Citizen {} has full access to {} services",
            hex::encode(&identity_id.0[..8]),
            service_tokens.len()
        );

        Ok(Self::new(
            identity_id.clone(),
            service_tokens,
            access_proof,
            current_time,
            AccessLevel::FullCitizen,
            vec![], // No restrictions for citizens
        ))
    }


    /// Check if has access to specific service
    pub fn has_service_access(&self, service: &str) -> bool {
        self.service_tokens.contains_key(service) && 
        self.access_level == AccessLevel::FullCitizen
    }

    /// Get service token for specific service
    pub fn get_service_token(&self, service: &str) -> Option<&String> {
        self.service_tokens.get(service)
    }

    /// Get all available services
    pub fn get_available_services(&self) -> Vec<&String> {
        self.service_tokens.keys().collect()
    }

    /// Check if access is unrestricted
    pub fn is_unrestricted(&self) -> bool {
        self.restrictions.is_empty() && self.access_level == AccessLevel::FullCitizen
    }

    /// Get access summary
    pub fn get_access_summary(&self) -> Web4AccessSummary {
        Web4AccessSummary {
            identity_id: self.identity_id.clone(),
            service_count: self.service_tokens.len(),
            access_level: self.access_level.clone(),
            is_unrestricted: self.is_unrestricted(),
            granted_at: self.granted_at,
            restrictions_count: self.restrictions.len(),
        }
    }

    /// Add new service access
    pub fn add_service_access(&mut self, service: String, token: String) {
        self.service_tokens.insert(service, token);
    }

    /// Remove service access
    pub fn remove_service_access(&mut self, service: &str) {
        self.service_tokens.remove(service);
    }

    /// Update access level
    pub fn update_access_level(&mut self, new_level: AccessLevel) {
        self.access_level = new_level;
    }

    /// Add restriction
    pub fn add_restriction(&mut self, restriction: String) {
        if !self.restrictions.contains(&restriction) {
            self.restrictions.push(restriction);
        }
    }

    /// Remove restriction
    pub fn remove_restriction(&mut self, restriction: &str) {
        self.restrictions.retain(|r| r != restriction);
    }
}

