pub struct Mempool {
    /// Pending transactions by hash
    transactions: HashMap<Hash, Transaction>,
    /// Transaction order for prioritization
    transaction_queue: VecDeque<Hash>,
    /// Maximum size of the mempool
    max_size: usize,
    /// Minimum fee rate for acceptance
    min_fee_rate: u64,
}

impl Mempool {
    /// Create a new mempool
    pub fn new(max_size: usize, min_fee_rate: u64) -> Self {
        Self {
            transactions: HashMap::new(),
            transaction_queue: VecDeque::new(),
            max_size,
            min_fee_rate,
        }
    }

    /// Add a transaction to the mempool
    pub fn add_transaction(&mut self, transaction: Transaction) -> Result<(), MempoolError> {
        let tx_hash = transaction.hash();

        // Check if already exists
        if self.transactions.contains_key(&tx_hash) {
            return Err(MempoolError::TransactionExists);
        }

        // Validate transaction
        self.validate_transaction(&transaction)?;

        // Check fee rate
        let fee_rate = transaction.fee as f64 / transaction.size() as f64;
        if fee_rate < self.min_fee_rate as f64 {
            return Err(MempoolError::InsufficientFee);
        }

        // Make room if necessary
        while self.transactions.len() >= self.max_size {
            self.evict_lowest_fee_transaction()?;
        }

        // Add to mempool
        self.transactions.insert(tx_hash, transaction);
        self.transaction_queue.push_back(tx_hash);

        Ok(())
    }

    /// Remove a transaction from the mempool
    pub fn remove_transaction(&mut self, tx_hash: &Hash) -> Option<Transaction> {
        if let Some(transaction) = self.transactions.remove(tx_hash) {
            self.transaction_queue.retain(|hash| hash != tx_hash);
            Some(transaction)
        } else {
            None
        }
    }

    /// Get a transaction by hash
    pub fn get_transaction(&self, tx_hash: &Hash) -> Option<&Transaction> {
        self.transactions.get(tx_hash)
    }

    /// Get all pending transactions
    pub fn get_all_transactions(&self) -> Vec<&Transaction> {
        self.transactions.values().collect()
    }

    /// Get transactions for block creation (highest fee first)
    pub fn get_transactions_for_block(&self, max_count: usize, max_size: usize) -> Vec<Transaction> {
        let mut selected = Vec::new();
        let mut total_size = 0;

        // Sort by fee rate (highest first)
        let mut tx_refs: Vec<_> = self.transactions.values().collect();
        tx_refs.sort_by(|a, b| {
            let fee_rate_a = a.fee as f64 / a.size() as f64;
            let fee_rate_b = b.fee as f64 / b.size() as f64;
            fee_rate_b.partial_cmp(&fee_rate_a).unwrap_or(std::cmp::Ordering::Equal)
        });

        for tx in tx_refs {
            if selected.len() >= max_count {
                break;
            }

            let tx_size = tx.size();
            if total_size + tx_size > max_size {
                continue;
            }

            selected.push(tx.clone());
            total_size += tx_size;
        }

        selected
    }

    /// Remove multiple transactions (after block inclusion)
    pub fn remove_transactions(&mut self, tx_hashes: &[Hash]) {
        for tx_hash in tx_hashes {
            self.remove_transaction(tx_hash);
        }
    }

    /// Get mempool statistics
    pub fn stats(&self) -> MempoolStats {
        let total_fees: u64 = self.transactions.values().map(|tx| tx.fee).sum();
        let total_size: usize = self.transactions.values().map(|tx| tx.size()).sum();
        let avg_fee_rate = if total_size > 0 {
            total_fees as f64 / total_size as f64
        } else {
            0.0
        };

        MempoolStats {
            transaction_count: self.transactions.len(),
            total_fees,
            total_size,
            average_fee_rate: avg_fee_rate,
            min_fee_rate: self.min_fee_rate,
            max_size: self.max_size,
        }
    }

    /// Check if mempool contains transaction
    pub fn contains(&self, tx_hash: &Hash) -> bool {
        self.transactions.contains_key(tx_hash)
    }

    /// Clear all transactions
    pub fn clear(&mut self) {
        self.transactions.clear();
        self.transaction_queue.clear();
    }

    /// Validate transaction for mempool inclusion
    fn validate_transaction(&self, transaction: &Transaction) -> Result<(), MempoolError> {
        // Use transaction validator
        let validator = crate::transaction::validation::TransactionValidator::new();

        match validator.validate_transaction(transaction) {
            Ok(()) => {
                log::info!("Transaction validation successful");
                Ok(())
            },
            Err(ValidationError::DoubleSpend) => {
                log::error!("Validation failed: DoubleSpend");
                Err(MempoolError::DoubleSpend)
            },
            Err(ValidationError::InvalidSignature) => {
                log::error!("Validation failed: InvalidSignature");
                Err(MempoolError::InvalidSignature)
            },
            Err(ValidationError::InvalidZkProof) => {
                log::error!("Validation failed: InvalidZkProof - ZK proof verification failed");
                Err(MempoolError::InvalidProof)
            },
            Err(e) => {
                log::error!("Validation failed: {:?}", e);
                Err(MempoolError::InvalidTransaction)
            },
        }
    }

    /// Evict lowest fee transaction to make room
    fn evict_lowest_fee_transaction(&mut self) -> Result<(), MempoolError> {
        if self.transactions.is_empty() {
            return Err(MempoolError::MempoolEmpty);
        }

        // Find transaction with lowest fee rate
        let mut lowest_fee_rate = f64::INFINITY;
        let mut lowest_hash = None;

        for (hash, tx) in &self.transactions {
            let fee_rate = tx.fee as f64 / tx.size() as f64;
            if fee_rate < lowest_fee_rate {
                lowest_fee_rate = fee_rate;
                lowest_hash = Some(*hash);
            }
        }

        if let Some(hash) = lowest_hash {
            self.remove_transaction(&hash);
            Ok(())
        } else {
            Err(MempoolError::EvictionFailed)
        }
    }
}

impl Default for Mempool {
    fn default() -> Self {
        Self::new(10000, 1) // Default: 10k transactions, 1 unit/byte min fee
    }
}

impl std::fmt::Display for MempoolError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MempoolError::TransactionExists => write!(f, "Transaction already exists in mempool"),
            MempoolError::InsufficientFee => write!(f, "Transaction fee too low"),
            MempoolError::InvalidTransaction => write!(f, "Invalid transaction"),
            MempoolError::InvalidSignature => write!(f, "Invalid transaction signature"),
            MempoolError::InvalidProof => write!(f, "Invalid zero-knowledge proof"),
            MempoolError::DoubleSpend => write!(f, "Double spend detected"),
            MempoolError::MempoolFull => write!(f, "Mempool is full"),
            MempoolError::MempoolEmpty => write!(f, "Mempool is empty"),
            MempoolError::EvictionFailed => write!(f, "Failed to evict transaction"),
        }
    }
}

pub async fn initialize_global_blockchain_provider(blockchain: Blockchain) -> Result<()> {
    let shared_blockchain = Arc::new(RwLock::new(blockchain));

    GLOBAL_BLOCKCHAIN.set(shared_blockchain.clone())
        .map_err(|_| anyhow::anyhow!("Global blockchain provider already initialized"))?;

    tracing::info!("Global blockchain provider initialized successfully");
    Ok(())
}

pub async fn set_global_blockchain(blockchain: Blockchain) -> Result<()> {
    match GLOBAL_BLOCKCHAIN.get() {
        Some(shared_blockchain) => {
            let mut guard = shared_blockchain.write().await;
            *guard = blockchain;
            tracing::info!(" Global blockchain instance updated");
            Ok(())
        }
        None => {
            // Initialize if not already done
            initialize_global_blockchain_provider(blockchain).await
        }
    }
}

pub async fn get_global_blockchain() -> Result<Arc<RwLock<Blockchain>>> {
    GLOBAL_BLOCKCHAIN.get()
        .ok_or_else(|| anyhow::anyhow!("Global blockchain provider not initialized"))
        .map(|blockchain| blockchain.clone())
}

pub fn is_global_blockchain_initialized() -> bool {
    GLOBAL_BLOCKCHAIN.get().is_some()
}

pub fn reset_global_blockchain_provider() {
    // Note: OnceCell doesn't support reset, so this is primarily for documentation
    // In practice, you'd need to restart the application to truly reset
    tracing::warn!("Global blockchain provider reset requested - requires application restart");
}

//! Utility functions for the ZHTP blockchain
//! 
//! Common utilities used throughout the blockchain package.

use crate::types::{Hash, Difficulty};
use crate::transaction::Transaction;
use crate::block::Block;

/// Time utilities
pub mod time {
    /// Get current UNIX timestamp
    pub fn current_timestamp() -> u64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs()
    }
    
    /// Check if timestamp is reasonable (not too far in future)
    pub fn is_reasonable_timestamp(timestamp: u64) -> bool {
        let now = current_timestamp();
        // Allow up to 2 hours in the future
        timestamp <= now + 7200
    }
    
    /// Format timestamp for display
    pub fn format_timestamp(timestamp: u64) -> String {
        use std::time::{UNIX_EPOCH, Duration};
        let datetime = UNIX_EPOCH + Duration::from_secs(timestamp);
        format!("{:?}", datetime)
    }
}

/// Size utilities
pub mod size {
    use super::*;
    
    /// Calculate transaction size in bytes
    pub fn transaction_size(transaction: &Transaction) -> usize {
        bincode::serialize(transaction).map(|data| data.len()).unwrap_or(0)
    }
    
    /// Calculate block size in bytes
    pub fn block_size(block: &Block) -> usize {
        bincode::serialize(block).map(|data| data.len()).unwrap_or(0)
    }
    
    /// Format size for human reading
    pub fn format_size(size: usize) -> String {
        if size < 1024 {
            format!("{} B", size)
        } else if size < 1024 * 1024 {
            format!("{:.2} KB", size as f64 / 1024.0)
        } else {
            format!("{:.2} MB", size as f64 / (1024.0 * 1024.0))
        }
    }
}

/// Hash utilities
pub mod hash {
    use super::*;
    
    /// Convert hash to hex string
    pub fn hash_to_hex(hash: &Hash) -> String {
        hex::encode(hash.as_bytes())
    }
    
    /// Parse hex string to hash
    pub fn hex_to_hash(hex: &str) -> Result<Hash, String> {
        let bytes = hex::decode(hex).map_err(|e| e.to_string())?;
        if bytes.len() != 32 {
            return Err("Hash must be 32 bytes".to_string());
        }
        Ok(Hash::from_slice(&bytes))
    }
    
    /// Generate random hash (for testing)
    pub fn random_hash() -> Hash {
        use rand::RngCore;
        let mut rng = rand::rngs::OsRng;
        let mut bytes = [0u8; 32];
        rng.fill_bytes(&mut bytes);
        Hash::from_slice(&bytes)
    }
}

/// Fee calculation utilities
pub mod fees {
    use super::*;
    
    /// Calculate minimum fee for transaction
    pub fn calculate_minimum_fee(transaction: &Transaction) -> u64 {
        let base_fee = 1000u64; // Base fee
        let size_fee = size::transaction_size(transaction) as u64; // 1 unit per byte
        base_fee + size_fee
    }
    
    /// Calculate fee rate (fee per byte)
    pub fn calculate_fee_rate(transaction: &Transaction) -> f64 {
        let tx_size = size::transaction_size(transaction);
        if tx_size > 0 {
            transaction.fee as f64 / tx_size as f64
        } else {
            0.0
        }
    }
    
    /// Check if transaction has sufficient fee
    pub fn has_sufficient_fee(transaction: &Transaction) -> bool {
        transaction.fee >= calculate_minimum_fee(transaction)
    }
}

/// Difficulty utilities
pub mod difficulty {
    use super::*;
    
    /// Calculate target from difficulty
    pub fn calculate_target(difficulty: Difficulty) -> [u8; 32] {
        difficulty.target()
    }
    
    /// Check if hash meets difficulty
    pub fn meets_difficulty(hash: &Hash, difficulty: Difficulty) -> bool {
        difficulty.check_hash(hash)
    }
    
    /// Calculate next difficulty adjustment
    pub fn calculate_next_difficulty(
        current_difficulty: Difficulty,
        actual_timespan: u64,
        target_timespan: u64,
    ) -> Difficulty {
        let actual_timespan = actual_timespan.max(target_timespan / 4).min(target_timespan * 4);
        let new_bits = (current_difficulty.bits() as u64 * target_timespan / actual_timespan) as u32;
        Difficulty::from_bits(new_bits)
    }
}

/// Validation utilities
pub mod validation {
    use super::*;
    
    /// Quick validation of transaction structure
    pub fn quick_validate_transaction(transaction: &Transaction) -> bool {
        // Basic checks
        transaction.version > 0 &&
        !transaction.signature.signature.is_empty() &&
        (transaction.inputs.is_empty() || transaction.transaction_type.is_identity_transaction())
    }
    
    /// Quick validation of block structure
    pub fn quick_validate_block(block: &Block) -> bool {
        block.header.version > 0 &&
        block.header.height < u64::MAX &&
        block.header.timestamp > 0 &&
        block.transaction_count() <= crate::MAX_TRANSACTIONS_PER_BLOCK
    }
    
    /// Check if DID format is valid
    pub fn is_valid_did_format(did: &str) -> bool {
        did.starts_with("did:zhtp:") && did.len() > 9
    }
}

/// Encoding utilities
pub mod encoding {
    use super::*;
    
    /// Encode transaction as JSON
    pub fn transaction_to_json(transaction: &Transaction) -> Result<String, String> {
        serde_json::to_string_pretty(transaction).map_err(|e| e.to_string())
    }
    
    /// Decode transaction from JSON
    pub fn transaction_from_json(json: &str) -> Result<Transaction, String> {
        serde_json::from_str(json).map_err(|e| e.to_string())
    }
    
    /// Encode block as JSON
    pub fn block_to_json(block: &Block) -> Result<String, String> {
        serde_json::to_string_pretty(block).map_err(|e| e.to_string())
    }
    
    /// Decode block from JSON
    pub fn block_from_json(json: &str) -> Result<Block, String> {
        serde_json::from_str(json).map_err(|e| e.to_string())
    }
    
    /// Encode as hex
    pub fn encode_hex(data: &[u8]) -> String {
        hex::encode(data)
    }
    
    /// Decode from hex
    pub fn decode_hex(hex: &str) -> Result<Vec<u8>, String> {
        hex::decode(hex).map_err(|e| e.to_string())
    }
}

