    /// Create a public contract call (no special permissions required)
    pub fn public_call(
        contract_type: ContractType,
        method: String,
        params: Vec<u8>,
    ) -> Self {
        Self::new(contract_type, method, params, CallPermissions::Public)
    }

    /// Create a token contract call
    pub fn token_call(method: String, params: Vec<u8>) -> Self {
        Self::public_call(ContractType::Token, method, params)
    }

    /// Create a messaging contract call
    pub fn messaging_call(method: String, params: Vec<u8>) -> Self {
        Self::public_call(ContractType::WhisperMessaging, method, params)
    }

    /// Create a contact contract call
    pub fn contact_call(method: String, params: Vec<u8>) -> Self {
        Self::public_call(ContractType::ContactRegistry, method, params)
    }

    /// Create a group contract call
    pub fn group_call(method: String, params: Vec<u8>) -> Self {
        Self::public_call(ContractType::GroupChat, method, params)
    }

    /// Create a file contract call
    pub fn file_call(method: String, params: Vec<u8>) -> Self {
        Self::public_call(ContractType::FileSharing, method, params)
    }

    /// Validate the contract call structure
    pub fn validate(&self) -> Result<(), String> {
        if self.method.is_empty() {
            return Err("Method name cannot be empty".to_string());
        }

        if self.method.len() > 64 {
            return Err("Method name too long (max 64 characters)".to_string());
        }

        // Validate method name contains only alphanumeric characters and underscores
        if !self
            .method
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_')
        {
            return Err("Method name contains invalid characters".to_string());
        }

        // Validate parameter size
        if self.params.len() > 1024 * 1024 {
            return Err("Parameters too large (max 1MB)".to_string());
        }

        Ok(())
    }

    /// Get the caller's public key from permissions (if available)
    pub fn get_caller(&self) -> Result<crate::integration::crypto_integration::PublicKey, String> {
        match &self.permissions {
            CallPermissions::Public => {
                Err("Public call does not specify caller".to_string())
            }
            CallPermissions::Restricted { caller, .. } => {
                Ok(caller.clone())
            }
            CallPermissions::AdminOnly { admin } => {
                Ok(admin.clone())
            }
        }
    }

    /// Serialize a parameter for inclusion in params
    pub fn serialize_params<T: Serialize>(params: &T) -> Result<Vec<u8>, bincode::Error> {
        bincode::serialize(params)
    }

    /// Deserialize parameters from the call
    pub fn deserialize_params<T: for<'de> Deserialize<'de>>(&self) -> Result<T, String> {
        bincode::deserialize(&self.params)
            .map_err(|e| format!("Failed to deserialize parameters: {}", e))
    }

    /// Check if the call has parameters
    pub fn has_params(&self) -> bool {
        !self.params.is_empty()
    }

    /// Get parameter size
    pub fn param_size(&self) -> usize {
        self.params.len()
    }

    /// Get contract type gas cost
    pub fn base_gas_cost(&self) -> u64 {
        self.contract_type.gas_cost()
    }
}

pub enum CallPermissions {
    /// Public call, no special permissions required
    Public,
    /// Restricted call requiring specific caller
    Restricted {
        caller: crate::integration::crypto_integration::PublicKey,
        permissions: Vec<String>,
    },
    /// Admin-only call
    AdminOnly {
        admin: crate::integration::crypto_integration::PublicKey,
    },
}

impl CallPermissions {
    /// Create restricted permissions
    pub fn restricted(caller: crate::integration::crypto_integration::PublicKey, permissions: Vec<String>) -> Self {
        Self::Restricted { caller, permissions }
    }

    /// Create admin-only permissions
    pub fn admin_only(admin: crate::integration::crypto_integration::PublicKey) -> Self {
        Self::AdminOnly { admin }
    }

    /// Check if permissions allow a specific operation
    pub fn allows_operation(&self, operation: &str, caller: &crate::integration::crypto_integration::PublicKey) -> bool {
        match self {
            CallPermissions::Public => true,
            CallPermissions::Restricted { caller: allowed_caller, permissions } => {
                allowed_caller == caller && (permissions.is_empty() || permissions.contains(&operation.to_string()))
            }
            CallPermissions::AdminOnly { admin } => admin == caller,
        }
    }

    /// Check if permissions require a specific caller
    pub fn requires_caller(&self) -> bool {
        !matches!(self, CallPermissions::Public)
    }
}

pub enum ContractType {
    /// Token contract - supports ZHTP native and custom tokens
    Token,
    /// Whisper messaging contract - encrypted messaging with token gates
    WhisperMessaging,
    /// Contact registry contract - decentralized address book
    ContactRegistry,
    /// Group chat contract - multi-party encrypted communication
    GroupChat,
    /// File sharing contract - encrypted file storage and sharing
    FileSharing,
    /// Governance contract - on-chain governance and voting
    Governance,
    /// Web4 website contract - decentralized website hosting
    Web4Website,
}

impl ContractType {
    /// Get the gas cost multiplier for this contract type
    pub fn gas_cost(&self) -> u64 {
        match self {
            ContractType::Token => crate::contracts::GAS_TOKEN,
            ContractType::WhisperMessaging => crate::contracts::GAS_MESSAGING,
            ContractType::ContactRegistry => crate::contracts::GAS_CONTACT,
            ContractType::GroupChat => crate::contracts::GAS_GROUP,
            ContractType::FileSharing => crate::contracts::GAS_MESSAGING, // Same as messaging due to complexity
            ContractType::Governance => crate::contracts::GAS_GROUP, // Same as group due to voting complexity
            ContractType::Web4Website => crate::contracts::GAS_MESSAGING, // Similar to file sharing complexity
        }
    }

    /// Check if this contract type supports minting operations
    pub fn supports_minting(&self) -> bool {
        matches!(self, ContractType::Token)
    }

    /// Check if this contract type supports burning operations
    pub fn supports_burning(&self) -> bool {
        matches!(
            self,
            ContractType::Token | ContractType::WhisperMessaging
        )
    }

    /// Get human-readable name for the contract type
    pub fn name(&self) -> &'static str {
        match self {
            ContractType::Token => "Token Contract",
            ContractType::WhisperMessaging => "Whisper Messaging Contract",
            ContractType::ContactRegistry => "Contact Registry Contract",
            ContractType::GroupChat => "Group Chat Contract",
            ContractType::FileSharing => "File Sharing Contract",
            ContractType::Governance => "Governance Contract",
            ContractType::Web4Website => "Web4 Website Contract",
        }
    }
}

pub struct ContractLog {
    /// ID of the contract that emitted this log
    pub contract_id: [u8; 32],
    /// Event name (e.g., "Transfer", "MessageSent", "GroupCreated")
    pub event: String,
    /// Event data (serialized event parameters)
    pub data: Vec<u8>,
    /// Indexed fields for efficient filtering and searching
    pub indexed_fields: Vec<Vec<u8>>,
}

impl ContractLog {
    /// Create a new contract log
    pub fn new(
        contract_id: [u8; 32],
        event: String,
        data: Vec<u8>,
        indexed_fields: Vec<Vec<u8>>,
    ) -> Self {
        Self {
            contract_id,
            event,
            data,
            indexed_fields,
        }
    }

    /// Create a log with serialized data
    pub fn with_data<T: Serialize>(
        contract_id: [u8; 32],
        event: String,
        data: &T,
        indexed_fields: Vec<Vec<u8>>,
    ) -> Result<Self, bincode::Error> {
        Ok(Self {
            contract_id,
            event,
            data: bincode::serialize(data)?,
            indexed_fields,
        })
    }

    /// Create a Transfer event log
    pub fn transfer_event(
        contract_id: [u8; 32],
        from: &[u8],
        to: &[u8],
        amount: u64,
    ) -> Result<Self, bincode::Error> {
        let data = (from, to, amount);
        Self::with_data(
            contract_id,
            "Transfer".to_string(),
            &data,
            vec![from.to_vec(), to.to_vec()],
        )
    }

    /// Create a MessageSent event log
    pub fn message_sent_event(
        contract_id: [u8; 32],
        sender: &[u8],
        recipient: Option<&[u8]>,
        message_id: &[u8; 32],
    ) -> Result<Self, bincode::Error> {
        let data = (sender, recipient, message_id);
        let mut indexed_fields = vec![sender.to_vec()];
        if let Some(recipient) = recipient {
            indexed_fields.push(recipient.to_vec());
        }

        Self::with_data(
            contract_id,
            "MessageSent".to_string(),
            &data,
            indexed_fields,
        )
    }

    /// Create a GroupCreated event log
    pub fn group_created_event(
        contract_id: [u8; 32],
        creator: &[u8],
        group_id: &[u8; 32],
        group_name: &str,
    ) -> Result<Self, bincode::Error> {
        let data = (creator, group_id, group_name);
        Self::with_data(
            contract_id,
            "GroupCreated".to_string(),
            &data,
            vec![creator.to_vec()],
        )
    }

    /// Create a ContactAdded event log
    pub fn contact_added_event(
        contract_id: [u8; 32],
        owner: &[u8],
        contact_id: &[u8; 32],
        contact_key: &[u8],
    ) -> Result<Self, bincode::Error> {
        let data = (owner, contact_id, contact_key);
        Self::with_data(
            contract_id,
            "ContactAdded".to_string(),
            &data,
            vec![owner.to_vec(), contact_key.to_vec()],
        )
    }

    /// Get the event data as a specific type
    pub fn get_data<T: for<'de> Deserialize<'de>>(&self) -> Result<T, bincode::Error> {
        bincode::deserialize(&self.data)
    }

    /// Check if this log contains a specific indexed field
    pub fn has_indexed_field(&self, field: &[u8]) -> bool {
        self.indexed_fields.iter().any(|f| f == field)
    }

    /// Get the size of the log in bytes (for storage calculations)
    pub fn size(&self) -> usize {
        32 + // contract_id
        4 + self.event.len() + // event string with length prefix
        4 + self.data.len() + // data with length prefix
        4 + self.indexed_fields.iter().map(|f| 4 + f.len()).sum::<usize>() // indexed_fields with length prefixes
    }

    /// Check if this is a specific event type
    pub fn is_event(&self, event_name: &str) -> bool {
        self.event == event_name
    }

    /// Get a summary of the log for debugging
    pub fn summary(&self) -> String {
        format!(
            "ContractLog {{ contract: {}, event: {}, data_size: {}, indexed_fields: {} }}",
            hex::encode(self.contract_id),
            self.event,
            self.data.len(),
            self.indexed_fields.len()
        )
    }
}

pub enum MessageType {
    /// Direct message between two users
    DirectMessage,
    /// Message sent to a group
    GroupMessage,
    /// File attachment message
    FileAttachment,
    /// System-generated message
    SystemMessage,
    /// Message burn request
    BurnRequest,
}

impl MessageType {
    /// Get string representation of message type
    pub fn as_str(&self) -> &'static str {
        match self {
            MessageType::DirectMessage => "DirectMessage",
            MessageType::GroupMessage => "GroupMessage",
            MessageType::FileAttachment => "FileAttachment",
            MessageType::SystemMessage => "SystemMessage",
            MessageType::BurnRequest => "BurnRequest",
        }
    }

    /// Check if this message type supports encryption
    pub fn supports_encryption(&self) -> bool {
        matches!(
            self,
            MessageType::DirectMessage | MessageType::GroupMessage | MessageType::FileAttachment
        )
    }

    /// Check if this message type can be burned
    pub fn can_be_burned(&self) -> bool {
        matches!(
            self,
            MessageType::DirectMessage | MessageType::GroupMessage | MessageType::FileAttachment
        )
    }

    /// Get the base gas cost for this message type
    pub fn base_gas_cost(&self) -> u64 {
        match self {
            MessageType::DirectMessage => 3000,
            MessageType::GroupMessage => 4000, // Higher cost for group distribution
            MessageType::FileAttachment => 5000, // Highest cost for file handling
            MessageType::SystemMessage => 1000, // Lower cost for system messages
            MessageType::BurnRequest => 1500, // Moderate cost for burning
        }
    }
}

pub struct ContractPermissions {
    /// Whether the contract can mint new tokens/assets
    pub can_mint: bool,
    /// Whether the contract can burn tokens/assets
    pub can_burn: bool,
    /// Whether the contract can be paused for emergency situations
    pub can_pause: bool,
    /// List of administrators who can perform privileged operations
    pub admins: Vec<crate::integration::crypto_integration::PublicKey>,
}

impl ContractPermissions {
    /// Create new permissions with default settings
    pub fn new() -> Self {
        Self {
            can_mint: false,
            can_burn: false,
            can_pause: false,
            admins: Vec::new(),
        }
    }

    /// Create permissions for a token contract
    pub fn for_token(creator: crate::integration::crypto_integration::PublicKey, can_mint: bool, can_burn: bool) -> Self {
        Self {
            can_mint,
            can_burn,
            can_pause: false,
            admins: vec![creator],
        }
    }

    /// Create permissions for ZHTP native token
    pub fn for_lib_token() -> Self {
        Self {
            can_mint: true, // For network rewards
            can_burn: false, // ZHTP is not deflationary
            can_pause: false,
            admins: vec![], // No single admin for native token
        }
    }

    /// Create permissions for messaging contracts
    pub fn for_messaging() -> Self {
        Self {
            can_mint: false,
            can_burn: true, // Messages can be burned
            can_pause: false,
            admins: vec![],
        }
    }

    /// Create permissions for social contracts (contacts, groups)
    pub fn for_social(creator: crate::integration::crypto_integration::PublicKey) -> Self {
        Self {
            can_mint: false,
            can_burn: false,
            can_pause: false,
            admins: vec![creator],
        }
    }

    /// Check if a public key is an admin
    pub fn is_admin(&self, public_key: &crate::integration::crypto_integration::PublicKey) -> bool {
        self.admins.contains(public_key)
    }

    /// Add a new admin
    pub fn add_admin(&mut self, admin: crate::integration::crypto_integration::PublicKey) {
        if !self.admins.contains(&admin) {
            self.admins.push(admin);
        }
    }

    /// Remove an admin
    pub fn remove_admin(&mut self, admin: &crate::integration::crypto_integration::PublicKey) {
        self.admins.retain(|a| a != admin);
    }

    /// Check if any privileged operation is allowed
    pub fn has_privileged_permissions(&self) -> bool {
        self.can_mint || self.can_burn || self.can_pause || !self.admins.is_empty()
    }

    /// Validate permissions for a specific operation
    pub fn can_perform_operation(&self, operation: &str, caller: &crate::integration::crypto_integration::PublicKey) -> bool {
        match operation {
            "mint" => self.can_mint && (self.admins.is_empty() || self.is_admin(caller)),
            "burn" => self.can_burn,
            "pause" => self.can_pause && self.is_admin(caller),
            "admin" => self.is_admin(caller),
            _ => false,
        }
    }
}

impl Default for ContractPermissions {
    fn default() -> Self {
        Self::new()
    }
}

pub struct ContractResult {
    /// Whether the contract execution was successful
    pub success: bool,
    /// Return data from the contract function
    pub return_data: Vec<u8>,
    /// Amount of gas consumed during execution
    pub gas_used: u64,
    /// Events logged during execution
    pub logs: Vec<super::ContractLog>,
    /// State changes to be applied to contract storage
    pub state_changes: HashMap<Vec<u8>, Vec<u8>>,
}

impl ContractResult {
    /// Create a new successful contract result
    pub fn success() -> Self {
        Self {
            success: true,
            return_data: Vec::new(),
            gas_used: 0,
            logs: Vec::new(),
            state_changes: HashMap::new(),
        }
    }

    /// Create a new failed contract result
    pub fn failure(gas_used: u64) -> Self {
        Self {
            success: false,
            return_data: Vec::new(),
            gas_used,
            logs: Vec::new(),
            state_changes: HashMap::new(),
        }
    }

    /// Create a contract result with specific gas usage
    pub fn with_gas(gas_used: u64) -> Self {
        Self {
            success: true,
            return_data: Vec::new(),
            gas_used,
            logs: Vec::new(),
            state_changes: HashMap::new(),
        }
    }

    /// Create a contract result with return data
    pub fn with_return_data<T: Serialize>(data: &T, gas_used: u64) -> Result<Self, bincode::Error> {
        Ok(Self {
            success: true,
            return_data: bincode::serialize(data)?,
            gas_used,
            logs: Vec::new(),
            state_changes: HashMap::new(),
        })
    }

    /// Set return data for the result
    pub fn set_return_data<T: Serialize>(&mut self, data: &T) -> Result<(), bincode::Error> {
        self.return_data = bincode::serialize(data)?;
        Ok(())
    }

    /// Get return data as a specific type
    pub fn get_return_data<T: for<'de> Deserialize<'de>>(&self) -> Result<T, bincode::Error> {
        bincode::deserialize(&self.return_data)
    }

    /// Add a log entry to the result
    pub fn add_log(&mut self, log: super::ContractLog) {
        self.logs.push(log);
    }

    /// Add a state change to the result
    pub fn add_state_change(&mut self, key: Vec<u8>, value: Vec<u8>) {
        self.state_changes.insert(key, value);
    }

    /// Remove a state entry (set to empty for deletion)
    pub fn remove_state(&mut self, key: Vec<u8>) {
        self.state_changes.insert(key, Vec::new());
    }

    /// Check if the result has any state changes
    pub fn has_state_changes(&self) -> bool {
        !self.state_changes.is_empty()
    }

    /// Check if the result has any logs
    pub fn has_logs(&self) -> bool {
        !self.logs.is_empty()
    }

    /// Check if the result has return data
    pub fn has_return_data(&self) -> bool {
        !self.return_data.is_empty()
    }

    /// Calculate total cost (gas used plus any additional fees)
    pub fn total_cost(&self, gas_price: u64) -> u64 {
        self.gas_used * gas_price
    }

    /// Mark the result as failed
    pub fn mark_failed(&mut self) {
        self.success = false;
        // Clear state changes on failure (rollback)
        self.state_changes.clear();
    }

    /// Merge another result into this one (for complex operations)
    pub fn merge(&mut self, other: ContractResult) {
        if !other.success {
            self.mark_failed();
            return;
        }

        self.gas_used += other.gas_used;
        self.logs.extend(other.logs);
        self.state_changes.extend(other.state_changes);

        // If other has return data, it overrides ours
        if !other.return_data.is_empty() {
            self.return_data = other.return_data;
        }
    }

    /// Create a summary of the execution result
    pub fn summary(&self) -> String {
        format!(
            "ContractResult {{ success: {}, gas_used: {}, logs: {}, state_changes: {}, return_data_size: {} }}",
            self.success,
            self.gas_used,
            self.logs.len(),
            self.state_changes.len(),
            self.return_data.len()
        )
    }
}

impl Default for ContractResult {
    fn default() -> Self {
        Self::success()
    }
}

pub struct TokenContract {
    /// Unique token identifier
    pub token_id: [u8; 32],
    /// Human-readable token name
    pub name: String,
    /// Token symbol (e.g., "ZHTP", "WHISPER")
    pub symbol: String,
    /// Number of decimal places
    pub decimals: u8,
    /// Current total supply in circulation
    pub total_supply: u64,
    /// Maximum supply that can ever exist
    pub max_supply: u64,
    /// Whether the token burns on transfer (deflationary)
    pub is_deflationary: bool,
    /// Amount burned per transfer (if deflationary)
    pub burn_rate: u64,
    /// Account balances mapping
    pub balances: HashMap<PublicKey, u64>,
    /// Allowances for third-party transfers
    pub allowances: HashMap<PublicKey, HashMap<PublicKey, u64>>,
    /// Token creator
    pub creator: PublicKey,
}

impl TokenContract {
    /// Create a new token contract
    pub fn new(
        token_id: [u8; 32],
        name: String,
        symbol: String,
        decimals: u8,
        max_supply: u64,
        is_deflationary: bool,
        burn_rate: u64,
        creator: PublicKey,
    ) -> Self {
        Self {
            token_id,
            name,
            symbol,
            decimals,
            total_supply: 0,
            max_supply,
            is_deflationary,
            burn_rate,
            balances: HashMap::new(),
            allowances: HashMap::new(),
            creator,
        }
    }

    /// Create ZHTP native token
    pub fn new_zhtp() -> Self {
        let creator = PublicKey::new(vec![0u8; 1312]); // Mock creator for ZHTP
        Self::new(
            crate::contracts::utils::generate_lib_token_id(),
            crate::contracts::ZHTP_TOKEN_NAME.to_string(),
            crate::contracts::ZHTP_TOKEN_SYMBOL.to_string(),
            crate::contracts::ZHTP_DECIMALS,
            crate::contracts::ZHTP_MAX_SUPPLY,
            false, // ZHTP is not deflationary
            0,     // No burn rate for ZHTP
            creator,
        )
    }

    /// Create a custom token (for dApps)
    pub fn new_custom(
        name: String,
        symbol: String,
        initial_supply: u64,
        creator: PublicKey,
    ) -> Self {
        let token_id = crate::contracts::utils::generate_custom_token_id(&name, &symbol);
        let mut token = Self::new(
            token_id,
            name,
            symbol,
            8, // Default 8 decimals
            u64::MAX, // Very large max supply
            false, // Not deflationary by default
            0,     // No burn rate
            creator.clone(),
        );

        // Mint initial supply to creator
        if initial_supply > 0 {
            let _ = token.mint(&creator, initial_supply);
        }

        token
    }

    /// Get balance of an account
    pub fn balance_of(&self, account: &PublicKey) -> u64 {
        self.balances.get(account).copied().unwrap_or(0)
    }

    /// Get allowance for a spender
    pub fn allowance(&self, owner: &PublicKey, spender: &PublicKey) -> u64 {
        self.allowances
            .get(owner)
            .and_then(|spenders| spenders.get(spender))
            .copied()
            .unwrap_or(0)
    }

    /// Transfer tokens between accounts
    pub fn transfer(&mut self, from: &PublicKey, to: &PublicKey, amount: u64) -> Result<u64, String> {
        let from_balance = self.balance_of(from);
        if from_balance < amount {
            return Err("Insufficient balance".to_string());
        }

        // Calculate burn amount if deflationary
        let burn_amount = if self.is_deflationary {
            std::cmp::min(self.burn_rate, amount)
        } else {
            0
        };

        // Perform transfer
        self.balances.insert(from.clone(), from_balance - amount);
        let to_balance = self.balance_of(to);
        self.balances.insert(to.clone(), to_balance + amount);

        // Apply burn
        if burn_amount > 0 {
            self.total_supply = self.total_supply.saturating_sub(burn_amount);
        }

        Ok(burn_amount)
    }

    /// Transfer from an allowance
    pub fn transfer_from(
        &mut self,
        owner: &PublicKey,
        to: &PublicKey,
        amount: u64,
        spender: &PublicKey,
    ) -> Result<u64, String> {
        let allowance = self.allowance(owner, spender);
        if allowance < amount {
            return Err("Insufficient allowance".to_string());
        }

        // Reduce allowance
        self.allowances
            .entry(owner.clone())
            .or_insert_with(HashMap::new)
            .insert(spender.clone(), allowance - amount);

        // Perform transfer
        self.transfer(owner, to, amount)
    }

    /// Approve spending allowance
    pub fn approve(&mut self, owner: &PublicKey, spender: &PublicKey, amount: u64) {
        self.allowances
            .entry(owner.clone())
            .or_insert_with(HashMap::new)
            .insert(spender.clone(), amount);
    }

    /// Mint new tokens
    pub fn mint(&mut self, to: &PublicKey, amount: u64) -> Result<(), String> {
        if self.total_supply + amount > self.max_supply {
            return Err("Would exceed maximum supply".to_string());
        }

        let balance = self.balance_of(to);
        self.balances.insert(to.clone(), balance + amount);
        self.total_supply += amount;

        Ok(())
    }

    /// Burn tokens from an account
    pub fn burn(&mut self, from: &PublicKey, amount: u64) -> Result<(), String> {
        let balance = self.balance_of(from);
        if balance < amount {
            return Err("Insufficient balance to burn".to_string());
        }

        self.balances.insert(from.clone(), balance - amount);
        self.total_supply = self.total_supply.saturating_sub(amount);

        Ok(())
    }

    /// Check if supply can accommodate minting
    pub fn can_mint(&self, amount: u64) -> bool {
        self.total_supply + amount <= self.max_supply
    }

    /// Get remaining mintable supply
    pub fn remaining_supply(&self) -> u64 {
        self.max_supply.saturating_sub(self.total_supply)
    }

    /// Get token information as a summary
    pub fn info(&self) -> TokenInfo {
        TokenInfo {
            token_id: self.token_id,
            name: self.name.clone(),
            symbol: self.symbol.clone(),
            decimals: self.decimals,
            total_supply: self.total_supply,
            max_supply: self.max_supply,
            is_deflationary: self.is_deflationary,
            burn_rate: self.burn_rate,
            creator: self.creator.clone(),
        }
    }

    /// Validate token parameters
    pub fn validate(&self) -> Result<(), String> {
        if self.name.is_empty() {
            return Err("Token name cannot be empty".to_string());
        }

        if self.symbol.is_empty() {
            return Err("Token symbol cannot be empty".to_string());
        }

        if self.symbol.len() > 10 {
            return Err("Token symbol too long (max 10 characters)".to_string());
        }

        if self.decimals > 18 {
            return Err("Too many decimal places (max 18)".to_string());
        }

        if self.max_supply == 0 {
            return Err("Maximum supply must be greater than 0".to_string());
        }

        if self.total_supply > self.max_supply {
            return Err("Total supply cannot exceed maximum supply".to_string());
        }

        if self.is_deflationary && self.burn_rate == 0 {
            return Err("Deflationary token must have burn rate > 0".to_string());
        }

        Ok(())
    }

    /// Get the total number of holders
    pub fn holder_count(&self) -> usize {
        self.balances.iter().filter(|(_, &balance)| balance > 0).count()
    }

    /// Calculate market cap (requires external price data)
    pub fn market_cap(&self, price_per_token: f64) -> f64 {
        (self.total_supply as f64 / 10f64.powi(self.decimals as i32)) * price_per_token
    }
}

pub fn get_balance(contract: &TokenContract, account: &PublicKey) -> u64 {
    contract.balance_of(account)
}

pub fn get_token_info(contract: &TokenContract) -> TokenInfo {
    contract.info()
}

pub fn validate_token(contract: &TokenContract) -> Result<(), String> {
    contract.validate()
}

pub fn can_mint_amount(contract: &TokenContract, amount: u64) -> bool {
    contract.can_mint(amount)
}

pub fn get_remaining_supply(contract: &TokenContract) -> u64 {
    contract.remaining_supply()
}

pub fn get_holder_count(contract: &TokenContract) -> usize {
    contract.holder_count()
}

pub fn calculate_market_cap(contract: &TokenContract, price_per_token: f64) -> f64 {
    contract.market_cap(price_per_token)
}

pub fn create_zhtp_token() -> TokenContract {
    TokenContract::new_zhtp()
}

pub fn calculate_tvl(contract: &TokenContract, price_per_token: f64) -> f64 {
    let total_locked: u64 = contract.balances.values().sum();
    (total_locked as f64 / 10f64.powi(contract.decimals as i32)) * price_per_token
}

pub fn get_distribution_stats(contract: &TokenContract) -> TokenDistributionStats {
    let balances: Vec<u64> = contract.balances
        .values()
        .filter(|&&balance| balance > 0)
        .copied()
        .collect();

    if balances.is_empty() {
        return TokenDistributionStats::default();
    }

    let total_holders = balances.len();
    let total_supply = contract.total_supply;
    let largest_balance = *balances.iter().max().unwrap_or(&0);
    let smallest_balance = *balances.iter().min().unwrap_or(&0);
    let average_balance = total_supply / total_holders as u64;

    // Calculate concentration (percentage held by top holder)
    let concentration = if total_supply > 0 {
        (largest_balance as f64 / total_supply as f64) * 100.0
    } else {
        0.0
    };

    TokenDistributionStats {
        total_holders,
        largest_balance,
        smallest_balance,
        average_balance,
        concentration_percentage: concentration,
        total_supply,
    }
}

impl Default for TokenDistributionStats {
    fn default() -> Self {
        Self {
            total_holders: 0,
            largest_balance: 0,
            smallest_balance: 0,
            average_balance: 0,
            concentration_percentage: 0.0,
            total_supply: 0,
        }
    }
}

