}

pub struct SandboxConfig {
    /// Security level
    pub security_level: SecurityLevel,
    /// Memory limits
    pub memory_limits: MemoryLimits,
    /// Execution limits
    pub execution_limits: ExecutionLimits,
    /// Allowed host functions
    pub allowed_host_functions: Vec<String>,
    /// Resource limits
