pub struct ContractUTXO {
    /// Transaction output representing the UTXO
    pub output: TransactionOutput,
    /// Transaction hash containing this output
    pub txid: [u8; 32],
    /// Output index in the transaction
    pub vout: u32,
    /// Contract state hash
    pub state_hash: [u8; 32],
    /// Contract type identifier
    pub contract_type: ContractType,
    /// Additional contract metadata
    pub metadata: Vec<u8>,
}

impl ContractUTXO {
    /// Create new contract UTXO
    pub fn new(
        output: TransactionOutput,
        txid: [u8; 32],
        vout: u32,
        state_hash: [u8; 32],
        contract_type: ContractType,
        metadata: Vec<u8>,
    ) -> Self {
        Self {
            output,
            txid,
            vout,
            state_hash,
            contract_type,
            metadata,
        }
    }

    /// Validate contract UTXO
    pub fn validate(&self) -> Result<()> {
        // Validate state hash
        if self.state_hash == [0u8; 32] {
            return Err(anyhow!("Invalid state hash"));
        }

        // Validate metadata size
        if self.metadata.len() > 1024 {
            return Err(anyhow!("Contract metadata too large"));
        }

        Ok(())
    }

    /// Get contract identifier
    pub fn contract_id(&self) -> [u8; 32] {
        crate::contracts::utils::generate_contract_id(&[
            &self.txid,
            &self.vout.to_le_bytes(),
            &self.state_hash,
        ])
    }
}

pub struct ContractTransactionBuilder {
    calls: Vec<(ContractCall, Signature)>,
    inputs: Vec<TransactionInput>,
    outputs: Vec<TransactionOutput>,
    fee: u64,
}

impl ContractTransactionBuilder {
    /// Create new transaction builder
    pub fn new() -> Self {
        Self {
            calls: Vec::new(),
            inputs: Vec::new(),
            outputs: Vec::new(),
            fee: 0,
        }
    }

    /// Add contract call
    pub fn add_call(&mut self, call: ContractCall, signature: Signature) -> &mut Self {
        self.calls.push((call, signature));
        self
    }

    /// Add input
    pub fn add_input(&mut self, input: TransactionInput) -> &mut Self {
        self.inputs.push(input);
        self
    }

    /// Add output
    pub fn add_output(&mut self, output: TransactionOutput) -> &mut Self {
        self.outputs.push(output);
        self
    }

    /// Set transaction fee
    pub fn set_fee(&mut self, fee: u64) -> &mut Self {
        self.fee = fee;
        self
    }

    /// Build transaction
    pub fn build(&self, keypair: &KeyPair) -> Result<Transaction> {
        if self.calls.is_empty() {
            return Err(anyhow!("No contract calls specified"));
        }

        // Serialize contract calls
        let mut memo = Vec::new();
        memo.extend_from_slice(b"ZHTP"); // Contract transaction marker

        for (call, signature) in &self.calls {
            let call_data = bincode::serialize(&(call, signature))?;
            memo.extend_from_slice(&call_data);
        }

        // Sign transaction (simplified - would need proper signing logic)
        let temp_tx = Transaction {
            version: 1,
            chain_id: 0x03, // Default to development network
            transaction_type: TransactionType::ContractExecution,
            inputs: self.inputs.clone(),
            outputs: self.outputs.clone(),
            fee: self.fee,
            signature: crate::integration::crypto_integration::Signature {
                signature: Vec::new(),
                public_key: crate::integration::crypto_integration::PublicKey::new(Vec::new()),
                algorithm: crate::integration::crypto_integration::SignatureAlgorithm::Dilithium2,
                timestamp: 0,
            }, // Temporary placeholder
            memo: memo.clone(),
            identity_data: None,
            wallet_data: None,
            validator_data: None,
            dao_proposal_data: None,
            dao_vote_data: None,
            dao_execution_data: None,
        };

        let tx_hash = temp_tx.signing_hash();
        let signature = keypair.sign(&tx_hash.as_array())?;

        let tx = Transaction {
            version: 1,
            chain_id: 0x03, // Default to development network
            transaction_type: TransactionType::ContractExecution,
            inputs: self.inputs.clone(),
            outputs: self.outputs.clone(),
            fee: self.fee,
            signature,
            memo,
            identity_data: None,
            wallet_data: None,
            validator_data: None,
            dao_proposal_data: None,
            dao_vote_data: None,
            dao_execution_data: None,
        };

        Ok(tx)
    }
}

impl Default for ContractTransactionBuilder {
    fn default() -> Self {
        Self::new()
    }
}

pub enum ContractEvent {
    /// Token transfer event
    TokenTransfer {
        token_id: [u8; 32],
        from: PublicKey,
        to: PublicKey,
        amount: u64,
    },
    /// Message sent event
    MessageSent {
        message_id: [u8; 32],
        sender: PublicKey,
        recipient: Option<PublicKey>,
        group_id: Option<[u8; 32]>,
    },
    /// Contact added event
    ContactAdded {
        contact_id: [u8; 32],
        owner: PublicKey,
        contact: PublicKey,
    },
    /// Group created event
    GroupCreated {
        group_id: [u8; 32],
        creator: PublicKey,
        name: String,
    },
    /// File shared event
    FileShared {
        file_id: [u8; 32],
        owner: PublicKey,
        filename: String,
    },
}

impl ContractEvent {
    /// Get event type as string
    pub fn event_type(&self) -> &'static str {
        match self {
            ContractEvent::TokenTransfer { .. } => "TokenTransfer",
            ContractEvent::MessageSent { .. } => "MessageSent",
            ContractEvent::ContactAdded { .. } => "ContactAdded",
            ContractEvent::GroupCreated { .. } => "GroupCreated",
            ContractEvent::FileShared { .. } => "FileShared",
        }
    }

    /// Serialize event to bytes
    pub fn to_bytes(&self) -> Result<Vec<u8>> {
        bincode::serialize(self).map_err(|e| anyhow!("Serialization error: {}", e))
    }

    /// Deserialize event from bytes
    pub fn from_bytes(data: &[u8]) -> Result<Self> {
        bincode::deserialize(data).map_err(|e| anyhow!("Deserialization error: {}", e))
    }
}

pub trait ContractEventListener {
    /// Handle contract event
    fn on_event(&mut self, event: ContractEvent) -> Result<()>;
}

pub struct ContractEventPublisher {
    listeners: Vec<Box<dyn ContractEventListener>>,
}

impl ContractEventPublisher {
    /// Create new event publisher
    pub fn new() -> Self {
        Self {
            listeners: Vec::new(),
        }
    }

    /// Add event listener
    pub fn add_listener(&mut self, listener: Box<dyn ContractEventListener>) {
        self.listeners.push(listener);
    }

    /// Publish event to all listeners
    pub fn publish(&mut self, event: ContractEvent) -> Result<()> {
        for listener in &mut self.listeners {
            listener.on_event(event.clone())?;
        }
        Ok(())
    }
}

impl Default for ContractEventPublisher {
    fn default() -> Self {
        Self::new()
    }
}

pub struct GroupChat {
    /// Unique group identifier
    pub group_id: [u8; 32],
    /// Group name
    pub name: String,
    /// Group description
    pub description: String,
    /// Group creator
    pub creator: PublicKey,
    /// List of group administrators
    pub admins: Vec<PublicKey>,
    /// List of group members
    pub members: Vec<PublicKey>,
    /// Maximum number of members allowed
    pub max_members: u32,
    /// Whether the group is private (invite-only)
    pub is_private: bool,
    /// Timestamp when group was created
    pub created_timestamp: u64,
    /// Cost in WHISPER tokens to join the group
    pub whisper_token_cost: u64,
}

impl GroupChat {
    /// Create a new group
    pub fn new(
        name: String,
        description: String,
        creator: PublicKey,
        max_members: u32,
        is_private: bool,
        whisper_token_cost: u64,
    ) -> Self {
        let created_timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let group_id = crate::contracts::utils::generate_group_id(
            &creator.key_id,
            &name,
            created_timestamp as u128 * 1_000_000_000,
        );

        Self {
            group_id,
            name,
            description,
            creator: creator.clone(),
            admins: vec![creator.clone()],
            members: vec![creator],
            max_members,
            is_private,
            created_timestamp,
            whisper_token_cost,
        }
    }

    /// Check if a user is a member
    pub fn is_member(&self, user: &PublicKey) -> bool {
        self.members.contains(user)
    }

    /// Check if a user is an admin
    pub fn is_admin(&self, user: &PublicKey) -> bool {
        self.admins.contains(user)
    }

    /// Check if the group can accept new members
    pub fn can_add_member(&self) -> bool {
        (self.members.len() as u32) < self.max_members
    }

    /// Add a new member to the group
    pub fn add_member(&mut self, user: PublicKey) -> Result<(), String> {
        if self.is_member(&user) {
            return Err("User is already a member".to_string());
        }

        if !self.can_add_member() {
            return Err("Group is at maximum capacity".to_string());
        }

        self.members.push(user);
        Ok(())
    }

    /// Remove a member from the group
    pub fn remove_member(&mut self, user: &PublicKey) -> Result<(), String> {
        if !self.is_member(user) {
            return Err("User is not a member".to_string());
        }

        // Creator cannot be removed
        if *user == self.creator {
            return Err("Cannot remove group creator".to_string());
        }

        self.members.retain(|m| m != user);
        self.admins.retain(|a| a != user); // Also remove from admins if they were one
        Ok(())
    }

    /// Add a new admin
    pub fn add_admin(&mut self, user: PublicKey) -> Result<(), String> {
        if !self.is_member(&user) {
            return Err("User must be a member to become admin".to_string());
        }

        if self.is_admin(&user) {
            return Err("User is already an admin".to_string());
        }

        self.admins.push(user);
        Ok(())
    }

    /// Remove an admin
    pub fn remove_admin(&mut self, user: &PublicKey) -> Result<(), String> {
        if *user == self.creator {
            return Err("Cannot remove creator from admin role".to_string());
        }

        if !self.is_admin(user) {
            return Err("User is not an admin".to_string());
        }

        self.admins.retain(|a| a != user);
        Ok(())
    }

    /// Get member count
    pub fn member_count(&self) -> usize {
        self.members.len()
    }

    /// Get storage key for this group
    pub fn storage_key(&self) -> Vec<u8> {
        crate::contracts::utils::generate_storage_key("group", &self.group_id)
    }

    /// Validate group structure
    pub fn validate(&self) -> Result<(), String> {
        if self.name.is_empty() {
            return Err("Group name cannot be empty".to_string());
        }

        if self.name.len() > 64 {
            return Err("Group name too long (max 64 characters)".to_string());
        }

        if self.description.len() > 512 {
            return Err("Group description too long (max 512 characters)".to_string());
        }

        if self.max_members == 0 {
            return Err("Maximum members must be greater than 0".to_string());
        }

        if self.max_members > 10000 {
            return Err("Maximum members too high (max 10000)".to_string());
        }

        if !self.is_member(&self.creator) {
            return Err("Creator must be a member of the group".to_string());
        }

        if !self.is_admin(&self.creator) {
            return Err("Creator must be an admin of the group".to_string());
        }

        // Check for duplicate members
        let mut unique_members = self.members.clone();
        unique_members.sort_by_key(|k| k.key_id.clone());
        unique_members.dedup();
        if unique_members.len() != self.members.len() {
            return Err("Duplicate members found".to_string());
        }

        // Check that all admins are members
        for admin in &self.admins {
            if !self.is_member(admin) {
                return Err("Admin must also be a member".to_string());
            }
        }

        Ok(())
    }
}

pub struct GroupContract {
    /// All groups in the system
    pub groups: HashMap<[u8; 32], GroupChat>,
    /// User group memberships (user -> group_ids)
    pub user_groups: HashMap<PublicKey, Vec<[u8; 32]>>,
    /// Group invitation system (group_id -> pending_invites)
    pub pending_invites: HashMap<[u8; 32], Vec<GroupInvite>>,
    /// Group join requests for private groups
    pub join_requests: HashMap<[u8; 32], Vec<JoinRequest>>,
}

impl GroupContract {
    /// Create a new group contract
    pub fn new() -> Self {
        Self {
            groups: HashMap::new(),
            user_groups: HashMap::new(),
            pending_invites: HashMap::new(),
            join_requests: HashMap::new(),
        }
    }

    /// Create a new group
    pub fn create_group(
        &mut self,
        name: String,
        description: String,
        creator: PublicKey,
        max_members: u32,
        is_private: bool,
        whisper_token_cost: u64,
    ) -> Result<[u8; 32], String> {
        let group = GroupChat::new(
            name,
            description,
            creator.clone(),
            max_members,
            is_private,
            whisper_token_cost,
        );

        group.validate()?;

        let group_id = group.group_id;

        // Add creator to user groups
        self.user_groups
            .entry(creator)
            .or_insert_with(Vec::new)
            .push(group_id);

        // Store the group
        self.groups.insert(group_id, group);

        Ok(group_id)
    }

    /// Get a group by ID
    pub fn get_group(&self, group_id: &[u8; 32]) -> Option<&GroupChat> {
        self.groups.get(group_id)
    }

    /// Get all groups a user is a member of
    pub fn get_user_groups(&self, user: &PublicKey) -> Vec<&GroupChat> {
        self.user_groups
            .get(user)
            .map(|group_ids| {
                group_ids
                    .iter()
                    .filter_map(|id| self.groups.get(id))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Join a public group
    pub fn join_group(
        &mut self,
        group_id: &[u8; 32],
        user: PublicKey,
    ) -> Result<(), String> {
        let group = self.groups.get_mut(group_id)
            .ok_or("Group not found")?;

        if group.is_private {
            return Err("Cannot join private group without invitation".to_string());
        }

        group.add_member(user.clone())?;

        // Add to user groups
        self.user_groups
            .entry(user)
            .or_insert_with(Vec::new)
            .push(*group_id);

        Ok(())
    }

    /// Request to join a private group
    pub fn request_to_join(
        &mut self,
        group_id: &[u8; 32],
        user: PublicKey,
        message: String,
    ) -> Result<(), String> {
        let group = self.groups.get(group_id)
            .ok_or("Group not found")?;

        if !group.is_private {
            return Err("Use join_group for public groups".to_string());
        }

        if group.is_member(&user) {
            return Err("User is already a member".to_string());
        }

        // Check if request already exists
        if let Some(requests) = self.join_requests.get(group_id) {
            if requests.iter().any(|r| r.user == user) {
                return Err("Join request already pending".to_string());
            }
        }

        let request = JoinRequest {
            user,
            message,
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
        };

        self.join_requests
            .entry(*group_id)
            .or_insert_with(Vec::new)
            .push(request);

        Ok(())
    }

    /// Approve a join request (admin only)
    pub fn approve_join_request(
        &mut self,
        group_id: &[u8; 32],
        requesting_user: &PublicKey,
        approver: &PublicKey,
    ) -> Result<(), String> {
        let group = self.groups.get(group_id)
            .ok_or("Group not found")?;

        if !group.is_admin(approver) {
            return Err("Only admins can approve join requests".to_string());
        }

        // Remove the join request
        if let Some(requests) = self.join_requests.get_mut(group_id) {
            requests.retain(|r| r.user != *requesting_user);
            if requests.is_empty() {
                self.join_requests.remove(group_id);
            }
        }

        // Add user to group
        let group = self.groups.get_mut(group_id).unwrap();
        group.add_member(requesting_user.clone())?;

        // Add to user groups
        self.user_groups
            .entry(requesting_user.clone())
            .or_insert_with(Vec::new)
            .push(*group_id);

        Ok(())
    }

    /// Invite a user to a group (admin only)
    pub fn invite_user(
        &mut self,
        group_id: &[u8; 32],
        inviter: &PublicKey,
        invitee: PublicKey,
        message: String,
    ) -> Result<(), String> {
        let group = self.groups.get(group_id)
            .ok_or("Group not found")?;

        if !group.is_admin(inviter) {
            return Err("Only admins can invite users".to_string());
        }

        if group.is_member(&invitee) {
            return Err("User is already a member".to_string());
        }

        // Check if invitation already exists
        if let Some(invites) = self.pending_invites.get(group_id) {
            if invites.iter().any(|i| i.invitee == invitee) {
                return Err("User already has a pending invitation".to_string());
            }
        }

        let invite = GroupInvite {
            group_id: *group_id,
            inviter: inviter.clone(),
            invitee: invitee.clone(),
            message,
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
        };

        self.pending_invites
            .entry(*group_id)
            .or_insert_with(Vec::new)
            .push(invite);

        Ok(())
    }

    /// Accept a group invitation
    pub fn accept_invitation(
        &mut self,
        group_id: &[u8; 32],
        user: &PublicKey,
    ) -> Result<(), String> {
        // Remove the invitation
        if let Some(invites) = self.pending_invites.get_mut(group_id) {
            let had_invite = invites.iter().any(|i| i.invitee == *user);
            if !had_invite {
                return Err("No pending invitation found".to_string());
            }
            invites.retain(|i| i.invitee != *user);
            if invites.is_empty() {
                self.pending_invites.remove(group_id);
            }
        } else {
            return Err("No pending invitation found".to_string());
        }

        // Add user to group
        let group = self.groups.get_mut(group_id)
            .ok_or("Group not found")?;
        group.add_member(user.clone())?;

        // Add to user groups
        self.user_groups
            .entry(user.clone())
            .or_insert_with(Vec::new)
            .push(*group_id);

        Ok(())
    }

    /// Leave a group
    pub fn leave_group(
        &mut self,
        group_id: &[u8; 32],
        user: &PublicKey,
    ) -> Result<(), String> {
        let group = self.groups.get_mut(group_id)
            .ok_or("Group not found")?;

        group.remove_member(user)?;

        // Remove from user groups
        if let Some(user_groups) = self.user_groups.get_mut(user) {
            user_groups.retain(|id| id != group_id);
            if user_groups.is_empty() {
                self.user_groups.remove(user);
            }
        }

        Ok(())
    }

    /// Promote a member to admin (admin only)
    pub fn promote_to_admin(
        &mut self,
        group_id: &[u8; 32],
        promoter: &PublicKey,
        user_to_promote: PublicKey,
    ) -> Result<(), String> {
        let group = self.groups.get_mut(group_id)
            .ok_or("Group not found")?;

        if !group.is_admin(promoter) {
            return Err("Only admins can promote users".to_string());
        }

        group.add_admin(user_to_promote)
    }

    /// Remove admin privileges (creator only)
    pub fn remove_admin(
        &mut self,
        group_id: &[u8; 32],
        remover: &PublicKey,
        admin_to_remove: &PublicKey,
    ) -> Result<(), String> {
        let group = self.groups.get_mut(group_id)
            .ok_or("Group not found")?;

        if group.creator != *remover {
            return Err("Only group creator can remove admin privileges".to_string());
        }

        group.remove_admin(admin_to_remove)
    }

    /// Get pending invitations for a user
    pub fn get_user_invitations(&self, user: &PublicKey) -> Vec<&GroupInvite> {
        self.pending_invites
            .values()
            .flatten()
            .filter(|invite| invite.invitee == *user)
            .collect()
    }

    /// Get pending join requests for a group (admin only)
    pub fn get_join_requests(
        &self,
        group_id: &[u8; 32],
        requester: &PublicKey,
    ) -> Result<Vec<&JoinRequest>, String> {
        let group = self.groups.get(group_id)
            .ok_or("Group not found")?;

        if !group.is_admin(requester) {
            return Err("Only admins can view join requests".to_string());
        }

        Ok(self.join_requests
            .get(group_id)
            .map(|requests| requests.iter().collect())
            .unwrap_or_default())
    }

    /// Search public groups by name
    pub fn search_public_groups(&self, search_term: &str) -> Vec<&GroupChat> {
        self.groups
            .values()
            .filter(|group| {
                !group.is_private && 
                group.name.to_lowercase().contains(&search_term.to_lowercase())
            })
            .collect()
    }

    /// Get group statistics
    pub fn get_group_stats(&self, group_id: &[u8; 32]) -> Option<GroupStats> {
        self.groups.get(group_id).map(|group| GroupStats {
            group_id: *group_id,
            member_count: group.member_count(),
            admin_count: group.admins.len(),
            is_private: group.is_private,
            created_timestamp: group.created_timestamp,
            capacity_utilization: (group.member_count() as f64 / group.max_members as f64) * 100.0,
        })
    }

    /// Get total group count
    pub fn total_group_count(&self) -> usize {
        self.groups.len()
    }

    /// Get system-wide group statistics
    pub fn get_system_stats(&self) -> GroupSystemStats {
        let total_groups = self.groups.len();
        let public_groups = self.groups.values().filter(|g| !g.is_private).count();
        let private_groups = total_groups - public_groups;
        let total_members: usize = self.groups.values().map(|g| g.member_count()).sum();
        let total_admins: usize = self.groups.values().map(|g| g.admins.len()).sum();

        GroupSystemStats {
            total_groups,
            public_groups,
            private_groups,
            total_members,
            total_admins,
            average_group_size: if total_groups > 0 {
                total_members as f64 / total_groups as f64
            } else {
                0.0
            },
        }
    }
}

