pub struct SharedFile {
    /// Unique file identifier
    pub file_id: [u8; 32],
    /// Original filename
    pub filename: String,
    /// File description
    pub description: String,
    /// File owner
    pub owner: PublicKey,
    ///  hash or content hash
    pub content_hash: [u8; 32],
    /// File size in bytes
    pub file_size: u64,
    /// MIME type of the file
    pub mime_type: String,
    /// Timestamp when file was uploaded
    pub upload_timestamp: u64,
    /// Whether the file is publicly accessible
    pub is_public: bool,
    /// List of users who have access to the file
    pub access_list: Vec<PublicKey>,
    /// Number of downloads
    pub download_count: u64,
    /// Cost in ZHTP tokens to download (if not free)
    pub download_cost: u64,
    /// File encryption status
    pub is_encrypted: bool,
    /// Encryption key hash (if encrypted)
    pub encryption_key_hash: Option<[u8; 32]>,
    /// File tags for categorization
    pub tags: Vec<String>,
    /// Maximum downloads allowed (0 for unlimited)
    pub max_downloads: u64,
}

impl SharedFile {
    /// Create a new shared file
    pub fn new(
        filename: String,
        description: String,
        owner: PublicKey,
        content_hash: [u8; 32],
        file_size: u64,
        mime_type: String,
        is_public: bool,
        download_cost: u64,
        is_encrypted: bool,
        encryption_key_hash: Option<[u8; 32]>,
        tags: Vec<String>,
        max_downloads: u64,
    ) -> Self {
        let upload_timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let file_id = crate::contracts::utils::id_generation::generate_file_id(
            &owner.key_id,
            &content_hash,
            upload_timestamp as u128 * 1_000_000_000,
        );

        Self {
            file_id,
            filename,
            description,
            owner: owner.clone(),
            content_hash,
            file_size,
            mime_type,
            upload_timestamp,
            is_public,
            access_list: vec![owner], // Owner always has access
            download_count: 0,
            download_cost,
            is_encrypted,
            encryption_key_hash,
            tags,
            max_downloads,
        }
    }

    /// Check if a user has access to the file
    pub fn has_access(&self, user: &PublicKey) -> bool {
        self.is_public || self.access_list.contains(user)
    }

    /// Grant access to a user
    pub fn grant_access(&mut self, user: PublicKey) -> Result<(), String> {
        if self.has_access(&user) {
            return Err("User already has access".to_string());
        }

        self.access_list.push(user);
        Ok(())
    }

    /// Revoke access from a user
    pub fn revoke_access(&mut self, user: &PublicKey) -> Result<(), String> {
        if *user == self.owner {
            return Err("Cannot revoke access from file owner".to_string());
        }

        if !self.has_access(user) {
            return Err("User does not have access".to_string());
        }

        self.access_list.retain(|u| u != user);
        Ok(())
    }

    /// Check if the file can still be downloaded
    pub fn can_download(&self) -> bool {
        if self.max_downloads == 0 {
            return true; // Unlimited downloads
        }
        self.download_count < self.max_downloads
    }

    /// Record a download
    pub fn record_download(&mut self) -> Result<(), String> {
        if !self.can_download() {
            return Err("Download limit reached".to_string());
        }

        self.download_count += 1;
        Ok(())
    }

    /// Add a tag to the file
    pub fn add_tag(&mut self, tag: String) -> Result<(), String> {
        if tag.is_empty() {
            return Err("Tag cannot be empty".to_string());
        }

        if tag.len() > 32 {
            return Err("Tag too long (max 32 characters)".to_string());
        }

        if self.tags.contains(&tag) {
            return Err("Tag already exists".to_string());
        }

        if self.tags.len() >= 20 {
            return Err("Too many tags (max 20)".to_string());
        }

        self.tags.push(tag);
        Ok(())
    }

    /// Remove a tag from the file
    pub fn remove_tag(&mut self, tag: &str) -> Result<(), String> {
        if !self.tags.contains(&tag.to_string()) {
            return Err("Tag not found".to_string());
        }

        self.tags.retain(|t| t != tag);
        Ok(())
    }

    /// Get file size in human-readable format
    pub fn get_formatted_size(&self) -> String {
        let size = self.file_size as f64;

        if size < 1024.0 {
            format!("{} B", size)
        } else if size < 1024.0 * 1024.0 {
            format!("{:.2} KB", size / 1024.0)
        } else if size < 1024.0 * 1024.0 * 1024.0 {
            format!("{:.2} MB", size / (1024.0 * 1024.0))
        } else {
            format!("{:.2} GB", size / (1024.0 * 1024.0 * 1024.0))
        }
    }

    /// Get storage key for this file
    pub fn storage_key(&self) -> Vec<u8> {
        crate::contracts::utils::id_generation::generate_storage_key("file", &self.file_id)
    }

    /// Check if file is available for public download
    pub fn is_available_for_download(&self, user: &PublicKey) -> bool {
        self.has_access(user) && self.can_download()
    }

    /// Validate file structure
    pub fn validate(&self) -> Result<(), String> {
        if self.filename.is_empty() {
            return Err("Filename cannot be empty".to_string());
        }

        if self.filename.len() > 255 {
            return Err("Filename too long (max 255 characters)".to_string());
        }

        if self.description.len() > 1024 {
            return Err("Description too long (max 1024 characters)".to_string());
        }

        if self.file_size == 0 {
            return Err("File size cannot be zero".to_string());
        }

        if self.file_size > 100 * 1024 * 1024 * 1024 {
            return Err("File too large (max 100GB)".to_string());
        }

        if self.mime_type.is_empty() {
            return Err("MIME type cannot be empty".to_string());
        }

        if self.mime_type.len() > 128 {
            return Err("MIME type too long (max 128 characters)".to_string());
        }

        // Validate tags
        for tag in &self.tags {
            if tag.is_empty() {
                return Err("Tag cannot be empty".to_string());
            }
            if tag.len() > 32 {
                return Err("Tag too long (max 32 characters)".to_string());
            }
        }

        if self.tags.len() > 20 {
            return Err("Too many tags (max 20)".to_string());
        }

        // Check for duplicate tags
        let mut unique_tags = self.tags.clone();
        unique_tags.sort();
        unique_tags.dedup();
        if unique_tags.len() != self.tags.len() {
            return Err("Duplicate tags found".to_string());
        }

        // Owner must be in access list
        if !self.access_list.contains(&self.owner) {
            return Err("Owner must have access to the file".to_string());
        }

        // Check for duplicate access entries
        let mut unique_access = self.access_list.clone();
        unique_access.sort_by_key(|k| k.key_id);
        unique_access.dedup();
        if unique_access.len() != self.access_list.len() {
            return Err("Duplicate access entries found".to_string());
        }

        // If encrypted, must have encryption key hash
        if self.is_encrypted && self.encryption_key_hash.is_none() {
            return Err("Encrypted file must have encryption key hash".to_string());
        }

        // If not encrypted, should not have encryption key hash
        if !self.is_encrypted && self.encryption_key_hash.is_some() {
            return Err("Non-encrypted file should not have encryption key hash".to_string());
        }

        Ok(())
    }
}

pub struct FileContract {
    /// All files in the system
    pub files: HashMap<[u8; 32], SharedFile>,
    /// User file indexes (owner -> file IDs)
    pub user_files: HashMap<PublicKey, Vec<[u8; 32]>>,
    /// Public files index
    pub public_files: Vec<[u8; 32]>,
    /// Tag index (tag -> file IDs)
    pub tag_index: HashMap<String, Vec<[u8; 32]>>,
    /// File type index (MIME type -> file IDs)
    pub type_index: HashMap<String, Vec<[u8; 32]>>,
}

impl FileContract {
    /// Create a new file contract
    pub fn new() -> Self {
        Self {
            files: HashMap::new(),
            user_files: HashMap::new(),
            public_files: Vec::new(),
            tag_index: HashMap::new(),
            type_index: HashMap::new(),
        }
    }

    /// Add a file to the contract
    pub fn add_file(&mut self, file: SharedFile) -> Result<(), String> {
        file.validate()?;

        let file_id = file.file_id;

        // Add to user file index
        self.user_files
            .entry(file.owner.clone())
            .or_insert_with(Vec::new)
            .push(file_id);

        // Add to public files if public
        if file.is_public {
            self.public_files.push(file_id);
        }

        // Add to tag index
        for tag in &file.tags {
            self.tag_index
                .entry(tag.clone())
                .or_insert_with(Vec::new)
                .push(file_id);
        }

        // Add to type index
        self.type_index
            .entry(file.mime_type.clone())
            .or_insert_with(Vec::new)
            .push(file_id);

        // Store the file
        self.files.insert(file_id, file);

        Ok(())
    }

    /// Get a file by ID
    pub fn get_file(&self, file_id: &[u8; 32]) -> Option<&SharedFile> {
        self.files.get(file_id)
    }

    /// Get a mutable file by ID
    pub fn get_file_mut(&mut self, file_id: &[u8; 32]) -> Option<&mut SharedFile> {
        self.files.get_mut(file_id)
    }

    /// Get files owned by a user
    pub fn get_user_files(&self, user: &PublicKey) -> Vec<&SharedFile> {
        self.user_files
            .get(user)
            .map(|file_ids| {
                file_ids
                    .iter()
                    .filter_map(|id| self.files.get(id))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get public files
    pub fn get_public_files(&self) -> Vec<&SharedFile> {
        self.public_files
            .iter()
            .filter_map(|id| self.files.get(id))
            .collect()
    }

    /// Get files by tag
    pub fn get_files_by_tag(&self, tag: &str) -> Vec<&SharedFile> {
        self.tag_index
            .get(tag)
            .map(|file_ids| {
                file_ids
                    .iter()
                    .filter_map(|id| self.files.get(id))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get files by MIME type
    pub fn get_files_by_type(&self, mime_type: &str) -> Vec<&SharedFile> {
        self.type_index
            .get(mime_type)
            .map(|file_ids| {
                file_ids
                    .iter()
                    .filter_map(|id| self.files.get(id))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get files accessible to a user
    pub fn get_accessible_files(&self, user: &PublicKey) -> Vec<&SharedFile> {
        self.files
            .values()
            .filter(|file| file.has_access(user))
            .collect()
    }

    /// Remove a file
    pub fn remove_file(&mut self, file_id: &[u8; 32]) -> Option<SharedFile> {
        if let Some(file) = self.files.remove(file_id) {
            // Remove from user index
            if let Some(user_files) = self.user_files.get_mut(&file.owner) {
                user_files.retain(|id| id != file_id);
            }

            // Remove from public files
            self.public_files.retain(|id| id != file_id);

            // Remove from tag index
            for tag in &file.tags {
                if let Some(tag_files) = self.tag_index.get_mut(tag) {
                    tag_files.retain(|id| id != file_id);
                    if tag_files.is_empty() {
                        self.tag_index.remove(tag);
                    }
                }
            }

            // Remove from type index
            if let Some(type_files) = self.type_index.get_mut(&file.mime_type) {
                type_files.retain(|id| id != file_id);
                if type_files.is_empty() {
                    self.type_index.remove(&file.mime_type);
                }
            }

            Some(file)
        } else {
            None
        }
    }

    /// Update file visibility
    pub fn update_file_visibility(&mut self, file_id: &[u8; 32], is_public: bool) -> Result<(), String> {
        if let Some(file) = self.files.get_mut(file_id) {
            if file.is_public == is_public {
                return Ok(()); // No change needed
            }

            file.is_public = is_public;

            if is_public {
                // Add to public files
                if !self.public_files.contains(file_id) {
                    self.public_files.push(*file_id);
                }
            } else {
                // Remove from public files
                self.public_files.retain(|id| id != file_id);
            }

            Ok(())
        } else {
            Err("File not found".to_string())
        }
    }

    /// Grant access to a file
    pub fn grant_file_access(&mut self, file_id: &[u8; 32], user: PublicKey) -> Result<(), String> {
        if let Some(file) = self.files.get_mut(file_id) {
            file.grant_access(user)
        } else {
            Err("File not found".to_string())
        }
    }

    /// Revoke access from a file
    pub fn revoke_file_access(&mut self, file_id: &[u8; 32], user: &PublicKey) -> Result<(), String> {
        if let Some(file) = self.files.get_mut(file_id) {
            file.revoke_access(user)
        } else {
            Err("File not found".to_string())
        }
    }

    /// Record a file download
    pub fn record_download(&mut self, file_id: &[u8; 32]) -> Result<(), String> {
        if let Some(file) = self.files.get_mut(file_id) {
            file.record_download()
        } else {
            Err("File not found".to_string())
        }
    }

    /// Get file count
    pub fn file_count(&self) -> usize {
        self.files.len()
    }

    /// Get user file count
    pub fn user_file_count(&self, user: &PublicKey) -> usize {
        self.user_files.get(user).map_or(0, |files| files.len())
    }

    /// Search files by name pattern
    pub fn search_files(&self, pattern: &str) -> Vec<&SharedFile> {
        let pattern_lower = pattern.to_lowercase();
        self.files
            .values()
            .filter(|file| {
                file.filename.to_lowercase().contains(&pattern_lower) ||
                file.description.to_lowercase().contains(&pattern_lower)
            })
            .collect()
    }
}

impl Default for FileContract {
    fn default() -> Self {
        Self::new()
    }
}

pub struct ExecutionContext {
    /// Current caller's public key
    pub caller: PublicKey,
    /// Current block number
    pub block_number: u64,
    /// Current block timestamp
    pub timestamp: u64,
    /// Gas limit for this execution
    pub gas_limit: u64,
    /// Gas used so far
    pub gas_used: u64,
    /// Transaction hash that triggered this execution
    pub tx_hash: [u8; 32],
}

impl ExecutionContext {
    /// Create new execution context
    pub fn new(
        caller: PublicKey,
        block_number: u64,
        timestamp: u64,
        gas_limit: u64,
        tx_hash: [u8; 32],
    ) -> Self {
        Self {
            caller,
            block_number,
            timestamp,
            gas_limit,
            gas_used: 0,
            tx_hash,
        }
    }

    /// Check if there's enough gas remaining
    pub fn check_gas(&self, required: u64) -> Result<()> {
        if self.gas_used + required > self.gas_limit {
            return Err(anyhow!("Out of gas: required {}, available {}", 
                required, self.gas_limit - self.gas_used));
        }
        Ok(())
    }

    /// Consume gas
    pub fn consume_gas(&mut self, amount: u64) -> Result<()> {
        self.check_gas(amount)?;
        self.gas_used += amount;
        Ok(())
    }

    /// Get remaining gas
    pub fn remaining_gas(&self) -> u64 {
        self.gas_limit - self.gas_used
    }
}

pub trait ContractStorage {
    /// Get value from storage
    fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>>;

    /// Set value in storage
    fn set(&mut self, key: &[u8], value: &[u8]) -> Result<()>;

    /// Delete value from storage
    fn delete(&mut self, key: &[u8]) -> Result<()>;

    /// Check if key exists in storage
    fn exists(&self, key: &[u8]) -> Result<bool>;
}

pub struct MemoryStorage {
    data: HashMap<Vec<u8>, Vec<u8>>,
}

impl ContractStorage for MemoryStorage {
    fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>> {
        Ok(self.data.get(key).cloned())
    }

    fn set(&mut self, key: &[u8], value: &[u8]) -> Result<()> {
        self.data.insert(key.to_vec(), value.to_vec());
        Ok(())
    }

    fn delete(&mut self, key: &[u8]) -> Result<()> {
        self.data.remove(key);
        Ok(())
    }

    fn exists(&self, key: &[u8]) -> Result<bool> {
        Ok(self.data.contains_key(key))
    }
}

pub struct PlatformIsolationManager {
    /// Active isolation contexts
    isolation_contexts: HashMap<String, IsolationContext>,
    /// Global isolation configuration
    global_config: PlatformIsolationConfig,
}

pub struct PlatformIsolationConfig {
    /// Enable file system isolation
    pub enable_filesystem_isolation: bool,
    /// Enable network isolation
    pub enable_network_isolation: bool,
    /// Enable process isolation
    pub enable_process_isolation: bool,
    /// Maximum memory per contract
    pub max_memory_per_contract: u64,
    /// Maximum CPU time per contract
    pub max_cpu_time_ms: u64,
    /// Allowed system calls (whitelist)
    pub allowed_syscalls: Vec<String>,
}

struct IsolationContext {
    /// Contract ID
    contract_id: String,
    /// Sandbox configuration
    sandbox_config: SandboxConfig,
    /// Resource usage tracking
    resource_usage: ResourceUsage,
    /// Isolation start time
    start_time: std::time::Instant,
}

struct ResourceUsage {
    /// Memory allocated (bytes)
    memory_allocated: u64,
    /// CPU time used (milliseconds)
    cpu_time_ms: u64,
    /// Number of system calls made
    syscall_count: u32,
    /// Number of file operations
    file_operations: u32,
    /// Number of network operations
    network_operations: u32,
}

impl PlatformIsolationManager {
    /// Create new platform isolation manager
    pub fn new(config: PlatformIsolationConfig) -> Self {
        Self {
            isolation_contexts: HashMap::new(),
            global_config: config,
        }
    }

    /// Create isolated execution environment for a contract
    pub fn create_isolation_context(
        &mut self,
        contract_id: String,
        security_level: SecurityLevel,
    ) -> Result<()> {
        let sandbox_config = SandboxConfig::for_security_level(security_level);

        let context = IsolationContext {
            contract_id: contract_id.clone(),
            sandbox_config,
            resource_usage: ResourceUsage::default(),
            start_time: std::time::Instant::now(),
        };

        self.isolation_contexts.insert(contract_id.clone(), context);

        log::info!("Created isolation context for contract: {}", contract_id);
        Ok(())
    }

    /// Execute contract in isolated environment
    pub fn execute_isolated<F, T>(&mut self, contract_id: &str, execution_fn: F) -> Result<T>
    where
        F: FnOnce() -> Result<T>,
    {
        // Pre-execution checks
        {
            let context = self.isolation_contexts.get(contract_id)
                .ok_or_else(|| anyhow!("Isolation context not found: {}", contract_id))?;
            self.validate_resource_limits(context)?;
        }

        // Execute with monitoring
        let start = std::time::Instant::now();
        let result = execution_fn()?;
        let execution_time = start.elapsed();

        // Update resource usage and post-execution validation
        {
            let context = self.isolation_contexts.get_mut(contract_id)
                .ok_or_else(|| anyhow!("Isolation context not found: {}", contract_id))?;

            context.resource_usage.cpu_time_ms += execution_time.as_millis() as u64;
        }

        // Validate post-execution state (separate borrow)
        {
            let context = self.isolation_contexts.get(contract_id)
                .ok_or_else(|| anyhow!("Isolation context not found: {}", contract_id))?;
            self.validate_post_execution(context)?;
        }

        log::debug!("Isolated execution completed for contract: {} in {:?}", 
                   contract_id, execution_time);

        Ok(result)
    }

    /// Validate resource limits before execution
    fn validate_resource_limits(&self, context: &IsolationContext) -> Result<()> {
        // Check memory limits
        if context.resource_usage.memory_allocated > self.global_config.max_memory_per_contract {
            return Err(anyhow!("Memory limit exceeded: {} > {}", 
                context.resource_usage.memory_allocated, 
                self.global_config.max_memory_per_contract));
        }

        // Check CPU time limits
        if context.resource_usage.cpu_time_ms > self.global_config.max_cpu_time_ms {
            return Err(anyhow!("CPU time limit exceeded: {} > {}", 
                context.resource_usage.cpu_time_ms, 
                self.global_config.max_cpu_time_ms));
        }

        Ok(())
    }

    /// Validate state after execution
    fn validate_post_execution(&self, context: &IsolationContext) -> Result<()> {
        let execution_time = context.start_time.elapsed();

        // Check if execution time is reasonable
        if execution_time > context.sandbox_config.execution_limits.max_execution_time {
            return Err(anyhow!("Execution timeout: {:?} > {:?}", 
                execution_time, 
                context.sandbox_config.execution_limits.max_execution_time));
        }

        Ok(())
    }

    /// Track memory allocation
    pub fn track_memory_allocation(&mut self, contract_id: &str, bytes: u64) -> Result<()> {
        if let Some(context) = self.isolation_contexts.get_mut(contract_id) {
            context.resource_usage.memory_allocated += bytes;

            // Check limits
            if context.resource_usage.memory_allocated > self.global_config.max_memory_per_contract {
                return Err(anyhow!("Memory allocation would exceed limit"));
            }
        }
        Ok(())
    }

    /// Track system call
    pub fn track_syscall(&mut self, contract_id: &str, syscall_name: &str) -> Result<()> {
        // Check if syscall is allowed
        if !self.global_config.allowed_syscalls.contains(&syscall_name.to_string()) {
            return Err(anyhow!("System call not allowed: {}", syscall_name));
        }

        if let Some(context) = self.isolation_contexts.get_mut(contract_id) {
            context.resource_usage.syscall_count += 1;
        }

        Ok(())
    }

    /// Track file operation
    pub fn track_file_operation(&mut self, contract_id: &str) -> Result<()> {
        if !self.global_config.enable_filesystem_isolation {
            return Err(anyhow!("File system access not allowed"));
        }

        if let Some(context) = self.isolation_contexts.get_mut(contract_id) {
            context.resource_usage.file_operations += 1;
        }

        Ok(())
    }

    /// Track network operation
    pub fn track_network_operation(&mut self, contract_id: &str) -> Result<()> {
        if !self.global_config.enable_network_isolation {
            return Err(anyhow!("Network access not allowed"));
        }

        if let Some(context) = self.isolation_contexts.get_mut(contract_id) {
            context.resource_usage.network_operations += 1;
        }

        Ok(())
    }

    /// Remove isolation context
    pub fn remove_context(&mut self, contract_id: &str) -> Option<IsolationReport> {
        if let Some(context) = self.isolation_contexts.remove(contract_id) {
            let total_time = context.start_time.elapsed();

            Some(IsolationReport {
                contract_id: context.contract_id,
                total_execution_time: total_time,
                memory_used: context.resource_usage.memory_allocated,
                cpu_time_ms: context.resource_usage.cpu_time_ms,
                syscall_count: context.resource_usage.syscall_count,
                file_operations: context.resource_usage.file_operations,
                network_operations: context.resource_usage.network_operations,
            })
        } else {
            None
        }
    }

    /// Get resource usage for a contract
    pub fn get_resource_usage(&self, contract_id: &str) -> Option<&ResourceUsage> {
        self.isolation_contexts.get(contract_id).map(|ctx| &ctx.resource_usage)
    }
}

impl Default for PlatformIsolationConfig {
    fn default() -> Self {
        Self {
            enable_filesystem_isolation: true,
            enable_network_isolation: true,
            enable_process_isolation: true,
            max_memory_per_contract: 16 * 1024 * 1024, // 16MB
            max_cpu_time_ms: 5000, // 5 seconds
            allowed_syscalls: vec![
                "read".to_string(),
                "write".to_string(),
                "mmap".to_string(),
                "munmap".to_string(),
                "brk".to_string(),
            ],
        }
    }
}

pub fn create_isolation_manager(security_level: SecurityLevel) -> PlatformIsolationManager {
    let config = match security_level {
        SecurityLevel::Minimal => PlatformIsolationConfig {
            max_memory_per_contract: 64 * 1024 * 1024, // 64MB
            max_cpu_time_ms: 30000, // 30 seconds
            ..Default::default()
        },
        SecurityLevel::Standard => PlatformIsolationConfig::default(),
        SecurityLevel::Maximum => PlatformIsolationConfig {
            max_memory_per_contract: 8 * 1024 * 1024, // 8MB
            max_cpu_time_ms: 1000, // 1 second
            allowed_syscalls: vec!["read".to_string(), "write".to_string()], // Minimal syscalls
            ..Default::default()
        },
    };

    PlatformIsolationManager::new(config)
}

pub struct ContactEntry {
    /// Unique contact identifier
    pub contact_id: [u8; 32],
    /// Owner of this contact entry
    pub owner: PublicKey,
    /// Display name for the contact
    pub display_name: String,
    /// Contact's public key
    pub public_key: PublicKey,
    /// Optional avatar hash ( hash)
    pub avatar_hash: Option<String>,
    /// Status message
    pub status_message: String,
    /// Whether the contact is verified
    pub verified: bool,
    /// Timestamp when contact was added
    pub added_timestamp: u64,
}

impl ContactEntry {
    /// Create a new contact entry
    pub fn new(
        owner: PublicKey,
        display_name: String,
        public_key: PublicKey,
    ) -> Self {
        let contact_id = crate::contracts::utils::generate_contact_id(&owner.key_id, &public_key.key_id);
        let added_timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        Self {
            contact_id,
            owner,
            display_name,
            public_key,
            avatar_hash: None,
            status_message: String::new(),
            verified: false,
            added_timestamp,
        }
    }

    /// Set avatar hash
    pub fn set_avatar(&mut self, avatar_hash: String) {
        self.avatar_hash = Some(avatar_hash);
    }

    /// Set status message
    pub fn set_status(&mut self, status_message: String) {
        self.status_message = status_message;
    }

    /// Mark contact as verified
    pub fn verify(&mut self) {
        self.verified = true;
    }

    /// Get storage key for this contact
    pub fn storage_key(&self) -> Vec<u8> {
        crate::contracts::utils::generate_indexed_storage_key(
            "contact",
            &[&self.owner.key_id, &self.contact_id],
        )
    }

    /// Validate contact entry
    pub fn validate(&self) -> Result<(), String> {
        if self.display_name.is_empty() {
            return Err("Display name cannot be empty".to_string());
        }

        if self.display_name.len() > 64 {
            return Err("Display name too long (max 64 characters)".to_string());
        }

        if self.status_message.len() > 256 {
            return Err("Status message too long (max 256 characters)".to_string());
        }

        Ok(())
    }
}

pub struct ContactContract {
    /// All contact entries indexed by contact_id
    pub contacts: HashMap<[u8; 32], ContactEntry>,
    /// User contact lists (owner -> contact_ids)
    pub user_contacts: HashMap<PublicKey, Vec<[u8; 32]>>,
    /// Reverse lookup (public_key -> owners who have this contact)
    pub public_key_index: HashMap<PublicKey, Vec<PublicKey>>,
}

impl ContactContract {
    /// Create a new contact contract
    pub fn new() -> Self {
        Self {
            contacts: HashMap::new(),
            user_contacts: HashMap::new(),
            public_key_index: HashMap::new(),
        }
    }

    /// Add a new contact
    pub fn add_contact(
        &mut self,
        owner: PublicKey,
        display_name: String,
        public_key: PublicKey,
    ) -> Result<[u8; 32], String> {
        // Check if contact already exists
        if let Some(existing_contacts) = self.user_contacts.get(&owner) {
            for contact_id in existing_contacts {
                if let Some(contact) = self.contacts.get(contact_id) {
                    if contact.public_key == public_key {
                        return Err("Contact already exists".to_string());
                    }
                }
            }
        }

        let contact = ContactEntry::new(owner.clone(), display_name, public_key.clone());
        contact.validate()?;

        let contact_id = contact.contact_id;

        // Add to user contacts list
        self.user_contacts
            .entry(owner.clone())
            .or_insert_with(Vec::new)
            .push(contact_id);

        // Add to public key index
        self.public_key_index
            .entry(public_key.clone())
            .or_insert_with(Vec::new)
            .push(owner);

        // Store the contact
        self.contacts.insert(contact_id, contact);

        Ok(contact_id)
    }

    /// Get a contact by ID
    pub fn get_contact(&self, contact_id: &[u8; 32]) -> Option<&ContactEntry> {
        self.contacts.get(contact_id)
    }

    /// Get all contacts for a user
    pub fn get_user_contacts(&self, owner: &PublicKey) -> Vec<&ContactEntry> {
        self.user_contacts
            .get(owner)
            .map(|contact_ids| {
                contact_ids
                    .iter()
                    .filter_map(|id| self.contacts.get(id))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Remove a contact
    pub fn remove_contact(
        &mut self,
        owner: &PublicKey,
        contact_id: &[u8; 32],
    ) -> Result<(), String> {
        // Check if contact exists and belongs to owner
        if let Some(contact) = self.contacts.get(contact_id) {
            if contact.owner != *owner {
                return Err("Contact does not belong to this owner".to_string());
            }
        } else {
            return Err("Contact not found".to_string());
        }

        let contact = self.contacts.remove(contact_id).unwrap();

        // Remove from user contacts list
        if let Some(user_contacts) = self.user_contacts.get_mut(owner) {
            user_contacts.retain(|id| id != contact_id);
            if user_contacts.is_empty() {
                self.user_contacts.remove(owner);
            }
        }

        // Remove from public key index
        if let Some(owners) = self.public_key_index.get_mut(&contact.public_key) {
            owners.retain(|o| o != owner);
            if owners.is_empty() {
                self.public_key_index.remove(&contact.public_key);
            }
        }

        Ok(())
    }

    /// Update contact information
    pub fn update_contact(
        &mut self,
        owner: &PublicKey,
        contact_id: &[u8; 32],
        display_name: Option<String>,
        avatar_hash: Option<String>,
        status_message: Option<String>,
    ) -> Result<(), String> {
        if let Some(contact) = self.contacts.get_mut(contact_id) {
            if contact.owner != *owner {
                return Err("Contact does not belong to this owner".to_string());
            }

            if let Some(name) = display_name {
                contact.display_name = name;
            }

            if let Some(hash) = avatar_hash {
                contact.set_avatar(hash);
            }

            if let Some(status) = status_message {
                contact.set_status(status);
            }

            contact.validate()?;
            Ok(())
        } else {
            Err("Contact not found".to_string())
        }
    }

    /// Verify a contact
    pub fn verify_contact(
        &mut self,
        owner: &PublicKey,
        contact_id: &[u8; 32],
    ) -> Result<(), String> {
        if let Some(contact) = self.contacts.get_mut(contact_id) {
            if contact.owner != *owner {
                return Err("Contact does not belong to this owner".to_string());
            }

            contact.verify();
            Ok(())
        } else {
            Err("Contact not found".to_string())
        }
    }

    /// Search contacts by display name
    pub fn search_contacts(
        &self,
        owner: &PublicKey,
        search_term: &str,
    ) -> Vec<&ContactEntry> {
        self.get_user_contacts(owner)
            .into_iter()
            .filter(|contact| {
                contact.display_name.to_lowercase().contains(&search_term.to_lowercase())
            })
            .collect()
    }

    /// Get contacts by verification status
    pub fn get_verified_contacts(&self, owner: &PublicKey) -> Vec<&ContactEntry> {
        self.get_user_contacts(owner)
            .into_iter()
            .filter(|contact| contact.verified)
            .collect()
    }

    /// Get contact count for a user
    pub fn get_contact_count(&self, owner: &PublicKey) -> usize {
        self.user_contacts
            .get(owner)
            .map(|contacts| contacts.len())
            .unwrap_or(0)
    }

    /// Check if two users have each other as contacts (mutual)
    pub fn are_mutual_contacts(&self, user1: &PublicKey, user2: &PublicKey) -> bool {
        let user1_has_user2 = self.user_contacts
            .get(user1)
            .map(|contacts| {
                contacts.iter().any(|contact_id| {
                    if let Some(contact) = self.contacts.get(contact_id) {
                        contact.public_key == *user2
                    } else {
                        false
                    }
                })
            })
            .unwrap_or(false);

        let user2_has_user1 = self.user_contacts
            .get(user2)
            .map(|contacts| {
                contacts.iter().any(|contact_id| {
                    if let Some(contact) = self.contacts.get(contact_id) {
                        contact.public_key == *user1
                    } else {
                        false
                    }
                })
            })
            .unwrap_or(false);

        user1_has_user2 && user2_has_user1
    }

    /// Get all users who have a specific public key as a contact
    pub fn get_users_with_contact(&self, public_key: &PublicKey) -> Vec<&PublicKey> {
        self.public_key_index
            .get(public_key)
            .map(|owners| owners.iter().collect())
            .unwrap_or_default()
    }

    /// Get recent contacts (sorted by added timestamp)
    pub fn get_recent_contacts(&self, owner: &PublicKey, limit: usize) -> Vec<&ContactEntry> {
        let mut contacts = self.get_user_contacts(owner);
        contacts.sort_by(|a, b| b.added_timestamp.cmp(&a.added_timestamp));
        contacts.into_iter().take(limit).collect()
    }

    /// Export contacts for backup
    pub fn export_contacts(&self, owner: &PublicKey) -> Vec<ContactEntry> {
        self.get_user_contacts(owner)
            .into_iter()
            .cloned()
            .collect()
    }

    /// Import contacts from backup
    pub fn import_contacts(
        &mut self,
        owner: &PublicKey,
        contacts: Vec<ContactEntry>,
    ) -> Result<usize, String> {
        let mut imported_count = 0;

        for mut contact in contacts {
            // Update owner to match current user
            contact.owner = owner.clone();

            // Regenerate contact ID
            contact.contact_id = crate::contracts::utils::generate_contact_id(
                &owner.key_id,
                &contact.public_key.key_id,
            );

            // Check if contact already exists
            let already_exists = self.user_contacts
                .get(owner)
                .map(|existing_contacts| {
                    existing_contacts.iter().any(|id| {
                        if let Some(existing) = self.contacts.get(id) {
                            existing.public_key == contact.public_key
                        } else {
                            false
                        }
                    })
                })
                .unwrap_or(false);

            if !already_exists {
                contact.validate()?;
                let contact_id = contact.contact_id;

                // Add to user contacts list
                self.user_contacts
                    .entry(owner.clone())
                    .or_insert_with(Vec::new)
                    .push(contact_id);

                // Add to public key index
                self.public_key_index
                    .entry(contact.public_key.clone())
                    .or_insert_with(Vec::new)
                    .push(owner.clone());

                // Store the contact
                self.contacts.insert(contact_id, contact);
                imported_count += 1;
            }
        }

        Ok(imported_count)
    }

    /// Get total contact count across all users
    pub fn total_contact_count(&self) -> usize {
        self.contacts.len()
    }

    /// Get statistics about the contact system
    pub fn get_stats(&self) -> ContactStats {
        let total_contacts = self.contacts.len();
        let total_users = self.user_contacts.len();
        let verified_contacts = self.contacts.values().filter(|c| c.verified).count();

        let mut contact_counts: Vec<usize> = self.user_contacts
            .values()
            .map(|contacts| contacts.len())
            .collect();
        contact_counts.sort();

        let average_contacts_per_user = if total_users > 0 {
            total_contacts as f64 / total_users as f64
        } else {
            0.0
        };

        let median_contacts_per_user = if contact_counts.is_empty() {
            0
        } else {
            contact_counts[contact_counts.len() / 2]
        };

        ContactStats {
            total_contacts,
            total_users,
            verified_contacts,
            average_contacts_per_user,
            median_contacts_per_user,
        }
    }
}

