pub fn create_genesis_block() -> Block {
    // FIXED genesis timestamp for network consistency
    // November 1, 2025 00:00:00 UTC - ensures all nodes create identical genesis
    let genesis_timestamp = 1730419200;
    // Genesis blocks should use easy consensus difficulty like other system transaction blocks
    let genesis_difficulty = Difficulty::from_bits(0x1fffffff);

    let header = BlockHeader::new(
        1, // version
        Hash::default(), // previous_block_hash (none for genesis)
        Hash::default(), // merkle_root (will be calculated)
        genesis_timestamp,
        genesis_difficulty,
        0, // height
        0, // transaction_count
        0, // block_size
        genesis_difficulty, // cumulative_difficulty
    );

    let genesis_block = Block::new(header, Vec::new());

    // For genesis block, we might want to add special transactions
    // This is handled by the blockchain initialization logic

    genesis_block
}

impl std::fmt::Display for BlockValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            BlockValidationError::InvalidHeader => write!(f, "Invalid block header"),
            BlockValidationError::InvalidMerkleRoot => write!(f, "Invalid merkle root"),
            BlockValidationError::InvalidTimestamp => write!(f, "Invalid timestamp"),
            BlockValidationError::InvalidDifficulty => write!(f, "Invalid difficulty"),
            BlockValidationError::InvalidProofOfWork => write!(f, "Invalid proof of work"),
            BlockValidationError::InvalidTransactions => write!(f, "Invalid transactions"),
            BlockValidationError::InvalidSize => write!(f, "Invalid block size"),
            BlockValidationError::InvalidHeight => write!(f, "Invalid block height"),
        }
    }
}

impl BlockBuilder {
    /// Create a new block builder
    pub fn new(
        previous_block_hash: Hash,
        height: u64,
        difficulty: Difficulty,
    ) -> Self {
        Self {
            version: 1,
            previous_block_hash,
            timestamp: crate::utils::time::current_timestamp(),
            difficulty,
            height,
            transactions: Vec::new(),
        }
    }

    /// Set block version
    pub fn version(mut self, version: u32) -> Self {
        self.version = version;
        self
    }

    /// Set block timestamp
    pub fn timestamp(mut self, timestamp: u64) -> Self {
        self.timestamp = timestamp;
        self
    }

    /// Add a transaction to the block
    pub fn add_transaction(mut self, transaction: Transaction) -> Self {
        self.transactions.push(transaction);
        self
    }

    /// Add multiple transactions to the block
    pub fn add_transactions(mut self, transactions: Vec<Transaction>) -> Self {
        self.transactions.extend(transactions);
        self
    }

    /// Set all transactions (replacing existing ones)
    pub fn transactions(mut self, transactions: Vec<Transaction>) -> Self {
        self.transactions = transactions;
        self
    }

    /// Build the block
    pub fn build(self) -> Result<Block> {
        // Calculate merkle root
        let merkle_root = crate::transaction::hashing::calculate_transaction_merkle_root(&self.transactions);

        // Calculate block size
        let transaction_count = self.transactions.len() as u32;
        let block_size = self.calculate_block_size();

        // Calculate cumulative difficulty (simplified)
        let cumulative_difficulty = self.difficulty;

        // Create header
        let header = BlockHeader::new(
            self.version,
            self.previous_block_hash,
            merkle_root,
            self.timestamp,
            self.difficulty,
            self.height,
            transaction_count,
            block_size,
            cumulative_difficulty,
        );

        Ok(Block::new(header, self.transactions))
    }

    /// Calculate the size of the block being built
    fn calculate_block_size(&self) -> u32 {
        let header_size = 200; // Approximate header size
        let transactions_size: usize = self.transactions
            .iter()
            .map(|tx| crate::utils::size::transaction_size(tx))
            .sum();
        (header_size + transactions_size) as u32
    }
}

