pub use packet::{DnsPacket, DnsQuestion, DnsAnswer, MAX_UDP_SIZE};
pub use transport::{ZdnsTransportServer, ZdnsServerConfig, TransportStats, DNS_PORT};

pub struct DnsPacket {
    /// Transaction ID
    pub id: u16,
    /// Is this a response?
    pub is_response: bool,
    /// Query domain name
    pub question: Option<DnsQuestion>,
    /// Answer records
    pub answers: Vec<DnsAnswer>,
    /// Response code (0 = no error, 3 = NXDOMAIN)
    pub rcode: u8,
}

pub struct DnsQuestion {
    /// Domain name (e.g., "myapp.zhtp")
    pub name: String,
    /// Query type (1 = A)
    pub qtype: u16,
    /// Query class (1 = IN)
    pub qclass: u16,
}

pub struct DnsAnswer {
    /// Domain name
    pub name: String,
    /// Record type
    pub rtype: u16,
    /// Record class
    pub rclass: u16,
    /// TTL in seconds
    pub ttl: u32,
    /// Record data (4 bytes for A record)
    pub rdata: Vec<u8>,
}

impl DnsPacket {
    /// Parse a DNS packet from bytes
    pub fn parse(data: &[u8]) -> Result<Self> {
        if data.len() < 12 {
            return Err(anyhow!("DNS packet too short: {} bytes", data.len()));
        }

        // Parse header
        let id = u16::from_be_bytes([data[0], data[1]]);
        let flags = u16::from_be_bytes([data[2], data[3]]);
        let is_response = (flags & QR_RESPONSE) != 0;
        let rcode = (flags & 0x000F) as u8;
        let qdcount = u16::from_be_bytes([data[4], data[5]]);
        let ancount = u16::from_be_bytes([data[6], data[7]]);

        let mut offset = 12;

        // Parse question section
        let question = if qdcount > 0 {
            let (name, new_offset) = Self::parse_name(data, offset)?;
            offset = new_offset;

            if offset + 4 > data.len() {
                return Err(anyhow!("DNS packet truncated in question section"));
            }

            let qtype = u16::from_be_bytes([data[offset], data[offset + 1]]);
            let qclass = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
            offset += 4;

            Some(DnsQuestion { name, qtype, qclass })
        } else {
            None
        };

        // Parse answer section (for responses)
        let mut answers = Vec::new();
        for _ in 0..ancount {
            if offset >= data.len() {
                break;
            }

            let (name, new_offset) = Self::parse_name(data, offset)?;
            offset = new_offset;

            if offset + 10 > data.len() {
                break;
            }

            let rtype = u16::from_be_bytes([data[offset], data[offset + 1]]);
            let rclass = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
            let ttl = u32::from_be_bytes([
                data[offset + 4],
                data[offset + 5],
                data[offset + 6],
                data[offset + 7],
            ]);
            let rdlength = u16::from_be_bytes([data[offset + 8], data[offset + 9]]) as usize;
            offset += 10;

            if offset + rdlength > data.len() {
                break;
            }

            let rdata = data[offset..offset + rdlength].to_vec();
            offset += rdlength;

            answers.push(DnsAnswer {
                name,
                rtype,
                rclass,
                ttl,
                rdata,
            });
        }

        Ok(DnsPacket {
            id,
            is_response,
            question,
            answers,
            rcode,
        })
    }

    /// Parse a domain name from DNS wire format
    fn parse_name(data: &[u8], mut offset: usize) -> Result<(String, usize)> {
        let mut labels = Vec::new();
        let mut jumped = false;
        let mut jump_offset = 0;

        loop {
            if offset >= data.len() {
                return Err(anyhow!("DNS name parsing: unexpected end of data"));
            }

            let len = data[offset] as usize;

            // Check for compression pointer
            if len & 0xC0 == 0xC0 {
                if offset + 1 >= data.len() {
                    return Err(anyhow!("DNS name parsing: truncated pointer"));
                }
                let ptr = ((len & 0x3F) << 8 | data[offset + 1] as usize) as usize;
                if !jumped {
                    jump_offset = offset + 2;
                }
                offset = ptr;
                jumped = true;
                continue;
            }

            // End of name
            if len == 0 {
                if !jumped {
                    jump_offset = offset + 1;
                }
                break;
            }

            // Read label
            offset += 1;
            if offset + len > data.len() {
                return Err(anyhow!("DNS name parsing: label extends past end"));
            }

            let label = String::from_utf8_lossy(&data[offset..offset + len]).to_string();
            labels.push(label);
            offset += len;
        }

        Ok((labels.join("."), jump_offset))
    }

    /// Create an A record response
    pub fn a_record(query: &DnsPacket, ip: Ipv4Addr, ttl: u32) -> Self {
        let question = query.question.clone();
        let name = question.as_ref().map(|q| q.name.clone()).unwrap_or_default();

        DnsPacket {
            id: query.id,
            is_response: true,
            question,
            answers: vec![DnsAnswer {
                name,
                rtype: TYPE_A,
                rclass: CLASS_IN,
                ttl,
                rdata: ip.octets().to_vec(),
            }],
            rcode: 0,
        }
    }

    /// Create an NXDOMAIN response
    pub fn nxdomain(query: &DnsPacket) -> Self {
        DnsPacket {
            id: query.id,
            is_response: true,
            question: query.question.clone(),
            answers: vec![],
            rcode: 3, // NXDOMAIN
        }
    }

    /// Create a SERVFAIL response
    pub fn servfail(query: &DnsPacket) -> Self {
        DnsPacket {
            id: query.id,
            is_response: true,
            question: query.question.clone(),
            answers: vec![],
            rcode: 2, // SERVFAIL
        }
    }

    /// Create a NOTIMP (Not Implemented) response for unsupported query types
    /// Used when the domain exists but we don't support the requested record type (e.g., AAAA, MX)
    pub fn notimp(query: &DnsPacket) -> Self {
        DnsPacket {
            id: query.id,
            is_response: true,
            question: query.question.clone(),
            answers: vec![],
            rcode: 4, // NOTIMP
        }
    }

    /// Serialize to DNS wire format
    pub fn serialize(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(MAX_UDP_SIZE);

        // Header
        buf.extend_from_slice(&self.id.to_be_bytes());

        // Flags
        let mut flags: u16 = 0;
        if self.is_response {
            flags |= QR_RESPONSE;
            flags |= AA_AUTHORITATIVE;
            flags |= RA_RECURSION_AVAILABLE;
        }
        flags |= RD_RECURSION_DESIRED;
        flags |= (self.rcode as u16) & 0x000F;
        buf.extend_from_slice(&flags.to_be_bytes());

        // Counts
        let qdcount: u16 = if self.question.is_some() { 1 } else { 0 };
        let ancount: u16 = self.answers.len() as u16;
        buf.extend_from_slice(&qdcount.to_be_bytes());
        buf.extend_from_slice(&ancount.to_be_bytes());
        buf.extend_from_slice(&0u16.to_be_bytes()); // NSCOUNT
        buf.extend_from_slice(&0u16.to_be_bytes()); // ARCOUNT

        // Question section
        if let Some(ref q) = self.question {
            Self::write_name(&mut buf, &q.name);
            buf.extend_from_slice(&q.qtype.to_be_bytes());
            buf.extend_from_slice(&q.qclass.to_be_bytes());
        }

        // Answer section
        for answer in &self.answers {
            Self::write_name(&mut buf, &answer.name);
            buf.extend_from_slice(&answer.rtype.to_be_bytes());
            buf.extend_from_slice(&answer.rclass.to_be_bytes());
            buf.extend_from_slice(&answer.ttl.to_be_bytes());
            buf.extend_from_slice(&(answer.rdata.len() as u16).to_be_bytes());
            buf.extend_from_slice(&answer.rdata);
        }

        buf
    }

    /// Write a domain name in DNS wire format
    fn write_name(buf: &mut Vec<u8>, name: &str) {
        for label in name.split('.') {
            if label.is_empty() {
                continue;
            }
            buf.push(label.len() as u8);
            buf.extend_from_slice(label.as_bytes());
        }
        buf.push(0); // Root label
    }

    /// Get the queried domain name
    pub fn query_name(&self) -> Option<&str> {
        self.question.as_ref().map(|q| q.name.as_str())
    }

    /// Check if this is an A record query
    pub fn is_a_query(&self) -> bool {
        self.question.as_ref().map(|q| q.qtype == TYPE_A).unwrap_or(false)
    }
}

pub struct Web4Record {
    /// Domain name
    pub domain: String,
    /// Owner identity (hex-encoded hash for privacy)
    pub owner: String,
    /// Content mappings (path -> content_hash)
    pub content_mappings: HashMap<String, String>,
    /// Content serving mode (Static or SPA)
    pub content_mode: Option<ContentMode>,
    /// SPA entry point (e.g., "index.html")
    pub spa_entry: Option<String>,
    /// Asset prefixes that should not fallback to SPA entry
    pub asset_prefixes: Option<Vec<String>>,
    /// Web4 capability level
    pub capability: Option<Web4Capability>,
    /// Record TTL in seconds
    pub ttl: u64,
    /// Registration timestamp
    pub registered_at: u64,
    /// Expiration timestamp
    pub expires_at: u64,
}

impl Web4Record {
    /// Check if the domain has expired
    pub fn is_expired(&self) -> bool {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        self.expires_at < now
    }

    /// Check if domain has content mappings
    pub fn has_content(&self) -> bool {
        !self.content_mappings.is_empty()
    }

    /// Get effective content mode (defaults to SPA)
    pub fn effective_content_mode(&self) -> ContentMode {
        self.content_mode.unwrap_or(ContentMode::Spa)
    }

    /// Get effective capability (defaults to SpaServe)
    pub fn effective_capability(&self) -> Web4Capability {
        self.capability.unwrap_or(Web4Capability::SpaServe)
    }
}

pub struct CachedRecord {
    /// The resolved Web4 record (None for negative cache entries)
    pub record: Option<Web4Record>,
    /// When this entry was cached
    pub cached_at: Instant,
    /// Cache TTL for this entry
    pub ttl: Duration,
}

impl CachedRecord {
    /// Check if the cached entry has expired
    pub fn is_expired(&self) -> bool {
        self.cached_at.elapsed() >= self.ttl
    }

    /// Create a positive cache entry
    pub fn positive(record: Web4Record, ttl: Duration) -> Self {
        Self {
            record: Some(record),
            cached_at: Instant::now(),
            ttl,
        }
    }

    /// Create a negative cache entry (domain not found)
    pub fn negative(ttl: Duration) -> Self {
        Self {
            record: None,
            cached_at: Instant::now(),
            ttl,
        }
    }
}

pub struct ResolverMetrics {
    /// Total cache hits
    pub cache_hits: u64,
    /// Total cache misses
    pub cache_misses: u64,
    /// Total negative cache hits (cached not-found)
    pub negative_hits: u64,
    /// Total registry lookups performed
    pub registry_lookups: u64,
    /// Total expired entries encountered
    pub expired_entries: u64,
    /// Total invalidations performed
    pub invalidations: u64,
}

impl ResolverMetrics {
    /// Calculate cache hit ratio
    pub fn hit_ratio(&self) -> f64 {
        let total = self.cache_hits + self.cache_misses;
        if total == 0 {
            0.0
        } else {
            self.cache_hits as f64 / total as f64
        }
    }
}

pub struct ZdnsResolver {
    /// Domain registry for lookups
    domain_registry: Arc<DomainRegistry>,
    /// LRU cache for resolved records
    cache: Arc<RwLock<LruCache<String, CachedRecord>>>,
    /// Resolver configuration
    config: ZdnsConfig,
    /// Metrics for monitoring
    metrics: Arc<RwLock<ResolverMetrics>>,
}

impl ZdnsResolver {
    /// Create a new ZDNS resolver
    pub fn new(domain_registry: Arc<DomainRegistry>, config: ZdnsConfig) -> Self {
        info!(
            cache_size = config.cache_size,
            default_ttl_secs = config.default_ttl.as_secs(),
            "ZDNS resolver initialized"
        );

        Self {
            domain_registry,
            cache: Arc::new(RwLock::new(LruCache::new(
                std::num::NonZeroUsize::new(config.cache_size).unwrap_or(
                    std::num::NonZeroUsize::new(1).unwrap()
                )
            ))),
            config,
            metrics: Arc::new(RwLock::new(ResolverMetrics::default())),
        }
    }

    /// Resolve a Web4 domain with caching
    ///
    /// Returns the resolved Web4 record, using cache when available.
    /// Cache misses trigger a registry lookup and cache the result.
    pub async fn resolve_web4(&self, domain: &str) -> Result<Web4Record, ZdnsError> {
        // Validate domain format
        if !Self::is_valid_domain(domain) {
            return Err(ZdnsError::InvalidDomain(domain.to_string()));
        }

        // Normalize domain (lowercase, trim whitespace)
        let domain = domain.to_lowercase().trim().to_string();

        // Check cache first
        {
            let mut cache = self.cache.write().await;
            if let Some(cached) = cache.get(&domain) {
                if !cached.is_expired() {
                    // Update metrics
                    if self.config.enable_metrics {
                        let mut metrics = self.metrics.write().await;
                        if cached.record.is_some() {
                            metrics.cache_hits += 1;
                        } else {
                            metrics.negative_hits += 1;
                        }
                    }

                    if self.config.debug_cache {
                        debug!(
                            domain = %domain,
                            is_negative = cached.record.is_none(),
                            age_ms = cached.cached_at.elapsed().as_millis(),
                            "Cache hit"
                        );
                    }

                    // Return cached result
                    return match &cached.record {
                        Some(record) => Ok(record.clone()),
                        None => Err(ZdnsError::DomainNotFound(domain)),
                    };
                } else {
                    // Expired entry - will be replaced
                    if self.config.enable_metrics {
                        let mut metrics = self.metrics.write().await;
                        metrics.expired_entries += 1;
                    }

                    if self.config.debug_cache {
                        debug!(domain = %domain, "Cache entry expired");
                    }
                }
            }
        }

        // Cache miss - resolve from registry
        if self.config.enable_metrics {
            let mut metrics = self.metrics.write().await;
            metrics.cache_misses += 1;
            metrics.registry_lookups += 1;
        }

        let result = self.resolve_from_registry(&domain).await;

        // Cache the result
        {
            let mut cache = self.cache.write().await;
            match &result {
                Ok(record) => {
                    let ttl = if record.ttl > 0 {
                        Duration::from_secs(record.ttl)
                    } else {
                        self.config.default_ttl
                    };
                    cache.put(domain.clone(), CachedRecord::positive(record.clone(), ttl));

                    if self.config.debug_cache {
                        debug!(
                            domain = %domain,
                            ttl_secs = ttl.as_secs(),
                            "Cached positive result"
                        );
                    }
                }
                Err(ZdnsError::DomainNotFound(_)) => {
                    // Cache negative result
                    cache.put(domain.clone(), CachedRecord::negative(self.config.negative_ttl));

                    if self.config.debug_cache {
                        debug!(
                            domain = %domain,
                            ttl_secs = self.config.negative_ttl.as_secs(),
                            "Cached negative result"
                        );
                    }
                }
                Err(_) => {
                    // Don't cache errors other than not-found
                }
            }
        }

        result
    }

    /// Invalidate cache entry for a domain
    ///
    /// Call this when a domain is registered, updated, or content is published.
    pub async fn invalidate(&self, domain: &str) {
        let domain = domain.to_lowercase().trim().to_string();

        let mut cache = self.cache.write().await;
        if cache.pop(&domain).is_some() {
            if self.config.enable_metrics {
                drop(cache); // Release cache lock before acquiring metrics lock
                let mut metrics = self.metrics.write().await;
                metrics.invalidations += 1;
            }

            info!(domain = %domain, "Cache entry invalidated");
        }
    }

    /// Invalidate all cache entries (for maintenance/testing)
    pub async fn invalidate_all(&self) {
        let mut cache = self.cache.write().await;
        let count = cache.len();
        cache.clear();

        info!(entries_cleared = count, "All cache entries invalidated");
    }

    /// Get current resolver metrics
    pub async fn get_metrics(&self) -> ResolverMetrics {
        self.metrics.read().await.clone()
    }

    /// Get current cache size
    pub async fn cache_size(&self) -> usize {
        self.cache.read().await.len()
    }

    /// Resolve domain from registry (no caching)
    async fn resolve_from_registry(&self, domain: &str) -> Result<Web4Record, ZdnsError> {
        match self.domain_registry.lookup_domain(domain).await {
            Ok(lookup) if lookup.found => {
                if let Some(record) = lookup.record {
                    // Check if domain has expired
                    let now = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_secs())
                        .unwrap_or(0);

                    if record.expires_at < now {
                        return Err(ZdnsError::DomainExpired(domain.to_string()));
                    }

                    // Convert DomainRecord to Web4Record
                    let web4_record = Self::domain_record_to_web4(record);
                    Ok(web4_record)
                } else {
                    Err(ZdnsError::DomainNotFound(domain.to_string()))
                }
            }
            Ok(_) => {
                Err(ZdnsError::DomainNotFound(domain.to_string()))
            }
            Err(e) => {
                warn!(domain = %domain, error = %e, "Registry lookup failed");
                Err(ZdnsError::RegistryError(e.to_string()))
            }
        }
    }

    /// Convert DomainRecord to Web4Record
    ///
    /// TTL is calculated as the minimum of:
    /// - Time until domain expiration
    /// - Maximum cache TTL (1 hour)
    fn domain_record_to_web4(record: DomainRecord) -> Web4Record {
        // Extract owner as hex-encoded hash for privacy
        let owner = hex::encode(&record.owner.0[..16]);

        // Calculate TTL based on domain expiration
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        // TTL is time until expiration, capped at 1 hour max
        const MAX_TTL_SECS: u64 = 3600; // 1 hour max cache
        let time_until_expiry = record.expires_at.saturating_sub(now);
        let ttl = time_until_expiry.min(MAX_TTL_SECS);

        // Determine content mode from metadata category
        // Domains with "static" category serve static content, others use SPA
        let content_mode = if record.metadata.category.to_lowercase() == "static" {
            ContentMode::Static
        } else {
            ContentMode::Spa
        };

        // Determine capability from metadata
        // If public = false, restrict to download only
        let capability = if !record.metadata.public {
            Web4Capability::DownloadOnly
        } else if content_mode == ContentMode::Static {
            Web4Capability::HttpServe
        } else {
            Web4Capability::SpaServe
        };

        Web4Record {
            domain: record.domain,
            owner,
            content_mappings: record.content_mappings,
            content_mode: Some(content_mode),
            spa_entry: Some("index.html".to_string()),
            asset_prefixes: Some(vec![
                "/assets/".to_string(),
                "/static/".to_string(),
                "/js/".to_string(),
                "/css/".to_string(),
                "/images/".to_string(),
            ]),
            capability: Some(capability),
            ttl,
            registered_at: record.registered_at,
            expires_at: record.expires_at,
        }
    }

    /// Allowed sovereign TLDs
    pub const ALLOWED_TLDS: &'static [&'static str] = &[".zhtp", ".sov"];

    /// Validate domain name format
    ///
    /// Enforces:
    /// - Must end with .zhtp or .sov (sovereign namespaces only)
    /// - DNS-compliant label rules (alphanumeric + hyphen, no leading/trailing hyphen)
    /// - Maximum 253 characters total, 63 per label
    /// - No underscores (not DNS compliant)
    pub fn is_valid_domain(domain: &str) -> bool {
        // Must not be empty
        if domain.is_empty() {
            return false;
        }

        // Must not exceed 253 characters (DNS limit)
        if domain.len() > 253 {
            return false;
        }

        // CRITICAL: Must end with allowed sovereign TLD (.zhtp or .sov)
        let has_valid_tld = Self::ALLOWED_TLDS.iter().any(|tld| domain.ends_with(tld));
        if !has_valid_tld {
            return false;
        }

        // Must contain only valid DNS characters (alphanumeric, hyphen, dot)
        // Note: underscores are NOT DNS compliant and are rejected
        for c in domain.chars() {
            if !c.is_ascii_alphanumeric() && c != '-' && c != '.' {
                return false;
            }
        }

        // Must not start or end with hyphen or dot
        if domain.starts_with('-') || domain.starts_with('.')
            || domain.ends_with('-') {
            return false;
        }

        // Must not have consecutive dots
        if domain.contains("..") {
            return false;
        }

        // Each label must not start or end with hyphen and must not exceed 63 chars
        for label in domain.split('.') {
            if label.is_empty() {
                return false;
            }
            if label.starts_with('-') || label.ends_with('-') {
                return false;
            }
            // Label must not exceed 63 characters
            if label.len() > 63 {
                return false;
            }
        }

        true
    }
}

pub struct ZdnsServerConfig {
    /// Port to listen on (default: 53)
    pub port: u16,
    /// Gateway IP address to return for resolved domains
    pub gateway_ip: Ipv4Addr,
    /// Default TTL for DNS responses (seconds) - used as max cap
    pub default_ttl: u32,
    /// Enable TCP support (in addition to UDP)
    pub enable_tcp: bool,
    /// Bind address (default: 127.0.0.1 for safety)
    pub bind_addr: IpAddr,
    /// Enable rate limiting
    pub enable_rate_limit: bool,
    /// Allowed capabilities for gateway routing (None = all allowed)
    pub allowed_capabilities: Option<Vec<Web4Capability>>,
}

impl Default for ZdnsServerConfig {
    fn default() -> Self {
        Self {
            port: DNS_PORT,
            gateway_ip: Ipv4Addr::new(127, 0, 0, 1),
            default_ttl: 3600,
            enable_tcp: true,
            // SECURITY: Default to localhost only - explicit config required for 0.0.0.0
            bind_addr: IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)),
            enable_rate_limit: true,
            // By default, only allow HttpServe and SpaServe (not DownloadOnly)
            allowed_capabilities: Some(vec![Web4Capability::HttpServe, Web4Capability::SpaServe]),
        }
    }
}

impl ZdnsServerConfig {
    /// Create config for local development
    pub fn localhost() -> Self {
        Self {
            port: 5353, // Non-privileged port for testing
            gateway_ip: Ipv4Addr::new(127, 0, 0, 1),
            default_ttl: 60,
            enable_tcp: true,
            bind_addr: IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)),
            enable_rate_limit: false, // Disabled for local testing
            allowed_capabilities: None, // Allow all for testing
        }
    }

    /// Create config for production with specified gateway IP
    /// SECURITY: Still binds to localhost by default - use with_bind_addr() to expose
    pub fn production(gateway_ip: Ipv4Addr) -> Self {
        Self {
            port: DNS_PORT,
            gateway_ip,
            default_ttl: 3600,
            enable_tcp: true,
            // SECURITY: Default to localhost - caller must explicitly set bind_addr
            bind_addr: IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)),
            enable_rate_limit: true,
            allowed_capabilities: Some(vec![Web4Capability::HttpServe, Web4Capability::SpaServe]),
        }
    }

    /// Set bind address (use with caution for non-localhost)
    pub fn with_bind_addr(mut self, addr: IpAddr) -> Self {
        if addr == IpAddr::V4(Ipv4Addr::new(0, 0, 0, 0)) {
            warn!("ZDNS binding to 0.0.0.0 - ensure firewall and rate limiting are configured");
        }
        self.bind_addr = addr;
        self
    }
}

struct RateLimitEntry {
    count: u32,
    window_start: Instant,
}

struct RateLimiter {
    entries: RwLock<HashMap<IpAddr, RateLimitEntry>>,
    max_queries: u32,
    window_duration: Duration,
}

impl RateLimiter {
    fn new(max_queries: u32, window_secs: u64) -> Self {
        Self {
            entries: RwLock::new(HashMap::new()),
            max_queries,
            window_duration: Duration::from_secs(window_secs),
        }
    }

    /// Check if request is allowed, returns false if rate limited
    async fn check_and_increment(&self, ip: IpAddr) -> bool {
        let now = Instant::now();
        let mut entries = self.entries.write().await;

        let entry = entries.entry(ip).or_insert(RateLimitEntry {
            count: 0,
            window_start: now,
        });

        // Reset window if expired
        if now.duration_since(entry.window_start) >= self.window_duration {
            entry.count = 0;
            entry.window_start = now;
        }

        if entry.count >= self.max_queries {
            return false; // Rate limited
        }

        entry.count += 1;
        true
    }

    /// Cleanup old entries periodically
    async fn cleanup_old_entries(&self) {
        let now = Instant::now();
        let mut entries = self.entries.write().await;
        entries.retain(|_, entry| {
            now.duration_since(entry.window_start) < self.window_duration * 2
        });
    }
}

pub struct ZdnsTransportServer {
    /// Domain resolver with caching
    resolver: Arc<ZdnsResolver>,
    /// Server configuration
    config: ZdnsServerConfig,
    /// Running state
    is_running: Arc<RwLock<bool>>,
    /// Statistics
    stats: Arc<RwLock<TransportStats>>,
    /// Rate limiter
    rate_limiter: Arc<RateLimiter>,
    /// Semaphore for bounding UDP handlers
    udp_semaphore: Arc<Semaphore>,
    /// Semaphore for bounding TCP connections
    tcp_semaphore: Arc<Semaphore>,
}

pub struct TransportStats {
    /// Total UDP queries received
    pub udp_queries: u64,
    /// Total TCP queries received
    pub tcp_queries: u64,
    /// Successful resolutions
    pub resolved: u64,
    /// NXDOMAIN responses
    pub nxdomain: u64,
    /// Errors
    pub errors: u64,
    /// Non-.zhtp/.sov queries (ignored)
    pub ignored: u64,
    /// Rate limited queries
    pub rate_limited: u64,
    /// Queries rejected due to capability mismatch
    pub capability_rejected: u64,
}

impl ZdnsTransportServer {
    /// Create a new ZDNS transport server
    pub fn new(resolver: Arc<ZdnsResolver>, config: ZdnsServerConfig) -> Self {
        info!(
            port = config.port,
            gateway_ip = %config.gateway_ip,
            tcp_enabled = config.enable_tcp,
            bind_addr = %config.bind_addr,
            rate_limit_enabled = config.enable_rate_limit,
            "ZDNS transport server created"
        );

        Self {
            resolver,
            config,
            is_running: Arc::new(RwLock::new(false)),
            stats: Arc::new(RwLock::new(TransportStats::default())),
            rate_limiter: Arc::new(RateLimiter::new(RATE_LIMIT_MAX_QUERIES, RATE_LIMIT_WINDOW_SECS)),
            udp_semaphore: Arc::new(Semaphore::new(MAX_CONCURRENT_UDP_HANDLERS)),
            tcp_semaphore: Arc::new(Semaphore::new(MAX_CONCURRENT_TCP_CONNECTIONS)),
        }
    }

    /// Start the DNS server
    pub async fn start(&self) -> Result<()> {
        let bind_addr = SocketAddr::new(self.config.bind_addr, self.config.port);

        info!("Starting ZDNS transport server on {}", bind_addr);

        // Start UDP listener
        let udp_socket = UdpSocket::bind(bind_addr).await?;
        info!("UDP listener bound to {}", bind_addr);

        // Clone for UDP task
        let resolver = Arc::clone(&self.resolver);
        let config = self.config.clone();
        let stats = Arc::clone(&self.stats);
        let is_running = Arc::clone(&self.is_running);
        let rate_limiter = Arc::clone(&self.rate_limiter);
        let udp_semaphore = Arc::clone(&self.udp_semaphore);

        *self.is_running.write().await = true;

        // Spawn rate limiter cleanup task
        let cleanup_rate_limiter = Arc::clone(&self.rate_limiter);
        let cleanup_is_running = Arc::clone(&self.is_running);
        tokio::spawn(async move {
            while *cleanup_is_running.read().await {
                tokio::time::sleep(Duration::from_secs(60)).await;
                cleanup_rate_limiter.cleanup_old_entries().await;
            }
        });

        // Spawn UDP handler
        let udp_handle = tokio::spawn(async move {
            Self::handle_udp(udp_socket, resolver, config, stats, is_running, rate_limiter, udp_semaphore).await;
        });

        // Start TCP listener if enabled
        if self.config.enable_tcp {
            let tcp_listener = TcpListener::bind(bind_addr).await?;
            info!("TCP listener bound to {}", bind_addr);

            let resolver = Arc::clone(&self.resolver);
            let config = self.config.clone();
            let stats = Arc::clone(&self.stats);
            let is_running = Arc::clone(&self.is_running);
            let rate_limiter = Arc::clone(&self.rate_limiter);
            let tcp_semaphore = Arc::clone(&self.tcp_semaphore);

            tokio::spawn(async move {
                Self::handle_tcp(tcp_listener, resolver, config, stats, is_running, rate_limiter, tcp_semaphore).await;
            });
        }

        // Wait for UDP handler (main loop)
        let _ = udp_handle.await;

        Ok(())
    }

    /// Stop the DNS server
    pub async fn stop(&self) {
        info!("Stopping ZDNS transport server");
        *self.is_running.write().await = false;
    }

    /// Get current statistics
    pub async fn get_stats(&self) -> TransportStats {
        self.stats.read().await.clone()
    }

    /// Handle UDP queries with rate limiting and bounded concurrency
    async fn handle_udp(
        socket: UdpSocket,
        resolver: Arc<ZdnsResolver>,
        config: ZdnsServerConfig,
        stats: Arc<RwLock<TransportStats>>,
        is_running: Arc<RwLock<bool>>,
        rate_limiter: Arc<RateLimiter>,
        semaphore: Arc<Semaphore>,
    ) {
        let socket = Arc::new(socket);
        let mut buf = [0u8; MAX_UDP_SIZE];

        loop {
            if !*is_running.read().await {
                break;
            }

            match socket.recv_from(&mut buf).await {
                Ok((len, src)) => {
                    stats.write().await.udp_queries += 1;

                    // Rate limiting check
                    if config.enable_rate_limit && !rate_limiter.check_and_increment(src.ip()).await {
                        debug!(src = %src.ip(), "Rate limited UDP query");
                        stats.write().await.rate_limited += 1;
                        continue; // Drop the query silently
                    }

                    // Try to acquire semaphore permit (bounded concurrency)
                    let permit = match semaphore.clone().try_acquire_owned() {
                        Ok(p) => p,
                        Err(_) => {
                            // At capacity - drop query (backpressure)
                            debug!("UDP handler at capacity, dropping query from {}", src);
                            stats.write().await.errors += 1;
                            continue;
                        }
                    };

                    let data = buf[..len].to_vec();
                    let resolver = Arc::clone(&resolver);
                    let config = config.clone();
                    let stats = Arc::clone(&stats);
                    let socket_clone = Arc::clone(&socket);

                    // Process with bounded task
                    tokio::spawn(async move {
                        let _permit = permit; // Hold permit until done
                        if let Some(response) = Self::process_query(&data, &resolver, &config, &stats).await {
                            let response_bytes = response.serialize();
                            if let Err(e) = socket_clone.send_to(&response_bytes, src).await {
                                warn!("Failed to send UDP response to {}: {}", src, e);
                            }
                        }
                    });
                }
                Err(e) => {
                    if *is_running.read().await {
                        error!("UDP recv error: {}", e);
                        stats.write().await.errors += 1;
                    }
                }
            }
        }
    }

    /// Handle TCP connections with rate limiting and bounded concurrency
    async fn handle_tcp(
        listener: TcpListener,
        resolver: Arc<ZdnsResolver>,
        config: ZdnsServerConfig,
        stats: Arc<RwLock<TransportStats>>,
        is_running: Arc<RwLock<bool>>,
        rate_limiter: Arc<RateLimiter>,
        semaphore: Arc<Semaphore>,
    ) {
        loop {
            if !*is_running.read().await {
                break;
            }

            match listener.accept().await {
                Ok((stream, src)) => {
                    debug!("TCP connection from {}", src);
                    stats.write().await.tcp_queries += 1;

                    // Rate limiting check
                    if config.enable_rate_limit && !rate_limiter.check_and_increment(src.ip()).await {
                        debug!(src = %src.ip(), "Rate limited TCP connection");
                        stats.write().await.rate_limited += 1;
                        continue; // Drop the connection
                    }

                    // Try to acquire semaphore permit
                    let permit = match semaphore.clone().try_acquire_owned() {
                        Ok(p) => p,
                        Err(_) => {
                            debug!("TCP handler at capacity, dropping connection from {}", src);
                            stats.write().await.errors += 1;
                            continue;
                        }
                    };

                    let resolver = Arc::clone(&resolver);
                    let config = config.clone();
                    let stats = Arc::clone(&stats);

                    tokio::spawn(async move {
                        let _permit = permit; // Hold permit until done
                        if let Err(e) = Self::handle_tcp_connection(stream, &resolver, &config, &stats).await {
                            debug!("TCP connection error from {}: {}", src, e);
                        }
                    });
                }
                Err(e) => {
                    if *is_running.read().await {
                        error!("TCP accept error: {}", e);
                        stats.write().await.errors += 1;
                    }
                }
            }
        }
    }

    /// Handle a single TCP connection
    async fn handle_tcp_connection(
        mut stream: TcpStream,
        resolver: &ZdnsResolver,
        config: &ZdnsServerConfig,
        stats: &Arc<RwLock<TransportStats>>,
    ) -> Result<()> {
        // Set read timeout to prevent slow loris attacks
        let timeout = Duration::from_secs(5);

        // TCP DNS uses 2-byte length prefix
        let mut len_buf = [0u8; 2];
        tokio::time::timeout(timeout, stream.read_exact(&mut len_buf)).await
            .map_err(|_| anyhow::anyhow!("TCP read timeout"))??;

        let len = u16::from_be_bytes(len_buf) as usize;

        // Validate message size
        if len > MAX_TCP_MESSAGE_SIZE {
            return Err(anyhow::anyhow!("DNS message too large: {} > {}", len, MAX_TCP_MESSAGE_SIZE));
        }
        if len == 0 {
            return Err(anyhow::anyhow!("Empty DNS message"));
        }

        let mut data = vec![0u8; len];
        tokio::time::timeout(timeout, stream.read_exact(&mut data)).await
            .map_err(|_| anyhow::anyhow!("TCP read timeout"))??;

        if let Some(response) = Self::process_query(&data, resolver, config, stats).await {
            let response_bytes = response.serialize();
            let len_bytes = (response_bytes.len() as u16).to_be_bytes();

            tokio::time::timeout(timeout, async {
                stream.write_all(&len_bytes).await?;
                stream.write_all(&response_bytes).await
            }).await.map_err(|_| anyhow::anyhow!("TCP write timeout"))??;
        }

        Ok(())
    }

    /// Process a DNS query and return response
    async fn process_query(
        data: &[u8],
        resolver: &ZdnsResolver,
        config: &ZdnsServerConfig,
        stats: &Arc<RwLock<TransportStats>>,
    ) -> Option<DnsPacket> {
        // Parse query
        let query = match DnsPacket::parse(data) {
            Ok(q) => q,
            Err(e) => {
                debug!("Failed to parse DNS query: {}", e);
                stats.write().await.errors += 1;
                return None;
            }
        };

        // Only handle queries (not responses)
        if query.is_response {
            return None;
        }

        // Get query name
        let domain = match query.query_name() {
            Some(d) => d,
            None => {
                stats.write().await.errors += 1;
                return Some(DnsPacket::servfail(&query));
            }
        };

        // Normalize to lowercase for consistent handling
        let domain_lower = domain.to_lowercase();

        debug!(domain = %domain_lower, "Processing DNS query");

        // SECURITY: Strict sovereign TLD validation
        if !domain_lower.ends_with(".zhtp") && !domain_lower.ends_with(".sov") {
            debug!(domain = %domain_lower, "Ignoring non-sovereign domain");
            stats.write().await.ignored += 1;
            return None; // Let other DNS servers handle it
        }

        // Only handle A record queries - return NOTIMP for other types (AAAA, MX, etc.)
        // NOTIMP is correct because the domain exists but we don't implement that record type
        if !query.is_a_query() {
            debug!(domain = %domain_lower, "Non-A query, returning NOTIMP");
            stats.write().await.errors += 1;
            return Some(DnsPacket::notimp(&query));
        }

        // Resolve domain using ZDNS resolver (with caching)
        match resolver.resolve_web4(&domain_lower).await {
            Ok(record) => {
                // SECURITY: Check capability before returning gateway IP
                if let Some(ref allowed_caps) = config.allowed_capabilities {
                    let domain_cap = record.capability.unwrap_or(Web4Capability::SpaServe);
                    if !allowed_caps.contains(&domain_cap) {
                        debug!(
                            domain = %domain_lower,
                            capability = ?domain_cap,
                            "Domain capability not allowed for gateway routing"
                        );
                        stats.write().await.capability_rejected += 1;
                        return Some(DnsPacket::nxdomain(&query));
                    }
                }

                // Calculate TTL: use the lesser of record TTL and config max TTL
                let record_ttl = record.ttl.min(config.default_ttl as u64) as u32;
                // Also check expiration - don't serve if expired
                let now = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs();

                if record.expires_at > 0 && now >= record.expires_at {
                    debug!(domain = %domain_lower, "Domain expired");
                    stats.write().await.nxdomain += 1;
                    return Some(DnsPacket::nxdomain(&query));
                }

                // Use remaining time until expiration as TTL if shorter
                let remaining_ttl = if record.expires_at > now {
                    (record.expires_at - now).min(record_ttl as u64) as u32
                } else {
                    record_ttl
                };

                debug!(
                    domain = %domain_lower,
                    gateway_ip = %config.gateway_ip,
                    ttl = remaining_ttl,
                    "Domain resolved, returning gateway IP"
                );
                stats.write().await.resolved += 1;
                Some(DnsPacket::a_record(&query, config.gateway_ip, remaining_ttl))
            }
            Err(e) => {
                debug!(domain = %domain_lower, error = %e, "Domain not found");
                stats.write().await.nxdomain += 1;
                Some(DnsPacket::nxdomain(&query))
            }
        }
    }
}

pub struct Web4Client {
    /// QUIC endpoint
    endpoint: Endpoint,

    /// Authenticated connection to node
    connection: Option<AuthenticatedConnection>,

    /// Client identity (for signing requests)
    identity: Arc<ZhtpIdentity>,

    /// Handshake context with nonce cache
    handshake_ctx: HandshakeContext,

    /// Trust configuration
    trust_config: TrustConfig,

    /// Trust verifier (stored for DID binding after handshake)
    trust_verifier: Option<Arc<ZhtpTrustVerifier>>,
}

struct AuthenticatedConnection {
    /// QUIC connection
    quic_conn: Connection,

    /// Master key for symmetric encryption (from UHP handshake)
    master_key: [u8; 32],

    /// Application-layer MAC key (derived from master_key)
    app_key: [u8; 32],

    /// Peer's verified DID (from UHP handshake)
    peer_did: String,

    /// Session ID
    session_id: [u8; 16],

    /// Request sequence counter (for replay protection)
    sequence: AtomicU64,
}

impl AuthenticatedConnection {
    /// Get next sequence number
    fn next_sequence(&self) -> u64 {
        self.sequence.fetch_add(1, Ordering::SeqCst)
    }

    /// Derive application-layer MAC key from master key
    fn derive_app_key(master_key: &[u8; 32], session_id: &[u8; 16], peer_did: &str, client_did: &str) -> [u8; 32] {
        // HKDF-style derivation using BLAKE3
        let mut input = Vec::new();
        input.extend_from_slice(b"zhtp-web4-app-mac");
        input.extend_from_slice(master_key);
        input.extend_from_slice(session_id);
        input.extend_from_slice(peer_did.as_bytes());
        input.extend_from_slice(client_did.as_bytes());
        lib_crypto::hash_blake3(&input)
    }
}

impl Web4Client {
    /// Create a new Web4 client with the given identity and trust config
    pub async fn new_with_trust(identity: ZhtpIdentity, trust_config: TrustConfig) -> Result<Self> {
        // Create QUIC endpoint (client-only, no listening)
        let endpoint = Endpoint::client("0.0.0.0:0".parse()?)?;

        // Create nonce cache in temp directory (for CLI single-use)
        let temp_dir = std::env::temp_dir().join(format!("web4_client_{}", std::process::id()));
        std::fs::create_dir_all(&temp_dir)?;
        let nonce_cache = NonceCache::open(&temp_dir.join("nonces"), 3600, 10_000)
            .context("Failed to create nonce cache")?;
        let handshake_ctx = HandshakeContext::new(nonce_cache);

        info!(
            node_id = ?identity.node_id,
            did = %identity.did,
            trust_mode = ?if trust_config.bootstrap_mode { "bootstrap" }
                         else if trust_config.allow_tofu { "tofu" }
                         else if trust_config.pin_spki.is_some() { "pinned" }
                         else { "strict" },
            "Web4 client initialized"
        );

        Ok(Self {
            endpoint,
            connection: None,
            identity: Arc::new(identity),
            handshake_ctx,
            trust_config,
            trust_verifier: None,
        })
    }

    /// Create a new Web4 client with default trust (strict - requires pin or TOFU)
    ///
    /// This will fail to connect unless trust is established via:
    /// - `--pin-spki <hash>`
    /// - `--tofu` (with trustdb)
    /// - Or existing trustdb entry
    pub async fn new(identity: ZhtpIdentity) -> Result<Self> {
        let trustdb_path = TrustConfig::default_trustdb_path()?;
        let trust_config = TrustConfig {
            trustdb_path: Some(trustdb_path),
            ..Default::default()
        };
        Self::new_with_trust(identity, trust_config).await
    }

    /// Create a new Web4 client in bootstrap mode (accepts any cert - DEV ONLY)
    ///
    /// WARNING: Bootstrap mode provides NO certificate verification.
    /// Use only for development or when connecting to known local nodes.
    pub async fn new_bootstrap(identity: ZhtpIdentity) -> Result<Self> {
        Self::ensure_bootstrap_allowed()?;
        warn!("Web4 client created in BOOTSTRAP MODE - NO TLS VERIFICATION");
        Self::new_with_trust(identity, TrustConfig::bootstrap()).await
    }

    /// Create a new Web4 client with TOFU (Trust On First Use)
    ///
    /// The first connection to a new node will be accepted and stored.
    /// Subsequent connections require the same certificate.
    pub async fn new_tofu(identity: ZhtpIdentity) -> Result<Self> {
        let trustdb_path = TrustConfig::default_trustdb_path()?;
        Self::new_with_trust(identity, TrustConfig::with_tofu(trustdb_path)).await
    }

    /// Enforce explicit bootstrap enablement in release builds
    fn ensure_bootstrap_allowed() -> Result<()> {
        let allowed = env::var("ZHTP_ALLOW_BOOTSTRAP").ok().map(|v| v == "1").unwrap_or(false);

        if !cfg!(debug_assertions) && !allowed {
            return Err(anyhow!(
                "Bootstrap mode is disabled in production builds. Set ZHTP_ALLOW_BOOTSTRAP=1 to proceed (dev only)."
            ));
        }
        if !allowed {
            return Err(anyhow!(
                "Bootstrap mode requires ZHTP_ALLOW_BOOTSTRAP=1. Use only with --trust-node for development."
            ));
        }
        Ok(())
    }

    /// Create a new Web4 client with SPKI pinning
    ///
    /// Only accepts connections to nodes with the exact SPKI hash.
    pub async fn new_pinned(identity: ZhtpIdentity, spki_sha256: String) -> Result<Self> {
        Self::new_with_trust(identity, TrustConfig::with_pin(spki_sha256)).await
    }

    /// Load identity from a keystore directory
    pub async fn from_keystore(keystore_path: &Path) -> Result<Self> {
        let identity = Self::load_identity_from_keystore(keystore_path)?;
        Self::new(identity).await
    }

    /// Load identity from keystore with specific trust config
    pub async fn from_keystore_with_trust(keystore_path: &Path, trust_config: TrustConfig) -> Result<Self> {
        let identity = Self::load_identity_from_keystore(keystore_path)?;
        Self::new_with_trust(identity, trust_config).await
    }

    fn load_identity_from_keystore(keystore_path: &Path) -> Result<ZhtpIdentity> {
        if !keystore_path.exists() {
            return Err(anyhow!("Keystore not found at {:?}", keystore_path));
        }

        let identity_path = keystore_path.join("identity.json");
        if identity_path.exists() {
            let identity_data = std::fs::read_to_string(&identity_path)?;
            let identity: ZhtpIdentity = serde_json::from_str(&identity_data)
                .context("Failed to parse identity.json")?;
            return Ok(identity);
        }

        Err(anyhow!("No identity.json found in keystore at {:?}", keystore_path))
    }

    /// Get the verified peer DID from the current connection
    pub fn peer_did(&self) -> Option<&str> {
        self.connection.as_ref().map(|c| c.peer_did.as_str())
    }

    /// Check if client is in bootstrap mode
    pub fn is_bootstrap_mode(&self) -> bool {
        self.trust_config.bootstrap_mode
    }

    /// Get the client's identity DID
    pub fn identity_did(&self) -> &str {
        &self.identity.did
    }

    /// Connect to a ZHTP node
    pub async fn connect(&mut self, addr: &str) -> Result<()> {
        let socket_addr: SocketAddr = addr.parse()
            .context("Invalid server address")?;

        info!("Connecting to ZHTP node at {}", socket_addr);

        if self.trust_config.bootstrap_mode {
            Self::ensure_bootstrap_allowed()?;
            warn!(
                "BOOTSTRAP MODE ENABLED - TLS certificates are not verified. Set ZHTP_ALLOW_BOOTSTRAP=1 intentionally."
            );
        }

        // Create trust verifier for this connection
        let verifier = Arc::new(ZhtpTrustVerifier::new(
            addr.to_string(),
            self.trust_config.clone(),
        )?);
        self.trust_verifier = Some(Arc::clone(&verifier));

        // Configure QUIC client with trust verifier
        let client_config = Self::configure_client(verifier)?;
        self.endpoint.set_default_client_config(client_config);

        // Establish QUIC connection (TLS handshake happens here)
        let connection = self.endpoint
            .connect(socket_addr, "zhtp-node")?
            .await
            .context("QUIC connection failed")?;

        info!("QUIC/TLS connection established");

        // Perform UHP+Kyber handshake
        let handshake_result = quic_handshake::handshake_as_initiator(
            &connection,
            &self.identity,
            &self.handshake_ctx,
        ).await.context("UHP+Kyber handshake failed")?;

        let peer_did = handshake_result.peer_identity.did.clone();

        // Verify node DID matches trust configuration
        if let Some(ref verifier) = self.trust_verifier {
            verifier.verify_node_did(&peer_did)?;
            // Bind DID to trustdb for future connections
            if let Err(e) = verifier.bind_node_did(&peer_did) {
                warn!("Failed to bind node DID to trustdb: {}", e);
            }
        }

        // Derive application-layer MAC key
        let app_key = AuthenticatedConnection::derive_app_key(
            &handshake_result.master_key,
            &handshake_result.session_id,
            &peer_did,
            &self.identity.did,
        );

        info!(
            peer_did = %peer_did,
            session_id = ?hex::encode(&handshake_result.session_id[..8]),
            "Authenticated with node (PQC encryption active)"
        );

        self.connection = Some(AuthenticatedConnection {
            quic_conn: connection,
            master_key: handshake_result.master_key,
            app_key,
            peer_did,
            session_id: handshake_result.session_id,
            sequence: AtomicU64::new(0),
        });

        Ok(())
    }

    /// Configure QUIC client with trust verifier
    fn configure_client(verifier: Arc<ZhtpTrustVerifier>) -> Result<ClientConfig> {
        // Install crypto provider for rustls 0.23+
        let _ = rustls::crypto::ring::default_provider().install_default();

        let mut crypto = rustls::ClientConfig::builder()
            .dangerous()
            .with_custom_certificate_verifier(verifier)
            .with_no_client_auth();

        // Configure ALPN for control plane operations (UHP handshake required)
        // This tells the server to expect UHP handshake before API requests
        crypto.alpn_protocols = crate::constants::client_control_plane_alpns();

        let mut config = ClientConfig::new(Arc::new(
            quinn::crypto::rustls::QuicClientConfig::try_from(crypto)?
        ));

        // Configure transport
        let mut transport = quinn::TransportConfig::default();
        transport.max_idle_timeout(Some(std::time::Duration::from_secs(30).try_into()?));
        config.transport_config(Arc::new(transport));

        Ok(config)
    }

    /// Check if connected
    pub fn is_connected(&self) -> bool {
        self.connection.is_some()
    }

    /// Send a request and receive response (internal - handles auth context)
    async fn send_request(&self, request: ZhtpRequest, require_auth: bool) -> Result<ZhtpResponse> {
        let conn = self.connection.as_ref()
            .ok_or_else(|| anyhow!("Not connected to node"))?;

        // Determine if this request needs authentication
        let is_mutation = matches!(request.method, ZhtpMethod::Post | ZhtpMethod::Put | ZhtpMethod::Delete);

        // Create wire request with auth context for mutations
        let wire_request = if is_mutation || require_auth {
            let seq = conn.next_sequence();
            ZhtpRequestWire::new_authenticated(
                request,
                conn.session_id,
                self.identity.did.clone(),
                seq,
                &conn.app_key,
            )
        } else {
            ZhtpRequestWire::new(request)
        };

        let request_id = wire_request.request_id;

        debug!(
            request_id = %wire_request.request_id_hex(),
            uri = %wire_request.request.uri,
            has_auth = wire_request.auth_context.is_some(),
            "Sending request"
        );

        // Open bidirectional stream
        let (mut send, mut recv) = conn.quic_conn.open_bi().await
            .context("Failed to open QUIC stream")?;

        // Send request
        write_request(&mut send, &wire_request).await
            .context("Failed to send request")?;

        // Finish sending
        send.finish()
            .context("Failed to finish send stream")?;

        // Read response
        let wire_response = read_response(&mut recv).await
            .context("Failed to read response")?;

        // Verify request ID matches
        if wire_response.request_id != request_id {
            return Err(anyhow!(
                "Response request_id mismatch: expected {}, got {}",
                hex::encode(request_id),
                wire_response.request_id_hex()
            ));
        }

        debug!(
            request_id = %wire_response.request_id_hex(),
            status = wire_response.status,
            "Received response"
        );

        Ok(wire_response.response)
    }

    /// Send a request (public API - auto-detects auth requirement)
    pub async fn request(&self, request: ZhtpRequest) -> Result<ZhtpResponse> {
        self.send_request(request, false).await
    }

    /// Upload a blob and get its content ID
    pub async fn put_blob(&self, content: Vec<u8>, content_type: &str) -> Result<String> {
        let request = ZhtpRequest::post(
            "/api/v1/web4/content/blob".to_string(),
            content,
            content_type.to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to upload blob: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        // Parse content ID from response
        let result: serde_json::Value = serde_json::from_slice(&response.body)
            .context("Invalid JSON response")?;

        result.get("content_id")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow!("Response missing content_id"))
    }

    /// Upload a manifest and get its content ID
    pub async fn put_manifest(&self, manifest: &serde_json::Value) -> Result<String> {
        let body = serde_json::to_vec(manifest)?;

        let request = ZhtpRequest::post(
            "/api/v1/web4/content/manifest".to_string(),
            body,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to upload manifest: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        let result: serde_json::Value = serde_json::from_slice(&response.body)?;

        result.get("manifest_cid")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow!("Response missing manifest_cid"))
    }

    /// Register a new domain
    pub async fn register_domain(
        &self,
        domain: &str,
        manifest_cid: &str,
    ) -> Result<serde_json::Value> {
        let body = serde_json::json!({
            "domain": domain,
            "manifest_cid": manifest_cid,
            "owner": self.identity.did.clone(),
        });

        let request = ZhtpRequest::post(
            "/api/v1/web4/domains/register".to_string(),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to register domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Publish/update a domain to point to new manifest
    pub async fn publish_domain(
        &self,
        domain: &str,
        manifest_cid: &str,
    ) -> Result<serde_json::Value> {
        let body = serde_json::json!({
            "domain": domain,
            "manifest_cid": manifest_cid,
        });

        let request = ZhtpRequest::post(
            format!("/api/v1/web4/domains/{}/publish", domain),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to publish domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Get domain info (no auth required for read)
    pub async fn get_domain(&self, domain: &str) -> Result<Option<serde_json::Value>> {
        let request = ZhtpRequest::get(
            format!("/api/v1/web4/domains/{}", domain),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if response.status.code() == 404 {
            return Ok(None);
        }

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to get domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        let result = serde_json::from_slice(&response.body)?;
        Ok(Some(result))
    }

    /// List all domains owned by the current identity
    pub async fn list_domains(&self) -> Result<Vec<serde_json::Value>> {
        let request = ZhtpRequest::get(
            format!("/api/v1/web4/domains?owner={}", self.identity.did),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to list domains: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        let result: serde_json::Value = serde_json::from_slice(&response.body)?;

        // Extract domains array from response
        if let Some(domains) = result.get("domains").and_then(|d| d.as_array()) {
            Ok(domains.clone())
        } else {
            Ok(Vec::new())
        }
    }

    // ========================================================================
    // Domain Versioning API
    // ========================================================================

    /// Get domain version status
    pub async fn get_domain_status(&self, domain: &str) -> Result<serde_json::Value> {
        let request = ZhtpRequest::get(
            format!("/api/v1/web4/domains/status/{}", domain),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to get domain status: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Get domain version history
    pub async fn get_domain_history(&self, domain: &str, limit: Option<usize>) -> Result<serde_json::Value> {
        let url = if let Some(limit) = limit {
            format!("/api/v1/web4/domains/history/{}?limit={}", domain, limit)
        } else {
            format!("/api/v1/web4/domains/history/{}", domain)
        };

        let request = ZhtpRequest::get(
            url,
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to get domain history: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Update domain with new manifest (atomic compare-and-swap)
    pub async fn update_domain(
        &self,
        domain: &str,
        new_manifest_cid: &str,
        expected_previous_cid: &str,
    ) -> Result<serde_json::Value> {
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        let body = serde_json::json!({
            "domain": domain,
            "new_manifest_cid": new_manifest_cid,
            "expected_previous_manifest_cid": expected_previous_cid,
            "signature": "", // TODO: Sign with identity
            "timestamp": timestamp,
        });

        let request = ZhtpRequest::post(
            "/api/v1/web4/domains/update".to_string(),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to update domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Rollback domain to a previous version
    pub async fn rollback_domain(&self, domain: &str, to_version: u64) -> Result<serde_json::Value> {
        let body = serde_json::json!({
            "to_version": to_version,
        });

        let request = ZhtpRequest::post(
            format!("/api/v1/web4/domains/{}/rollback", domain),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to rollback domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Resolve domain to manifest (optionally at specific version)
    pub async fn resolve_domain(&self, domain: &str, version: Option<u64>) -> Result<serde_json::Value> {
        let body = serde_json::json!({
            "domain": domain,
            "version": version,
        });

        let request = ZhtpRequest::post(
            "/api/v1/web4/domains/resolve".to_string(),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to resolve domain: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Upload a blob with automatic chunking for large files
    ///
    /// Files smaller than `chunk_size` are uploaded directly.
    /// Larger files are split into chunks and assembled on the server.
    ///
    /// # Arguments
    /// * `content` - The file content to upload
    /// * `content_type` - MIME type
    /// * `chunk_size` - Size of each chunk (default: 1MB)
    ///
    /// # Returns
    /// The content ID (CID) of the uploaded blob
    pub async fn put_blob_chunked(
        &self,
        content: Vec<u8>,
        content_type: &str,
        chunk_size: Option<usize>,
    ) -> Result<String> {
        let chunk_size = chunk_size.unwrap_or(1024 * 1024); // Default 1MB chunks

        // Small files: upload directly
        if content.len() <= chunk_size {
            return self.put_blob(content, content_type).await;
        }

        info!(
            total_size = content.len(),
            chunk_size = chunk_size,
            num_chunks = (content.len() + chunk_size - 1) / chunk_size,
            "Starting chunked upload"
        );

        // Calculate total hash for integrity
        let total_hash = hex::encode(&lib_crypto::hash_blake3(&content)[..16]);

        // Initiate chunked upload session
        let session = self.initiate_chunked_upload(
            content.len(),
            chunk_size,
            content_type,
            &total_hash,
        ).await?;

        let upload_id = session.get("upload_id")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Missing upload_id in session response"))?
            .to_string();

        debug!(upload_id = %upload_id, "Chunked upload session created");

        // Upload each chunk
        let mut chunk_cids = Vec::new();
        for (i, chunk) in content.chunks(chunk_size).enumerate() {
            let chunk_hash = hex::encode(&lib_crypto::hash_blake3(chunk)[..16]);

            debug!(
                chunk_index = i,
                chunk_size = chunk.len(),
                chunk_hash = %chunk_hash,
                "Uploading chunk"
            );

            let cid = self.upload_chunk(&upload_id, i, chunk.to_vec(), &chunk_hash).await?;
            chunk_cids.push(cid);
        }

        // Finalize upload - assemble chunks into blob
        let final_cid = self.finalize_chunked_upload(&upload_id, &chunk_cids, &total_hash).await?;

        info!(
            upload_id = %upload_id,
            cid = %final_cid,
            "Chunked upload completed"
        );

        Ok(final_cid)
    }

    /// Initiate a chunked upload session
    async fn initiate_chunked_upload(
        &self,
        total_size: usize,
        chunk_size: usize,
        content_type: &str,
        total_hash: &str,
    ) -> Result<serde_json::Value> {
        let body = serde_json::json!({
            "total_size": total_size,
            "chunk_size": chunk_size,
            "content_type": content_type,
            "total_hash": total_hash,
            "num_chunks": (total_size + chunk_size - 1) / chunk_size,
        });

        let request = ZhtpRequest::post(
            "/api/v1/web4/content/upload/init".to_string(),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to initiate chunked upload: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Upload a single chunk
    async fn upload_chunk(
        &self,
        upload_id: &str,
        chunk_index: usize,
        chunk_data: Vec<u8>,
        chunk_hash: &str,
    ) -> Result<String> {
        // Include metadata in headers via query params
        let uri = format!(
            "/api/v1/web4/content/upload/{}/chunk/{}?hash={}",
            upload_id, chunk_index, chunk_hash
        );

        let request = ZhtpRequest::post(
            uri,
            chunk_data,
            "application/octet-stream".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to upload chunk {}: {} {}",
                chunk_index,
                response.status.code(),
                response.status_message
            ));
        }

        let result: serde_json::Value = serde_json::from_slice(&response.body)?;

        result.get("chunk_cid")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow!("Response missing chunk_cid"))
    }

    /// Finalize chunked upload - assemble chunks into final blob
    async fn finalize_chunked_upload(
        &self,
        upload_id: &str,
        chunk_cids: &[String],
        total_hash: &str,
    ) -> Result<String> {
        let body = serde_json::json!({
            "upload_id": upload_id,
            "chunk_cids": chunk_cids,
            "total_hash": total_hash,
        });

        let request = ZhtpRequest::post(
            format!("/api/v1/web4/content/upload/{}/finalize", upload_id),
            serde_json::to_vec(&body)?,
            "application/json".to_string(),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, true).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to finalize chunked upload: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        let result: serde_json::Value = serde_json::from_slice(&response.body)?;

        result.get("content_id")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow!("Response missing content_id"))
    }

    /// Resume a chunked upload
    ///
    /// Queries the server for upload status and continues from where it left off.
    pub async fn resume_chunked_upload(
        &self,
        upload_id: &str,
        content: Vec<u8>,
        chunk_size: usize,
    ) -> Result<String> {
        // Get upload status
        let status = self.get_upload_status(upload_id).await?;

        let total_chunks = status.get("num_chunks")
            .and_then(|v| v.as_u64())
            .ok_or_else(|| anyhow!("Missing num_chunks"))? as usize;

        let uploaded_chunks: Vec<usize> = status.get("uploaded_chunks")
            .and_then(|v| v.as_array())
            .map(|arr| arr.iter().filter_map(|v| v.as_u64().map(|n| n as usize)).collect())
            .unwrap_or_default();

        let total_hash = status.get("total_hash")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("Missing total_hash"))?;

        info!(
            upload_id = %upload_id,
            total_chunks = total_chunks,
            uploaded = uploaded_chunks.len(),
            remaining = total_chunks - uploaded_chunks.len(),
            "Resuming chunked upload"
        );

        // Upload missing chunks
        let mut chunk_cids: Vec<(usize, String)> = Vec::new();

        // Get existing CIDs
        if let Some(existing) = status.get("chunk_cids").and_then(|v| v.as_object()) {
            for (idx_str, cid) in existing {
                if let (Ok(idx), Some(cid_str)) = (idx_str.parse::<usize>(), cid.as_str()) {
                    chunk_cids.push((idx, cid_str.to_string()));
                }
            }
        }

        for (i, chunk) in content.chunks(chunk_size).enumerate() {
            if uploaded_chunks.contains(&i) {
                continue; // Already uploaded
            }

            let chunk_hash = hex::encode(&lib_crypto::hash_blake3(chunk)[..16]);
            let cid = self.upload_chunk(upload_id, i, chunk.to_vec(), &chunk_hash).await?;
            chunk_cids.push((i, cid));
        }

        // Sort by index and extract CIDs
        chunk_cids.sort_by_key(|(idx, _)| *idx);
        let ordered_cids: Vec<String> = chunk_cids.into_iter().map(|(_, cid)| cid).collect();

        // Finalize
        self.finalize_chunked_upload(upload_id, &ordered_cids, total_hash).await
    }

    /// Get status of a chunked upload
    async fn get_upload_status(&self, upload_id: &str) -> Result<serde_json::Value> {
        let request = ZhtpRequest::get(
            format!("/api/v1/web4/content/upload/{}/status", upload_id),
            Some(self.identity.id.clone()),
        )?;

        let response = self.send_request(request, false).await?;

        if !response.status.is_success() {
            return Err(anyhow!(
                "Failed to get upload status: {} {}",
                response.status.code(),
                response.status_message
            ));
        }

        serde_json::from_slice(&response.body)
            .context("Invalid JSON response")
    }

    /// Close the connection
    pub async fn close(&mut self) {
        if let Some(conn) = self.connection.take() {
            conn.quic_conn.close(0u32.into(), b"done");
            info!("Connection closed");
        }
    }
}

impl Drop for Web4Client {
    fn drop(&mut self) {
        if let Some(conn) = self.connection.take() {
            conn.quic_conn.close(0u32.into(), b"client dropped");
        }
    }
}

pub struct ContentPublisher {
    /// Domain registry for ownership verification
    domain_registry: Arc<DomainRegistry>,
    /// DHT client for content storage and retrieval (optional - uses registry's DHT if None)
    dht_client: Arc<RwLock<Option<ZkDHTIntegration>>>,
    /// Storage backend
    storage_system: Arc<RwLock<UnifiedStorageSystem>>,
    /// Content statistics
    stats: Arc<RwLock<ContentPublishingStats>>,
}

pub struct ContentPublishingStats {
    /// Total content items published
    pub total_published: u64,
    /// Total storage used (bytes)
    pub storage_bytes: u64,
    /// Total publishing fees collected
    pub publishing_fees: f64,
    /// Content by domain
    pub content_by_domain: HashMap<String, u64>,
    /// Content by type
    pub content_by_type: HashMap<String, u64>,
}

impl ContentPublisher {
    /// Create new content publisher without creating a new DHT client
    pub async fn new(domain_registry: Arc<DomainRegistry>) -> Result<Self> {
        // Don't create a new DHT client - reuse the one from domain_registry if needed
        let storage_config = lib_storage::UnifiedStorageConfig::default();
        let storage_system = UnifiedStorageSystem::new(storage_config).await?;

        Ok(Self {
            domain_registry,
            dht_client: Arc::new(RwLock::new(None)), // Will use registry's DHT or be set later
            storage_system: Arc::new(RwLock::new(storage_system)),
            stats: Arc::new(RwLock::new(ContentPublishingStats::default())),
        })
    }

    /// Create new content publisher with existing storage system (avoids creating duplicates)
    pub async fn new_with_storage(domain_registry: Arc<DomainRegistry>, storage: std::sync::Arc<tokio::sync::RwLock<lib_storage::UnifiedStorageSystem>>) -> Result<Self> {
        Ok(Self {
            domain_registry,
            dht_client: Arc::new(RwLock::new(None)), // Will use registry's DHT or be set later
            storage_system: storage,
            stats: Arc::new(RwLock::new(ContentPublishingStats::default())),
        })
    }

    /// Publish content to Web4 domain
    pub async fn publish_content(&self, request: ContentPublishRequest) -> Result<ContentPublishResponse> {
        info!("Publishing content to {}{}", request.domain, request.path);

        // Verify domain ownership
        let domain_info = self.domain_registry.lookup_domain(&request.domain).await?;
        if !domain_info.found {
            return Ok(ContentPublishResponse {
                success: false,
                content_hash: String::new(),
                zhtp_url: String::new(),
                published_at: 0,
                storage_fees: 0.0,
                error: Some(format!("Domain not registered: {}", request.domain)),
            });
        }

        let domain_record = domain_info.record.unwrap();

        // Verify publisher is domain owner
        if domain_record.owner != request.publisher.id {
            // Also check if ownership proof is valid (allows delegation)
            if !self.verify_publishing_authorization(&request, &domain_record).await? {
                return Ok(ContentPublishResponse {
                    success: false,
                    content_hash: String::new(),
                    zhtp_url: String::new(),
                    published_at: 0,
                    storage_fees: 0.0,
                    error: Some("Not authorized to publish to this domain".to_string()),
                });
            }
        }

        // Validate content
        self.validate_content(&request).await?;

        // Store content in DHT if available, otherwise use storage system
        let content_hash = {
            let dht_client_guard = self.dht_client.read().await;
            if let Some(_dht_client) = dht_client_guard.as_ref() {
                // Use DHT for storage
                drop(dht_client_guard);
                let mut dht_client_mut = self.dht_client.write().await;
                if let Some(dht) = dht_client_mut.as_mut() {
                    dht.store_content(&request.domain, &request.path, request.content.clone()).await?;
                    // Return content hash after storing
                    let hash = lib_crypto::hash_blake3(&request.content);
                    hex::encode(hash)
                } else {
                    // Fallback to hash-based storage
                    let hash = lib_crypto::hash_blake3(&request.content);
                    hex::encode(hash)
                }
            } else {
                // No DHT available, use hash-based content addressing
                let hash = lib_crypto::hash_blake3(&request.content);
                hex::encode(hash)
            }
        };

        // Calculate storage fees
        let storage_fees = self.calculate_storage_fees(&request).await?;

        // Create ZHTP URL
        let zhtp_url = format!("zhtp://{}{}", request.domain, request.path);

        // Update domain content mappings
        self.update_domain_content_mapping(&request.domain, &request.path, &content_hash).await?;

        // Update statistics
        self.update_publishing_stats(&request, storage_fees).await?;

        let published_at = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        info!(" Content published successfully: {} -> {}", zhtp_url, content_hash);

        Ok(ContentPublishResponse {
            success: true,
            content_hash,
            zhtp_url,
            published_at,
            storage_fees,
            error: None,
        })
    }

    /// Update existing content
    pub async fn update_content(&self, request: ContentPublishRequest) -> Result<ContentPublishResponse> {
        info!(" Updating content at {}{}", request.domain, request.path);

        // Reuse publish logic but add versioning info
        let response = self.publish_content(request).await?;

        if response.success {
            // Update metadata to indicate this is an update
            info!("Content updated successfully at {}", response.zhtp_url);
        }

        Ok(response)
    }

    /// Delete content from domain
    pub async fn delete_content(
        &self,
        domain: &str,
        path: &str,
        requester: &ZhtpIdentity,
    ) -> Result<bool> {
        info!("🗑️ Deleting content from {}{}", domain, path);

        // Verify domain ownership
        let domain_info = self.domain_registry.lookup_domain(domain).await?;
        if !domain_info.found {
            return Err(anyhow!("Domain not registered: {}", domain));
        }

        let domain_record = domain_info.record.unwrap();

        // Verify requester is domain owner
        if domain_record.owner != requester.id {
            return Err(anyhow!("Not authorized to delete content from this domain"));
        }

        // Remove content mapping (actual content remains in DHT for other references)
        // In a full implementation, we'd also implement reference counting for cleanup

        // Update statistics
        {
            let mut stats = self.stats.write().await;
            stats.total_published = stats.total_published.saturating_sub(1);

            if let Some(count) = stats.content_by_domain.get_mut(domain) {
                *count = count.saturating_sub(1);
            }
        }

        info!(" Content deleted from {}{}", domain, path);
        Ok(true)
    }

    /// Get content metadata
    pub async fn get_content_metadata(
        &self,
        domain: &str,
        path: &str,
    ) -> Result<Option<ContentMetadata>> {
        // Look up domain to get content mappings
        let domain_info = self.domain_registry.lookup_domain(domain).await?;

        if !domain_info.found {
            return Ok(None);
        }

        // Check if content exists for this path
        let domain_record = domain_info.record.unwrap();
        if domain_record.content_mappings.contains_key(path) {
            // In a full implementation, we'd store and retrieve actual content metadata
            // For now, return basic metadata
            Ok(Some(ContentMetadata {
                title: format!("Content at {}", path),
                description: format!("Web4 content hosted at {}{}", domain, path),
                version: "1.0".to_string(),
                tags: vec!["web4".to_string()],
                public: true,
                license: "Web4 Standard".to_string(),
            }))
        } else {
            Ok(None)
        }
    }

    /// List all content for a domain
    pub async fn list_domain_content(&self, domain: &str) -> Result<HashMap<String, String>> {
        let domain_info = self.domain_registry.lookup_domain(domain).await?;

        if domain_info.found {
            Ok(domain_info.content_mappings)
        } else {
            Ok(HashMap::new())
        }
    }

    /// Get publishing statistics
    pub async fn get_statistics(&self) -> Result<ContentPublishingStats> {
        let stats = self.stats.read().await;
        Ok(stats.clone())
    }

    /// Validate content before publishing
    async fn validate_content(&self, request: &ContentPublishRequest) -> Result<()> {
        // Check content size limits
        if request.content.len() > 10 * 1024 * 1024 { // 10MB limit
            return Err(anyhow!("Content exceeds 10MB limit"));
        }

        // Validate path format
        if !request.path.starts_with('/') {
            return Err(anyhow!("Content path must start with '/'"));
        }

        // Check for invalid path characters
        if request.path.contains("..") || request.path.contains("//") {
            return Err(anyhow!("Invalid path format"));
        }

        Ok(())
    }

    /// Verify publishing authorization (for delegated publishing)
    async fn verify_publishing_authorization(
        &self,
        request: &ContentPublishRequest,
        domain_record: &DomainRecord,
    ) -> Result<bool> {
        // In production, this would verify ZK proofs for delegated publishing
        // For now, just verify the ownership proof is valid format
        Ok(!request.ownership_proof.proof_data.is_empty() &&
           !request.ownership_proof.verification_key.is_empty())
    }

    /// Calculate storage fees
    async fn calculate_storage_fees(&self, request: &ContentPublishRequest) -> Result<f64> {
        let base_fee = 0.1; // 0.1 ZHTP base fee
        let per_kb_fee = 0.001; // 0.001 ZHTP per KB

        let size_kb = (request.content.len() as f64) / 1024.0;
        let size_fee = size_kb * per_kb_fee;

        Ok(base_fee + size_fee)
    }

    /// Update domain content mapping
    async fn update_domain_content_mapping(
        &self,
        domain: &str,
        path: &str,
        content_hash: &str,
    ) -> Result<()> {
        // This would update the domain record's content mappings
        // For now, we'll rely on the DHT to handle the mapping
        info!("Content mapping updated: {}{} -> {}", domain, path, content_hash);
        Ok(())
    }

    /// Update publishing statistics
    async fn update_publishing_stats(
        &self,
        request: &ContentPublishRequest,
        storage_fees: f64,
    ) -> Result<()> {
        let mut stats = self.stats.write().await;

        stats.total_published += 1;
        stats.storage_bytes += request.content.len() as u64;
        stats.publishing_fees += storage_fees;

        // Update domain stats
        *stats.content_by_domain.entry(request.domain.clone()).or_insert(0) += 1;

        // Update content type stats
        *stats.content_by_type.entry(request.content_type.clone()).or_insert(0) += 1;

        Ok(())
    }
}

pub enum ContentMode {
    /// Static file serving - 404 for missing files
    Static,
    /// SPA mode - fallback to index.html for navigation routes
    #[default]
    Spa,
}

pub enum Web4Capability {
    /// Full HTTP serving (HTML, JS, CSS, images, etc.)
    HttpServe,
    /// SPA serving with client-side routing support (default)
    #[default]
    SpaServe,
    /// Download only - no browser rendering (for data/binary content)
    DownloadOnly,
}

pub struct Web4ContentDefaults {
    /// Default content mode
    pub content_mode: ContentMode,
    /// Default index document
    pub index_document: String,
    /// Default 404 document
    pub not_found_document: Option<String>,
    /// Default capability level
    pub capability: Web4Capability,
}

impl Default for Web4ContentDefaults {
    fn default() -> Self {
        Self {
            content_mode: ContentMode::Spa,
            index_document: "index.html".to_string(),
            not_found_document: Some("404.html".to_string()),
            capability: Web4Capability::SpaServe,
        }
    }
}

pub struct DomainContentConfig {
    /// Content mode override
    pub content_mode: Option<ContentMode>,
    /// Index document override
    pub index_document: Option<String>,
    /// Not found document override
    pub not_found_document: Option<String>,
    /// Capability override
    pub capability: Option<Web4Capability>,
    /// Custom headers for this domain
    pub custom_headers: HashMap<String, String>,
}

impl Default for DomainContentConfig {
    fn default() -> Self {
        Self {
            content_mode: None,
            index_document: None,
            not_found_document: None,
            capability: None,
            custom_headers: HashMap::new(),
        }
    }
}

pub struct ContentResult {
    /// The content bytes
    pub content: Vec<u8>,
    /// MIME type
    pub mime_type: String,
    /// Cache control header value
    pub cache_control: String,
    /// ETag header value (content hash)
    pub etag: Option<String>,
    /// Additional headers
    pub headers: HashMap<String, String>,
    /// Whether this is a fallback (SPA routing)
    pub is_fallback: bool,
}

pub struct Web4ContentService {
    /// Domain registry for lookups
    registry: Arc<DomainRegistry>,
    /// Optional ZDNS resolver for cached domain lookups
    zdns_resolver: Option<Arc<ZdnsResolver>>,
    /// Service-level defaults
    defaults: Web4ContentDefaults,
    /// Domain-specific configurations (domain -> config)
    domain_configs: Arc<RwLock<HashMap<String, DomainContentConfig>>>,
}

impl Web4ContentService {
    /// Create a new content service with default configuration
    pub fn new(registry: Arc<DomainRegistry>) -> Self {
        Self {
            registry,
            zdns_resolver: None,
            defaults: Web4ContentDefaults::default(),
            domain_configs: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Create with custom defaults
    pub fn with_defaults(registry: Arc<DomainRegistry>, defaults: Web4ContentDefaults) -> Self {
        Self {
            registry,
            zdns_resolver: None,
            defaults,
            domain_configs: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Create with ZDNS resolver for cached domain lookups
    pub fn with_zdns(
        registry: Arc<DomainRegistry>,
        zdns_resolver: Arc<ZdnsResolver>,
    ) -> Self {
        Self {
            registry,
            zdns_resolver: Some(zdns_resolver),
            defaults: Web4ContentDefaults::default(),
            domain_configs: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Create with ZDNS resolver and custom defaults
    pub fn with_zdns_and_defaults(
        registry: Arc<DomainRegistry>,
        zdns_resolver: Arc<ZdnsResolver>,
        defaults: Web4ContentDefaults,
    ) -> Self {
        Self {
            registry,
            zdns_resolver: Some(zdns_resolver),
            defaults,
            domain_configs: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Get reference to ZDNS resolver (if configured)
    pub fn zdns_resolver(&self) -> Option<&Arc<ZdnsResolver>> {
        self.zdns_resolver.as_ref()
    }

    /// Resolve domain metadata using ZDNS (cached) or registry (direct)
    ///
    /// Prefers ZDNS resolver if available for caching benefits.
    pub async fn resolve_domain(&self, domain: &str) -> Result<Web4Record> {
        if let Some(resolver) = &self.zdns_resolver {
            // Use ZDNS resolver for cached lookup
            resolver.resolve_web4(domain).await.map_err(|e| anyhow!("{}", e))
        } else {
            // Fall back to direct registry lookup
            let lookup = self.registry.lookup_domain(domain).await?;
            if lookup.found {
                if let Some(record) = lookup.record {
                    Ok(Web4Record {
                        domain: record.domain,
                        owner: hex::encode(&record.owner.0[..16]),
                        content_mappings: record.content_mappings,
                        content_mode: Some(ContentMode::Spa),
                        spa_entry: Some("index.html".to_string()),
                        asset_prefixes: Some(vec![
                            "/assets/".to_string(),
                            "/static/".to_string(),
                            "/js/".to_string(),
                            "/css/".to_string(),
                            "/images/".to_string(),
                        ]),
                        capability: Some(Web4Capability::SpaServe),
                        ttl: 300,
                        registered_at: record.registered_at,
                        expires_at: record.expires_at,
                    })
                } else {
                    Err(anyhow!("Domain not found: {}", domain))
                }
            } else {
                Err(anyhow!("Domain not found: {}", domain))
            }
        }
    }

    /// Invalidate ZDNS cache for a domain (call after publish/update)
    pub async fn invalidate_domain_cache(&self, domain: &str) {
        if let Some(resolver) = &self.zdns_resolver {
            resolver.invalidate(domain).await;
        }
    }

    /// Set domain-specific configuration
    pub async fn set_domain_config(&self, domain: &str, config: DomainContentConfig) {
        let mut configs = self.domain_configs.write().await;
        configs.insert(domain.to_string(), config);
    }

    /// Get effective content mode for a domain
    async fn get_content_mode(&self, domain: &str) -> ContentMode {
        let configs = self.domain_configs.read().await;
        configs
            .get(domain)
            .and_then(|c| c.content_mode)
            .unwrap_or(self.defaults.content_mode)
    }

    /// Get effective index document for a domain
    async fn get_index_document(&self, domain: &str) -> String {
        let configs = self.domain_configs.read().await;
        configs
            .get(domain)
            .and_then(|c| c.index_document.clone())
            .unwrap_or_else(|| self.defaults.index_document.clone())
    }

    /// Get effective capability for a domain
    async fn get_capability(&self, domain: &str) -> Web4Capability {
        let configs = self.domain_configs.read().await;
        configs
            .get(domain)
            .and_then(|c| c.capability)
            .unwrap_or(self.defaults.capability)
    }

    /// Normalize a path for security
    ///
    /// CRITICAL: This MUST be called BEFORE any asset detection or lookup.
    ///
    /// Rules:
    /// 1. Collapse multiple slashes: `//` -> `/`
    /// 2. Remove `.` segments: `/./` -> `/`
    /// 3. Resolve `..` segments safely (cannot escape root)
    /// 4. Ensure path starts with `/`
    /// 5. Remove trailing slash (except for root `/`)
    ///
    /// Returns `Err` if the path attempts to escape the root.
    pub fn normalize_path(path: &str) -> Result<String> {
        // Handle empty path
        if path.is_empty() {
            return Ok("/".to_string());
        }

        // Split into segments
        let mut segments: Vec<&str> = Vec::new();

        for segment in path.split('/') {
            match segment {
                "" | "." => {
                    // Skip empty segments (from // or .)
                    continue;
                }
                ".." => {
                    // Go up one level, but REJECT if trying to escape root
                    if segments.pop().is_none() {
                        // Attempting to go above root - this is a security violation
                        warn!(
                            "Path traversal attack blocked: attempted to escape root in path '{}'",
                            path
                        );
                        return Err(anyhow!(
                            "Path traversal rejected: cannot navigate above root"
                        ));
                    }
                }
                s => {
                    // URL decode the segment for safety check
                    let decoded = urlencoding::decode(s).unwrap_or_else(|_| s.into());

                    // Check for encoded traversal attempts
                    if decoded.contains("..") {
                        return Err(anyhow!("Path traversal attempt detected"));
                    }

                    segments.push(s);
                }
            }
        }

        // Build normalized path
        if segments.is_empty() {
            Ok("/".to_string())
        } else {
            Ok(format!("/{}", segments.join("/")))
        }
    }

    /// Check if a path looks like a hashed asset (immutable)
    ///
    /// Hashed assets are files with content hashes in their names, e.g.:
    /// - `main.a1b2c3d4.js`
    /// - `styles.f5e6d7c8.css`
    /// - `chunk-abc123def456.js`
    pub fn is_hashed_asset(path: &str) -> bool {
        // Extract filename from path (handle empty segments from trailing /)
        let filename = path
            .rsplit('/')
            .find(|s| !s.is_empty())
            .unwrap_or(path);

        // Check for chunk-style names first: chunk-abc123def456.js or chunk-abc12345.js
        // These are common bundler output patterns (webpack, vite, etc.)
        if filename.starts_with("chunk-") || filename.starts_with("vendor-") {
            // Extract the part after the prefix and before the extension
            let without_prefix = if filename.starts_with("chunk-") {
                &filename[6..]
            } else {
                &filename[7..] // "vendor-" is 7 chars
            };

            // Get the hash part (before the extension)
            if let Some(hash_part) = without_prefix.split('.').next() {
                if hash_part.len() >= 8 && hash_part.chars().all(|c| c.is_ascii_alphanumeric()) {
                    return true;
                }
            }
        }

        // Split by dots for standard name.hash.ext pattern
        let parts: Vec<&str> = filename.split('.').collect();

        // Need at least 3 parts: name.hash.ext
        if parts.len() < 3 {
            return false;
        }

        // Check for hash-like patterns in the parts
        // Common patterns:
        // - 8+ hex chars: a1b2c3d4
        // - base64-ish: abc123DEF
        for i in 1..parts.len() - 1 {
            let part = parts[i];
            // Check if this looks like a hash (8+ alphanumeric chars)
            if part.len() >= 8 && part.chars().all(|c| c.is_ascii_alphanumeric()) {
                return true;
            }
        }

        false
    }

    /// Determine MIME type from path
    ///
    /// Uses file extension to determine content type.
    /// Falls back to `application/octet-stream` for unknown types.
    pub fn mime_for_path(path: &str) -> String {
        let extension = path
            .rsplit('.')
            .next()
            .map(|s| s.to_lowercase())
            .unwrap_or_default();

        match extension.as_str() {
            // HTML
            "html" | "htm" => "text/html; charset=utf-8".to_string(),

            // JavaScript - using application/javascript per plan
            "js" | "mjs" => "application/javascript; charset=utf-8".to_string(),

            // CSS
            "css" => "text/css; charset=utf-8".to_string(),

            // JSON
            "json" => "application/json; charset=utf-8".to_string(),

            // Images
            "png" => "image/png".to_string(),
            "jpg" | "jpeg" => "image/jpeg".to_string(),
            "gif" => "image/gif".to_string(),
            "webp" => "image/webp".to_string(),
            "svg" => "image/svg+xml".to_string(),
            "ico" => "image/x-icon".to_string(),
            "avif" => "image/avif".to_string(),

            // Fonts
            "woff" => "font/woff".to_string(),
            "woff2" => "font/woff2".to_string(),
            "ttf" => "font/ttf".to_string(),
            "otf" => "font/otf".to_string(),
            "eot" => "application/vnd.ms-fontobject".to_string(),

            // Documents
            "pdf" => "application/pdf".to_string(),
            "xml" => "application/xml; charset=utf-8".to_string(),
            "txt" => "text/plain; charset=utf-8".to_string(),
            "md" => "text/markdown; charset=utf-8".to_string(),

            // Media
            "mp3" => "audio/mpeg".to_string(),
            "mp4" => "video/mp4".to_string(),
            "webm" => "video/webm".to_string(),
            "ogg" => "audio/ogg".to_string(),
            "wav" => "audio/wav".to_string(),

            // Data
            "wasm" => "application/wasm".to_string(),
            "map" => "application/json".to_string(), // Source maps

            // Web manifest
            "webmanifest" => "application/manifest+json".to_string(),

            // Default
            _ => "application/octet-stream".to_string(),
        }
    }

    /// Generate cache control header based on content type and path
    ///
    /// Rules:
    /// - Hashed assets: `public, max-age=31536000, immutable`
    /// - HTML/index: `no-store` (for SPA, always fetch fresh)
    /// - Other static: `public, max-age=3600`
    pub fn cache_control_for(path: &str, mime_type: &str, is_index: bool) -> String {
        // SPA entry points should never be cached
        if is_index || mime_type.starts_with("text/html") {
            return "no-store".to_string();
        }

        // Hashed assets are immutable
        if Self::is_hashed_asset(path) {
            return "public, max-age=31536000, immutable".to_string();
        }

        // Other static assets get moderate caching
        "public, max-age=3600".to_string()
    }

    /// Check if a path looks like an asset (has file extension)
    fn has_file_extension(path: &str) -> bool {
        let filename = path.rsplit('/').next().unwrap_or(path);
        // Must have a dot and extension after it
        if let Some(dot_pos) = filename.rfind('.') {
            // Extension must be at least 1 char and not at the start
            dot_pos > 0 && dot_pos < filename.len() - 1
        } else {
            false
        }
    }

    /// Check if a path looks like a navigation route (not an asset)
    ///
    /// Navigation routes are paths that don't have file extensions,
    /// like `/about`, `/users/123`, `/settings`.
    fn is_navigation_route(path: &str) -> bool {
        !Self::has_file_extension(path)
    }

    /// Serve content for a domain and path
    ///
    /// This is the main entry point for content retrieval.
    ///
    /// Flow:
    /// 1. Normalize path (SECURITY CRITICAL - must be first!)
    /// 2. Resolve domain via ZDNS (cached) to validate and get config
    /// 3. Check if path is index/directory
    /// 4. Try to fetch content from registry
    /// 5. If not found and SPA mode, apply fallback logic
    /// 6. Return content with appropriate headers
    pub async fn serve(&self, domain: &str, path: &str) -> Result<ContentResult> {
        // STEP 1: Normalize path FIRST (security critical!)
        let normalized_path = Self::normalize_path(path)?;
        debug!("Normalized path: '{}' -> '{}'", path, normalized_path);

        // STEP 2: Resolve domain via ZDNS resolver (uses cache if available)
        // This validates the domain exists and gets its configuration
        let (content_mode, index_doc, capability) = if let Some(resolver) = &self.zdns_resolver {
            // Use ZDNS resolver for cached lookup
            match resolver.resolve_web4(domain).await {
                Ok(record) => {
                    let mode = record.content_mode.unwrap_or(self.defaults.content_mode);
                    let index = record.spa_entry.unwrap_or_else(|| self.defaults.index_document.clone());
                    let cap = record.capability.unwrap_or(self.defaults.capability);
                    (mode, index, cap)
                }
                Err(e) => {
                    warn!(domain = %domain, error = %e, "ZDNS resolution failed");
                    return Err(anyhow!("Domain not found: {}", domain));
                }
            }
        } else {
            // Fall back to domain_configs and defaults (no ZDNS resolver)
            let mode = self.get_content_mode(domain).await;
            let index = self.get_index_document(domain).await;
            let cap = self.get_capability(domain).await;
            (mode, index, cap)
        };

        // Check capability
        if capability == Web4Capability::DownloadOnly {
            // For download-only domains, we don't serve HTML
            let mime = Self::mime_for_path(&normalized_path);
            if mime.starts_with("text/html") {
                return Err(anyhow!("Domain is download-only, HTML serving disabled"));
            }
        }

        // STEP 3: Determine effective path
        let effective_path = if normalized_path == "/" {
            // Root path -> index document
            format!("/{}", index_doc)
        } else if normalized_path.ends_with('/') {
            // Directory path -> index document in that directory
            format!("{}{}", normalized_path, index_doc)
        } else {
            normalized_path.clone()
        };

        // STEP 4: Try to fetch content
        let is_index = effective_path.ends_with(&index_doc);

        match self.fetch_content(domain, &effective_path).await {
            Ok(content) => {
                // Content found
                let mime_type = Self::mime_for_path(&effective_path);
                let cache_control = Self::cache_control_for(&effective_path, &mime_type, is_index);
                let etag = Some(Self::compute_etag(&content));

                Ok(ContentResult {
                    content,
                    mime_type,
                    cache_control,
                    etag,
                    headers: HashMap::new(),
                    is_fallback: false,
                })
            }
            Err(_) => {
                // Content not found - apply SPA fallback logic
                self.handle_not_found(domain, &normalized_path, content_mode, &index_doc)
                    .await
            }
        }
    }

    /// Handle not-found case with SPA fallback logic
    async fn handle_not_found(
        &self,
        domain: &str,
        normalized_path: &str,
        content_mode: ContentMode,
        index_doc: &str,
    ) -> Result<ContentResult> {
        match content_mode {
            ContentMode::Static => {
                // Static mode: 404 for missing files
                Err(anyhow!("Content not found: {}", normalized_path))
            }
            ContentMode::Spa => {
                // SPA mode: fallback logic

                // Rule: Files with extensions return 404 (they're missing assets)
                if Self::has_file_extension(normalized_path) {
                    return Err(anyhow!(
                        "Asset not found: {} (SPA fallback only applies to navigation routes)",
                        normalized_path
                    ));
                }

                // Navigation route -> fallback to index.html
                info!(
                    "SPA fallback: '{}' -> '/{}'",
                    normalized_path, index_doc
                );

                let index_path = format!("/{}", index_doc);
                match self.fetch_content(domain, &index_path).await {
                    Ok(content) => {
                        let mime_type = Self::mime_for_path(&index_path);
                        let cache_control = Self::cache_control_for(&index_path, &mime_type, true);
                        let etag = Some(Self::compute_etag(&content));

                        Ok(ContentResult {
                            content,
                            mime_type,
                            cache_control,
                            etag,
                            headers: HashMap::new(),
                            is_fallback: true,
                        })
                    }
                    Err(e) => {
                        Err(anyhow!(
                            "SPA fallback failed: index document not found ({})",
                            e
                        ))
                    }
                }
            }
        }
    }

    /// Fetch content from the registry/DHT
    async fn fetch_content(&self, domain: &str, path: &str) -> Result<Vec<u8>> {
        // Strip leading slash for registry lookup
        let lookup_path = path.strip_prefix('/').unwrap_or(path);

        // Try to get content from domain
        self.registry.get_domain_content(domain, &format!("/{}", lookup_path)).await
    }

    /// Compute ETag from content
    fn compute_etag(content: &[u8]) -> String {
        let hash = lib_crypto::hash_blake3(content);
        format!("\"{}\"", hex::encode(&hash[..16])) // Use first 16 bytes
    }
}

pub struct DomainRegistry {
    /// Domain records storage
    domain_records: Arc<RwLock<HashMap<String, DomainRecord>>>,
    /// DHT client for direct storage
    dht_client: Arc<RwLock<Option<ZkDHTIntegration>>>,
    /// Storage backend for persistence
    storage_system: Arc<RwLock<UnifiedStorageSystem>>,
    /// Content cache (hash -> bytes)
    content_cache: Arc<RwLock<HashMap<String, Vec<u8>>>>,
    /// Registry statistics
    stats: Arc<RwLock<Web4Statistics>>,
    /// Manifest history per domain (domain -> list of manifests, oldest first)
    manifest_history: Arc<RwLock<HashMap<String, Vec<Web4Manifest>>>>,
}

impl DomainRegistry {
    /// Create new domain registry
    pub async fn new() -> Result<Self> {
        Self::new_with_dht(None).await
    }

    /// Create new domain registry with existing storage system (avoids creating duplicates)
    pub async fn new_with_storage(storage: std::sync::Arc<tokio::sync::RwLock<lib_storage::UnifiedStorageSystem>>) -> Result<Self> {
        let registry = Self {
            domain_records: Arc::new(RwLock::new(HashMap::new())),
            dht_client: Arc::new(RwLock::new(None)), // No DHT client needed when using shared storage
            storage_system: storage,
            content_cache: Arc::new(RwLock::new(HashMap::new())),
            manifest_history: Arc::new(RwLock::new(HashMap::new())),
            stats: Arc::new(RwLock::new(Web4Statistics {
                total_domains: 0,
                total_content: 0,
                total_storage_bytes: 0,
                active_domains: 0,
                economic_stats: Web4EconomicStats {
                    registration_fees: 0.0,
                    storage_fees: 0.0,
                    transfer_fees: 0.0,
                    storage_capacity_gb: 1000.0, // 1TB default
                    storage_utilization: 0.0,
                },
            })),
        };

        // Load persisted domain records from storage
        registry.load_persisted_domains().await?;

        Ok(registry)
    }

    /// Create new domain registry with optional existing DHT client
    pub async fn new_with_dht(dht_client: Option<ZkDHTIntegration>) -> Result<Self> {
        let storage_config = lib_storage::UnifiedStorageConfig::default();
        let storage_system = UnifiedStorageSystem::new(storage_config).await?;

        let registry = Self {
            domain_records: Arc::new(RwLock::new(HashMap::new())),
            dht_client: Arc::new(RwLock::new(dht_client)), // Use provided DHT client if available
            storage_system: Arc::new(RwLock::new(storage_system)),
            content_cache: Arc::new(RwLock::new(HashMap::new())),
            manifest_history: Arc::new(RwLock::new(HashMap::new())),
            stats: Arc::new(RwLock::new(Web4Statistics {
                total_domains: 0,
                total_content: 0,
                total_storage_bytes: 0,
                active_domains: 0,
                economic_stats: Web4EconomicStats {
                    registration_fees: 0.0,
                    storage_fees: 0.0,
                    transfer_fees: 0.0,
                    storage_capacity_gb: 1000.0, // 1TB default
                    storage_utilization: 0.0,
                },
            })),
        };

        // Load persisted domain records from storage
        registry.load_persisted_domains().await?;

        Ok(registry)
    }

    // ========================================================================
    // Domain Persistence - Load and save domain records to lib-storage
    // ========================================================================

    /// Load all persisted domain records from lib-storage into the in-memory cache
    async fn load_persisted_domains(&self) -> Result<()> {
        // LOCK SAFETY: Acquire storage lock, do async work, release before acquiring other locks
        let records = {
            let mut storage = self.storage_system.write().await;
            storage.list_domain_records().await?
        }; // storage lock released here

        if records.is_empty() {
            info!("No persisted domain records found in storage");
            return Ok(());
        }

        // Parse records outside of any lock
        let mut parsed_records = Vec::new();
        for (domain, data) in records {
            match serde_json::from_slice::<DomainRecord>(&data) {
                Ok(record) => {
                    info!(" Loaded persisted domain: {} (v{})", record.domain, record.version);
                    parsed_records.push((domain, record));
                }
                Err(e) => {
                    warn!(" Failed to deserialize domain record: {}", e);
                }
            }
        }

        let loaded_count = parsed_records.len() as u64;

        // LOCK SAFETY: Acquire domain_records lock, do sync work only, release
        {
            let mut domain_records = self.domain_records.write().await;
            for (domain, record) in parsed_records {
                domain_records.insert(domain, record);
            }
        } // domain_records lock released here

        // LOCK SAFETY: Acquire stats lock separately
        {
            let mut stats = self.stats.write().await;
            stats.total_domains = loaded_count;
            stats.active_domains = loaded_count;
        } // stats lock released here

        info!(" Loaded {} persisted domain records from storage", loaded_count);
        Ok(())
    }

    /// Persist a domain record to lib-storage
    async fn persist_domain_record(&self, record: &DomainRecord) -> Result<()> {
        let data = serde_json::to_vec(record)
            .map_err(|e| anyhow!("Failed to serialize domain record: {}", e))?;

        let mut storage = self.storage_system.write().await;
        storage.store_domain_record(&record.domain, &data).await?;

        info!(" Persisted domain record: {} (v{})", record.domain, record.version);
        Ok(())
    }

    /// Delete a domain record from lib-storage
    async fn delete_persisted_domain(&self, domain: &str) -> Result<()> {
        let mut storage = self.storage_system.write().await;
        storage.delete_domain_record(domain).await?;

        info!(" Deleted persisted domain record: {}", domain);
        Ok(())
    }

    /// Register a new Web4 domain
    pub async fn register_domain(&self, request: DomainRegistrationRequest) -> Result<DomainRegistrationResponse> {
        info!("Registering Web4 domain: {}", request.domain);

        // Validate domain name
        self.validate_domain_name(&request.domain)?;

        // Check if domain is already registered
        {
            let records = self.domain_records.read().await;
            if records.contains_key(&request.domain) {
                return Ok(DomainRegistrationResponse {
                    domain: request.domain.clone(),
                    success: false,
                    registration_id: String::new(),
                    expires_at: 0,
                    fees_charged: 0.0,
                    error: Some("Domain already registered".to_string()),
                });
            }
        }

        // Verify registration proof
        if !self.verify_registration_proof(&request).await? {
            return Ok(DomainRegistrationResponse {
                domain: request.domain.clone(),
                success: false,
                registration_id: String::new(),
                expires_at: 0,
                fees_charged: 0.0,
                error: Some("Invalid registration proof".to_string()),
            });
        }

        // Calculate registration fee
        let registration_fee = self.calculate_registration_fee(&request).await?;

        // Create domain record
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        let expires_at = current_time + (request.duration_days * 24 * 60 * 60);

        // Create ownership proof
        let ownership_proof = self.create_ownership_proof(&request.owner, &request.domain, current_time).await?;

        // Store initial content if provided
        let mut content_mappings = HashMap::new();
        for (path, content) in &request.initial_content {
            let content_hash = self.store_domain_content(&request.domain, path, content.clone()).await?;
            content_mappings.insert(path.clone(), content_hash);
        }

        // Use provided manifest CID or generate one
        let manifest_cid = request.manifest_cid.clone().unwrap_or_else(|| {
            format!(
                "bafk{}",
                hex::encode(&lib_crypto::hash_blake3(
                    format!("{}:v1:{}", request.domain, current_time).as_bytes()
                )[..16])
            )
        });

        let domain_record = DomainRecord {
            domain: request.domain.clone(),
            owner: request.owner.id.clone(),
            current_manifest_cid: manifest_cid,
            version: 1,
            registered_at: current_time,
            updated_at: current_time,
            expires_at,
            ownership_proof,
            content_mappings,
            metadata: request.metadata.clone(),
            transfer_history: vec![],
        };

        // Store domain record (legacy method for compatibility)
        let registration_id = self.store_domain_record(&domain_record).await?;

        // Persist to lib-storage for durability
        self.persist_domain_record(&domain_record).await?;

        // Update in-memory registry cache
        {
            let mut records = self.domain_records.write().await;
            records.insert(request.domain.clone(), domain_record);
            info!(" DEBUG: Stored domain in registry. Total domains: {}. Registry ptr: {:p}",
                records.len(), &*self.domain_records);
        }

        // Update statistics
        self.update_registration_stats(registration_fee).await?;

        info!(" Domain {} registered successfully with ID {}", request.domain, registration_id);

        Ok(DomainRegistrationResponse {
            domain: request.domain,
            success: true,
            registration_id,
            expires_at,
            fees_charged: registration_fee,
            error: None,
        })
    }

    /// Look up domain information
    pub async fn lookup_domain(&self, domain: &str) -> Result<DomainLookupResponse> {
        info!(" Looking up Web4 domain: {}", domain);

        // First check local cache
        let records = self.domain_records.read().await;

        if let Some(record) = records.get(domain) {
            // Check if domain has expired
            let current_time = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_secs();

            if record.expires_at < current_time {
                info!(" Domain {} found locally but expired", domain);
            } else {
                info!(" Domain {} found in local cache", domain);
                let owner_info = PublicOwnerInfo {
                    identity_hash: hex::encode(&record.owner.0[..16]), // First 16 bytes for privacy
                    registered_at: record.registered_at,
                    verified: true, // All registered domains are verified
                    alias: None, // Could be added later
                };

                return Ok(DomainLookupResponse {
                    found: true,
                    record: Some(record.clone()),
                    content_mappings: record.content_mappings.clone(),
                    owner_info: Some(owner_info),
                });
            }
        }

        drop(records); // Release lock before blockchain query

        // Domain not found locally or expired - query blockchain
        info!(" Domain {} not found locally, querying blockchain...", domain);
        match self.query_blockchain_for_domain(domain).await {
            Ok(Some(domain_record)) => {
                info!(" Domain {} found on blockchain, caching locally", domain);

                // Cache the domain record locally for future lookups
                {
                    let mut records = self.domain_records.write().await;
                    records.insert(domain.to_string(), domain_record.clone());
                }

                let owner_info = PublicOwnerInfo {
                    identity_hash: hex::encode(&domain_record.owner.0[..16]),
                    registered_at: domain_record.registered_at,
                    verified: true,
                    alias: None,
                };

                Ok(DomainLookupResponse {
                    found: true,
                    record: Some(domain_record.clone()),
                    content_mappings: domain_record.content_mappings.clone(),
                    owner_info: Some(owner_info),
                })
            }
            Ok(None) => {
                info!(" Domain {} not found on blockchain either", domain);
                Ok(DomainLookupResponse {
                    found: false,
                    record: None,
                    content_mappings: HashMap::new(),
                    owner_info: None,
                })
            }
            Err(e) => {
                warn!(" Failed to query blockchain for domain {}: {}", domain, e);
                // Return not found rather than error to maintain compatibility
                Ok(DomainLookupResponse {
                    found: false,
                    record: None,
                    content_mappings: HashMap::new(),
                    owner_info: None,
                })
            }
        }
    }

