    /// Store content by CID (content-addressed)
    /// Returns the CID after successful storage
    pub async fn store_content_by_cid(&self, content: Vec<u8>) -> Result<String> {
        // Compute CID from content hash
        let content_hash = hash_blake3(&content);
        let cid = format!("bafk{}", hex::encode(&content_hash[..16]));

        // Store in content cache
        {
            let mut cache = self.content_cache.write().await;
            cache.insert(cid.clone(), content);
            info!(" Stored content by CID: {} ({} bytes)", cid, cache.get(&cid).map(|c| c.len()).unwrap_or(0));
        }

        Ok(cid)
    }

    /// Retrieve content by CID
    /// Returns None if content not found
    pub async fn get_content_by_cid(&self, cid: &str) -> Result<Option<Vec<u8>>> {
        let cache = self.content_cache.read().await;
        let content = cache.get(cid).cloned();

        if content.is_some() {
            info!(" Retrieved content by CID: {}", cid);
        } else {
            info!(" Content not found for CID: {}", cid);
        }

        Ok(content)
    }

    /// Get domain version history
    pub async fn get_domain_history(&self, domain: &str, limit: usize) -> Result<DomainHistoryResponse> {
        let records = self.domain_records.read().await;
        let manifests = self.manifest_history.read().await;

        let record = records.get(domain)
            .ok_or_else(|| anyhow!("Domain not found: {}", domain))?;

        // Get version history from manifest storage
        let mut versions = Vec::new();

        if let Some(domain_manifests) = manifests.get(domain) {
            for manifest in domain_manifests.iter().rev().take(limit) {
                versions.push(DomainVersionEntry {
                    version: manifest.version,
                    manifest_cid: manifest.compute_cid(),
                    created_at: manifest.created_at,
                    created_by: manifest.created_by.clone(),
                    message: manifest.message.clone(),
                    build_hash: manifest.build_hash.clone(),
                });
            }
        } else {
            // No history, return current version only
            versions.push(DomainVersionEntry {
                version: record.version,
                manifest_cid: record.current_manifest_cid.clone(),
                created_at: record.updated_at,
                created_by: format!("did:zhtp:{}", hex::encode(&record.owner.0[..16])),
                message: Some("Initial deployment".to_string()),
                build_hash: hex::encode(&hash_blake3(record.current_manifest_cid.as_bytes())[..16]),
            });
        }

        Ok(DomainHistoryResponse {
            domain: domain.to_string(),
            current_version: record.version,
            total_versions: versions.len() as u64,
            versions,
        })
    }

    /// Update domain with new manifest (atomic compare-and-swap)
    pub async fn update_domain(&self, update_request: DomainUpdateRequest) -> Result<DomainUpdateResponse> {
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();

        // Validate timestamp (within 5 minutes)
        let time_diff = if current_time > update_request.timestamp {
            current_time - update_request.timestamp
        } else {
            update_request.timestamp - current_time
        };

        if time_diff > 300 {
            return Ok(DomainUpdateResponse {
                success: false,
                new_version: 0,
                new_manifest_cid: String::new(),
                previous_manifest_cid: String::new(),
                updated_at: 0,
                error: Some(format!("Request expired. Timestamp difference: {} seconds", time_diff)),
            });
        }

        let mut records = self.domain_records.write().await;

        let record = records.get_mut(&update_request.domain)
            .ok_or_else(|| anyhow!("Domain not found: {}", update_request.domain))?;

        // Compare-and-swap: verify expected previous CID matches current
        if record.current_manifest_cid != update_request.expected_previous_manifest_cid {
            return Ok(DomainUpdateResponse {
                success: false,
                new_version: record.version,
                new_manifest_cid: record.current_manifest_cid.clone(),
                previous_manifest_cid: record.current_manifest_cid.clone(),
                updated_at: record.updated_at,
                error: Some(format!(
                    "Concurrent update detected. Expected previous CID: {}, actual: {}",
                    update_request.expected_previous_manifest_cid,
                    record.current_manifest_cid
                )),
            });
        }

        // TODO: Verify signature matches domain owner
        // For now, we trust the caller has verified authorization

        let previous_manifest_cid = record.current_manifest_cid.clone();
        let new_version = record.version + 1;
        let new_manifest_cid = update_request.new_manifest_cid.clone();

        // Create updated record for persistence (persist BEFORE mutating memory)
        let mut updated_record = record.clone();
        updated_record.current_manifest_cid = new_manifest_cid.clone();
        updated_record.version = new_version;
        updated_record.updated_at = current_time;

        // Release lock before persisting
        drop(records);

        // Persist FIRST - if this fails, memory stays unchanged (durability guarantee)
        self.persist_domain_record(&updated_record).await?;

        // Only mutate memory AFTER successful persistence
        {
            let mut records = self.domain_records.write().await;
            if let Some(record) = records.get_mut(&update_request.domain) {
                record.current_manifest_cid = updated_record.current_manifest_cid.clone();
                record.version = updated_record.version;
                record.updated_at = updated_record.updated_at;
            }
        }

        info!(
            " Domain {} updated: v{} -> v{} (CID: {} -> {})",
            update_request.domain,
            new_version - 1,
            new_version,
            &previous_manifest_cid[..16.min(previous_manifest_cid.len())],
            &new_manifest_cid[..16.min(new_manifest_cid.len())]
        );

        Ok(DomainUpdateResponse {
            success: true,
            new_version,
            new_manifest_cid,
            previous_manifest_cid,
            updated_at: current_time,
            error: None,
        })
    }

    /// Store a manifest in history
    pub async fn store_manifest(&self, manifest: Web4Manifest) -> Result<String> {
        let cid = manifest.compute_cid();

        // Validate manifest chain if we have the previous one
        if manifest.version > 1 {
            let manifests = self.manifest_history.read().await;
            if let Some(domain_manifests) = manifests.get(&manifest.domain) {
                if let Some(prev) = domain_manifests.last() {
                    manifest.validate_chain(Some(prev))
                        .map_err(|e| anyhow!("Manifest chain validation failed: {}", e))?;
                }
            }
        } else {
            manifest.validate_chain(None)
                .map_err(|e| anyhow!("Manifest validation failed: {}", e))?;
        }

        // Store manifest in history
        let mut manifests = self.manifest_history.write().await;
        manifests
            .entry(manifest.domain.clone())
            .or_insert_with(Vec::new)
            .push(manifest);

        info!(" Stored manifest {} for domain", cid);
        Ok(cid)
    }

    /// Get manifest by CID
    pub async fn get_manifest(&self, domain: &str, cid: &str) -> Result<Option<Web4Manifest>> {
        let manifests = self.manifest_history.read().await;

        if let Some(domain_manifests) = manifests.get(domain) {
            for manifest in domain_manifests {
                if manifest.compute_cid() == cid {
                    return Ok(Some(manifest.clone()));
                }
            }
        }

        Ok(None)
    }

    /// Rollback domain to a previous version
    pub async fn rollback_domain(&self, domain: &str, target_version: u64, owner_did: &str) -> Result<DomainUpdateResponse> {
        // Get the target manifest
        let manifests = self.manifest_history.read().await;
        let domain_manifests = manifests.get(domain)
            .ok_or_else(|| anyhow!("No history found for domain: {}", domain))?;

        let target_manifest = domain_manifests.iter()
            .find(|m| m.version == target_version)
            .ok_or_else(|| anyhow!("Version {} not found for domain {}", target_version, domain))?
            .clone();

        drop(manifests);

        let target_cid = target_manifest.compute_cid();

        // Get current state
        let records = self.domain_records.read().await;
        let current_cid = records.get(domain)
            .map(|r| r.current_manifest_cid.clone())
            .ok_or_else(|| anyhow!("Domain not found: {}", domain))?;
        drop(records);

        // Create rollback update request
        let update_request = DomainUpdateRequest {
            domain: domain.to_string(),
            new_manifest_cid: target_cid,
            expected_previous_manifest_cid: current_cid,
            signature: String::new(), // TODO: Require signature
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_secs(),
        };

        // Note: This creates a new version pointing to old content
        // The version number continues to increment (not reset to target)
        self.update_domain(update_request).await
    }
}

pub struct Web4Manager {
    /// Domain registry
    pub registry: Arc<DomainRegistry>,
    /// Content publisher
    pub content_publisher: ContentPublisher,
}

impl Web4Manager {
    /// Create new Web4 manager
    pub async fn new() -> Result<Self> {
        Self::new_with_dht(None).await
    }

    /// Create new Web4 manager with existing storage system (avoids creating duplicates)
    pub async fn new_with_storage(storage: std::sync::Arc<tokio::sync::RwLock<lib_storage::UnifiedStorageSystem>>) -> Result<Self> {
        let registry = DomainRegistry::new_with_storage(storage.clone()).await?;
        let registry_arc = Arc::new(registry);
        let content_publisher = super::content_publisher::ContentPublisher::new_with_storage(registry_arc.clone(), storage).await?;

        Ok(Self {
            registry: registry_arc,
            content_publisher,
        })
    }

    /// Create new Web4 manager with optional existing DHT client
    pub async fn new_with_dht(dht_client: Option<ZkDHTIntegration>) -> Result<Self> {
        let registry = DomainRegistry::new_with_dht(dht_client).await?;
        let registry_arc = Arc::new(registry);
        let content_publisher = super::content_publisher::ContentPublisher::new(registry_arc.clone()).await?;

        Ok(Self {
            registry: registry_arc,
            content_publisher,
        })
    }

    /// Create new Web4 manager with existing domain registry (avoids duplicates)
    /// This is the preferred constructor when a DomainRegistry already exists
    pub async fn new_with_registry(
        registry: Arc<DomainRegistry>,
        storage: std::sync::Arc<tokio::sync::RwLock<lib_storage::UnifiedStorageSystem>>,
    ) -> Result<Self> {
        let content_publisher = super::content_publisher::ContentPublisher::new_with_storage(
            registry.clone(),
            storage
        ).await?;

        Ok(Self {
            registry,
            content_publisher,
        })
    }

    /// Register domain with initial content
    pub async fn register_domain_with_content(
        &self,
        domain: String,
        owner: ZhtpIdentity,
        initial_content: HashMap<String, Vec<u8>>,
        metadata: DomainMetadata,
    ) -> Result<DomainRegistrationResponse> {
        // Create registration proof (simplified for now)
        let registration_proof = ZeroKnowledgeProof::new(
            "Plonky2".to_string(),
            hash_blake3(&[
                owner.id.0.as_slice(),
                domain.as_bytes(),
            ].concat()).to_vec(),
            owner.id.0.to_vec(),
            owner.id.0.to_vec(),
            None,
        );

        let request = DomainRegistrationRequest {
            domain,
            owner,
            duration_days: 365, // 1 year default
            metadata,
            initial_content,
            registration_proof,
            manifest_cid: None, // Auto-generate
        };

        self.registry.register_domain(request).await
    }

    /// Get domain info (public method)
    pub async fn get_domain_info(&self, domain: &str) -> Result<DomainLookupResponse> {
        self.registry.lookup_domain(domain).await
    }
}

pub async fn initialize_web4_system() -> Result<Web4Manager> {
    initialize_web4_system_with_dht(None).await
}

pub async fn initialize_web4_system_with_storage(storage: Arc<RwLock<lib_storage::UnifiedStorageSystem>>) -> Result<Web4Manager> {
    let manager = Web4Manager::new_with_storage(storage).await?;
    tracing::info!("Web4 domain registry and content publishing system initialized with existing storage");
    Ok(manager)
}

pub async fn initialize_web4_system_with_dht(dht_client: Option<ZkDHTIntegration>) -> Result<Web4Manager> {
    let manager = Web4Manager::new_with_dht(dht_client).await?;
    tracing::info!("Web4 domain registry and content publishing system initialized");
    Ok(manager)
}

pub enum TrustPolicy {
    /// Explicitly pinned (highest trust)
    Pinned,
    /// Trust on first use (persisted after first connection)
    Tofu,
    /// Bootstrap mode (dev only, no persistence)
    Bootstrap,
}

pub struct TrustAnchor {
    /// Node address (ip:port or hostname:port)
    pub node_addr: String,
    /// Node DID (verified via UHP handshake)
    pub node_did: Option<String>,
    /// SPKI SHA-256 hash (base64 encoded)
    pub spki_sha256: String,
    /// Certificate fingerprint (for display/audit)
    pub cert_fingerprint: String,
    /// First seen timestamp
    pub first_seen: u64,
    /// Last seen timestamp
    pub last_seen: u64,
    /// Trust policy
    pub policy: TrustPolicy,
}

pub struct TrustDb {
    /// Version for forward compatibility
    pub version: u32,
    /// Trust anchors by node address
    pub anchors: HashMap<String, TrustAnchor>,
}

impl TrustDb {
    /// Create empty trust database
    pub fn new() -> Self {
        Self {
            version: 1,
            anchors: HashMap::new(),
        }
    }

    /// Load from file, or create new if not exists
    pub fn load_or_create(path: &Path) -> Result<Self> {
        if path.exists() {
            Self::validate_permissions(path)?;
            let data = std::fs::read_to_string(path)
                .context("Failed to read trustdb")?;
            let db: TrustDb = serde_json::from_str(&data)
                .context("Failed to parse trustdb")?;
            Ok(db)
        } else {
            Ok(Self::new())
        }
    }

    /// Save to file
    pub fn save(&self, path: &Path) -> Result<()> {
        // Ensure parent directory exists
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let data = serde_json::to_string_pretty(self)?;
        std::fs::write(path, data)?;
        // Enforce strict permissions
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut perms = std::fs::metadata(path)?.permissions();
            perms.set_mode(0o600);
            std::fs::set_permissions(path, perms)?;
        }
        Ok(())
    }

    /// Append audit entry
    pub fn append_audit_entry(path: &Path, entry: &TrustAuditEntry) -> Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }

        let line = serde_json::to_string(entry)? + "\n";
        std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .write(true)
            .open(path)
            .and_then(|mut f| {
                use std::io::Write;
                f.write_all(line.as_bytes())
            })?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut perms = std::fs::metadata(path)?.permissions();
            perms.set_mode(0o600);
            std::fs::set_permissions(path, perms)?;
        }

        Ok(())
    }

    /// Validate permissions on trustdb (fail closed in production)
    fn validate_permissions(path: &Path) -> Result<()> {
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            let meta = std::fs::metadata(path)
                .context("Failed to stat trustdb")?;
            let mode = meta.mode() & 0o777;

            // Only owner rw allowed
            if mode & 0o077 != 0 {
                return Err(anyhow!(
                    "Insecure permissions on trustdb {:?} (mode {:o}). Set to 0600",
                    path, mode
                ));
            }

            // Owner must be current user
            let uid = meta.uid();
            let current_uid = unsafe { libc::geteuid() } as u32;
            if uid != current_uid {
                return Err(anyhow!(
                    "Trustdb {:?} is owned by uid {}, expected {}",
                    path, uid, current_uid
                ));
            }
        }
        Ok(())
    }

    /// Get anchor for node address
    pub fn get(&self, node_addr: &str) -> Option<&TrustAnchor> {
        self.anchors.get(node_addr)
    }

    /// Add or update anchor
    pub fn set(&mut self, anchor: TrustAnchor) {
        self.anchors.insert(anchor.node_addr.clone(), anchor);
    }

    /// Remove anchor
    pub fn remove(&mut self, node_addr: &str) -> Option<TrustAnchor> {
        self.anchors.remove(node_addr)
    }
}

pub struct TrustConfig {
    /// Pinned SPKI hash (base64 SHA-256)
    pub pin_spki: Option<String>,
    /// Expected node DID
    pub node_did: Option<String>,
    /// Allow TOFU (trust on first use)
    pub allow_tofu: bool,
    /// Bootstrap mode (insecure, dev only)
    pub bootstrap_mode: bool,
    /// Path to trust database
    pub trustdb_path: Option<PathBuf>,
    /// Path to audit log
    pub audit_log_path: Option<PathBuf>,
}

impl Default for TrustConfig {
    fn default() -> Self {
        Self {
            pin_spki: None,
            node_did: None,
            allow_tofu: false,
            bootstrap_mode: false,
            trustdb_path: None,
            audit_log_path: None,
        }
    }
}

impl TrustConfig {
    /// Create config for bootstrap mode (dev only)
    pub fn bootstrap() -> Self {
        Self {
            bootstrap_mode: true,
            ..Default::default()
        }
    }

    /// Create config with SPKI pin
    pub fn with_pin(spki_sha256: String) -> Self {
        Self {
            pin_spki: Some(spki_sha256),
            ..Default::default()
        }
    }

    /// Create config with TOFU enabled
    pub fn with_tofu(trustdb_path: PathBuf) -> Self {
        Self {
            allow_tofu: true,
            trustdb_path: Some(trustdb_path),
            audit_log_path: Some(Self::default_audit_path()),
            ..Default::default()
        }
    }

    /// Set expected node DID
    pub fn expect_node_did(mut self, did: String) -> Self {
        self.node_did = Some(did);
        self
    }

    /// Get default trustdb path
    pub fn default_trustdb_path() -> Result<PathBuf> {
        let home = std::env::var("HOME")
            .or_else(|_| std::env::var("USERPROFILE"))
            .context("Could not determine home directory")?;
        Ok(PathBuf::from(home).join(".zhtp").join("trustdb.json"))
    }

    /// Get default audit log path (same dir as trustdb)
    pub fn default_audit_path() -> PathBuf {
        let home = std::env::var("HOME")
            .or_else(|_| std::env::var("USERPROFILE"))
            .unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".zhtp").join("trust_audit.log")
    }
}

pub struct TlsVerificationResult {
    /// SPKI SHA-256 hash of the certificate
    pub spki_sha256: String,
    /// Certificate fingerprint (for display)
    pub cert_fingerprint: String,
    /// Whether this was a TOFU acceptance
    pub tofu_accepted: bool,
}

pub struct ZhtpTrustVerifier {
    /// Trust configuration
    config: TrustConfig,
    /// Trust database (loaded at creation, saved on TOFU)
    trustdb: Arc<RwLock<TrustDb>>,
    /// Node address being connected to
    node_addr: String,
    /// Verification result (set after successful verify)
    result: Arc<RwLock<Option<TlsVerificationResult>>>,
}

impl ZhtpTrustVerifier {
    /// Create a new verifier for the given node address
    pub fn new(node_addr: String, config: TrustConfig) -> Result<Self> {
        // Load trustdb if path provided
        let trustdb = if let Some(ref path) = config.trustdb_path {
            TrustDb::load_or_create(path)?
        } else {
            TrustDb::new()
        };

        Ok(Self {
            config,
            trustdb: Arc::new(RwLock::new(trustdb)),
            node_addr,
            result: Arc::new(RwLock::new(None)),
        })
    }

    /// Get verification result after successful TLS handshake
    pub fn verification_result(&self) -> Option<TlsVerificationResult> {
        self.result.read().ok()?.clone()
    }

    /// Compute SPKI hash from certificate (no fallback)
    ///
    /// Fails if SPKI cannot be extracted, per security requirements.
    fn compute_spki_hash(cert: &CertificateDer<'_>) -> Result<String> {
        let (_, parsed_cert) = X509Certificate::from_der(cert.as_ref())
            .map_err(|e| anyhow!("Failed to parse X.509 certificate for SPKI extraction: {}", e))?;

        // DER-encoded SubjectPublicKeyInfo
        let spki_bytes = parsed_cert.public_key().raw;

        let hash = lib_crypto::hash_blake3(spki_bytes);
        Ok(hex::encode(hash))
    }

    /// Compute certificate fingerprint for display (full cert hash)
    fn compute_fingerprint(cert: &CertificateDer<'_>) -> String {
        let hash = lib_crypto::hash_blake3(cert.as_ref());
        hex::encode(&hash[..16])
    }

    /// Store TOFU anchor after successful verification
    fn store_tofu_anchor(&self, spki_hash: &str, fingerprint: &str) -> Result<()> {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        let anchor = TrustAnchor {
            node_addr: self.node_addr.clone(),
            node_did: None, // Will be set after UHP handshake
            spki_sha256: spki_hash.to_string(),
            cert_fingerprint: fingerprint.to_string(),
            first_seen: now,
            last_seen: now,
            policy: TrustPolicy::Tofu,
        };

        {
            let mut db = self.trustdb.write()
                .map_err(|_| anyhow!("Failed to lock trustdb"))?;
            db.set(anchor);
        }

        // Save to disk if path configured
        if let Some(ref path) = self.config.trustdb_path {
            let db = self.trustdb.read()
                .map_err(|_| anyhow!("Failed to lock trustdb"))?;
            db.save(path)?;
        }

        // Append audit log entry
        let audit_path = self.config.audit_log_path.clone().unwrap_or_else(|| TrustConfig::default_audit_path());
        if self.config.allow_tofu || self.config.bootstrap_mode {
            let entry = TrustAuditEntry {
                timestamp: now,
                node_addr: self.node_addr.clone(),
                node_did: None,
                spki_sha256: spki_hash.to_string(),
                tool_version: env!("CARGO_PKG_VERSION").to_string(),
            };
            if let Err(e) = TrustDb::append_audit_entry(&audit_path, &entry) {
                warn!("Failed to append TOFU audit log: {}", e);
            }
        }

        Ok(())
    }

    /// Update anchor with verified node DID (called after UHP handshake)
    pub fn bind_node_did(&self, node_did: &str) -> Result<()> {
        let mut db = self.trustdb.write()
            .map_err(|_| anyhow!("Failed to lock trustdb"))?;

        if let Some(anchor) = db.anchors.get_mut(&self.node_addr) {
            // Verify DID matches if already set
            if let Some(ref existing_did) = anchor.node_did {
                if existing_did != node_did {
                    return Err(anyhow!(
                        "Node DID mismatch: expected {}, got {}",
                        existing_did, node_did
                    ));
                }
            } else {
                // First time seeing DID, store it
                anchor.node_did = Some(node_did.to_string());
                anchor.last_seen = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs();
            }
        }

        // Save if path configured
        drop(db);
        if let Some(ref path) = self.config.trustdb_path {
            let db = self.trustdb.read()
                .map_err(|_| anyhow!("Failed to lock trustdb"))?;
            db.save(path)?;
        }

        Ok(())
    }

    /// Verify node DID matches configuration
    pub fn verify_node_did(&self, node_did: &str) -> Result<()> {
        // Check explicit --node-did flag
        if let Some(ref expected) = self.config.node_did {
            if expected != node_did {
                return Err(anyhow!(
                    "Node DID mismatch: expected {} (from --node-did), got {}",
                    expected, node_did
                ));
            }
        }

        // Check trustdb entry
        let db = self.trustdb.read()
            .map_err(|_| anyhow!("Failed to lock trustdb"))?;

        if let Some(anchor) = db.get(&self.node_addr) {
            if let Some(ref stored_did) = anchor.node_did {
                if stored_did != node_did {
                    return Err(anyhow!(
                        "Node DID mismatch: trusted {} but node presented {}",
                        stored_did, node_did
                    ));
                }
            }
        }

        Ok(())
    }
}

impl ServerCertVerifier for ZhtpTrustVerifier {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        _intermediates: &[CertificateDer<'_>],
        server_name: &ServerName<'_>,
        _ocsp_response: &[u8],
        _now: UnixTime,
    ) -> std::result::Result<ServerCertVerified, TlsError> {
        let spki_hash = Self::compute_spki_hash(end_entity)
            .map_err(|e| TlsError::General(format!("{}", e).into()))?;
        let fingerprint = Self::compute_fingerprint(end_entity);

        debug!(
            server_name = ?server_name,
            spki_hash = %spki_hash,
            fingerprint = %fingerprint,
            "Verifying ZHTP node certificate"
        );

        // 1. Check explicit pin
        if let Some(ref pin) = self.config.pin_spki {
            if &spki_hash == pin {
                info!(
                    fingerprint = %fingerprint,
                    "Certificate verified via SPKI pin"
                );
                if let Ok(mut result) = self.result.write() {
                    *result = Some(TlsVerificationResult {
                        spki_sha256: spki_hash,
                        cert_fingerprint: fingerprint,
                        tofu_accepted: false,
                    });
                }
                return Ok(ServerCertVerified::assertion());
            } else {
                return Err(TlsError::General(format!(
                    "SPKI pin mismatch: expected {}, got {}",
                    pin, spki_hash
                ).into()));
            }
        }

        // 2. Check trustdb
        if let Ok(db) = self.trustdb.read() {
            if let Some(anchor) = db.get(&self.node_addr) {
                if anchor.spki_sha256 == spki_hash {
                    info!(
                        fingerprint = %fingerprint,
                        policy = ?anchor.policy,
                        "Certificate verified via trustdb"
                    );
                    if let Ok(mut result) = self.result.write() {
                        *result = Some(TlsVerificationResult {
                            spki_sha256: spki_hash,
                            cert_fingerprint: fingerprint,
                            tofu_accepted: false,
                        });
                    }
                    return Ok(ServerCertVerified::assertion());
                } else {
                    return Err(TlsError::General(format!(
                        "Certificate changed! Trusted fingerprint: {}, presented: {}. \
                        If this is expected, remove the old entry with: zhtp trust remove {}",
                        anchor.cert_fingerprint, fingerprint, self.node_addr
                    ).into()));
                }
            }
        }

        // 3. Check TOFU
        if self.config.allow_tofu {
            // Print fingerprint prominently for user awareness
            warn!("╔══════════════════════════════════════════════════════════════╗");
            warn!("║  TOFU: Trusting certificate on first use                     ║");
            warn!("╠══════════════════════════════════════════════════════════════╣");
            warn!("║  Node: {:<52} ║", &self.node_addr);
            warn!("║  Fingerprint: {:<46} ║", &fingerprint);
            warn!("║  SPKI Hash: {}...  ║", &spki_hash[..32]);
            warn!("╠══════════════════════════════════════════════════════════════╣");
            warn!("║  This certificate is now trusted for future connections.     ║");
            warn!("║  If this is unexpected, your connection may be compromised!  ║");
            warn!("║  To reset: delete ~/.zhtp/trustdb.json                       ║");
            warn!("╚══════════════════════════════════════════════════════════════╝");

            // Store anchor
            if let Err(e) = self.store_tofu_anchor(&spki_hash, &fingerprint) {
                warn!("Failed to store TOFU anchor: {}", e);
            }

            if let Ok(mut result) = self.result.write() {
                *result = Some(TlsVerificationResult {
                    spki_sha256: spki_hash,
                    cert_fingerprint: fingerprint,
                    tofu_accepted: true,
                });
            }
            return Ok(ServerCertVerified::assertion());
        }

        // 4. Check bootstrap mode
        if self.config.bootstrap_mode {
            // Log fingerprint even in bootstrap mode for debugging/auditing
            warn!("╔══════════════════════════════════════════════════════════════╗");
            warn!("║  INSECURE: Bootstrap mode - accepting ANY certificate        ║");
            warn!("╠══════════════════════════════════════════════════════════════╣");
            warn!("║  Node: {:<52} ║", &self.node_addr);
            warn!("║  Fingerprint: {:<46} ║", &fingerprint);
            warn!("║  SPKI Hash: {}...  ║", &spki_hash[..32]);
            warn!("╠══════════════════════════════════════════════════════════════╣");
            warn!("║  WARNING: No verification performed! Vulnerable to MITM!     ║");
            warn!("║  For production, use: --pin-spki {} ║", &spki_hash[..32]);
            warn!("╚══════════════════════════════════════════════════════════════╝");

            if let Ok(mut result) = self.result.write() {
                *result = Some(TlsVerificationResult {
                    spki_sha256: spki_hash,
                    cert_fingerprint: fingerprint,
                    tofu_accepted: false,
                });
            }
            return Ok(ServerCertVerified::assertion());
        }

        // 5. No trust anchor - reject with actionable error
        Err(TlsError::General(format!(
            "No trust anchor for node {}. Options:\n\
            1. Pin the certificate: --pin-spki {}\n\
            2. Trust on first use: --tofu\n\
            3. Specify expected node: --node-did <did>\n\
            4. Development only: --trust-node (insecure)",
            self.node_addr, spki_hash
        ).into()))
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        rustls::crypto::verify_tls12_signature(
            message,
            cert,
            dss,
            &rustls::crypto::ring::default_provider().signature_verification_algorithms,
        )
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        rustls::crypto::verify_tls13_signature(
            message,
            cert,
            dss,
            &rustls::crypto::ring::default_provider().signature_verification_algorithms,
        )
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        rustls::crypto::ring::default_provider()
            .signature_verification_algorithms
            .supported_schemes()
    }
}

