    pub fn new() -> Self {
        Self {
            topology_graph: Arc::new(RwLock::new(TopologyGraph {
                nodes: HashMap::new(),
                edges: HashMap::new(),
                adjacency_list: HashMap::new(),
                version: 0,
            })),
            path_cache: Arc::new(RwLock::new(HashMap::new())),
