            ("OneWeb", 7700, "LEO", 1200),
            ("Amazon Kuiper", 13000, "LEO", 630),
            ("Telesat", 1671, "LEO", 1000),
        ];

        for (name, count, orbit_type, altitude) in available_constellations {
            // Simulate signal detection
