                }
            }
            _ => {
                // Fallback: use blueutil if available
                let blueutil_output = std::process::Command::new("blueutil")
                    .args(&["--paired"])
                    .output();

                if let Ok(result) = blueutil_output {
                    let output_str = String::from_utf8_lossy(&result.stdout);
