    /// Start full RFCOMM service with all 4 channels
    pub async fn start_full_service(&self) -> Result<()> {
        info!(" Starting full RFCOMM service with all 4 ZHTP channels");

        // Start advertising
        self.start_advertising().await?;

        // Start listeners on all 4 channels
        self.listen_on_channel(rfcomm_channels::ZK_AUTH).await?;
        info!(" Channel {} (ZK_AUTH) listening", rfcomm_channels::ZK_AUTH);

        self.listen_on_channel(rfcomm_channels::QUANTUM_ROUTING).await?;
        info!(" Channel {} (QUANTUM_ROUTING) listening", rfcomm_channels::QUANTUM_ROUTING);

        self.listen_on_channel(rfcomm_channels::MESH_DATA).await?;
        info!(" Channel {} (MESH_DATA) listening", rfcomm_channels::MESH_DATA);

        self.listen_on_channel(rfcomm_channels::COORDINATION).await?;
        info!(" Channel {} (COORDINATION) listening", rfcomm_channels::COORDINATION);

        info!(" Full RFCOMM service started - accepting connections on 4 channels");
        Ok(())
    }

    /// Disconnect from a peer and cleanup resources
    pub async fn disconnect_peer(&self, peer_address: &str) -> Result<()> {
        info!("🔌 Disconnecting from peer: {}", peer_address);

        // Remove from active connections
        if let Some(removed_conn) = self.active_connections.write().await.remove(peer_address) {
            info!(" Removed connection metadata for {}", peer_address);
            debug!("   Channel: {}, MTU: {}, Outgoing: {}", 
                   removed_conn.channel, removed_conn.mtu, removed_conn.is_outgoing);
        } else {
            warn!(" No active connection found for {}", peer_address);
        }

        // Remove from active streams (this will close the socket)
        if let Some(removed_stream) = self.active_streams.write().await.remove(peer_address) {
            info!(" Removed stream for {}", peer_address);

            // The stream will be dropped here, closing the socket
            drop(removed_stream);
        } else {
            warn!(" No active stream found for {}", peer_address);
        }

        // Remove from authenticated peers
        if self.authenticated_peers.write().await.remove(peer_address).is_some() {
            info!(" Removed authentication for {}", peer_address);
        }

        info!(" Disconnected from {}", peer_address);
        Ok(())
    }

    /// Disconnect all peers and cleanup resources
    pub async fn disconnect_all(&self) -> Result<()> {
        info!("🔌 Disconnecting from all peers");

        let peer_addresses: Vec<String> = self.active_connections.read().await
            .keys()
            .cloned()
            .collect();

        let mut disconnect_count = 0;
        for peer_addr in peer_addresses {
            if self.disconnect_peer(&peer_addr).await.is_ok() {
                disconnect_count += 1;
            }
        }

        info!(" Disconnected from {} peers", disconnect_count);
        Ok(())
    }
}

pub fn parse_mac_address(mac_str: &str) -> Result<[u8; 6]> {
    let clean = mac_str.replace([':', '-'], "");
    if clean.len() != 12 {
        return Err(anyhow!("Invalid MAC address length: expected 12 hex chars, got {}", clean.len()));
    }

    let mut mac = [0u8; 6];
    for i in 0..6 {
        mac[i] = u8::from_str_radix(&clean[i*2..i*2+2], 16)
            .map_err(|e| anyhow!("Failed to parse MAC address byte at position {}: {}", i, e))?;
    }
    Ok(mac)
}

pub fn get_system_bluetooth_mac() -> Result<[u8; 6]> {
    #[cfg(target_os = "windows")]
    {
        use std::process::Command;

        info!(" Windows: Detecting Bluetooth MAC address via PowerShell");
        let output = Command::new("powershell")
            .args(&["-Command", "Get-NetAdapter | Where-Object {$_.Name -like '*Bluetooth*'} | Select-Object -ExpandProperty MacAddress"])
            .output();

        if let Ok(result) = output {
            let mac_str = String::from_utf8_lossy(&result.stdout);
            let trimmed = mac_str.trim();
            if !trimmed.is_empty() {
                if let Ok(mac) = parse_mac_address(trimmed) {
                    info!(" Detected Windows Bluetooth MAC: {}", trimmed);
                    return Ok(mac);
                }
            }
        }
        warn!(" Windows: Could not detect Bluetooth MAC via PowerShell");
    }

    #[cfg(target_os = "linux")]
    {
        info!("🐧 Linux: Detecting Bluetooth MAC address from /sys/class/bluetooth");

        if let Ok(adapters) = std::fs::read_dir("/sys/class/bluetooth") {
            for adapter in adapters.flatten() {
                let address_path = adapter.path().join("address");
                if let Ok(address) = std::fs::read_to_string(address_path) {
                    let trimmed = address.trim();
                    if let Ok(mac) = parse_mac_address(trimmed) {
                        info!(" Detected Linux Bluetooth MAC: {}", trimmed);
                        return Ok(mac);
                    }
                }
            }
        }
        warn!(" Linux: Could not detect Bluetooth MAC from sysfs");
    }

    #[cfg(target_os = "macos")]
    {
        use std::process::Command;

        info!("🍎 macOS: Detecting Bluetooth MAC address via system_profiler");
        let output = Command::new("system_profiler")
            .args(&["SPBluetoothDataType", "-xml"])
            .output();

        if let Ok(result) = output {
            let output_str = String::from_utf8_lossy(&result.stdout);

            // Simple parsing - look for MAC address patterns
            for line in output_str.lines() {
                if line.contains("Address") || line.contains("address") {
                    // Look for MAC address pattern (XX:XX:XX:XX:XX:XX)
                    for word in line.split_whitespace() {
                        if word.len() == 17 && word.matches(':').count() == 5 {
                            if let Ok(mac) = parse_mac_address(word) {
                                info!(" Detected macOS Bluetooth MAC: {}", word);
                                return Ok(mac);
                            }
                        }
                    }
                }
            }
        }
        warn!(" macOS: Could not detect Bluetooth MAC via system_profiler");
    }

    // Fallback: Generate deterministic locally-administered MAC
    info!(" Generating deterministic fallback Bluetooth MAC address");
    generate_fallback_mac()
}

fn generate_fallback_mac() -> Result<[u8; 6]> {
    use sha2::{Sha256, Digest};

    // Get system identifier
    let system_id = std::env::var("COMPUTERNAME")
        .or_else(|_| std::env::var("HOSTNAME"))
        .or_else(|_| std::env::var("HOST"))
        .unwrap_or_else(|_| "UNKNOWN_HOST".to_string());

    // Hash to generate deterministic MAC
    let mut hasher = Sha256::new();
    hasher.update(b"BLUETOOTH_FALLBACK_MAC");
    hasher.update(system_id.as_bytes());
    let hash = hasher.finalize();

    let mut mac = [0u8; 6];
    mac.copy_from_slice(&hash[0..6]);

    // Set locally administered bit (bit 1 of first octet)
    mac[0] |= 0x02;
    // Clear multicast bit (bit 0 of first octet)
    mac[0] &= 0xFE;

    info!(" Generated fallback MAC: {:02X}:{:02X}:{:02X}:{:02X}:{:02X}:{:02X}", 
          mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);

    Ok(mac)
}

pub fn format_mac_address(mac: &[u8; 6]) -> String {
    format!("{:02X}:{:02X}:{:02X}:{:02X}:{:02X}:{:02X}",
        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5])
}

pub fn mac_to_dbus_path(mac: &[u8; 6]) -> String {
    format!("dev_{:02X}_{:02X}_{:02X}_{:02X}_{:02X}_{:02X}",
        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5])
}

pub fn parse_uuid_to_guid(uuid_str: &str) -> Result<windows::core::GUID> {
    use windows::core::GUID;

    // Remove hyphens and validate length
    let clean = uuid_str.replace("-", "");
    if clean.len() != 32 {
        return Err(anyhow!("Invalid UUID format: expected 32 hex chars"));
    }

    // Parse components
    let data1 = u32::from_str_radix(&clean[0..8], 16)?;
    let data2 = u16::from_str_radix(&clean[8..12], 16)?;
    let data3 = u16::from_str_radix(&clean[12..16], 16)?;

    let mut data4 = [0u8; 8];
    for i in 0..8 {
        data4[i] = u8::from_str_radix(&clean[16 + i*2..16 + i*2 + 2], 16)?;
    }

    Ok(GUID::from_values(data1, data2, data3, data4))
}

pub struct BlueZDBusClient {
    connection: Connection,
    adapter_path: String,
}

impl BlueZDBusClient {
    /// Create a new BlueZ D-Bus client
    pub fn new() -> Result<Self> {
        info!(" Initializing BlueZ D-Bus client");

        let connection = Connection::new_system()
            .map_err(|e| anyhow!("Failed to connect to system D-Bus: {}", e))?;

        // Default adapter path (usually hci0)
        let adapter_path = "/org/bluez/hci0".to_string();

        info!(" BlueZ D-Bus client initialized on {}", adapter_path);
        Ok(Self {
            connection,
            adapter_path,
        })
    }

    /// Start device discovery
    pub fn start_discovery(&self) -> Result<(), anyhow::Error> {
        info!(" Starting BlueZ device discovery via D-Bus");

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            &self.adapter_path,
            Duration::from_secs(5),
        );

        proxy.method_call(ADAPTER_INTERFACE, "StartDiscovery", ())
            .map_err(|e| anyhow!("Failed to start discovery: {}", e))?;

        info!(" Discovery started");
        Ok(())
    }

    /// Stop device discovery
    pub fn stop_discovery(&self) -> Result<(), anyhow::Error> {
        debug!("🛑 Stopping BlueZ device discovery");

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            &self.adapter_path,
            Duration::from_secs(5),
        );

        proxy.method_call(ADAPTER_INTERFACE, "StopDiscovery", ())
            .map_err(|e| anyhow!("Failed to stop discovery: {}", e))?;

        Ok(())
    }

    /// Get list of discovered devices
    pub fn get_devices(&self) -> Result<Vec<DeviceInfo>> {
        debug!(" Getting device list via D-Bus");

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            "/org/bluez",
            Duration::from_secs(5),
        );

        // Get managed objects (all BlueZ objects)
        let (objects,): (HashMap<dbus::Path, HashMap<String, HashMap<String, Variant<Box<dyn RefArg>>>>>,) = 
            proxy.method_call("org.freedesktop.DBus.ObjectManager", "GetManagedObjects", ())
                .map_err(|e| anyhow!("Failed to get managed objects: {}", e))?;

        let mut devices = Vec::new();

        for (path, interfaces) in objects {
            // Check if this object is a device
            if let Some(device_props) = interfaces.get(DEVICE_INTERFACE) {
                let address = device_props.get("Address")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();

                let name = device_props.get("Name")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string());

                let rssi = device_props.get("RSSI")
                    .and_then(|v| v.as_i64())
                    .unwrap_or(0) as i32;

                let connected = device_props.get("Connected")
                    .and_then(|v| v.as_i64())
                    .map(|v| v != 0)
                    .unwrap_or(false);

                if !address.is_empty() {
                    devices.push(DeviceInfo {
                        path: path.to_string(),
                        address,
                        name,
                        rssi,
                        connected,
                    });
                }
            }
        }

        debug!(" Found {} devices", devices.len());
        Ok(devices)
    }

    /// Connect to a device by address
    pub fn connect_device(&self, device_address: &str) -> Result<(), anyhow::Error> {
        info!(" Connecting to device {} via D-Bus", device_address);

        let device_path = self.get_device_path(device_address)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            device_path,
            Duration::from_secs(30), // Longer timeout for connection
        );

        proxy.method_call(DEVICE_INTERFACE, "Connect", ())
            .map_err(|e| anyhow!("Failed to connect to device: {}", e))?;

        info!(" Connected to {}", device_address);
        Ok(())
    }

    /// Disconnect from a device
    pub fn disconnect_device(&self, device_address: &str) -> Result<(), anyhow::Error> {
        info!("🔌 Disconnecting from device {} via D-Bus", device_address);

        let device_path = self.get_device_path(device_address)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            device_path,
            Duration::from_secs(10),
        );

        proxy.method_call(DEVICE_INTERFACE, "Disconnect", ())
            .map_err(|e| anyhow!("Failed to disconnect from device: {}", e))?;

        info!(" Disconnected from {}", device_address);
        Ok(())
    }

    /// Read GATT characteristic value
    pub fn read_gatt_characteristic(&self, device_address: &str, char_uuid: &str) -> Result<Vec<u8>> {
        debug!("📖 Reading GATT characteristic {} via D-Bus", char_uuid);

        let char_path = self.get_characteristic_path(device_address, char_uuid)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            char_path,
            Duration::from_secs(10),
        );

        // Call ReadValue method with empty options
        let options: HashMap<String, Variant<Box<dyn RefArg>>> = HashMap::new();
        let (value,): (Vec<u8>,) = proxy.method_call(GATT_CHARACTERISTIC_INTERFACE, "ReadValue", (options,))
            .map_err(|e| anyhow!("Failed to read characteristic: {}", e))?;

        debug!("📖 Read {} bytes from characteristic {}", value.len(), char_uuid);
        Ok(value)
    }

    /// Write GATT characteristic value
    pub fn write_gatt_characteristic(&self, device_address: &str, char_uuid: &str, data: &[u8]) -> Result<(), anyhow::Error> {
        debug!("✍️ Writing {} bytes to GATT characteristic {} via D-Bus", data.len(), char_uuid);

        let char_path = self.get_characteristic_path(device_address, char_uuid)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            char_path,
            Duration::from_secs(10),
        );

        // Call WriteValue method
        let options: HashMap<String, Variant<Box<dyn RefArg>>> = HashMap::new();
        proxy.method_call(GATT_CHARACTERISTIC_INTERFACE, "WriteValue", (data.to_vec(), options))
            .map_err(|e| anyhow!("Failed to write characteristic: {}", e))?;

        debug!(" Wrote {} bytes to characteristic {}", data.len(), char_uuid);
        Ok(())
    }

    /// Enable notifications on a characteristic
    pub fn enable_notifications(&self, device_address: &str, char_uuid: &str) -> Result<(), anyhow::Error> {
        info!(" Enabling notifications for characteristic {} via D-Bus", char_uuid);

        let char_path = self.get_characteristic_path(device_address, char_uuid)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            char_path,
            Duration::from_secs(10),
        );

        proxy.method_call(GATT_CHARACTERISTIC_INTERFACE, "StartNotify", ())
            .map_err(|e| anyhow!("Failed to enable notifications: {}", e))?;

        info!(" Notifications enabled for {}", char_uuid);
        Ok(())
    }

    /// Disable notifications on a characteristic
    pub fn disable_notifications(&self, device_address: &str, char_uuid: &str) -> Result<(), anyhow::Error> {
        debug!("🔕 Disabling notifications for characteristic {}", char_uuid);

        let char_path = self.get_characteristic_path(device_address, char_uuid)?;

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            char_path,
            Duration::from_secs(10),
        );

        proxy.method_call(GATT_CHARACTERISTIC_INTERFACE, "StopNotify", ())
            .map_err(|e| anyhow!("Failed to disable notifications: {}", e))?;

        Ok(())
    }

    /// Get device path from MAC address
    fn get_device_path(&self, device_address: &str) -> Result<String> {
        // Convert MAC address to BlueZ device path format
        // Example: "AA:BB:CC:DD:EE:FF" -> "/org/bluez/hci0/dev_AA_BB_CC_DD_EE_FF"
        let normalized = device_address.replace(':', "_");
        Ok(format!("{}/dev_{}", self.adapter_path, normalized))
    }

    /// Get characteristic path (simplified - in production, would enumerate services)
    fn get_characteristic_path(&self, device_address: &str, char_uuid: &str) -> Result<String> {
        let device_path = self.get_device_path(device_address)?;

        // In production, we'd enumerate GATT services and characteristics
        // For now, construct a typical path
        // Example: "/org/bluez/hci0/dev_XX_XX_XX_XX_XX_XX/service0001/char0003"

        // This is a simplified version - real implementation would use GetManagedObjects
        // to find the actual characteristic path

        warn!(" Using simplified characteristic path resolution - production code should enumerate services");

        // Return a generic path that needs to be resolved
        Ok(format!("{}/service0001/char0001", device_path))
    }

    /// Get adapter MAC address
    pub fn get_adapter_address(&self) -> Result<String> {
        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            &self.adapter_path,
            Duration::from_secs(5),
        );

        let address: String = proxy.get(ADAPTER_INTERFACE, "Address")
            .map_err(|e| anyhow!("Failed to get adapter address: {}", e))?;

        Ok(address)
    }

    /// Check if adapter is powered on
    pub fn is_powered(&self) -> Result<bool> {
        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            &self.adapter_path,
            Duration::from_secs(5),
        );

        let powered: bool = proxy.get(ADAPTER_INTERFACE, "Powered")
            .map_err(|e| anyhow!("Failed to get adapter power state: {}", e))?;

        Ok(powered)
    }

    /// Power on the adapter
    pub fn power_on(&self) -> Result<(), anyhow::Error> {
        info!("⚡ Powering on Bluetooth adapter via D-Bus");

        let proxy = self.connection.with_proxy(
            BLUEZ_SERVICE,
            &self.adapter_path,
            Duration::from_secs(5),
        );

        proxy.set(ADAPTER_INTERFACE, "Powered", true)
            .map_err(|e| anyhow!("Failed to power on adapter: {}", e))?;

        info!(" Adapter powered on");
        Ok(())
    }
}

pub enum ConnectionState {
    Disconnected,
    Connecting,
    Connected,
    Disconnecting,
}

pub trait BluetoothDeviceInfo {
    /// Get device address (may be ephemeral for BLE)
    fn address(&self) -> &str;

    /// Get device name if available
    fn name(&self) -> Option<&str>;

    /// Get RSSI (signal strength)
    fn rssi(&self) -> Option<i16>;

    /// Get list of advertised service UUIDs
    fn services(&self) -> &[String];

    /// Check if device is currently connected
    fn is_connected(&self) -> bool;

    /// Get last seen timestamp (Unix epoch seconds)
    fn last_seen(&self) -> u64;
}

pub struct BleDevice {
    /// Encrypted MAC address hash (one-way, cannot recover original)
    pub encrypted_mac_hash: [u8; 32],

    /// Secure node identifier derived from node_id + MAC
    pub secure_node_id: [u8; 32],

    /// Ephemeral discovery address (rotates every 15 minutes for privacy)
    pub ephemeral_address: String,

    /// Device name if advertised
    pub device_name: Option<String>,

    /// Advertised service UUIDs
    pub services: Vec<String>,

    /// GATT characteristics discovered
    pub characteristics: HashMap<String, CharacteristicInfo>,

    /// Connection handle (if connected)
    pub connection_handle: Option<u16>,

    /// Connection state
    pub connection_state: ConnectionState,

    /// Signal strength (RSSI)
    pub signal_strength: i16,

    /// Last seen timestamp (Unix epoch)
    pub last_seen: u64,
}

