pub fn parse_characteristic_properties(flags: &[String]) -> Vec<GattOperation> {
    let mut operations = Vec::new();

    for flag in flags {
        match flag.to_lowercase().as_str() {
            "read" => operations.push(GattOperation::Read),
            "write" => operations.push(GattOperation::Write),
            "write-without-response" => operations.push(GattOperation::WriteWithoutResponse),
            "notify" => operations.push(GattOperation::Notify),
            "indicate" => operations.push(GattOperation::Indicate),
            _ => debug!("Unknown GATT property: {}", flag),
        }
    }

    operations
}

pub fn supports_operation(properties: &[String], operation: GattOperation) -> bool {
    parse_characteristic_properties(properties).contains(&operation)
}

pub fn validate_write_size(data: &[u8], mtu: u16) -> Result<()> {
    // GATT ATT header is 3 bytes
    let max_data_size = (mtu as usize).saturating_sub(3);

    if data.len() > max_data_size {
        return Err(anyhow!(
            "Data size {} exceeds MTU limit {} (MTU: {} - 3 byte header)",
            data.len(), max_data_size, mtu
        ));
    }

    Ok(())
}

pub fn fragment_data(data: &[u8], mtu: u16) -> Vec<Vec<u8>> {
    let max_chunk_size = (mtu as usize).saturating_sub(3);

    data.chunks(max_chunk_size)
        .map(|chunk| chunk.to_vec())
        .collect()
}

pub fn fragment_large_message(message_id: u64, data: &[u8], mtu: u16) -> Vec<Vec<u8>> {
    const HEADER_SIZE: usize = 11; // message_id(8) + total_fragments(2) + sequence(1)
    let max_data_per_fragment = (mtu as usize).saturating_sub(3 + HEADER_SIZE);

    let chunks: Vec<&[u8]> = data.chunks(max_data_per_fragment).collect();
    let total_fragments = chunks.len() as u16;

    chunks.into_iter().enumerate().map(|(index, chunk)| {
        let mut fragment = Vec::with_capacity(HEADER_SIZE + chunk.len());
        fragment.extend_from_slice(&message_id.to_le_bytes());
        fragment.extend_from_slice(&total_fragments.to_le_bytes());
        fragment.push(index as u8);
        fragment.extend_from_slice(chunk);
        fragment
    }).collect()
}

pub struct FragmentReassembler {
    fragments: HashMap<u64, HashMap<u8, Vec<u8>>>,  // message_id -> (fragment_index -> data)
    total_fragments: HashMap<u64, u16>,              // message_id -> total count
}

impl FragmentReassembler {
    pub fn new() -> Self {
        Self {
            fragments: HashMap::new(),
            total_fragments: HashMap::new(),
        }
    }

    /// Add a fragment and return complete message if all fragments received
    pub fn add_fragment(&mut self, fragment: Vec<u8>) -> Result<Option<Vec<u8>>> {
        if fragment.len() < 11 {
            return Err(anyhow!("Fragment too small: {} bytes", fragment.len()));
        }

        let message_id = u64::from_le_bytes(fragment[0..8].try_into()?);
        let total_fragments = u16::from_le_bytes(fragment[8..10].try_into()?);
        let fragment_index = fragment[10];
        let data = fragment[11..].to_vec();

        // Store total fragments count
        self.total_fragments.insert(message_id, total_fragments);

        // Store this fragment
        self.fragments.entry(message_id)
            .or_insert_with(HashMap::new)
            .insert(fragment_index, data);

        // Check if all fragments received
        let received_count = self.fragments.get(&message_id).map(|f| f.len()).unwrap_or(0);
        if received_count == total_fragments as usize {
            // Reassemble in order
            let mut complete_data = Vec::new();
            for i in 0..total_fragments {
                if let Some(fragment_data) = self.fragments.get(&message_id).and_then(|f| f.get(&(i as u8))) {
                    complete_data.extend_from_slice(fragment_data);
                } else {
                    return Err(anyhow!("Missing fragment {} for message {}", i, message_id));
                }
            }

            // Clean up
            self.fragments.remove(&message_id);
            self.total_fragments.remove(&message_id);

            info!(" Reassembled message {} from {} fragments ({} bytes)", 
                message_id, total_fragments, complete_data.len());

            return Ok(Some(complete_data));
        }

        debug!(" Fragment {}/{} received for message {}", 
            received_count, total_fragments, message_id);

        Ok(None)
    }

    /// Clear stale fragments older than timeout
    pub fn cleanup_stale_fragments(&mut self, message_id: u64) {
        self.fragments.remove(&message_id);
        self.total_fragments.remove(&message_id);
        warn!("🗑️ Cleaned up stale fragments for message {}", message_id);
    }
}

pub fn calculate_optimal_mtu(requested_mtu: u16, max_mtu: u16) -> u16 {
    // BLE spec minimum is 23, maximum is typically 512
    const MIN_MTU: u16 = 23;
    const MAX_BLE_MTU: u16 = 512;

    let effective_max = max_mtu.min(MAX_BLE_MTU);
    requested_mtu.clamp(MIN_MTU, effective_max)
}

pub enum GattMessage {
    /// Raw data from GATT write (characteristic UUID, data)
    RawData(String, Vec<u8>),
    /// Mesh handshake (data, optional peripheral_id for macOS)
    MeshHandshake { data: Vec<u8>, peripheral_id: Option<String> },
    /// DHT bridge message
    DhtBridge(String),
    /// ZHTP relay query
    RelayQuery(Vec<u8>),
    /// Edge node headers request (lightweight sync)
    HeadersRequest {
        request_id: u64,
        start_height: u64,
        count: u32,
    },
    /// Edge node headers response
    HeadersResponse {
        request_id: u64,
        headers: Vec<BlockHeader>,
    },
    /// Edge node bootstrap proof request (ZK proof + recent headers)
    BootstrapProofRequest {
        request_id: u64,
        current_height: u64,
    },
    /// Edge node bootstrap proof response
    BootstrapProofResponse {
        request_id: u64,
        proof_data: Vec<u8>,  // Serialized ChainRecursiveProof
        proof_height: u64,
        headers: Vec<BlockHeader>,
    },
    /// Multi-fragment message header (for messages >512 bytes)
    FragmentHeader {
        message_id: u64,
        total_fragments: u16,
        fragment_index: u16,
        data: Vec<u8>,
    },
}

pub enum EdgeSyncMessage {
    HeadersRequest {
        request_id: u64,
        start_height: u64,
        count: u32,
    },
    HeadersResponse {
        request_id: u64,
        headers: Vec<BlockHeader>,
    },
    BootstrapProofRequest {
        request_id: u64,
        current_height: u64,
    },
    BootstrapProofResponse {
        request_id: u64,
        proof_data: Vec<u8>,
        proof_height: u64,
        headers: Vec<BlockHeader>,
    },
}

impl GattMessage {
    /// Parse raw GATT data into appropriate message type
    pub fn from_raw(char_uuid: &str, data: Vec<u8>) -> Self {
        // Try to parse based on characteristic UUID and data content
        match char_uuid {
            uuid if uuid.contains("6ba7b813") => {
                // Mesh data characteristic - check for edge sync messages
                if data.len() >= 11 && data.starts_with(&[0xED, 0x6E]) {
                    // Edge sync message marker "EDge Node"
                    if let Ok(edge_msg) = bincode::deserialize::<EdgeSyncMessage>(&data[2..]) {
                        match edge_msg {
                            EdgeSyncMessage::HeadersRequest { request_id, start_height, count } => {
                                GattMessage::HeadersRequest { request_id, start_height, count }
                            }
                            EdgeSyncMessage::HeadersResponse { request_id, headers } => {
                                GattMessage::HeadersResponse { request_id, headers }
                            }
                            EdgeSyncMessage::BootstrapProofRequest { request_id, current_height } => {
                                GattMessage::BootstrapProofRequest { request_id, current_height }
                            }
                            EdgeSyncMessage::BootstrapProofResponse { request_id, proof_data, proof_height, headers } => {
                                GattMessage::BootstrapProofResponse { request_id, proof_data, proof_height, headers }
                            }
                        }
                    } else {
                        // Failed to deserialize edge sync message, treat as raw data
                        GattMessage::RawData(uuid.to_string(), data.to_vec())
                    }
                }
                // Check for fragmented message
                else if data.len() >= 11 {
                    // Might be a fragment (has message_id + total_fragments + sequence)
                    GattMessage::FragmentHeader {
                        message_id: u64::from_le_bytes(data[0..8].try_into().unwrap_or_default()),
                        total_fragments: u16::from_le_bytes(data[8..10].try_into().unwrap_or_default()),
                        fragment_index: u16::from_le_bytes(data[10..12].try_into().unwrap_or_default()),
                        data: data[12..].to_vec(),
                    }
                } else if data.len() >= 8 {
                    // Regular mesh handshake
                    GattMessage::MeshHandshake { data, peripheral_id: None }
                } else if let Ok(text) = String::from_utf8(data.clone()) {
                    if text.starts_with("DHT:") {
                        GattMessage::DhtBridge(text)
                    } else {
                        GattMessage::RawData(uuid.to_string(), data)
                    }
                } else {
                    // Too short for any structured message, treat as raw data
                    GattMessage::RawData(uuid.to_string(), data.to_vec())
                }
            }
            _ => GattMessage::RawData(char_uuid.to_string(), data)
        }
    }

    /// Serialize edge sync message to bytes (with marker)
    pub fn serialize_edge_sync(msg: &EdgeSyncMessage) -> Result<Vec<u8>> {
        let mut data = vec![0xED, 0x6E]; // "EDge Node" marker
        let serialized = bincode::serialize(msg)
            .map_err(|e| anyhow!("Failed to serialize edge sync message: {}", e))?;
        data.extend_from_slice(&serialized);
        Ok(data)
    }
}

pub struct LinuxBluetoothOps {
    #[cfg(feature = "linux-dbus")]
    dbus_client: Option<BlueZDBusClient>,
}

impl LinuxBluetoothOps {
    /// Create new Linux Bluetooth operations handler
    pub fn new() -> Self {
        #[cfg(feature = "linux-dbus")]
        {
            info!(" Initializing Linux Bluetooth with D-Bus support");
            let dbus_client = match BlueZDBusClient::new() {
                Ok(client) => {
                    info!(" D-Bus BlueZ client initialized");
                    Some(client)
                }
                Err(e) => {
                    warn!(" Failed to initialize D-Bus client: {}", e);
                    warn!("   Falling back to CLI tools (bluetoothctl, hcitool)");
                    None
                }
            };

            Self { dbus_client }
        }

        #[cfg(not(feature = "linux-dbus"))]
        {
            info!(" Using CLI-only Bluetooth (no D-Bus support compiled in)");
            Self {}
        }
    }

    /// Start device discovery
    pub async fn start_discovery(&self) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.start_discovery();
        }

        // Fallback: CLI-based discovery
        self.cli_start_discovery().await
    }

    /// Stop device discovery
    pub async fn stop_discovery(&self) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.stop_discovery();
        }

        // Fallback: CLI stop (no-op, discovery times out naturally)
        Ok(())
    }

    /// Scan for ZHTP mesh peers
    pub async fn scan_mesh_peers(&self) -> Result<Vec<MeshPeer>> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return self.dbus_scan_mesh_peers(client).await;
        }

        // Fallback: CLI-based scanning
        self.cli_scan_mesh_peers().await
    }

    /// Connect to a device
    pub async fn connect_device(&self, address: &str) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.connect_device(address);
        }

        // Fallback: CLI connection
        self.cli_connect_device(address).await
    }

    /// Disconnect from a device
    pub async fn disconnect_device(&self, address: &str) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.disconnect_device(address);
        }

        // Fallback: CLI disconnection
        self.cli_disconnect_device(address).await
    }

    /// Read GATT characteristic
    pub async fn read_gatt_characteristic(&self, device_address: &str, char_uuid: &str) -> Result<Vec<u8>> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.read_gatt_characteristic(device_address, char_uuid);
        }

        // Fallback: CLI GATT read
        self.cli_read_gatt_characteristic(device_address, char_uuid).await
    }

    /// Write GATT characteristic
    pub async fn write_gatt_characteristic(&self, device_address: &str, char_uuid: &str, data: &[u8]) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.write_gatt_characteristic(device_address, char_uuid, data);
        }

        // Fallback: CLI GATT write
        self.cli_write_gatt_characteristic(device_address, char_uuid, data).await
    }

    /// Enable notifications on a characteristic
    pub async fn enable_notifications(&self, device_address: &str, char_uuid: &str) -> Result<()> {
        #[cfg(feature = "linux-dbus")]
        if let Some(ref client) = self.dbus_client {
            return client.enable_notifications(device_address, char_uuid);
        }

        // Fallback: CLI notifications (limited support)
        warn!(" GATT notifications not supported via CLI tools");
        Ok(())
    }

    // ========== D-Bus Implementation ==========

    #[cfg(feature = "linux-dbus")]
    async fn dbus_scan_mesh_peers(&self, client: &BlueZDBusClient) -> Result<Vec<MeshPeer>> {
        info!(" Scanning for ZHTP mesh peers via D-Bus");

        client.start_discovery()?;

        // Wait for discovery
        tokio::time::sleep(tokio::time::Duration::from_secs(10)).await;

        let devices = client.get_devices()?;
        client.stop_discovery()?;

        let mut peers = Vec::new();

        for device in devices {
            // Check if device name contains ZHTP or SOVNET
            if let Some(ref name) = device.name {
                if name.contains("ZHTP") || name.contains("SOVNET") {
                    let peer = MeshPeer {
                        peer_id: device.address.clone(),
                        address: device.address.clone(),
                        rssi: device.rssi as i16,
                        last_seen: std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        mesh_capable: true,
                        services: vec!["ZHTP-MESH".to_string()],
                        quantum_secure: true,
                    };
                    info!(" Found ZHTP mesh peer: {} ({})", peer.peer_id, device.address);
                    peers.push(peer);
                }
            }
        }

        info!(" Found {} ZHTP mesh peers via D-Bus", peers.len());
        Ok(peers)
    }

    // ========== CLI Fallback Implementation ==========

    async fn cli_start_discovery(&self) -> Result<()> {
        use std::process::Command;

        debug!(" Starting discovery via bluetoothctl");

        let _ = Command::new("bluetoothctl")
            .args(&["scan", "on"])
            .spawn();

        Ok(())
    }

    async fn cli_scan_mesh_peers(&self) -> Result<Vec<MeshPeer>> {
        use std::process::Command;

        info!(" Scanning for ZHTP mesh peers via CLI tools");

        // Start BLE scan
        let scan_output = Command::new("timeout")
            .args(&["10s", "hcitool", "lescan"])
            .output();

        let mut peers = Vec::new();

        if let Ok(result) = scan_output {
            let output = String::from_utf8_lossy(&result.stdout);
            for line in output.lines() {
                if let Some(peer) = Self::parse_hcitool_peer(line) {
                    peers.push(peer);
                }
            }
        }

        // Also scan using bluetoothctl for services
        let bt_scan = Command::new("timeout")
            .args(&["10s", "bluetoothctl", "scan", "on"])
            .output();

        if let Ok(bt_result) = bt_scan {
            let bt_output = String::from_utf8_lossy(&bt_result.stdout);
            for line in bt_output.lines() {
                if let Some(peer) = Self::parse_bluetoothctl_peer(line) {
                    peers.push(peer);
                }
            }
        }

        info!(" Found {} ZHTP mesh peers via CLI", peers.len());
        Ok(peers)
    }

    async fn cli_connect_device(&self, address: &str) -> Result<()> {
        use std::process::Command;

        info!(" Connecting to device {} via bluetoothctl", address);

        let connect_output = Command::new("bluetoothctl")
            .args(&["connect", address])
            .output()?;

        let output = String::from_utf8_lossy(&connect_output.stdout);
        if output.contains("Connection successful") {
            info!(" Connected to {}", address);
            Ok(())
        } else {
            Err(anyhow!("Failed to connect: {}", output))
        }
    }

    async fn cli_disconnect_device(&self, address: &str) -> Result<()> {
        use std::process::Command;

        debug!(" Disconnecting from device {} via bluetoothctl", address);

        let _ = Command::new("bluetoothctl")
            .args(&["disconnect", address])
            .output()?;

        Ok(())
    }

    async fn cli_read_gatt_characteristic(&self, device_address: &str, char_uuid: &str) -> Result<Vec<u8>> {
        use std::process::Command;

        debug!(" Reading GATT characteristic {} via gatttool", char_uuid);

        // Note: gatttool requires handle, not UUID - this is a limitation
        warn!(" gatttool requires characteristic handle, not UUID");
        warn!("   Production systems should use D-Bus for proper GATT operations");

        Err(anyhow!("GATT read via CLI requires characteristic handle"))
    }

    async fn cli_write_gatt_characteristic(&self, device_address: &str, char_uuid: &str, data: &[u8]) -> Result<()> {
        use std::process::Command;

        debug!(" Writing GATT characteristic {} via gatttool", char_uuid);

        // Note: gatttool requires handle, not UUID - this is a limitation
        warn!(" gatttool requires characteristic handle, not UUID");
        warn!("   Production systems should use D-Bus for proper GATT operations");

        Err(anyhow!("GATT write via CLI requires characteristic handle"))
    }

    // ========== Parsing Helpers ==========

    fn parse_hcitool_peer(line: &str) -> Option<MeshPeer> {
        // Parse hcitool lescan output: "AA:BB:CC:DD:EE:FF ZHTP-BYPASS"
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 && parts[0].len() == 17 && parts[1].contains("ZHTP") {
            Some(MeshPeer {
                peer_id: parts[0].to_string(),
                address: parts[0].to_string(),
                rssi: -60, // Default RSSI
                last_seen: std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                mesh_capable: true,
                services: vec!["ZHTP-MESH".to_string()],
                quantum_secure: true,
            })
        } else {
            None
        }
    }

    fn parse_bluetoothctl_peer(line: &str) -> Option<MeshPeer> {
        // Parse bluetoothctl format: "[CHG] Device AA:BB:CC:DD:EE:FF Name: ZHTP-BYPASS"
        if let Some(device_start) = line.find("Device ") {
            let device_part = &line[device_start + 7..];
            if let Some(space_pos) = device_part.find(' ') {
                let address = &device_part[..space_pos];
                if address.len() == 17 && line.contains("ZHTP") {
                    return Some(MeshPeer {
                        peer_id: address.to_string(),
                        address: address.to_string(),
                        rssi: -55,
                        last_seen: std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        mesh_capable: true,
                        services: vec!["ZHTP-MESH".to_string()],
                        quantum_secure: true,
                    });
                }
            }
        }
        None
    }
}

