        if output.status.success() {
            info!(" Linux: Notifications enabled for characteristic {}", char_uuid);
            Ok(())
        } else {
            Err(anyhow!("Failed to enable notifications: {}", 
                       String::from_utf8_lossy(&output.stderr)))
