pub struct UnifiedPeerId {
    /// Decentralized Identifier (DID) - Sovereign Identity
    /// Format: "did:zhtp:<hash>"
    pub did: String,

    /// Cryptographic public key for signature verification
    /// This is the peer's public key from their identity
    pub public_key: PublicKey,

    /// Canonical node identifier from lib-identity
    /// Derived as: Blake3(DID || device_name)
    pub node_id: NodeId,

    /// Device identifier (e.g., "laptop", "phone", "server-01")
    /// Used to distinguish multiple devices under same DID
    pub device_id: String,

    /// Optional display name for this peer
    pub display_name: Option<String>,

    /// Timestamp of identity creation (Unix timestamp)
    pub created_at: u64,

    /// CRITICAL-1 FIX: Bootstrap mode flag
    ///
    /// When true, this peer was created via legacy path (from_public_key_legacy)
    /// and has NOT been verified against the blockchain. Such peers:
    /// - CANNOT participate in consensus
    /// - CANNOT submit transactions
    /// - CANNOT access DHT content
    /// - CAN create blockchain identity
    /// - CAN query bootstrap nodes
    ///
    /// This flag MUST be checked before allowing security-critical operations.
    #[serde(default)]
    pub bootstrap_mode: bool,
}

impl UnifiedPeerId {
    /// Create UnifiedPeerId from ZhtpIdentity (primary constructor)
    ///
    /// This is the preferred way to create a UnifiedPeerId as it ensures
    /// all fields are properly populated from the authoritative identity source.
    ///
    /// # Security
    ///
    /// Validates all inputs to enforce trust boundary:
    /// - DID format (must start with "did:zhtp:")
    /// - Device ID entropy and format
    /// - Timestamp freshness
    /// - Cryptographic binding (NodeId matches DID + device)
    ///
    /// # Returns
    ///
    /// - `Ok(Self)` if all validations pass
    /// - `Err(...)` if any validation fails
    pub fn from_zhtp_identity(identity: &ZhtpIdentity) -> Result<Self> {
        // SECURITY FIX #3 (Finding #3): Validate at trust boundary

        // Validate DID format
        if !identity.did.starts_with("did:zhtp:") {
            return Err(anyhow!(
                "Invalid DID format: must start with 'did:zhtp:', got '{}'",
                &identity.did[..20.min(identity.did.len())]
            ));
        }

        // Validate device_id
        validate_device_id(&identity.primary_device)?;

        // Validate timestamp
        validate_peer_timestamp(identity.created_at)?;

        // Create instance with bootstrap_mode = false (verified identity)
        let peer = Self {
            did: identity.did.clone(),
            public_key: identity.public_key.clone(),
            node_id: identity.node_id.clone(),
            device_id: identity.primary_device.clone(),
            display_name: identity.metadata.get("display_name").cloned(),
            created_at: identity.created_at,
            bootstrap_mode: false, // CRITICAL-1: Verified identity, NOT in bootstrap mode
        };

        // Validate cryptographic binding
        peer.verify_node_id()?;

        Ok(peer)
    }

    /// Check if this peer is in bootstrap mode (unverified identity)
    ///
    /// # Security
    ///
    /// Peers in bootstrap mode were created via `from_public_key_legacy` and
    /// have NOT been verified against the blockchain. They should be denied
    /// access to security-critical operations.
    pub fn is_bootstrap_mode(&self) -> bool {
        self.bootstrap_mode
    }

    /// Check if this peer is verified (NOT in bootstrap mode)
    pub fn is_verified(&self) -> bool {
        !self.bootstrap_mode
    }

    /// Verify that node_id matches Blake3(DID || device_id) per lib-identity rules
    pub fn verify_node_id(&self) -> Result<()> {
        let expected = NodeId::from_did_device(&self.did, &self.device_id)?;
        if self.node_id.as_bytes() != expected.as_bytes() {
            return Err(anyhow!(
                "NodeId mismatch: expected {} but got {}",
                expected.to_hex(),
                self.node_id.to_hex()
            ));
        }
        Ok(())
    }

    /// Get a compact string representation for logging
    pub fn to_compact_string(&self) -> String {
        format!("{}@{}", self.device_id, &self.did[..std::cmp::min(20, self.did.len())])
    }

    /// Get the NodeId (canonical identifier)
    pub fn node_id(&self) -> &NodeId {
        &self.node_id
    }

    /// Get the PublicKey
    pub fn public_key(&self) -> &PublicKey {
        &self.public_key
    }

    /// Get the DID
    pub fn did(&self) -> &str {
        &self.did
    }

    /// Get the device ID
    pub fn device_id(&self) -> &str {
        &self.device_id
    }

    /// Create UnifiedPeerId from just a PublicKey (legacy compatibility)
    ///
    /// # DEPRECATED - Security Warning (CRITICAL-1 Fix)
    ///
    /// **⚠️ SECURITY WARNING:** This method bypasses blockchain identity verification.
    /// The resulting peer will be in `bootstrap_mode` and should be DENIED access to:
    /// - DHT content storage/retrieval
    /// - Transaction submission
    /// - Blockchain consensus participation
    /// - Mesh relay services
    ///
    /// The peer CAN:
    /// - Create blockchain identity via /api/v1/identity/create
    /// - Query bootstrap nodes
    ///
    /// **Prefer `from_zhtp_identity()` for all security-critical operations.**
    ///
    /// # Audit Trail (MEDIUM-2 Fix)
    ///
    /// This method logs a warning and increments a global counter for monitoring.
    /// Production deployments should alert on high usage of this path.
    ///
    /// # Device ID (MEDIUM-1 Fix)
    ///
    /// Generates a unique device_id using timestamp + random bytes to prevent
    /// collisions between legacy peers.
    #[deprecated(
        since = "0.2.0",
        note = "Use from_zhtp_identity() for verified peers. This method creates unverified bootstrap-mode peers."
    )]
    pub fn from_public_key_legacy(public_key: PublicKey) -> Self {
        // MEDIUM-2: Audit trail - log usage and increment counter
        LEGACY_PATH_USAGE_COUNT.fetch_add(1, Ordering::Relaxed);
        let usage_count = LEGACY_PATH_USAGE_COUNT.load(Ordering::Relaxed);

        warn!(
            "⚠️ SECURITY: from_public_key_legacy() called (usage #{}) - peer will be in bootstrap_mode",
            usage_count
        );

        // CRITICAL-1: Log caller context for security audit
        if usage_count > 100 {
            error!(
                "🚨 HIGH LEGACY PATH USAGE: {} calls to from_public_key_legacy(). \
                Consider migrating to from_zhtp_identity().",
                usage_count
            );
        }

        // Derive NodeId from public key hash
        let pk_hash = blake3::hash(&public_key.dilithium_pk);
        let node_id = NodeId::from_bytes(*pk_hash.as_bytes());

        // Create a derived DID (marked as unverified)
        let did = format!("did:zhtp:unverified:{}", hex::encode(&pk_hash.as_bytes()[..16]));

        // MEDIUM-1: Generate unique device_id with entropy
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let random_suffix = &pk_hash.as_bytes()[16..24];
        let device_id = format!(
            "bootstrap-{}-{}",
            timestamp % 1_000_000_000,
            hex::encode(random_suffix)
        );

        Self {
            did,
            public_key,
            node_id,
            device_id,
            display_name: None,
            created_at: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            bootstrap_mode: true, // CRITICAL-1: Mark as unverified bootstrap peer
        }
    }

    /// Create a verified UnifiedPeerId from PublicKey with blockchain verification
    ///
    /// This is the secure alternative to `from_public_key_legacy()`. It requires
    /// the caller to provide proof that the identity exists on the blockchain.
    ///
    /// # Arguments
    ///
    /// * `public_key` - The peer's cryptographic public key
    /// * `did` - The peer's DID (must be verified to exist on blockchain)
    /// * `device_id` - The device identifier for this peer
    ///
    /// # Security
    ///
    /// The caller is responsible for verifying the DID exists on the blockchain
    /// before calling this method. The resulting peer will have `bootstrap_mode = false`.
    pub fn from_verified_public_key(
        public_key: PublicKey,
        did: String,
        device_id: String,
    ) -> Result<Self> {
        // Validate DID format
        if !did.starts_with("did:zhtp:") {
            return Err(anyhow!(
                "Invalid DID format: must start with 'did:zhtp:', got '{}'",
                &did[..20.min(did.len())]
            ));
        }

        // Reject unverified DIDs
        if did.contains("unverified") {
            return Err(anyhow!(
                "Cannot create verified peer from unverified DID: {}",
                &did[..30.min(did.len())]
            ));
        }

        // Validate device_id
        validate_device_id(&device_id)?;

        // Derive NodeId from DID + device_id
        let node_id = NodeId::from_did_device(&did, &device_id)?;

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        Ok(Self {
            did,
            public_key,
            node_id,
            device_id,
            display_name: None,
            created_at: now,
            bootstrap_mode: false, // Verified peer
        })
    }
}

impl PartialEq for UnifiedPeerId {
    /// CRITICAL-2 FIX: Compare NodeId, PublicKey, AND DID
    ///
    /// Previously only compared NodeId, allowing collision attacks where an attacker
    /// could craft a NodeId that collides with a legitimate peer but has a different
    /// PublicKey, enabling impersonation.
    ///
    /// Now we compare all three cryptographic identifiers to ensure full identity match.
    fn eq(&self, other: &Self) -> bool {
        // CRITICAL-2: Check for collision attack - log if NodeId matches but other fields don't
        if self.node_id == other.node_id {
            if self.public_key.dilithium_pk != other.public_key.dilithium_pk {
                error!(
                    "🚨 COLLISION ATTACK DETECTED: NodeId {} matches but PublicKey differs! \
                    This may be an impersonation attempt.",
                    self.node_id.to_hex()
                );
                return false; // Reject collision
            }
            if self.did != other.did {
                error!(
                    "🚨 COLLISION ATTACK DETECTED: NodeId {} matches but DID differs! \
                    Self DID: {}, Other DID: {}",
                    self.node_id.to_hex(),
                    &self.did[..30.min(self.did.len())],
                    &other.did[..30.min(other.did.len())]
                );
                return false; // Reject collision
            }
            true
        } else {
            false
        }
    }
}

impl std::hash::Hash for UnifiedPeerId {
    /// CRITICAL-2 FIX: Hash includes NodeId, PublicKey, AND DID
    ///
    /// Previously only hashed NodeId, making collision attacks easier.
    /// Now we hash all three cryptographic identifiers.
    ///
    /// Note: This changes the hash value and may affect existing stored data.
    /// Migration may be required for persistent peer storage.
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        // Include all cryptographic identifiers in hash
        self.node_id.as_bytes().hash(state);
        self.public_key.dilithium_pk.hash(state);
        self.did.hash(state);
    }
}

impl fmt::Display for UnifiedPeerId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "UnifiedPeerId({})", self.to_compact_string())
    }
}

pub struct PeerMapperConfig {
    /// Maximum total peers in mapper (DoS protection)
    pub max_peers: usize,
    /// Maximum devices per DID (Sybil attack protection)
    pub max_devices_per_did: usize,
}

impl Default for PeerMapperConfig {
    fn default() -> Self {
        Self {
            max_peers: 100_000,         // 100K peers max
            max_devices_per_did: 10,    // 10 devices per identity
        }
    }
}

struct MapperState {
    /// Main storage: NodeId → Arc<UnifiedPeerId>
    by_node_id: HashMap<NodeId, Arc<UnifiedPeerId>>,

    /// Index: PublicKey → NodeId (for fast lookup)
    by_public_key: HashMap<PublicKey, NodeId>,

    /// Index: DID → Vec<NodeId> (one DID can have multiple devices)
    by_did: HashMap<String, Vec<NodeId>>,
}

impl MapperState {
    fn new() -> Self {
        Self {
            by_node_id: HashMap::new(),
            by_public_key: HashMap::new(),
            by_did: HashMap::new(),
        }
    }
}

pub struct PeerIdMapper {
    /// CRITICAL FIX C3: Single atomic state with parking_lot::RwLock
    state: Arc<RwLock<MapperState>>,

    /// Configuration limits
    config: PeerMapperConfig,
}

impl PeerIdMapper {
    /// Create a new empty peer ID mapper with default config
    pub fn new() -> Self {
        Self::with_config(PeerMapperConfig::default())
    }

    /// Create a new peer ID mapper with custom config
    pub fn with_config(config: PeerMapperConfig) -> Self {
        Self {
            state: Arc::new(RwLock::new(MapperState::new())),
            config,
        }
    }

    /// CRITICAL FIX C3: Atomic registration with single lock
    ///
    /// Register a peer in the mapper (creates all indexes)
    ///
    /// # Security
    ///
    /// - **Atomic**: Entire operation under single write lock (no TOCTOU)
    /// - **Verified**: Cryptographic NodeId binding checked
    /// - **Bounded**: Memory limits enforced
    /// - **Audited**: Security events logged
    ///
    /// # Implementation
    ///
    /// The entire registration is atomic:
    /// 1. Acquire write lock
    /// 2. Check max_peers limit
    /// 3. Check duplicate registration
    /// 4. Check max_devices_per_did limit
    /// 5. Verify cryptographic binding
    /// 6. Insert into all indexes
    /// 7. Release lock
    ///
    /// No race condition window between steps 3-6.
    ///
    /// # Returns
    ///
    /// - `Ok(())` if registration succeeded
    /// - `Err(...)` if verification failed, limits exceeded, or already registered
    pub fn register(&self, peer: UnifiedPeerId) -> Result<()> {
        // Verify cryptographic binding (outside lock - pure computation)
        peer.verify_node_id()?;

        // Validate timestamp (outside lock - pure computation)
        validate_peer_timestamp(peer.created_at)?;

        // Validate device_id entropy (outside lock - pure computation)
        validate_device_id(&peer.device_id)?;

        let node_id = peer.node_id.clone();
        let public_key = peer.public_key.clone();
        let did = peer.did.clone();

        // CRITICAL FIX C3: SINGLE ATOMIC LOCK for entire registration
        // This prevents the TOCTOU race condition
        let mut state = self.state.write();

        // Check 1: max_peers limit (DoS protection)
        if state.by_node_id.len() >= self.config.max_peers {
            warn!(
                "Peer registration rejected: max_peers limit reached ({}/{})",
                state.by_node_id.len(),
                self.config.max_peers
            );
            return Err(anyhow!(
                "Peer limit reached: {} peers (max: {})",
                state.by_node_id.len(),
                self.config.max_peers
            ));
        }

        // Check 2: Duplicate registration (idempotency)
        if state.by_node_id.contains_key(&node_id) {
            warn!(
                "Duplicate peer registration attempt: {}",
                node_id.to_hex()
            );
            return Err(anyhow!("Peer already registered: {}", node_id.to_hex()));
        }

        // Check 3: max_devices_per_did limit (Sybil protection)
        // CRITICAL: This check MUST be under the same lock as the insert
        let device_count = state.by_did.get(&did).map(|v| v.len()).unwrap_or(0);
        if device_count >= self.config.max_devices_per_did {
            warn!(
                "Device limit exceeded for DID {}: {}/{} devices",
                &did[..20.min(did.len())],
                device_count,
                self.config.max_devices_per_did
            );
            return Err(anyhow!(
                "Device limit reached for DID {}: {} devices (max: {})",
                &did[..20.min(did.len())],
                device_count,
                self.config.max_devices_per_did
            ));
        }

        // All checks passed - insert atomically into all indexes
        let peer_arc = Arc::new(peer);

        // Insert into main storage
        state.by_node_id.insert(node_id.clone(), peer_arc.clone());

        // Insert into PublicKey index
        state.by_public_key.insert(public_key, node_id.clone());

        // Insert into DID index (supports multi-device)
        state.by_did.entry(did.clone()).or_insert_with(Vec::new).push(node_id.clone());

        // Audit log successful registration
        info!(
            "Peer registered: {} (DID: {}, devices: {})",
            node_id.to_hex(),
            &did[..20.min(did.len())],
            state.by_did.get(&did).map(|v| v.len()).unwrap_or(0)
        );

        // Lock released here - entire operation was atomic
        Ok(())
    }

    /// CRITICAL FIX C3: Atomic unregister with single lock
    ///
    /// Remove a peer from the mapper (cleans up all indexes)
    ///
    /// # Security
    ///
    /// - Atomic unregister (all-or-nothing, no partial state)
    /// - Single lock acquisition (prevents race conditions)
    pub fn unregister(&self, node_id: &NodeId) -> Option<Arc<UnifiedPeerId>> {
        // CRITICAL FIX C3: Single atomic lock for entire unregister
        let mut state = self.state.write();

        // Remove from main map
        let peer = state.by_node_id.remove(node_id)?;

        // Remove PublicKey → NodeId index
        state.by_public_key.remove(&peer.public_key);

        // Remove from DID → Vec<NodeId> index
        if let Some(nodes) = state.by_did.get_mut(&peer.did) {
            nodes.retain(|n| n != node_id);
            if nodes.is_empty() {
                state.by_did.remove(&peer.did);
            }
        }

        // Audit log
        info!("Peer unregistered: {}", node_id.to_hex());

        Some(peer)
    }

    /// Lookup peer by NodeId (canonical identifier)
    pub fn lookup_by_node_id(&self, node_id: &NodeId) -> Option<UnifiedPeerId> {
        let state = self.state.read();
        state.by_node_id.get(node_id).map(|arc| (**arc).clone())
    }

    /// Lookup peer by PublicKey
    pub fn lookup_by_public_key(&self, public_key: &PublicKey) -> Option<UnifiedPeerId> {
        let state = self.state.read();
        let node_id = state.by_public_key.get(public_key).cloned()?;
        state.by_node_id.get(&node_id).map(|arc| (**arc).clone())
    }

    /// Lookup all peers by DID (returns all devices for this identity)
    pub fn lookup_by_did(&self, did: &str) -> Vec<UnifiedPeerId> {
        let state = self.state.read();

        match state.by_did.get(did) {
            Some(ids) => {
                ids.iter()
                    .filter_map(|id| state.by_node_id.get(id).map(|arc| (**arc).clone()))
                    .collect()
            }
            None => Vec::new(),
        }
    }

    /// Get all registered peers
    pub fn all_peers(&self) -> Vec<UnifiedPeerId> {
        let state = self.state.read();
        state.by_node_id.values().map(|arc| (**arc).clone()).collect()
    }

    /// Get total peer count
    pub fn peer_count(&self) -> usize {
        let state = self.state.read();
        state.by_node_id.len()
    }

    /// Clear all mappings
    pub fn clear(&self) {
        let mut state = self.state.write();
        state.by_node_id.clear();
        state.by_public_key.clear();
        state.by_did.clear();
    }

    /// Check if a peer is registered by NodeId
    pub fn contains_node_id(&self, node_id: &NodeId) -> bool {
        let state = self.state.read();
        state.by_node_id.contains_key(node_id)
    }

    /// Check if a peer is registered by PublicKey
    pub fn contains_public_key(&self, public_key: &PublicKey) -> bool {
        let state = self.state.read();
        state.by_public_key.contains_key(public_key)
    }

    /// Check if any peers are registered for a DID
    pub fn contains_did(&self, did: &str) -> bool {
        let state = self.state.read();
        state.by_did.contains_key(did)
    }
}

impl Default for PeerIdMapper {
    fn default() -> Self {
        Self::new()
    }
}

pub struct BlockchainHandshakeContext {
    /// Chain identifier (prevents cross-chain replay attacks)
    pub chain_id: String,

    /// Current block hash (detects chain forks)
    pub block_hash: Hash,

    /// Parent block hash (P1-2 FIX: enables fork detection across heights)
    pub parent_hash: Option<Hash>,

    /// Recent block hashes (P1-2 FIX: for common ancestor verification)
    /// Last N block hashes for detecting divergence
    pub recent_block_hashes: Vec<Hash>,

    /// Current epoch number (consensus round alignment)
    pub epoch: u64,

    /// Current block height
    pub height: u64,

    /// Validator stake (if peer is a validator)
    pub validator_stake: Option<u64>,

    /// Genesis hash (ensures same network)
    pub genesis_hash: String,

    /// Validator set hash (ensures compatible validator set)
    pub validator_set_hash: String,
}

impl BlockchainHandshakeContext {
    /// Create blockchain context from chain summary and latest block
    ///
    /// # Arguments
    /// * `summary` - Chain summary with validator and network info
    /// * `latest_block_hash` - Hash of the latest block (from blockchain.latest_block())
    /// * `current_epoch` - Current consensus epoch number
    pub fn from_chain_state(
        summary: &ChainSummary,
        latest_block_hash: Hash,
        current_epoch: u64,
    ) -> Self {
        Self {
            // SECURITY (P0-2 FIX): Use full genesis hash for chain ID (no truncation)
            // Prevents collision attacks and ensures 256-bit security
            chain_id: summary.genesis_hash.clone(),
            block_hash: latest_block_hash,
            parent_hash: None, // Set via with_parent_hash()
            recent_block_hashes: Vec::new(), // Set via with_recent_hashes()
            epoch: current_epoch,
            height: summary.height,
            validator_stake: None, // Will be set via with_validator_stake()
            genesis_hash: summary.genesis_hash.clone(),
            validator_set_hash: summary.validator_set_hash.clone(),
        }
    }

    /// Create blockchain context directly (for testing or custom scenarios)
    pub fn new(
        chain_id: String,
        block_hash: Hash,
        epoch: u64,
        height: u64,
        genesis_hash: String,
        validator_set_hash: String,
    ) -> Self {
        Self {
            chain_id,
            block_hash,
            parent_hash: None,
            recent_block_hashes: Vec::new(),
            epoch,
            height,
            validator_stake: None,
            genesis_hash,
            validator_set_hash,
        }
    }

    /// Create context with validator stake information
    pub fn with_validator_stake(mut self, stake: u64) -> Self {
        self.validator_stake = Some(stake);
        self
    }

    /// Add parent hash for fork detection (P1-2 FIX)
    pub fn with_parent_hash(mut self, parent: Hash) -> Self {
        self.parent_hash = Some(parent);
        self
    }

    /// Add recent block hashes for common ancestor verification (P1-2 FIX)
    pub fn with_recent_hashes(mut self, hashes: Vec<Hash>) -> Self {
        self.recent_block_hashes = hashes;
        self
    }
}

pub enum PeerTier {
    /// Verified validator with on-chain stake
    Validator,

    /// Node with stake but not actively validating
    StakedNode,

    /// Unverified peer (default for new connections)
    Unverified,
}

impl PeerTier {
    /// Get minimum stake required for this tier
    pub fn min_stake(&self) -> u64 {
        match self {
            PeerTier::Validator => 1_000 * 1_000_000, // 1000 ZHTP minimum for validators
            PeerTier::StakedNode => 100 * 1_000_000,   // 100 ZHTP minimum for staked nodes
            PeerTier::Unverified => 0,
        }
    }

    /// Check if this tier can participate in consensus
    pub fn can_validate(&self) -> bool {
        matches!(self, PeerTier::Validator)
    }

    /// Check if this tier has enhanced network privileges
    pub fn has_enhanced_privileges(&self) -> bool {
        matches!(self, PeerTier::Validator | PeerTier::StakedNode)
    }

    /// Get trust score for this tier (0.0 - 1.0)
    pub fn trust_score(&self) -> f64 {
        match self {
            PeerTier::Validator => 1.0,
            PeerTier::StakedNode => 0.7,
            PeerTier::Unverified => 0.3,
        }
    }
}

impl Default for PeerTier {
    fn default() -> Self {
        PeerTier::Unverified
    }
}

pub struct BlockchainVerificationResult {
    /// Whether verification succeeded
    pub verified: bool,

    /// Determined peer tier
    pub peer_tier: PeerTier,

    /// Verification details/errors
    pub details: String,

    /// Whether chain fork was detected
    pub fork_detected: bool,

    /// Whether epoch mismatch was detected
    pub epoch_mismatch: bool,
}

impl BlockchainVerificationResult {
    /// Create a successful verification result
    pub fn success(peer_tier: PeerTier, details: String) -> Self {
        Self {
            verified: true,
            peer_tier,
            details,
            fork_detected: false,
            epoch_mismatch: false,
        }
    }

    /// Create a failed verification result
    pub fn failure(reason: String) -> Self {
        Self {
            verified: false,
            peer_tier: PeerTier::Unverified,
            details: reason,
            fork_detected: false,
            epoch_mismatch: false,
        }
    }

    /// Create a fork detection result
    pub fn fork_detected(details: String) -> Self {
        Self {
            verified: false,
            peer_tier: PeerTier::Unverified,
            details,
            fork_detected: true,
            epoch_mismatch: false,
        }
    }

    /// Create an epoch mismatch result
    pub fn epoch_mismatch(details: String) -> Self {
        Self {
            verified: false,
            peer_tier: PeerTier::Unverified,
            details,
            fork_detected: false,
            epoch_mismatch: true,
        }
    }
}

pub struct StakeEntry {
    /// Stake amount in ZHTP
    pub amount: u64,

    /// Epoch when this stake was last updated
    pub epoch: u64,

    /// Timestamp when this stake was last updated (Unix seconds)
    pub updated_at: u64,
}

impl StakeEntry {
    /// Create a new stake entry
    pub fn new(amount: u64, epoch: u64) -> Self {
        Self {
            amount,
            epoch,
            updated_at: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
        }
    }

    /// Check if this entry is stale compared to another
    pub fn is_stale_compared_to(&self, other: &StakeEntry) -> bool {
        self.epoch < other.epoch ||
        (self.epoch == other.epoch && self.updated_at < other.updated_at)
    }
}

pub struct BlockchainHandshakeVerifier {
    /// Local blockchain context
    local_context: BlockchainHandshakeContext,

    /// Validator stake table (identity_hash -> versioned stake entry)
    /// SECURITY (P0-1 FIX): Thread-safe with RwLock to prevent race conditions
    /// ENHANCEMENT: Now uses StakeEntry for timestamp/epoch tracking
    validator_stakes: Arc<RwLock<std::collections::HashMap<Hash, StakeEntry>>>,

    /// Maximum allowed epoch difference (prevents time-travel attacks)
    max_epoch_diff: u64,

    /// Maximum allowed height difference for same epoch
    max_height_diff: u64,

    /// Optional rate limiter for DoS protection
    /// ENHANCEMENT: Prevents verification spam attacks
    rate_limiter: Option<super::RateLimiter>,
}

impl BlockchainHandshakeVerifier {
    /// Create a new blockchain handshake verifier
    pub fn new(local_context: BlockchainHandshakeContext) -> Self {
        Self {
            local_context,
            validator_stakes: Arc::new(RwLock::new(std::collections::HashMap::new())),
            max_epoch_diff: 5,      // Allow 5 epoch difference
            max_height_diff: 100,   // Allow 100 block difference
            rate_limiter: None,     // No rate limiting by default
        }
    }

    /// Add rate limiting to prevent DoS attacks
    /// ENHANCEMENT: Integrates with UHP rate limiter for verification spam protection
    pub fn with_rate_limiting(mut self, rate_limiter: super::RateLimiter) -> Self {
        self.rate_limiter = Some(rate_limiter);
        self
    }

    /// Update validator stakes from on-chain state
    /// SECURITY (P0-1 FIX): Thread-safe update with write lock
    /// ENHANCEMENT: Uses versioned StakeEntry with epoch tracking
    pub fn update_validator_stakes(&self, stakes: std::collections::HashMap<Hash, u64>, epoch: u64) {
        let mut stakes_guard = self.validator_stakes.write().unwrap();

        // Convert to StakeEntry and only update if newer
        for (identity, amount) in stakes {
            let new_entry = StakeEntry::new(amount, epoch);

            // Only update if newer than existing entry
            if let Some(existing) = stakes_guard.get(&identity) {
                if !existing.is_stale_compared_to(&new_entry) {
                    continue; // Skip stale updates
                }
            }

            stakes_guard.insert(identity, new_entry);
        }
    }

    /// Add a single validator stake
    /// SECURITY (P0-1 FIX): Thread-safe insert with write lock
    /// ENHANCEMENT: Uses versioned StakeEntry with epoch tracking
    pub fn add_validator_stake(&self, identity: Hash, stake: u64, epoch: u64) {
        let mut stakes_guard = self.validator_stakes.write().unwrap();
        let new_entry = StakeEntry::new(stake, epoch);

        // Only update if newer than existing entry
        if let Some(existing) = stakes_guard.get(&identity) {
            if !existing.is_stale_compared_to(&new_entry) {
                return; // Skip stale update
            }
        }

        stakes_guard.insert(identity, new_entry);
    }

    /// Verify peer blockchain context and determine tier
    ///
    /// # Security Checks
    ///
    /// 1. **Rate Limiting**: Prevents verification spam DoS (if enabled)
    /// 2. **Chain ID Verification**: Prevents cross-chain replay attacks
    /// 3. **Genesis Hash Match**: Ensures same network
    /// 4. **Block Hash Verification**: Detects chain forks
    /// 5. **Epoch Alignment**: Prevents time-travel attacks
    /// 6. **Validator Stake Verification**: Authenticates validators
    ///
    /// # Parameters
    ///
    /// - `peer_context`: Blockchain context from peer
    /// - `peer_identity`: Optional peer identity hash for stake verification
    /// - `peer_ip`: Optional peer IP address for rate limiting
    ///
    /// # Returns
    ///
    /// - `BlockchainVerificationResult` with verification status and peer tier
    pub fn verify_peer(
        &self,
        peer_context: &BlockchainHandshakeContext,
        peer_identity: Option<&Hash>,
        peer_ip: Option<std::net::IpAddr>,
    ) -> Result<BlockchainVerificationResult> {
        // 0. Rate limiting check (if enabled)
        // ENHANCEMENT: Prevents verification spam DoS attacks
        if let Some(ref rate_limiter) = self.rate_limiter {
            if let Some(ip) = peer_ip {
                if let Err(e) = rate_limiter.check_handshake(ip) {
                    tracing::warn!(
                        security_event = "rate_limit_exceeded",
                        peer_ip = ?ip,
                        error = ?e,
                    );
                    return Ok(BlockchainVerificationResult::failure(
                        "Rate limit exceeded".to_string()
                    ));
                }
            }
        }
        // 1. Verify chain_id matches (prevents cross-chain replay)
        if self.local_context.chain_id != peer_context.chain_id {
            return Ok(BlockchainVerificationResult::failure(
                format!(
                    "Chain ID mismatch: local={}, peer={}",
                    self.local_context.chain_id,
                    peer_context.chain_id
                )
            ));
        }

        // 2. Verify genesis hash matches (same network)
        // SECURITY (P1-1 FIX): Constant-time comparison to prevent timing side-channels
        if self.local_context.genesis_hash.len() != peer_context.genesis_hash.len()
            || self.local_context.genesis_hash.as_bytes().ct_eq(peer_context.genesis_hash.as_bytes()).unwrap_u8() == 0 {
            return Ok(BlockchainVerificationResult::failure(
                "Genesis hash mismatch".to_string()
            ));
        }

        // 3. Detect chain fork via block hash mismatch
        // If peers are at the same height but have different block hashes, it's a fork
        if self.local_context.height == peer_context.height 
            && self.local_context.block_hash != peer_context.block_hash {
            return Ok(BlockchainVerificationResult::fork_detected(
                format!(
                    "Fork detected at height {}: local_hash={:?}, peer_hash={:?}",
                    self.local_context.height,
                    self.local_context.block_hash,
                    peer_context.block_hash
                )
            ));
        }

        // 4. Verify epoch alignment (prevents time-travel attacks)
        // SECURITY (P0-4 FIX): Asymmetric epoch check
        // Reject peers from the future (time-travel attack)
        if peer_context.epoch > self.local_context.epoch + 1 {
            return Ok(BlockchainVerificationResult::epoch_mismatch(
                format!(
                    "Peer epoch too far in future: local={}, peer={}",
                    self.local_context.epoch,
                    peer_context.epoch
                )
            ));
        }

        // Allow historical peers (sync scenarios) up to max_epoch_diff
        if self.local_context.epoch > peer_context.epoch + self.max_epoch_diff {
            return Ok(BlockchainVerificationResult::epoch_mismatch(
                format!(
                    "Peer epoch too far in past: local={}, peer={}, diff={}",
                    self.local_context.epoch,
                    peer_context.epoch,
                    self.local_context.epoch - peer_context.epoch
                )
            ));
        }

        // 5. Verify height alignment
        // SECURITY (P2-1 FIX): Reject (not just warn) excessive height difference
        let height_diff = if self.local_context.height > peer_context.height {
            self.local_context.height - peer_context.height
        } else {
            peer_context.height - self.local_context.height
        };

        if height_diff > self.max_height_diff {
            return Ok(BlockchainVerificationResult::failure(
                format!(
                    "Height difference exceeds safety threshold: local={}, peer={}, diff={}",
                    self.local_context.height,
                    peer_context.height,
                    height_diff
                )
            ));
        }

        // 6. Verify validator set compatibility
        // SECURITY (P0-3 FIX): Enforce validator set verification
        if !self.verify_validator_set(peer_context)? {
            return Ok(BlockchainVerificationResult::failure(
                "Incompatible validator set".to_string()
            ));
        }

        // 7. Determine peer tier based on stake
        // SECURITY (P0-1 FIX): Thread-safe read access to validator stakes
        // ENHANCEMENT: Now uses StakeEntry with versioning
        let peer_tier = if let Some(stake) = peer_context.validator_stake {
            // Peer claims to be a validator - verify against on-chain stake table
            if let Some(peer_id) = peer_identity {
                let stakes_guard = self.validator_stakes.read().unwrap();
                match stakes_guard.get(peer_id) {
                    Some(stake_entry) => {
                        let on_chain_stake = stake_entry.amount;

                        // Verify claimed stake matches on-chain stake
                        if stake != on_chain_stake {
                            // SECURITY (P1-3 FIX): Sanitize error message
                            tracing::warn!(
                                security_event = "stake_mismatch",
                                peer_id = ?peer_id,
                                claimed = stake,
                                actual = on_chain_stake,
                                stake_epoch = stake_entry.epoch,
                                stake_updated_at = stake_entry.updated_at,
                            );
                            return Ok(BlockchainVerificationResult::failure(
                                "Validator authentication failed".to_string()
                            ));
                        }

                        // Determine tier based on stake amount
                        if stake >= PeerTier::Validator.min_stake() {
                            PeerTier::Validator
                        } else if stake >= PeerTier::StakedNode.min_stake() {
                            PeerTier::StakedNode
                        } else {
                            PeerTier::Unverified
                        }
                    }
                    None => {
                        // Peer claims stake but not in on-chain table
                        // SECURITY (P1-3 FIX): Sanitize error message
                        tracing::warn!(
                            security_event = "validator_not_found",
                            peer_id = ?peer_id,
                        );
                        return Ok(BlockchainVerificationResult::failure(
                            "Validator authentication failed".to_string()
                        ));
                    }
                }
            } else {
                // No identity provided - cannot verify stake
                PeerTier::Unverified
            }
        } else {
            // Peer does not claim validator status
            PeerTier::Unverified
        };

        Ok(BlockchainVerificationResult::success(
            peer_tier,
            format!(
                "Verified peer: tier={:?}, height_diff={}",
                peer_tier,
                height_diff
            )
        ))
    }

    /// Verify validator set compatibility
    ///
    /// Checks if the peer's validator set is compatible with ours.
    /// This is important for consensus participation.
    pub fn verify_validator_set(&self, peer_context: &BlockchainHandshakeContext) -> Result<bool> {
        // If validator set hashes match, sets are compatible
        if self.local_context.validator_set_hash == peer_context.validator_set_hash {
            return Ok(true);
        }

        // If hashes differ but we're not too far apart in height, allow with warning
        let height_diff = if self.local_context.height > peer_context.height {
            self.local_context.height - peer_context.height
        } else {
            peer_context.height - self.local_context.height
        };

        if height_diff <= self.max_height_diff {
            tracing::warn!(
                "Validator set hash mismatch but within acceptable height difference: {}",
                height_diff
            );
            return Ok(true);
        }

        Ok(false)
    }

    /// Update local blockchain context (called when chain advances)
    pub fn update_local_context(&mut self, new_context: BlockchainHandshakeContext) {
        self.local_context = new_context;
    }

    /// Get current local blockchain context
    pub fn local_context(&self) -> &BlockchainHandshakeContext {
        &self.local_context
    }
}

pub enum HandshakeIoError {
    /// Network I/O error
    Io(std::io::Error),

    /// Message serialization/deserialization error
    Serialization(String),

    /// Signature verification failed
    InvalidSignature,

    /// Replay attack detected (duplicate nonce)
    ReplayDetected,

    /// Nonce missing or invalid
    NonceMissing,

    /// Messages received out of order or with mismatched nonces
    InvalidMessageOrder,

    /// Unexpected message type
    UnexpectedMessageType {
        expected: String,
        got: String,
    },

    /// Protocol error
    Protocol(String),

    /// Identity missing required fields
    IdentityError(String),
}

impl std::fmt::Display for HandshakeIoError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Io(e) => write!(f, "I/O error: {}", e),
            Self::Serialization(s) => write!(f, "Serialization error: {}", s),
            Self::InvalidSignature => write!(f, "Invalid signature"),
            Self::ReplayDetected => write!(f, "Replay attack detected"),
            Self::NonceMissing => write!(f, "Invalid nonce"),
            Self::InvalidMessageOrder => write!(f, "Invalid message order or nonce mismatch"),
            Self::UnexpectedMessageType { expected, got } => {
                write!(f, "Unexpected message type: expected {}, got {}", expected, got)
            }
            Self::Protocol(s) => write!(f, "Protocol error: {}", s),
            Self::IdentityError(s) => write!(f, "Identity error: {}", s),
        }
    }
}

impl From<std::io::Error> for HandshakeIoError {
    fn from(err: std::io::Error) -> Self {
        HandshakeIoError::Io(err)
    }
}

pub struct NonceTracker<'a> {
    cache: &'a super::NonceCache,
}

fn validate_protocol_version(version: u8) -> Result<()> {
    if version < MIN_SUPPORTED_VERSION || version > MAX_SUPPORTED_VERSION {
        return Err(anyhow!(
            "Unsupported protocol version: {} (supported: {}-{})",
            version,
            MIN_SUPPORTED_VERSION,
            MAX_SUPPORTED_VERSION
        ));
    }
    Ok(())
}

pub struct HandshakeContext {
    /// Nonce cache for replay attack prevention
