pub struct HandshakeResult {
    /// Peer's verified node identity (public fields only)
    pub peer_identity: NodeIdentity,

    /// Negotiated session capabilities
    pub capabilities: NegotiatedCapabilities,

    /// Session key for symmetric encryption (derived from handshake)
    pub session_key: [u8; 32],

    /// Session identifier
    pub session_id: [u8; 16],

    /// Timestamp when handshake completed
    pub completed_at: u64,
}

impl HandshakeResult {
    /// Create a new handshake result
    ///
    /// **VULN-003 FIX:** Uses ClientHello timestamp for deterministic session key derivation.
    /// Both client and server MUST use the same timestamp (from ClientHello) to derive
    /// identical session keys.
    ///
    /// # Arguments
    /// * `client_hello_timestamp` - Timestamp from ClientHello message (MUST be same on both sides)
    pub fn new(
        peer_identity: NodeIdentity,
        capabilities: NegotiatedCapabilities,
        client_nonce: &[u8; 32],
        server_nonce: &[u8; 32],
        client_did: &str,
        server_did: &str,
        client_hello_timestamp: u64,
    ) -> Result<Self> {
        // Build session context for HKDF domain separation
        // CRITICAL: Use ClientHello timestamp (deterministic, agreed by both parties)
        let context = SessionContext {
            protocol_version: UHP_VERSION as u32,
            client_did: client_did.to_string(),
            server_did: server_did.to_string(),
            timestamp: client_hello_timestamp, // VULN-003 FIX: Deterministic timestamp
        };

        // Derive session key using HKDF (NIST SP 800-108 compliant)
        let session_key = derive_session_key_hkdf(client_nonce, server_nonce, &context)?;

        // Generate session ID from first 16 bytes of session key
        let mut session_id = [0u8; 16];
        session_id.copy_from_slice(&session_key[..16]);

        Ok(Self {
            peer_identity,
            capabilities,
            session_key,
            session_id,
            completed_at: current_timestamp()?, // Completion time (for logging only)
        })
    }
}

pub enum HandshakeError {
    /// NodeId verification failed
    NodeIdMismatch {
        claimed: String,
        expected: String,
        did: String,
        device: String,
    },

    /// Signature verification failed
    InvalidSignature { peer: String },

    /// Protocol version not supported
    UnsupportedVersion {
        version: u8,
        min: u8,
        max: u8,
    },

    /// No compatible capabilities found
    IncompatibleCapabilities {
        client_caps: String,
        server_caps: String,
    },

    /// Handshake timeout
    Timeout { seconds: u64 },

    /// Challenge failed (provisional handshake)
    ChallengeFailed { reason: String },

    /// Connection closed during handshake
    ConnectionClosed { stage: String },

    /// Invalid message format
    InvalidMessage { reason: String },

    /// Replay attack detected
    ReplayDetected { timestamp: u64 },

    /// Internal error
    Internal { message: String },
}

pub struct HandshakeErrorMessage {
    /// Error code
    pub code: String,

    /// Human-readable error message
    pub message: String,

    /// Whether the connection should be closed
    pub fatal: bool,
}

impl std::fmt::Display for HandshakeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            HandshakeError::NodeIdMismatch { claimed, expected, did, device } => {
                write!(f, "NodeId mismatch: claimed {} but expected {} from DID '{}' + device '{}'", claimed, expected, did, device)
            }
            HandshakeError::InvalidSignature { peer } => write!(f, "Invalid signature from peer {}", peer),
            HandshakeError::UnsupportedVersion { version, min, max } => {
                write!(f, "Unsupported protocol version {} (supported: {}-{})", version, min, max)
            }
            HandshakeError::IncompatibleCapabilities { client_caps, server_caps } => {
                write!(f, "No compatible capabilities: client supports {}, server supports {}", client_caps, server_caps)
            }
            HandshakeError::Timeout { seconds } => write!(f, "Handshake timeout after {} seconds", seconds),
            HandshakeError::ChallengeFailed { reason } => write!(f, "Challenge verification failed: {}", reason),
            HandshakeError::ConnectionClosed { stage } => write!(f, "Connection closed during handshake at stage {}", stage),
            HandshakeError::InvalidMessage { reason } => write!(f, "Invalid handshake message: {}", reason),
            HandshakeError::ReplayDetected { timestamp } => write!(f, "Replay attack detected: timestamp {} is too old", timestamp),
            HandshakeError::Internal { message } => write!(f, "Internal handshake error: {}", message),
        }
    }
}

impl From<HandshakeError> for HandshakeErrorMessage {
    fn from(err: HandshakeError) -> Self {
        let code = match &err {
            HandshakeError::NodeIdMismatch { .. } => "NODE_ID_MISMATCH",
            HandshakeError::InvalidSignature { .. } => "INVALID_SIGNATURE",
            HandshakeError::UnsupportedVersion { .. } => "UNSUPPORTED_VERSION",
            HandshakeError::IncompatibleCapabilities { .. } => "INCOMPATIBLE_CAPABILITIES",
            HandshakeError::Timeout { .. } => "TIMEOUT",
            HandshakeError::ChallengeFailed { .. } => "CHALLENGE_FAILED",
            HandshakeError::ConnectionClosed { .. } => "CONNECTION_CLOSED",
            HandshakeError::InvalidMessage { .. } => "INVALID_MESSAGE",
            HandshakeError::ReplayDetected { .. } => "REPLAY_DETECTED",
            HandshakeError::Internal { .. } => "INTERNAL_ERROR",
        };

        Self {
            code: code.to_string(),
            message: err.to_string(),
            fatal: true,
        }
    }
}

impl NetworkEpoch {
    fn new() -> Self { Self(0) }
    fn increment(&mut self) { self.0 += 1; }
    fn current(&self) -> u64 { self.0 }
}

struct PersistentNonceEntry {
    epoch: u64,
    timestamp: u64,
    message_timestamp: u64,
}

struct MemoryNonceEntry {
    timestamp: Instant,
    message_timestamp: u64,
}

impl NonceCache {
    pub const DEFAULT_MAX_SIZE: usize = 1_000_000;
    pub const SYNC_MAX_SIZE: usize = 5_000_000;

    const NONCE_PREFIX: &'static str = "nonce:";
    const EPOCH_KEY: &'static str = "meta:epoch";

    /// Open or create persistent nonce cache at `db_path`.
    pub fn open<P: AsRef<Path>>(
        db_path: P,
        ttl_secs: u64,
        max_memory_size: usize,
    ) -> Result<Self> {
        let db = sled::open(db_path.as_ref())
            .map_err(|e| anyhow!("Failed to open nonce cache DB: {}", e))?;
        let db = Arc::new(db);

        let epoch = Self::load_epoch(&db)?;
        info!("Loaded network epoch: {}", epoch.current());

        let capacity = std::num::NonZeroUsize::new(max_memory_size)
            .ok_or_else(|| anyhow!("max_memory_size must be > 0"))?;
        let memory_cache = Arc::new(RwLock::new(lru::LruCache::new(capacity)));

        let cache = Self {
            memory_cache,
            db,
            epoch: Arc::new(RwLock::new(epoch)),
            ttl: Duration::from_secs(ttl_secs),
            max_memory_size,
        };

        cache.load_current_epoch_nonces()?;
        cache.cleanup_old_epochs()?;

        Ok(cache)
    }

    pub fn open_default<P: AsRef<Path>>(db_path: P, ttl_secs: u64) -> Result<Self> {
        Self::open(db_path, ttl_secs, Self::DEFAULT_MAX_SIZE)
    }

    pub fn open_sync<P: AsRef<Path>>(db_path: P, ttl_secs: u64) -> Result<Self> {
        Self::open(db_path, ttl_secs, Self::SYNC_MAX_SIZE)
    }

    /// Atomic check-and-store with persistence.
    /// Returns Ok(()) if nonce is new; Err if replay detected.
    pub fn check_and_store(&self, nonce: &[u8; 32], message_timestamp: u64) -> Result<()> {
        // Fast path: memory cache (read lock)
        {
            let memory = self.memory_cache.read();
            if memory.peek(nonce).is_some() {
                debug!("Replay detected in memory cache: nonce={}", hex::encode(nonce));
                return Err(anyhow!("Replay detected: nonce already used (memory)"));
            }
        }

        // Slow path: persistent check + atomic insert (write lock)
        let mut memory = self.memory_cache.write();
        let current_epoch = self.epoch.read().current();

        if memory.peek(nonce).is_some() {
            return Err(anyhow!("Replay detected: nonce already used (race)"));
        }

        let nonce_key = Self::nonce_key(nonce);
        if let Some(entry_bytes) = self.db.get(&nonce_key)
            .map_err(|e| anyhow!("DB read error: {}", e))? {
            let entry: PersistentNonceEntry = bincode::deserialize(&entry_bytes)
                .map_err(|e| anyhow!("Failed to deserialize nonce entry: {}", e))?;
            if entry.epoch == current_epoch {
                warn!("Replay detected in persistent cache: nonce={}, epoch={}",
                    hex::encode(nonce), entry.epoch);
                return Err(anyhow!("Replay detected: nonce already used (disk, current epoch)"));
            }
            debug!("Nonce from old epoch {} (current: {}), allowing reuse", entry.epoch, current_epoch);
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|e| anyhow!("System time error: {}", e))?
            .as_secs();

        memory.put(*nonce, MemoryNonceEntry {
            timestamp: Instant::now(),
            message_timestamp,
        });

        let persistent_entry = PersistentNonceEntry {
            epoch: current_epoch,
            timestamp: now,
            message_timestamp,
        };
        let entry_bytes = bincode::serialize(&persistent_entry)
            .map_err(|e| anyhow!("Failed to serialize nonce entry: {}", e))?;

        self.db.insert(&nonce_key, entry_bytes)
            .map_err(|e| anyhow!("Failed to persist nonce: {}", e))?;

        debug!("Stored nonce: epoch={}, timestamp={}", current_epoch, now);
        Ok(())
    }

    fn load_epoch(db: &sled::Db) -> Result<NetworkEpoch> {
        match db.get(Self::EPOCH_KEY).map_err(|e| anyhow!("DB read error: {}", e))? {
            Some(bytes) => {
                let epoch: NetworkEpoch = bincode::deserialize(&bytes)
                    .map_err(|e| anyhow!("Failed to deserialize epoch: {}", e))?;
                Ok(epoch)
            }
            None => Ok(NetworkEpoch::new()),
        }
    }

    fn save_epoch(db: &sled::Db, epoch: &NetworkEpoch) -> Result<()> {
        let bytes = bincode::serialize(epoch)
            .map_err(|e| anyhow!("Failed to serialize epoch: {}", e))?;
        db.insert(Self::EPOCH_KEY, bytes)
            .map_err(|e| anyhow!("Failed to save epoch: {}", e))?;
        Ok(())
    }

    fn load_current_epoch_nonces(&self) -> Result<()> {
        let current_epoch = self.epoch.read().current();
        let mut loaded = 0;
        let mut memory = self.memory_cache.write();

        for item in self.db.iter() {
            let (key, value) = item.map_err(|e| anyhow!("DB iteration error: {}", e))?;

            if key.starts_with(b"meta:") { continue; }
            if !key.starts_with(Self::NONCE_PREFIX.as_bytes()) { continue; }

            let entry: PersistentNonceEntry = match bincode::deserialize(&value) {
                Ok(e) => e,
                Err(e) => { warn!("Failed to deserialize nonce entry: {}", e); continue; }
            };

            if entry.epoch != current_epoch { continue; }

            let nonce_start = Self::NONCE_PREFIX.len();
            if key.len() != nonce_start + 64 {
                warn!("Invalid nonce key length: {}", key.len());
                continue;
            }

            let nonce_hex = &key[nonce_start..];
            let nonce = match hex::decode(nonce_hex) {
                Ok(n) if n.len() == 32 => {
                    let mut arr = [0u8; 32];
                    arr.copy_from_slice(&n);
                    arr
                }
                _ => { warn!("Invalid nonce hex encoding"); continue; }
            };

            memory.put(nonce, MemoryNonceEntry {
                timestamp: Instant::now(),
                message_timestamp: entry.message_timestamp,
            });
            loaded += 1;

            if loaded >= self.max_memory_size {
                warn!("Memory cache full during load, stopping at {} entries", loaded);
                break;
            }
        }

        info!("Loaded {} nonces from epoch {} into memory cache", loaded, current_epoch);
        Ok(())
    }

    fn cleanup_old_epochs(&self) -> Result<()> {
        let current_epoch = self.epoch.read().current();
        let mut deleted = 0;
        let mut keys_to_delete = Vec::new();

        for item in self.db.iter() {
            let (key, value) = item.map_err(|e| anyhow!("DB iteration error: {}", e))?;
            if key.starts_with(b"meta:") { continue; }
            if !key.starts_with(Self::NONCE_PREFIX.as_bytes()) { continue; }

            let entry: PersistentNonceEntry = match bincode::deserialize(&value) {
                Ok(e) => e,
                Err(_) => { keys_to_delete.push(key.to_vec()); continue; }
            };

            if entry.epoch < current_epoch {
                keys_to_delete.push(key.to_vec());
            }
        }

        for key in keys_to_delete {
            self.db.remove(&key)
                .map_err(|e| anyhow!("Failed to delete old nonce: {}", e))?;
            deleted += 1;
        }

        info!("Cleaned up {} nonces from previous epochs", deleted);
        Ok(())
    }

    /// Remove expired nonces from memory and disk (cleanup task).
    pub fn cleanup_expired(&self) {
        let now = Instant::now();
        let now_unix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        let mut memory = self.memory_cache.write();
        let expired_nonces: Vec<[u8; 32]> = memory
            .iter()
            .filter_map(|(nonce, entry)| {
                if now.duration_since(entry.timestamp) >= self.ttl { Some(*nonce) } else { None }
            })
            .collect();

        let memory_expired = expired_nonces.len();
        for nonce in &expired_nonces { memory.pop(nonce); }
        drop(memory);

        let mut keys_to_delete = Vec::new();
        for item in self.db.iter() {
            let (key, value) = match item {
                Ok(kv) => kv,
                Err(e) => { warn!("DB iteration error during cleanup: {}", e); continue; }
            };
            if !key.starts_with(Self::NONCE_PREFIX.as_bytes()) { continue; }
            let entry: PersistentNonceEntry = match bincode::deserialize(&value) {
                Ok(e) => e,
                Err(_) => { keys_to_delete.push(key.to_vec()); continue; }
            };
            let age = now_unix.saturating_sub(entry.timestamp);
            if age > self.ttl.as_secs() { keys_to_delete.push(key.to_vec()); }
        }

        let mut disk_expired = 0;
        for key in keys_to_delete {
            if let Err(e) = self.db.remove(&key) {
                warn!("Failed to delete expired nonce from disk: {}", e);
            } else {
                disk_expired += 1;
            }
        }

        if memory_expired > 0 || disk_expired > 0 {
            debug!("Cleaned up {} memory nonces, {} disk nonces", memory_expired, disk_expired);
        }
    }

    pub fn size(&self) -> usize { self.memory_cache.read().len() }
    pub fn max_size(&self) -> usize { self.max_memory_size }
    pub fn utilization(&self) -> f64 {
        self.size() as f64 / self.max_memory_size as f64
    }
    pub fn current_epoch(&self) -> u64 { self.epoch.read().current() }

    fn nonce_key(nonce: &[u8; 32]) -> Vec<u8> {
        let mut key = Vec::with_capacity(Self::NONCE_PREFIX.len() + 64);
        key.extend_from_slice(Self::NONCE_PREFIX.as_bytes());
        key.extend_from_slice(hex::encode(nonce).as_bytes());
        key
    }

    #[cfg(test)]
    pub fn new_test(ttl_secs: u64, max_memory_size: usize) -> Self {
        static TEST_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let counter = TEST_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let temp_dir = tempfile::TempDir::new().expect("Failed to create temp dir for test");
        let db_path = temp_dir.path().join(format!("nonce_cache_{}", counter));
        let cache = Self::open(&db_path, ttl_secs, max_memory_size)
            .expect("Failed to create test nonce cache");
        std::mem::forget(temp_dir);
        cache
    }

    #[cfg(test)]
    pub fn clear(&self) {
        self.memory_cache.write().clear();
        let mut keys_to_delete = Vec::new();
        for item in self.db.iter() {
            if let Ok((key, _)) = item {
                if key.starts_with(Self::NONCE_PREFIX.as_bytes()) {
                    keys_to_delete.push(key.to_vec());
                }
            }
        }
        for key in keys_to_delete { let _ = self.db.remove(&key); }
    }
}

pub async fn start_nonce_cleanup_task(cache: NonceCache, interval_secs: u64) {
    let mut interval = tokio::time::interval(Duration::from_secs(interval_secs));
    loop {
        interval.tick().await;
        cache.cleanup_expired();
    }
}

pub enum HandshakeEvent {
    /// ClientHello message received
    ClientHelloReceived,
    /// ClientHello signature verification started
    ClientHelloVerificationStarted,
    /// ClientHello signature verification succeeded
    ClientHelloVerificationSuccess,
    /// ClientHello signature verification failed
    ClientHelloVerificationFailed,

    /// ServerHello message created
    ServerHelloCreated,
    /// ServerHello signature verification started
    ServerHelloVerificationStarted,
    /// ServerHello signature verification succeeded
    ServerHelloVerificationSuccess,
    /// ServerHello signature verification failed
    ServerHelloVerificationFailed,

    /// ClientFinish message received
    ClientFinishReceived,
    /// ClientFinish signature verification started
    ClientFinishVerificationStarted,
    /// ClientFinish signature verification succeeded
    ClientFinishVerificationSuccess,
    /// ClientFinish signature verification failed
    ClientFinishVerificationFailed,

    /// Handshake completed successfully
    HandshakeComplete,

    /// Replay attack detected
    ReplayAttackDetected,
    /// Invalid timestamp detected
    InvalidTimestampDetected,
    /// Invalid protocol version detected
    InvalidProtocolVersionDetected,
    /// NodeId verification failed
    NodeIdVerificationFailed,
    /// Nonce cache full (may indicate DoS)
    NonceCacheFull,
}

pub enum FailureReason {
    /// Replay attack (nonce already used)
    ReplayAttack,
    /// Invalid signature
    InvalidSignature,
    /// Invalid timestamp (too old/too new)
    InvalidTimestamp,
    /// Invalid protocol version
    InvalidProtocolVersion,
    /// NodeId verification failed
    NodeIdVerificationFailed,
    /// Other error with description
    Other(String),
}

pub struct HandshakeMetrics {
    /// Duration of verification operation
    pub duration_micros: u64,
    /// Nonce cache size
    pub nonce_cache_size: usize,
    /// Nonce cache utilization (0.0 to 1.0)
    pub nonce_cache_utilization: f64,
    /// Protocol version
    pub protocol_version: u8,
}

pub trait HandshakeObserver: Send + Sync {
    /// Called when a handshake event occurs
    ///
    /// # Parameters
    /// - `event`: The type of event that occurred
    /// - `metrics`: Optional metrics snapshot at time of event
    fn on_event(&self, event: HandshakeEvent, metrics: Option<HandshakeMetrics>);

    /// Called when a handshake operation fails
    ///
    /// # Parameters
    /// - `event`: The event that failed
    /// - `reason`: Why the operation failed
    /// - `metrics`: Optional metrics snapshot at time of failure
    fn on_failure(&self, event: HandshakeEvent, reason: FailureReason, metrics: Option<HandshakeMetrics>);
}

impl HandshakeObserver for NoOpObserver {
    fn on_event(&self, _event: HandshakeEvent, _metrics: Option<HandshakeMetrics>) {
        // No-op
    }

    fn on_failure(&self, _event: HandshakeEvent, _reason: FailureReason, _metrics: Option<HandshakeMetrics>) {
        // No-op
    }
}

impl HandshakeObserver for LoggingObserver {
    fn on_event(&self, event: HandshakeEvent, metrics: Option<HandshakeMetrics>) {
        if let Some(m) = metrics {
            tracing::debug!(
                event = ?event,
                duration_micros = m.duration_micros,
                nonce_cache_size = m.nonce_cache_size,
                nonce_cache_utilization = m.nonce_cache_utilization,
                protocol_version = m.protocol_version,
                "Handshake event"
            );
        } else {
            tracing::debug!(event = ?event, "Handshake event");
        }
    }

    fn on_failure(&self, event: HandshakeEvent, reason: FailureReason, metrics: Option<HandshakeMetrics>) {
        if let Some(m) = metrics {
            tracing::warn!(
                event = ?event,
                reason = ?reason,
                duration_micros = m.duration_micros,
                nonce_cache_size = m.nonce_cache_size,
                "Handshake failure"
            );
        } else {
            tracing::warn!(event = ?event, reason = ?reason, "Handshake failure");
        }
    }
}

