pub struct RateLimiter {
    /// Per-IP rate limiters
    limiters: Arc<RwLock<HashMap<IpAddr, DefaultDirectRateLimiter>>>,

    /// Configuration
    config: RateLimitConfig,
}

impl RateLimiter {
    /// Create a new rate limiter with given configuration
    pub fn new(config: RateLimitConfig) -> Self {
        Self {
            limiters: Arc::new(RwLock::new(HashMap::new())),
            config,
        }
    }

    /// Create with default configuration
    pub fn default() -> Self {
        Self::new(RateLimitConfig::default())
    }

    /// Check if a handshake from this IP is allowed
    ///
    /// # Returns
    /// - `Ok(())` if handshake is allowed (within rate limit)
    /// - `Err(...)` if rate limit exceeded
    ///
    /// # Example
    /// ```no_run
    /// # use lib_network::handshake::RateLimiter;
    /// # use std::net::IpAddr;
    /// let limiter = RateLimiter::default();
    /// let ip: IpAddr = "192.168.1.1".parse().unwrap();
    ///
    /// match limiter.check_handshake(ip) {
    ///     Ok(()) => println!("Handshake allowed"),
    ///     Err(e) => println!("Rate limit exceeded: {}", e),
    /// }
    /// ```
    pub fn check_handshake(&self, ip: IpAddr) -> Result<()> {
        let mut limiters = self.limiters.write()
            .map_err(|e| anyhow!("Rate limiter lock poisoned: {}", e))?;

        // Get or create limiter for this IP
        let limiter = limiters.entry(ip).or_insert_with(|| {
            // Create quota: X per second with burst capacity Y
            let quota = Quota::per_second(
                NonZeroU32::new(self.config.handshakes_per_second)
                    .expect("handshakes_per_second must be > 0")
            ).allow_burst(
                NonZeroU32::new(self.config.burst_capacity)
                    .expect("burst_capacity must be > 0")
            );

            GovernorRateLimiter::direct(quota)
        });

        // Check if request is allowed
        match limiter.check() {
            Ok(_) => Ok(()),
            Err(_) => Err(anyhow!(
                "Rate limit exceeded for IP {}: {} handshakes/sec (burst: {})",
                ip,
                self.config.handshakes_per_second,
                self.config.burst_capacity
            )),
        }
    }

    /// Get number of IPs being tracked
    pub fn tracked_ips(&self) -> usize {
        self.limiters.read()
            .map(|l| l.len())
            .unwrap_or(0)
    }

    /// Clear all rate limiters (for testing)
    #[cfg(test)]
    pub fn clear(&self) {
        if let Ok(mut limiters) = self.limiters.write() {
            limiters.clear();
        }
    }
}

impl Clone for RateLimiter {
    fn clone(&self) -> Self {
        Self {
            limiters: Arc::clone(&self.limiters),
            config: self.config.clone(),
        }
    }
}

pub struct TimestampConfig {
    /// Maximum age of message in seconds (default: 300 = 5 minutes)
    pub max_age_secs: u64,
    /// Clock skew tolerance in seconds (default: 300 = 5 minutes)
    pub clock_skew_tolerance: u64,
    /// Minimum valid timestamp (ZHTP launch date, default: Nov 2023)
    pub min_timestamp: u64,
}

impl Default for TimestampConfig {
    fn default() -> Self {
        Self {
            max_age_secs: 300,
            clock_skew_tolerance: 300,
            min_timestamp: 1700000000, // Nov 2023
        }
    }
}

pub fn current_timestamp() -> Result<u64> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .map_err(|e| anyhow!("System clock error: {}", e))
}

pub fn validate_timestamp(timestamp: u64, config: &TimestampConfig) -> Result<()> {
    let now = current_timestamp()?;

    // 1. Reject future timestamps (with clock skew tolerance)
    if timestamp > now + config.clock_skew_tolerance {
        return Err(anyhow!(
            "Timestamp in future: {} > {} (+{} tolerance)",
            timestamp, now, config.clock_skew_tolerance
        ));
    }

    // 2. Reject very old timestamps
    let age = now.saturating_sub(timestamp);
    if age > config.max_age_secs {
        return Err(anyhow!(
            "Timestamp too old: {} seconds (max: {})",
            age, config.max_age_secs
        ));
    }

    // 3. Reject timestamps before protocol launch
    if timestamp < config.min_timestamp {
        return Err(anyhow!(
            "Timestamp predates protocol launch: {}",
            timestamp
        ));
    }

    // 4. Reject zero timestamp
    if timestamp == 0 {
        return Err(anyhow!("Timestamp is zero"));
    }

    Ok(())
}

pub struct SessionContext {
    /// Protocol version
    pub protocol_version: u32,
    /// Client DID
    pub client_did: String,
    /// Server DID
    pub server_did: String,
    /// Handshake timestamp
    pub timestamp: u64,
}

fn build_context_info(context: &SessionContext) -> Vec<u8> {
    let mut info = Vec::new();
    // CRITICAL: Domain separation to prevent key reuse across protocols
    // Network session keys MUST NEVER be used for blockchain transaction signing
    info.extend_from_slice(b"ZHTP-NETWORK-SESSION-ONLY-v1");  // Domain tag
    info.push(0x00); // Separator
    info.extend_from_slice(&context.protocol_version.to_le_bytes());
    info.extend_from_slice(context.client_did.as_bytes());
    info.extend_from_slice(context.server_did.as_bytes());
    info.extend_from_slice(&context.timestamp.to_le_bytes());
    info
}

pub fn ct_eq_bytes(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    bool::from(a.ct_eq(b))
}

pub fn ct_verify_eq(a: &[u8], b: &[u8], error_msg: &str) -> Result<()> {
    if !ct_eq_bytes(a, b) {
        return Err(anyhow!("{}", error_msg));
    }
    Ok(())
}

pub struct HardwareCapabilities {
    /// LoRaWAN radio hardware available
    pub lorawan_available: bool,
    /// Bluetooth LE hardware available
    pub bluetooth_available: bool,
    /// WiFi Direct hardware available
    pub wifi_direct_available: bool,
    /// Detected hardware details
    pub hardware_details: HashMap<String, HardwareDevice>,
}

pub struct HardwareDevice {
    /// Device name/identifier
    pub name: String,
    /// Device type (USB, SPI, I2C, etc.)
    pub device_type: String,
    /// Vendor/product information
    pub vendor_info: Option<String>,
    /// Device path or address
    pub device_path: Option<String>,
    /// Additional properties
    pub properties: HashMap<String, String>,
}

impl HardwareCapabilities {
    /// Detect all available hardware capabilities
    pub async fn detect() -> Result<Self> {
        info!("Detecting available mesh networking hardware...");

        let mut capabilities = Self::default();

        // Detect LoRaWAN hardware
        capabilities.lorawan_available = detect_lorawan_hardware(&mut capabilities.hardware_details).await;

        // Detect Bluetooth hardware
        capabilities.bluetooth_available = detect_bluetooth_hardware(&mut capabilities.hardware_details).await;

        // Detect WiFi Direct hardware
        capabilities.wifi_direct_available = detect_wifi_direct_hardware(&mut capabilities.hardware_details).await;

        info!("Hardware detection completed:");
        info!("   LoRaWAN: {}", if capabilities.lorawan_available { "Available" } else { "Not detected" });
        info!("    Bluetooth LE: {}", if capabilities.bluetooth_available { "Available" } else { "Not detected" });
        info!("   WiFi Direct: {}", if capabilities.wifi_direct_available { "Available" } else { "Not detected" });

        Ok(capabilities)
    }

    /// Get enabled protocols based on hardware availability
    pub fn get_enabled_protocols(&self) -> Vec<String> {
        let mut protocols = Vec::new();

        if self.bluetooth_available {
            protocols.push("Bluetooth LE".to_string());
        }

        if self.wifi_direct_available {
            protocols.push("WiFi Direct".to_string());
        }

        if self.lorawan_available {
            protocols.push("LoRaWAN".to_string());
        }

        protocols
    }

    /// Check if any mesh protocols are available
    pub fn has_mesh_capabilities(&self) -> bool {
        self.bluetooth_available || self.wifi_direct_available || self.lorawan_available
    }
}

