                    security: if parts.len() > 6 && parts[6].contains("WPA") {
                        WiFiSecurity::WPA2
                    } else {
                        WiFiSecurity::Open
                    },
                    bandwidth_estimate_mbps: estimate_bandwidth_from_signal(signal),
                });
            }
        }
    }

    Ok(networks)
}

