async fn is_lib_sharing_network(network: &WiFiNetworkInfo) -> bool {
    // Check for ZHTP mesh relay indicators:
    // 1. SSID contains "ZHTP" or "Mesh"
    // 2. Open network with ZHTP beacon
    // 3. Special vendor-specific information elements

    if network.ssid.contains("ZHTP") || network.ssid.contains("Mesh") {
        return true;
    }

    // For development, randomly mark some networks as sharing-enabled
    match network.security {
        WiFiSecurity::Open => rand::random::<f32>() < 0.1, // 10% of open networks
        _ => false, // Secured networks require authentication
    }
}

struct ZhtpServiceInfo {
    name: String,
    host: String,
    port: u16,
    txt_properties: std::collections::HashMap<String, String>,
}

impl ZhtpServiceInfo {
    /// Check if this service is a router (Group Owner)
    fn is_router(&self) -> bool {
        self.txt_properties.get("device_type")
            .map(|t| t == "router")
            .unwrap_or_else(|| {
                // Fallback: check group_owner flag
                self.txt_properties.get("group_owner")
                    .and_then(|v| v.parse::<bool>().ok())
                    .unwrap_or(false)
            })
    }

    /// Check if this service is a client
    fn is_client(&self) -> bool {
        !self.is_router()
    }

    /// Get node ID if available
    fn node_id(&self) -> Option<String> {
        self.txt_properties.get("node_id").cloned()
    }
}

