pub struct DHTPerformanceStats {
    // DHT-specific latency metrics
    pub avg_latency_ms: f64,
    pub median_latency_ms: f64,
    pub p95_latency_ms: f64,
    pub p99_latency_ms: f64,

    // DHT operation success rates
    pub success_rate: f64,
    pub error_rate: f64,

    // DHT operation counts
    pub total_operations: u64,
    pub operations_per_second: f64,

    // DHT cache performance (extends basic cache stats)
    pub cache_hit_rate: f64,
    pub cache_miss_rate: f64,
    pub cache_size: usize,

    // DHT-specific metrics
    pub content_resolution_time_ms: f64,
    pub peer_discovery_time_ms: f64,
    pub storage_operation_time_ms: f64,

    // Time range
    pub measurement_period_secs: u64,
    pub last_updated: SystemTime,
}

pub struct DHTPerformanceMonitor {
    metrics: VecDeque<DHTOperationMetric>,
    max_metrics: usize,
    window_duration: Duration,
    start_time: SystemTime,
}

impl DHTPerformanceMonitor {
    /// Create new performance monitor
    pub fn new(max_metrics: usize, window_duration: Duration) -> Self {
        Self {
            metrics: VecDeque::with_capacity(max_metrics),
            max_metrics,
            window_duration,
            start_time: SystemTime::now(),
        }
    }

    /// Record a completed operation
    pub fn record_operation(
        &mut self, 
        operation: DHTOperation, 
        duration: Duration, 
        success: bool,
        peer_count: usize
    ) {
        let metric = DHTOperationMetric {
            operation,
            duration,
            success,
            timestamp: SystemTime::now(),
            peer_count,
        };

        // Add new metric
        self.metrics.push_back(metric);

        // Remove old metrics if at capacity
        if self.metrics.len() > self.max_metrics {
            self.metrics.pop_front();
        }

        // Clean up metrics outside time window
        self.cleanup_old_metrics();
    }

    /// Get current DHT performance statistics
    pub fn get_stats(&self) -> DHTPerformanceStats {
        if self.metrics.is_empty() {
            return DHTPerformanceStats {
                avg_latency_ms: 0.0,
                median_latency_ms: 0.0,
                p95_latency_ms: 0.0,
                p99_latency_ms: 0.0,
                success_rate: 1.0,
                error_rate: 0.0,
                total_operations: 0,
                operations_per_second: 0.0,
                cache_hit_rate: 0.0,
                cache_miss_rate: 0.0,
                cache_size: 0,
                content_resolution_time_ms: 0.0,
                peer_discovery_time_ms: 0.0,
                storage_operation_time_ms: 0.0,
                measurement_period_secs: self.window_duration.as_secs(),
                last_updated: SystemTime::now(),
            };
        }

        let current_metrics: Vec<_> = self.metrics.iter().collect();

        // Calculate latency metrics
        let mut durations: Vec<_> = current_metrics.iter()
            .map(|m| m.duration.as_millis() as f64)
            .collect();
        durations.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let avg_latency_ms = durations.iter().sum::<f64>() / durations.len() as f64;
        let median_latency_ms = percentile(&durations, 0.5);
        let p95_latency_ms = percentile(&durations, 0.95);
        let p99_latency_ms = percentile(&durations, 0.99);

        // Calculate success rate
        let successful = current_metrics.iter().filter(|m| m.success).count();
        let total = current_metrics.len();
        let success_rate = if total > 0 { 
            successful as f64 / total as f64 
        } else { 
            1.0 
        };

        // Calculate operations per second
        let time_span = self.start_time.elapsed().unwrap_or(Duration::from_secs(1));
        let operations_per_second = total as f64 / time_span.as_secs_f64();

        // Calculate network health (based on peer count and success rate)
        let avg_peers = if !current_metrics.is_empty() {
            current_metrics.iter().map(|m| m.peer_count).sum::<usize>() as f64 
                / current_metrics.len() as f64
        } else {
            0.0
        };

        let _network_health = (success_rate * 0.7) +
                           ((avg_peers.min(10.0) / 10.0) * 0.3);

        // Calculate cache performance
        let cache_hits = current_metrics.iter()
            .filter(|m| m.operation == DHTOperation::CacheHit)
            .count();
        let cache_misses = current_metrics.iter()
            .filter(|m| m.operation == DHTOperation::CacheMiss)
            .count();

        let cache_hit_rate = if cache_hits + cache_misses > 0 {
            cache_hits as f64 / (cache_hits + cache_misses) as f64
        } else {
            0.0
        };

        DHTPerformanceStats {
            avg_latency_ms,
            median_latency_ms,
            p95_latency_ms,
            p99_latency_ms,
            success_rate,
            error_rate: 1.0 - success_rate,
            total_operations: total as u64,
            operations_per_second,
            cache_hit_rate,
            cache_miss_rate: 1.0 - cache_hit_rate,
            cache_size: 0, // To be filled by caller
            content_resolution_time_ms: self.calculate_operation_latency(DHTOperation::Resolve),
            peer_discovery_time_ms: self.calculate_operation_latency(DHTOperation::PeerDiscover),
            storage_operation_time_ms: self.calculate_operation_latency(DHTOperation::Store),
            measurement_period_secs: self.window_duration.as_secs(),
            last_updated: SystemTime::now(),
        }
    }

    /// Get DHT operation-specific statistics
    pub fn get_operation_stats(&self, operation: DHTOperation) -> DHTPerformanceStats {
        let filtered_metrics: Vec<_> = self.metrics.iter()
            .filter(|m| m.operation == operation)
            .collect();

        if filtered_metrics.is_empty() {
            return DHTPerformanceStats {
                avg_latency_ms: 0.0,
                median_latency_ms: 0.0,
                p95_latency_ms: 0.0,
                p99_latency_ms: 0.0,
                success_rate: 1.0,
                error_rate: 0.0,
                total_operations: 0,
                operations_per_second: 0.0,
                cache_hit_rate: 0.0,
                cache_miss_rate: 0.0,
                cache_size: 0,
                content_resolution_time_ms: 0.0,
                peer_discovery_time_ms: 0.0,
                storage_operation_time_ms: 0.0,
                measurement_period_secs: self.window_duration.as_secs(),
                last_updated: SystemTime::now(),
            };
        }

        let durations: Vec<_> = filtered_metrics.iter()
            .map(|m| m.duration.as_millis() as f64)
            .collect();

        let successful = filtered_metrics.iter().filter(|m| m.success).count();
        let total = filtered_metrics.len();

        DHTPerformanceStats {
            avg_latency_ms: durations.iter().sum::<f64>() / durations.len() as f64,
            median_latency_ms: percentile(&durations, 0.5),
            p95_latency_ms: percentile(&durations, 0.95),
            p99_latency_ms: percentile(&durations, 0.99),
            success_rate: successful as f64 / total as f64,
            error_rate: 1.0 - (successful as f64 / total as f64),
            total_operations: total as u64,
            operations_per_second: 0.0, // Not meaningful for single operation type
            cache_hit_rate: 0.0,
            cache_miss_rate: 1.0,
            cache_size: 0,
            content_resolution_time_ms: self.calculate_operation_latency(DHTOperation::Resolve),
            peer_discovery_time_ms: self.calculate_operation_latency(DHTOperation::PeerDiscover),
            storage_operation_time_ms: self.calculate_operation_latency(DHTOperation::Store),
            measurement_period_secs: self.window_duration.as_secs(),
            last_updated: SystemTime::now(),
        }
    }

    /// Reset all metrics
    pub fn reset(&mut self) {
        self.metrics.clear();
        self.start_time = SystemTime::now();
    }

    /// Calculate average latency for a specific operation type
    fn calculate_operation_latency(&self, operation: DHTOperation) -> f64 {
        let op_metrics: Vec<_> = self.metrics.iter()
            .filter(|m| m.operation == operation)
            .collect();

        if op_metrics.is_empty() {
            return 0.0;
        }

        let total_ms: f64 = op_metrics.iter()
            .map(|m| m.duration.as_millis() as f64)
            .sum();

        total_ms / op_metrics.len() as f64
    }

    /// Clean up metrics outside the time window
    fn cleanup_old_metrics(&mut self) {
        let cutoff_time = SystemTime::now() - self.window_duration;

        while let Some(front) = self.metrics.front() {
            if front.timestamp < cutoff_time {
                self.metrics.pop_front();
            } else {
                break;
            }
        }
    }
}

pub struct ThreadSafeDHTMonitor {
    monitor: Arc<Mutex<DHTPerformanceMonitor>>,
}

impl ThreadSafeDHTMonitor {
    /// Create new thread-safe monitor
    pub fn new(max_metrics: usize, window_duration: Duration) -> Self {
        Self {
            monitor: Arc::new(Mutex::new(
                DHTPerformanceMonitor::new(max_metrics, window_duration)
            )),
        }
    }

    /// Record operation (async)
    pub async fn record_operation(
        &self, 
        operation: DHTOperation, 
        duration: Duration, 
        success: bool,
        peer_count: usize
    ) {
        self.monitor.lock().await.record_operation(operation, duration, success, peer_count);
    }

    /// Get statistics (async)
    pub async fn get_stats(&self) -> DHTPerformanceStats {
        self.monitor.lock().await.get_stats()
    }

    /// Get operation-specific stats (async)  
    pub async fn get_operation_stats(&self, operation: DHTOperation) -> DHTPerformanceStats {
        self.monitor.lock().await.get_operation_stats(operation)
    }

    /// Reset metrics (async)
    pub async fn reset(&self) {
        self.monitor.lock().await.reset();
    }
}

pub struct OperationTimer {
    operation: DHTOperation,
    start_time: Instant,
    monitor: Arc<Mutex<DHTPerformanceMonitor>>,
    peer_count: usize,
}

impl OperationTimer {
    /// Start timing an operation
    pub fn start(
        operation: DHTOperation, 
        monitor: Arc<Mutex<DHTPerformanceMonitor>>,
        peer_count: usize
    ) -> Self {
        Self {
            operation,
            start_time: Instant::now(),
            monitor,
            peer_count,
        }
    }

    /// Complete the operation and record metrics
    pub async fn complete(self, success: bool) {
        let duration = self.start_time.elapsed();
        self.monitor.lock().await.record_operation(
            self.operation, 
            duration, 
            success,
            self.peer_count
        );
    }
}

fn percentile(sorted_data: &[f64], percentile: f64) -> f64 {
    if sorted_data.is_empty() {
        return 0.0;
    }

    let index = (sorted_data.len() as f64 * percentile) as usize;
    let index = index.min(sorted_data.len() - 1);
    sorted_data[index]
}

pub struct ZhtpPeerInfo {
    /// Blockchain identity public key
    pub blockchain_pubkey: PublicKey,

    /// Dilithium2 post-quantum signature public key
    pub dilithium_pubkey: Vec<u8>,

    /// Decentralized identifier (did:zhtp:...)
    pub did: String,

    /// Device name for NodeId derivation
    pub device_name: String,

    /// Node capabilities (DHT hosting, relay, etc.)
    pub capabilities: NodeCapabilities,

    /// Network addresses for this peer
    pub addresses: Vec<String>,

    /// Reputation score (0.0 - 1.0)
    pub reputation: f64,

    /// Last seen timestamp (Unix epoch)
    pub last_seen: u64,

    /// Registration timestamp
    pub registered_at: u64,

    /// TTL for this entry (seconds)
    pub ttl: u64,

    /// Signature of peer data (signed with blockchain key)
    pub signature: Vec<u8>,
}

impl ZhtpPeerInfo {
    /// Verify the blockchain signature on this peer info
    pub fn verify_signature(&self) -> Result<bool> {
        // Serialize peer data without signature
        let mut peer_data = self.clone();
        peer_data.signature = vec![];

        let serialized = bincode::serialize(&peer_data)
            .map_err(|e| anyhow!("Failed to serialize peer data: {}", e))?;

        let data_hash = hash_blake3(&serialized);

        // Verify Dilithium2 signature
        match dilithium2_verify(&data_hash, &self.signature, &self.dilithium_pubkey) {
            Ok(valid) => Ok(valid),
            Err(e) => {
                warn!("Signature verification failed: {}", e);
                Ok(false)
            }
        }
    }

    /// Check if this peer entry has expired
    pub fn is_expired(&self) -> bool {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        now > (self.registered_at + self.ttl)
    }

    /// Check if peer meets minimum reputation threshold
    pub fn meets_reputation_threshold(&self) -> bool {
        self.reputation >= MIN_REPUTATION_THRESHOLD
    }
}

pub struct PeerQueryFilter {
    /// Require DHT hosting capability
    pub requires_dht: bool,

    /// Require relay capability
    pub requires_relay: bool,

    /// Minimum bandwidth (bytes/sec)
    pub min_bandwidth: Option<u64>,

    /// Minimum reputation score
    pub min_reputation: Option<f64>,

    /// Required protocol support
    pub required_protocols: Vec<String>,

    /// Require post-quantum security
    pub require_quantum_secure: bool,

    /// Maximum results to return
    pub max_results: usize,
}

pub struct ZhtpPeerRegistry {
    /// Registered peers by node ID
    peers: Arc<RwLock<HashMap<[u8; 32], ZhtpPeerInfo>>>,

    /// Reputation scores by node ID
    reputation_scores: Arc<RwLock<HashMap<[u8; 32], f64>>>,

    /// Local node identity
    identity: ZhtpIdentity,
}

impl ZhtpPeerRegistry {
    /// Create a new peer registry
    pub fn new(identity: ZhtpIdentity) -> Self {
        Self {
            peers: Arc::new(RwLock::new(HashMap::new())),
            reputation_scores: Arc::new(RwLock::new(HashMap::new())),
            identity,
        }
    }

    /// Register a new peer (or update existing)
    pub async fn register_peer(&self, peer_info: ZhtpPeerInfo) -> Result<()> {
        // Verify signature before accepting
        if !peer_info.verify_signature()? {
            return Err(anyhow!("Invalid peer signature"));
        }

        // Check if expired
        if peer_info.is_expired() {
            return Err(anyhow!("Peer registration expired"));
        }

        // Generate node ID from DID + device (identity-based derivation)
        let node_id = self.generate_node_id(&peer_info.did, &peer_info.device_name)?;

        // Validate NodeId derivation for security
        let derived_node_id = lib_identity::NodeId::from_did_device(&peer_info.did, &peer_info.device_name)?;
        let node_id_bytes = *node_id.as_bytes();
        if node_id_bytes != *derived_node_id.as_bytes() {
            return Err(anyhow!(
                "NodeId validation failed: derived {} but got {}",
                hex::encode(derived_node_id.as_bytes()),
                hex::encode(node_id_bytes)
            ));
        }

        // Update last_seen timestamp
        let mut updated_peer = peer_info.clone();
        updated_peer.last_seen = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        // Store peer info
        let mut peers = self.peers.write().await;
        let node_id_bytes = *node_id.as_bytes();
        peers.insert(node_id_bytes, updated_peer.clone());

        // Update reputation score
        let mut scores = self.reputation_scores.write().await;
        scores.insert(node_id_bytes, updated_peer.reputation);

        info!(
            "Registered peer {} with reputation {:.2}",
            hex::encode(&node_id_bytes[..8]),
            updated_peer.reputation
        );

        Ok(())
    }

    /// Find peers matching the given filter criteria
    pub async fn find_peers(&self, filter: PeerQueryFilter) -> Result<Vec<ZhtpPeerInfo>> {
        let peers = self.peers.read().await;
        let mut matching_peers = Vec::new();

        for (node_id, peer_info) in peers.iter() {
            // Skip expired peers
            if peer_info.is_expired() {
                debug!("Skipping expired peer {}", hex::encode(&node_id[..8]));
                continue;
            }

            // Check DHT capability
            if filter.requires_dht && !peer_info.capabilities.has_dht {
                continue;
            }

            // Check relay capability
            if filter.requires_relay && !peer_info.capabilities.can_relay {
                continue;
            }

            // Check bandwidth requirement
            if let Some(min_bw) = filter.min_bandwidth {
                if peer_info.capabilities.max_bandwidth < min_bw {
                    continue;
                }
            }

            // Check reputation requirement
            if let Some(min_rep) = filter.min_reputation {
                if peer_info.reputation < min_rep {
                    continue;
                }
            }

            // Check protocol support
            if !filter.required_protocols.is_empty() {
                let has_all_protocols = filter.required_protocols.iter()
                    .all(|proto| peer_info.capabilities.protocols.contains(proto));

                if !has_all_protocols {
                    continue;
                }
            }

            // Check quantum security
            if filter.require_quantum_secure && !peer_info.capabilities.quantum_secure {
                continue;
            }

            matching_peers.push(peer_info.clone());
        }

        // Sort by reputation (highest first)
        matching_peers.sort_by(|a, b| {
            b.reputation.partial_cmp(&a.reputation).unwrap_or(std::cmp::Ordering::Equal)
        });

        // Limit results
        let max_results = filter.max_results.min(MAX_PEERS_PER_QUERY);
        matching_peers.truncate(max_results);

        info!(
            "Found {} peers matching filter (out of {} total)",
            matching_peers.len(),
            peers.len()
        );

        Ok(matching_peers)
    }

    /// Get a specific peer by node ID
    pub async fn get_peer(&self, node_id: &[u8; 32]) -> Result<Option<ZhtpPeerInfo>> {
        let peers = self.peers.read().await;

        if let Some(peer_info) = peers.get(node_id) {
            // Check if expired
            if peer_info.is_expired() {
                return Ok(None);
            }

            Ok(Some(peer_info.clone()))
        } else {
            Ok(None)
        }
    }

    /// Update reputation score for a peer
    pub async fn update_reputation(&self, node_id: &[u8; 32], new_reputation: f64) -> Result<()> {
        // Clamp reputation to [0.0, 1.0]
        let clamped_reputation = new_reputation.max(0.0).min(1.0);

        let mut peers = self.peers.write().await;

        if let Some(peer_info) = peers.get_mut(node_id) {
            peer_info.reputation = clamped_reputation;
            peer_info.last_seen = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();

            // Update reputation scores
            let mut scores = self.reputation_scores.write().await;
            scores.insert(*node_id, clamped_reputation);

            debug!(
                "Updated reputation for peer {} to {:.2}",
                hex::encode(&node_id[..8]),
                clamped_reputation
            );

            Ok(())
        } else {
            Err(anyhow!("Peer not found"))
        }
    }

    /// Remove a peer from the registry
    pub async fn remove_peer(&self, node_id: &[u8; 32]) -> Result<()> {
        let mut peers = self.peers.write().await;
        let mut scores = self.reputation_scores.write().await;

        peers.remove(node_id);
        scores.remove(node_id);

        info!("Removed peer {}", hex::encode(&node_id[..8]));

        Ok(())
    }

    /// Clean up expired peers
    pub async fn cleanup_expired_peers(&self) -> Result<usize> {
        let mut peers = self.peers.write().await;
        let mut scores = self.reputation_scores.write().await;

        let expired_nodes: Vec<[u8; 32]> = peers.iter()
            .filter(|(_, peer_info)| peer_info.is_expired())
            .map(|(node_id, _)| *node_id)
            .collect();

        let count = expired_nodes.len();

        for node_id in expired_nodes {
            peers.remove(&node_id);
            scores.remove(&node_id);
        }

        if count > 0 {
            info!("Cleaned up {} expired peers", count);
        }

        Ok(count)
    }

    /// Get total peer count
    pub async fn peer_count(&self) -> usize {
        let peers = self.peers.read().await;
        peers.len()
    }

    /// Get all peer IDs
    pub async fn get_all_peer_ids(&self) -> Vec<[u8; 32]> {
        let peers = self.peers.read().await;
        peers.keys().copied().collect()
    }

    /// Generate node ID from DID + device name (identity-based derivation)
    /// 
    /// This ensures NodeIds are deterministic and verifiable based on identity.
    /// 
    /// # Arguments
    /// * `did` - Decentralized identifier (did:zhtp:...)
    /// * `device_name` - Device identifier
    /// 
    /// # Returns
    /// Identity-derived NodeId
    fn generate_node_id(&self, did: &str, device_name: &str) -> Result<lib_identity::NodeId> {
        lib_identity::NodeId::from_did_device(did, device_name)
    }
}

pub enum DhtOperation {
    /// Query for content by domain/path
    Query,
    /// Response to a query
    QueryResponse,
    /// Store content in the DHT
    Store,
    /// Acknowledge successful store
    StoreAck,
    /// Discover peers in the network
    PeerDiscovery,
    /// Peer discovery response
    PeerResponse,
    /// Ping for connectivity testing
    Ping,
    /// Pong response to ping
    Pong,
    /// ZHTP Relay Query (Node B -> Node A: request DHT content)
    RelayQuery,
    /// ZHTP Relay Response (Node A -> Node B: return DHT content)
    RelayResponse,
    /// ZHTP Peer Registration (register blockchain-verified peer)
    PeerRegister,
    /// ZHTP Peer Registration Acknowledgment
    PeerRegisterAck,
    /// ZHTP Peer Query (find peers with capabilities)
