        Err(anyhow::anyhow!("Blockchain not available"))
    }

    async fn get_full_blockchain(&self) -> Result<Vec<u8>> {
        Err(anyhow::anyhow!("Blockchain not available"))
    }

    async fn is_available(&self) -> bool {
        false
    }
}

pub struct EdgeNodeSyncManager {
    /// Core edge node state (rolling header window + UTXOs)
    edge_state: Arc<RwLock<EdgeNodeState>>,
    /// Current network height (updated from peers)
    network_height: Arc<RwLock<u64>>,
    /// Node's own public keys for UTXO tracking
    my_addresses: Arc<RwLock<Vec<Vec<u8>>>>,
    /// Next request ID
    next_request_id: Arc<RwLock<u64>>,
}

impl EdgeNodeSyncManager {
    /// Create a new edge node sync manager
    /// 
    /// # Arguments
    /// * `max_headers` - Rolling window size (recommended: 500 for ~100KB storage)
    pub fn new(max_headers: usize) -> Self {
        info!(" Initializing EdgeNodeSyncManager with {} header capacity", max_headers);
        Self {
            edge_state: Arc::new(RwLock::new(EdgeNodeState::new(max_headers))),
            network_height: Arc::new(RwLock::new(0)),
            my_addresses: Arc::new(RwLock::new(Vec::new())),
            next_request_id: Arc::new(RwLock::new(1)),
        }
    }

    /// Add a public key to track for incoming payments
    pub async fn add_address(&self, address: Vec<u8>) {
        let mut addresses = self.my_addresses.write().await;
        if !addresses.contains(&address) {
            addresses.push(address.clone());
            self.edge_state.write().await.add_address(address);
            info!(" Added address to edge node tracking");
        }
    }

    /// Update the known network height (from peer announcements)
    pub async fn update_network_height(&self, height: u64) {
        let mut current = self.network_height.write().await;
        if height > *current {
            *current = height;
            debug!(" Network height updated to {}", height);
        }
    }

    /// Get the current sync strategy based on network state
    pub async fn get_sync_strategy(&self) -> Result<SyncStrategy> {
        let edge_state = self.edge_state.read().await;
        let network_height = *self.network_height.read().await;

        if network_height == 0 {
            return Err(anyhow!("Network height unknown - no peers connected"));
        }

        Ok(edge_state.get_sync_strategy(network_height))
    }

    /// Create a sync request message based on current state
    pub async fn create_sync_request(&self, requester: PublicKey) -> Result<(u64, ZhtpMeshMessage)> {
        let strategy = self.get_sync_strategy().await?;
        let mut next_id = self.next_request_id.write().await;
        let request_id = *next_id;
        *next_id += 1;

        let message = match strategy {
            SyncStrategy::HeadersOnly { start_height, count } => {
                info!("📥 Creating HeadersOnly request: height {} count {}", start_height, count);
                ZhtpMeshMessage::HeadersRequest {
                    requester: requester.clone(),
                    request_id,
                    start_height,
                    count: count as u32,
                }
            }
            SyncStrategy::BootstrapProof { proof_up_to_height, headers_from_height: _, headers_count: _ } => {
                let current_height = self.edge_state.read().await.current_height;
                info!("📥 Creating BootstrapProof request: current {} proof up to {}", 
                    current_height, proof_up_to_height);
                ZhtpMeshMessage::BootstrapProofRequest {
                    requester: requester.clone(),
                    request_id,
                    current_height,
                }
            }
        };

        Ok((request_id, message))
    }

    /// Process received block headers with validation and reorg detection
    pub async fn process_headers(&self, headers: Vec<BlockHeader>) -> Result<()> {
        if headers.is_empty() {
            return Ok(());
        }

        // CRITICAL: Verify headers are in sequential order
        for i in 1..headers.len() {
            if headers[i].height != headers[i-1].height + 1 {
                return Err(anyhow!(
                    "Headers not sequential: {}th header has height {}, previous was {}",
                    i, headers[i].height, headers[i-1].height
                ));
            }
            if headers[i].previous_block_hash != headers[i-1].block_hash {
                return Err(anyhow!(
                    "Headers chain broken at index {}: previous_hash mismatch",
                    i
                ));
            }
        }

        let mut edge_state = self.edge_state.write().await;

        // Check for chain reorganization before accepting headers
        if let Some(first_header) = headers.first() {
            if edge_state.detect_reorg(first_header) {
                warn!("⚠️  CHAIN REORGANIZATION DETECTED!");

                // Determine rollback point
                // We need to find the common ancestor between our chain and the new chain
                let rollback_height = if first_header.height > 0 {
                    first_header.height - 1
                } else {
                    0
                };

                // Rollback to the common ancestor
                if let Err(e) = edge_state.rollback_to_height(rollback_height) {
                    return Err(anyhow!("Rollback failed during reorg: {}", e));
                }

                info!("✅ Rolled back to height {} to handle reorg", rollback_height);

                // Create checkpoint for recovery
                let checkpoint = edge_state.create_checkpoint();
                info!(" Checkpoint created: height={}, headers={}, utxos={}", 
                    checkpoint.height, checkpoint.header_count, checkpoint.utxo_count);
            }
        }

        let mut added_count = 0;
        let header_count = headers.len();

        for header in headers {
            match edge_state.add_header(header.clone()) {
                Ok(()) => added_count += 1,
                Err(e) => {
                    warn!("⚠️  Failed to add header at height {}: {}", header.height, e);
                    // Stop processing on first error to prevent accepting invalid chain
                    return Err(anyhow!("Header validation failed: {}", e));
                }
            }
        }

        info!(" Processed {} of {} headers successfully, current height: {}", 
            added_count, header_count, edge_state.current_height);
        Ok(())
    }

    /// Process bootstrap proof response with ZK verification
    pub async fn process_bootstrap_proof(
        &self,
        proof_data: Vec<u8>,
        proof_height: u64,
        headers: Vec<BlockHeader>,
    ) -> Result<()> {
        info!(" Processing bootstrap proof up to height {}", proof_height);

        // STEP 1: Verify ZK proof (if proof_data is not empty)
        if !proof_data.is_empty() {
            match self.verify_chain_recursive_proof(&proof_data, proof_height, &headers).await {
                Ok(true) => {
                    info!("✅ Bootstrap ZK proof verified successfully");
                }
                Ok(false) => {
                    return Err(anyhow!("Bootstrap proof verification failed: proof is invalid"));
                }
                Err(e) => {
                    // Proof verification failed - this could be:
                    // 1. Invalid proof format
                    // 2. Proof doesn't match claimed height
                    // 3. Cryptographic verification failed
                    warn!("⚠️  ZK proof verification error: {} - REJECTING bootstrap", e);
                    return Err(anyhow!("Bootstrap proof verification error: {}", e));
                }
            }
        } else {
            // Empty proof_data means we're in development mode or new network
            warn!("⚠️  No ZK proof provided - accepting headers without cryptographic verification (INSECURE)");
        }

        // STEP 2: Validate headers are sequential before accepting
        if headers.len() > 1 {
            for i in 1..headers.len() {
                if headers[i].height != headers[i-1].height + 1 {
                    return Err(anyhow!("Bootstrap headers not sequential at index {}", i));
                }
                if headers[i].previous_block_hash != headers[i-1].block_hash {
                    return Err(anyhow!("Bootstrap headers chain broken at index {}", i));
                }
            }
        }

        // STEP 3: Verify first header links to proof (if we have existing headers)
        let edge_state = self.edge_state.read().await;
        if let Some(latest) = edge_state.get_latest_header() {
            if let Some(first_new_header) = headers.first() {
                if first_new_header.previous_block_hash != latest.block_hash {
                    warn!("⚠️  Bootstrap headers don't link to existing chain - potential reorg");
                    // Allow this but log it - might be valid during reorg
                }
            }
        }
        drop(edge_state);

        // STEP 4: Add headers to edge state
        let mut edge_state = self.edge_state.write().await;
        for header in headers {
            if let Err(e) = edge_state.add_header(header) {
                return Err(anyhow!("Failed to add bootstrap header: {}", e));
            }
        }

        info!("✅ Bootstrap complete at height {}", edge_state.current_height);
        Ok(())
    }

    /// Verify a ChainRecursiveProof using lib-proofs RecursiveProofAggregator
    async fn verify_chain_recursive_proof(
        &self,
        proof_data: &[u8],
        claimed_height: u64,
        headers: &[BlockHeader],
    ) -> Result<bool> {
        use lib_proofs::RecursiveProofAggregator;

        // Deserialize the recursive proof
        let chain_proof: lib_proofs::ChainRecursiveProof = bincode::deserialize(proof_data)
            .map_err(|e| anyhow!("Failed to deserialize ChainRecursiveProof: {}", e))?;

        // Validate proof metadata matches our expectations
        if chain_proof.chain_tip_height != claimed_height {
            return Err(anyhow!(
                "Proof height mismatch: claimed {} but proof is for {}",
                claimed_height,
                chain_proof.chain_tip_height
            ));
        }

        // Create aggregator for verification
        // Note: This creates a new instance each time. For production, consider caching.
        let aggregator = RecursiveProofAggregator::new()
            .map_err(|e| anyhow!("Failed to create proof aggregator: {}", e))?;

        // Verify the recursive chain proof cryptographically
        // This is the REAL verification - it checks:
        // 1. The recursive SNARK proof is valid
        // 2. Chain commitment matches (genesis -> tip)
        // 3. Proof timestamp is reasonable
        // 4. Chain bounds are consistent
        let is_valid = aggregator.verify_recursive_chain_proof(&chain_proof)
            .map_err(|e| anyhow!("Recursive proof verification failed: {}", e))?;

        if !is_valid {
            warn!("⚠️  Recursive proof cryptographic verification FAILED");
            return Ok(false);
        }

        // Additional check: Verify proof's state root links to our first header
        if let Some(first_header) = headers.first() {
            // The proof covers genesis -> proof_height
            // Our headers start from proof_height or later
            // So first header should be at or after proof height
            if first_header.height < chain_proof.chain_tip_height {
                warn!("⚠️  Header sequence doesn't align with proof height");
                return Ok(false);
            }

            debug!("Proof state root: {:?}", hex::encode(&chain_proof.current_state_root));
            debug!("First header: height={}, prev_hash={:?}", 
                first_header.height,
                hex::encode(&first_header.previous_block_hash.as_bytes()[..8])
            );
        }

        info!("✅ ChainRecursiveProof CRYPTOGRAPHICALLY VERIFIED: genesis {} -> tip {} ({} total txs)",
            chain_proof.genesis_height,
            chain_proof.chain_tip_height,
            chain_proof.total_transaction_count
        );

        Ok(true)
    }

    /// Add a UTXO that belongs to this edge node
    pub async fn add_utxo(&self, tx_hash: Hash, output_index: u32, output: TransactionOutput) {
        self.edge_state.write().await.add_utxo(tx_hash, output_index, &output);
    }

    /// Remove a spent UTXO
    pub async fn remove_utxo(&self, tx_hash: &Hash, output_index: u32) -> bool {
        self.edge_state.write().await.remove_utxo(tx_hash, output_index)
    }

    /// Get current edge node height
    pub async fn current_height(&self) -> u64 {
        self.edge_state.read().await.current_height
    }

    /// Get the known network height
    pub async fn network_height(&self) -> u64 {
        *self.network_height.read().await
    }

    /// Check if edge node needs bootstrap proof
    pub async fn needs_bootstrap_proof(&self) -> bool {
        let edge_state = self.edge_state.read().await;
        let network_height = *self.network_height.read().await;
        edge_state.needs_bootstrap_proof(network_height)
    }

    /// Get the number of headers currently stored
    pub async fn header_count(&self) -> usize {
        self.edge_state.read().await.headers.len()
    }

    /// Get estimated storage size in bytes
    pub async fn estimated_storage_bytes(&self) -> usize {
        // ~200 bytes per header + ~96 bytes per UTXO
        let header_count = self.header_count().await;
        let utxo_count = self.edge_state.read().await.utxo_count();
        (header_count * 200) + (utxo_count * 96)
    }
}

pub fn get_chunk_size_for_protocol(protocol: &NetworkProtocol) -> usize {
    match protocol {
        NetworkProtocol::BluetoothLE => BLE_CHUNK_SIZE,
        NetworkProtocol::BluetoothClassic => CLASSIC_CHUNK_SIZE,
        NetworkProtocol::WiFiDirect => WIFI_CHUNK_SIZE,
        NetworkProtocol::TCP | NetworkProtocol::UDP => WIFI_CHUNK_SIZE,
        _ => DEFAULT_CHUNK_SIZE,
    }
}

pub struct BlockchainSyncManager {
    /// Pending blockchain requests (request_id -> requester)
    pending_requests: Arc<RwLock<HashMap<u64, PublicKey>>>,
    /// Received chunks for reassembly (request_id -> chunks)
    received_chunks: Arc<RwLock<HashMap<u64, BlockchainChunkBuffer>>>,
    /// Next request ID
    next_request_id: Arc<RwLock<u64>>,
}

struct BlockchainChunkBuffer {
    chunks: HashMap<u32, Vec<u8>>,
    total_chunks: u32,
    complete_data_hash: [u8; 32],
    requester: PublicKey,
}

impl BlockchainSyncManager {
    pub fn new() -> Self {
        Self {
            pending_requests: Arc::new(RwLock::new(HashMap::new())),
            received_chunks: Arc::new(RwLock::new(HashMap::new())),
            next_request_id: Arc::new(RwLock::new(1)),
        }
    }

    /// Create a blockchain request message
    pub async fn create_blockchain_request(&self, requester: PublicKey, from_height: Option<u64>) -> Result<(u64, ZhtpMeshMessage)> {
        let mut next_id = self.next_request_id.write().await;
        let request_id = *next_id;
        *next_id += 1;

        // Store pending request
        self.pending_requests.write().await.insert(request_id, requester.clone());

        let request_type = if let Some(height) = from_height {
            crate::types::mesh_message::BlockchainRequestType::BlocksAfter(height)
        } else {
            crate::types::mesh_message::BlockchainRequestType::FullChain
        };

        let message = ZhtpMeshMessage::BlockchainRequest {
            requester,
            request_id,
            request_type,
        };

        info!(" Created blockchain request (ID: {})", request_id);
        Ok((request_id, message))
    }

    /// Chunk blockchain data with protocol-specific chunk size
    pub fn chunk_blockchain_data_for_protocol(
        sender: PublicKey,
        request_id: u64,
        data: Vec<u8>,
        protocol: &NetworkProtocol,
    ) -> Result<Vec<ZhtpMeshMessage>> {
        let chunk_size = get_chunk_size_for_protocol(protocol);
        Self::chunk_blockchain_data_with_size(sender, request_id, data, chunk_size)
    }

    /// Chunk blockchain data for mesh transmission (legacy - uses BLE size)
    pub fn chunk_blockchain_data(sender: PublicKey, request_id: u64, data: Vec<u8>) -> Result<Vec<ZhtpMeshMessage>> {
        Self::chunk_blockchain_data_with_size(sender, request_id, data, BLE_CHUNK_SIZE)
    }

    /// Chunk blockchain data with specific chunk size
    fn chunk_blockchain_data_with_size(
        sender: PublicKey,
        request_id: u64,
        data: Vec<u8>,
        chunk_size: usize,
    ) -> Result<Vec<ZhtpMeshMessage>> {
        let total_size = data.len();
        let chunks: Vec<&[u8]> = data.chunks(chunk_size).collect();
        let total_chunks = chunks.len() as u32;

        // Calculate hash of complete data
        let mut hasher = Sha256::new();
        hasher.update(&data);
        let hash_result = hasher.finalize();
        let mut complete_data_hash = [0u8; 32];
        complete_data_hash.copy_from_slice(&hash_result);

        info!(" Chunking blockchain data: {} bytes into {} chunks ({} bytes each)", 
            total_size, total_chunks, chunk_size);

        let mut messages = Vec::new();
        for (index, chunk) in chunks.iter().enumerate() {
            let message = ZhtpMeshMessage::BlockchainData {
                sender: sender.clone(),
                request_id,
                chunk_index: index as u32,
                total_chunks,
                data: chunk.to_vec(),
                complete_data_hash,
            };
            messages.push(message);
        }

        Ok(messages)
    }

    /// Add received chunk to buffer
    pub async fn add_chunk(
        &self,
        request_id: u64,
        chunk_index: u32,
        total_chunks: u32,
        data: Vec<u8>,
        complete_data_hash: [u8; 32],
    ) -> Result<Option<Vec<u8>>> {
        let mut buffers = self.received_chunks.write().await;

        let buffer = buffers.entry(request_id).or_insert_with(|| {
            // Get requester from pending requests
            let requester = PublicKey::new(vec![0; 32]); // Placeholder
            BlockchainChunkBuffer {
                chunks: HashMap::new(),
                total_chunks,
                complete_data_hash,
                requester,
            }
        });

        // Add chunk
        buffer.chunks.insert(chunk_index, data);
        debug!("Added chunk {}/{} for request {}", chunk_index + 1, total_chunks, request_id);

        // Check if all chunks received
        if buffer.chunks.len() as u32 == total_chunks {
            info!(" All chunks received for request {}, reassembling...", request_id);

            // Reassemble in order
            let mut complete_data = Vec::new();
            for i in 0..total_chunks {
                if let Some(chunk) = buffer.chunks.get(&i) {
                    complete_data.extend_from_slice(chunk);
                } else {
                    return Err(anyhow!("Missing chunk {} during reassembly", i));
                }
            }

            // Verify hash
            let mut hasher = Sha256::new();
            hasher.update(&complete_data);
            let hash_result = hasher.finalize();
            let mut computed_hash = [0u8; 32];
            computed_hash.copy_from_slice(&hash_result);

            if computed_hash != complete_data_hash {
                return Err(anyhow!("Blockchain data hash mismatch - data corrupted"));
            }

            info!(" Blockchain data verified: {} bytes", complete_data.len());

            // Remove from buffers
            buffers.remove(&request_id);

            return Ok(Some(complete_data));
        }

        Ok(None)
    }

    /// Check if a request is pending
    pub async fn is_request_pending(&self, request_id: u64) -> bool {
        self.pending_requests.read().await.contains_key(&request_id)
    }

    /// Complete a request
    pub async fn complete_request(&self, request_id: u64) {
        self.pending_requests.write().await.remove(&request_id);
        self.received_chunks.write().await.remove(&request_id);
        info!("Request {} completed and cleaned up", request_id);
    }
}

pub enum SyncType {
    /// Full blockchain sync (complete blocks, all transactions)
    FullBlockchain,
    /// Edge node sync (headers only + selective data)
    EdgeNode,
}

pub struct ActiveSync {
    pub sync_id: u64,
    pub protocol: NetworkProtocol,
    pub start_time: Instant,
}

pub struct PeerSyncState {
    /// Active syncs per type (sync_type -> sync info)
    /// Allows Edge and Full syncs to coexist
    pub active_syncs: HashMap<SyncType, ActiveSync>,
    /// Available protocols for this peer
    pub available_protocols: HashSet<NetworkProtocol>,
}

pub struct SyncCoordinator {
    /// Active syncs per peer (peer_id -> sync state)
    peer_syncs: Arc<RwLock<HashMap<PublicKey, PeerSyncState>>>,
    /// Sync timeout (if no progress in this time, allow new sync)
    sync_timeout: Duration,
}

impl SyncCoordinator {
    /// Create a new sync coordinator
    pub fn new() -> Self {
        Self {
            peer_syncs: Arc::new(RwLock::new(HashMap::new())),
            sync_timeout: Duration::from_secs(300), // 5 minutes timeout
        }
    }

    /// Register that a peer is available on a specific protocol
    /// Returns true if sync should be initiated, false if already syncing
    /// 
    /// # Arguments
    /// * `peer_id` - The peer's public key
    /// * `protocol` - The transport protocol (BLE, WiFi, TCP, etc.)
    /// * `sync_type` - Whether this is a full blockchain or edge node sync
    pub async fn register_peer_protocol(
        &self,
        peer_id: &PublicKey,
        protocol: NetworkProtocol,
        sync_type: SyncType,
    ) -> bool {
        let mut syncs = self.peer_syncs.write().await;

        let peer_state = syncs.entry(peer_id.clone()).or_insert_with(|| PeerSyncState {
            active_syncs: HashMap::new(),
            available_protocols: HashSet::new(),
        });

        // Add this protocol to available list
        peer_state.available_protocols.insert(protocol.clone());

        // Check if already syncing this type
        if let Some(active_sync) = peer_state.active_syncs.get(&sync_type) {
            // Check if sync has timed out
            if active_sync.start_time.elapsed() > self.sync_timeout {
                warn!(" Sync with peer {} timed out (type: {:?}, protocol: {:?}), allowing new sync",
                      hex::encode(&peer_id.key_id[..8]),
                      sync_type,
                      active_sync.protocol);

                // Clear timed-out sync
                peer_state.active_syncs.remove(&sync_type);
            } else {
                // Check if this is a protocol upgrade (higher priority protocol)
                let new_priority = protocol_priority(&protocol);
                let current_priority = protocol_priority(&active_sync.protocol);

                if new_priority > current_priority {
                    info!(" Allowing protocol upgrade from {:?} to {:?} for {:?} sync with peer {}",
                          active_sync.protocol, protocol, sync_type,
                          hex::encode(&peer_id.key_id[..8]));
                    return true;
                }

                info!(" Already syncing {:?} with peer {} via {:?}, skipping duplicate on {:?}",
                      sync_type,
                      hex::encode(&peer_id.key_id[..8]),
                      active_sync.protocol,
                      protocol);
                return false; // Already syncing same type, don't start another
            }
        }

        // Not currently syncing this type, should we initiate?
        self.should_initiate_sync_type(peer_state, sync_type, &protocol)
    }

    /// Determine if we should initiate a sync with this protocol for a specific sync type
    /// Priority: TCP/UDP (internet) > WiFi Direct > Bluetooth Classic > BLE
    fn should_initiate_sync_type(&self, peer_state: &PeerSyncState, sync_type: SyncType, new_protocol: &NetworkProtocol) -> bool {
        // If no active sync for this type, we should sync
        if !peer_state.active_syncs.contains_key(&sync_type) {
            return true;
        }

        // If we have a higher priority protocol for this sync type, upgrade
        if let Some(active_sync) = peer_state.active_syncs.get(&sync_type) {
            let new_priority = protocol_priority(new_protocol);
            let current_priority = protocol_priority(&active_sync.protocol);

            if new_priority > current_priority {
                info!(" Upgrading {:?} sync protocol from {:?} to {:?} (higher bandwidth)",
                      sync_type, active_sync.protocol, new_protocol);
                return true;
            }
        }

        false
    }

    /// Record that a sync has been initiated
    pub async fn start_sync(
        &self,
        peer_id: &PublicKey,
        sync_id: u64,
        sync_type: SyncType,
        protocol: NetworkProtocol,
    ) {
        let mut syncs = self.peer_syncs.write().await;

        if let Some(peer_state) = syncs.get_mut(peer_id) {
            peer_state.active_syncs.insert(sync_type, ActiveSync {
                sync_id,
                protocol: protocol.clone(),
                start_time: Instant::now(),
            });

            info!(" {:?} sync started with peer {} (ID: {}, protocol: {:?})",
                  sync_type,
                  hex::encode(&peer_id.key_id[..8]),
                  sync_id,
                  protocol);
        }
    }

    /// Record that a sync has completed
    pub async fn complete_sync(&self, peer_id: &PublicKey, sync_id: u64, sync_type: SyncType) {
        let mut syncs = self.peer_syncs.write().await;

        if let Some(peer_state) = syncs.get_mut(peer_id) {
            // Only clear if this is the active sync for this type
            if let Some(active_sync) = peer_state.active_syncs.get(&sync_type) {
                if active_sync.sync_id == sync_id {
                    let duration = active_sync.start_time.elapsed();

                    info!(" {:?} sync completed with peer {} (ID: {}, duration: {:?})",
                          sync_type,
                          hex::encode(&peer_id.key_id[..8]),
                          sync_id,
                          duration);

                    peer_state.active_syncs.remove(&sync_type);
                }
            }
        }
    }

    /// Record that a sync has failed
    pub async fn fail_sync(&self, peer_id: &PublicKey, sync_id: u64, sync_type: SyncType) {
        let mut syncs = self.peer_syncs.write().await;

        if let Some(peer_state) = syncs.get_mut(peer_id) {
            // Only clear if this is the active sync for this type
            if let Some(active_sync) = peer_state.active_syncs.get(&sync_type) {
                if active_sync.sync_id == sync_id {
                    warn!(" {:?} sync failed with peer {} (ID: {})",
                          sync_type,
                          hex::encode(&peer_id.key_id[..8]),
                          sync_id);

                    peer_state.active_syncs.remove(&sync_type);
                }
            }
        }
    }

    /// Remove a peer (cleanup when disconnected)
    pub async fn remove_peer(&self, peer_id: &PublicKey, protocol: NetworkProtocol) {
        let mut syncs = self.peer_syncs.write().await;

        if let Some(peer_state) = syncs.get_mut(peer_id) {
            // Remove this protocol
            peer_state.available_protocols.remove(&protocol);

            // Clear any syncs using this protocol
            peer_state.active_syncs.retain(|_, active_sync| {
                if active_sync.protocol == protocol {
                    debug!("🔌 Peer {} disconnected from {:?}, clearing sync state",
                           hex::encode(&peer_id.key_id[..8]), &protocol);
                    false
                } else {
                    true
                }
            });

            // If no protocols left, remove peer entirely
            if peer_state.available_protocols.is_empty() {
                syncs.remove(peer_id);
                debug!("🔌 Peer {} fully disconnected (all protocols)",
                       hex::encode(&peer_id.key_id[..8]));
            }
        }
    }

    /// Find peer by sync request ID
    /// Returns the peer's public key and sync type if found
    pub async fn find_peer_by_sync_id(&self, sync_id: u64) -> Option<(PublicKey, SyncType)> {
        let syncs = self.peer_syncs.read().await;

        for (peer_id, state) in syncs.iter() {
            for (sync_type, active_sync) in &state.active_syncs {
                if active_sync.sync_id == sync_id {
                    return Some((peer_id.clone(), *sync_type));
                }
            }
        }

        None
    }

    /// Get sync statistics
    pub async fn get_stats(&self) -> SyncStats {
        let syncs = self.peer_syncs.read().await;

        let total_peers = syncs.len();
        let active_syncs: usize = syncs.values()
            .map(|s| s.active_syncs.len())
            .sum();

        let mut protocol_counts: HashMap<NetworkProtocol, usize> = HashMap::new();
        for state in syncs.values() {
            for active_sync in state.active_syncs.values() {
                *protocol_counts.entry(active_sync.protocol.clone()).or_insert(0) += 1;
            }
        }

        SyncStats {
            total_peers,
            active_syncs,
            protocol_counts,
        }
    }
}

fn protocol_priority(protocol: &NetworkProtocol) -> u8 {
    match protocol {
        NetworkProtocol::TCP | NetworkProtocol::UDP => 100,      // Internet - fastest
        NetworkProtocol::WiFiDirect => 80,                        // WiFi Direct - very fast
        NetworkProtocol::BluetoothClassic => 50,                  // Bluetooth Classic - medium
        NetworkProtocol::BluetoothLE => 30,                       // BLE - slowest
        NetworkProtocol::LoRaWAN => 10,                           // LoRa - emergency only
        _ => 50,                                                   // Unknown - medium priority
    }
}

pub struct SyncStats {
    pub total_peers: usize,
    pub active_syncs: usize,
    pub protocol_counts: HashMap<NetworkProtocol, usize>,
}

